;---------------------------------------------------------------------------
; AmigaDOS hunk header, left in place. The bootblock loads this file raw to the
; address in $4.w and jumps to load+$20.
;---------------------------------------------------------------------------
HunkHeader:
	dc.b	$00,$00,$03,$F3,$00,$00,$00,$00,$00,$00,$00,$01,$00,$00,$00,$00
	dc.b	$00,$00,$00,$00,$00,$00,$62,$27,$00,$00,$03,$E9,$00,$00,$62,$27

;---------------------------------------------------------------------------
; Program entry point (load address + $20).
;---------------------------------------------------------------------------
ProgramEntry:
        bra.w   l_05A6E                         ; 00020  [1MB]   << changed from the 512K build ($000A0: bra.w $5aee) >>

;---------------------------------------------------------------------------
; === DATA: level map and tile tables ===
; Two separate tile systems share the map (WorldMap, one byte per 256 x 256-px cell):
;  graphics:  cell -> CellTiles: 16 x 16 tiles of 16 x 16 px, drawn from the level file
;  collision: cell -> BlockTiles: 8 x 8 tiles of 32 x 32 px -> TileAttr record (bank
;             from MapBlockIndex), which gives a profile for each 16 x 16 quadrant ->
;             FloorProfile / WallProfileR / WallProfileL (see MapTileAt).
; MapBlockIndex: per cell type, TileAttr bank x 8 (the value << 8 is the byte offset
; of the bank: 4 banks of 256 tiles x 8 bytes).
;---------------------------------------------------------------------------
MapBlockIndex:
	dc.b	$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$08	; cells $00-$0F
	dc.b	$08,$08,$08,$08,$08,$08,$08,$08,$08,$08,$08,$08,$18,$18,$08,$10	; cells $10-$1F
	dc.b	$10,$10,$10,$00,$00,$00,$10,$10,$10,$10,$10,$10,$10,$10,$10,$10	; cells $20-$2F
	dc.b	$10,$10,$10,$10,$10,$10,$10,$10,$10,$10,$10,$10,$10,$10,$10,$10	; cells $30-$3F
	dc.b	$10,$10,$10,$10,$10,$10,$10,$10,$10,$10,$18,$18,$18,$18,$18,$18	; cells $40-$4F
	dc.b	$18,$18,$18,$18,$18,$18,$18,$18,$18,$18,$18,$18,$18,$18,$18,$18	; cells $50-$5F
	dc.b	$18,$18,$18,$18,$10,$00,$10,$00,$00,$00,$00,$00,$00,$00,$00,$00	; cells $60-$6F

;---------------------------------------------------------------------------
; BlockTiles - per cell type ($00-$67), 64 collision-tile numbers: 8 columns of 8,
; each column listed from the bottom of the cell up (index = column*8 + row)
