;---------------------------------------------------------------------------
; MapTileAt - collision lookup for a world position
; In:  d6 = X, d7 = Y (level-relative pixels, Y increasing upwards)
; cell  = WorldMap byte at g_MapPtr + (X>>8) + (Y>>8)*32
; tile  = BlockTiles[cell*64 + ((X>>5)&7)*8 + ((Y>>5)&7)]   (8x8 grid of 32px tiles,
;         column-major, rows counted from the bottom of the cell)
; rec   = TileAttr + (MapBlockIndex[cell]<<8) + tile*8
; Out: a1 = rec + (X bit4 ? 2 : 0) + (Y bit4 ? 1 : 0)   (the 16x16 quadrant)
;      (a1)  = profile (SIGN-EXTENDED when indexing the tables below)
;              FloorProfile[p] = floor height 1-16 within the quadrant (0 = none)
;              WallProfileR/L[p] = wall offsets; p = $40-$7D = ladder
;      4(a1) = flags: bits 6-7 set = background / not solid (decorations, water)
;---------------------------------------------------------------------------
MapTileAt:
        movea.l g_MapPtr(a6),a1                 ; 059FC
        move.w  d6,d0                           ; 05A00
        lsr.w   #$8,d0                          ; 05A02
        adda.w  d0,a1                           ; 05A04
        move.w  d7,d0                           ; 05A06
        clr.b   d0                              ; 05A08
        lsr.w   #$3,d0                          ; 05A0A
        adda.w  d0,a1                           ; 05A0C
        move.b  (a1),d0                         ; 05A0E
        ext.w   d0                              ; 05A10
        lea.l   MapBlockIndex(pc),a1            ; 05A12
        adda.w  d0,a1                           ; 05A16
        swap    d0                              ; 05A18
        move.b  (a1),d0                         ; 05A1A
        lsl.w   #$8,d0                          ; 05A1C
        lea.l   TileAttr(pc),a1                 ; 05A1E
        pea.l   (a1,d0.w)                       ; 05A22
        swap    d0                              ; 05A26
        lsl.w   #$6,d0                          ; 05A28
        lea.l   BlockTiles(pc),a1               ; 05A2A
        adda.w  d0,a1                           ; 05A2E
        move.w  d6,d0                           ; 05A30
        lsr.w   #$5,d0                          ; 05A32
        andi.w  #$7,d0                          ; 05A34
        lsl.w   #$3,d0                          ; 05A38
        adda.w  d0,a1                           ; 05A3A
        move.w  d7,d0                           ; 05A3C
        lsr.w   #$5,d0                          ; 05A3E
        andi.w  #$7,d0                          ; 05A40
        adda.w  d0,a1                           ; 05A44
        clr.w   d0                              ; 05A46
        move.b  (a1),d0                         ; 05A48
        lsl.w   #$3,d0                          ; 05A4A
        movea.l (a7)+,a1                        ; 05A4C
        adda.w  d0,a1                           ; 05A4E
        btst    #$4,d6                          ; 05A50
        beq.b   l_05A58                         ; 05A54
        addq.l  #$2,a1                          ; 05A56
l_05A58:
        btst    #$4,d7                          ; 05A58
        beq.b   l_05A60                         ; 05A5C
        addq.l  #$1,a1                          ; 05A5E
l_05A60:
        rts                                     ; 05A60

;---------------------------------------------------------------------------
; CrashReset - target of every CPU exception vector ($8-$2C, $3C).
; Writes RESET / JMP $0.L ($4E70 $4EF9 0000) to address 0 and jumps there:
; any bus error, illegal instruction, trace etc. reboots the machine.
; This doubles as an anti-tamper / anti-debug measure.
;---------------------------------------------------------------------------
CrashReset:
        move.l  #$4e704ef9,(RESET_STUB).w       ; 05A62
        jmp     (RESET_STUB).w                  ; 05A6A
l_05A6E:
        movea.l $4.w,a1                         ; 05A6E  [1MB] a6 = GLOBALS + load address (from $4.w); the user stack sits below it  << 1MB only: 5 instruction(s) not in the 512K build >>
        lea.l   (GLOBALS).l,a6                  ; 05A72  [1MB] 
        adda.l  a1,a6                           ; 05A78  [1MB] 
        move    a6,usp                          ; 05A7A  [1MB] 
        move.l  a1,g_BaseAddr(a6)               ; 05A7C  [1MB] g_BaseAddr: added to every absolute program address from here on

;---------------------------------------------------------------------------
; ==================================================================
; Start - one-time initialisation
;  - point all exception vectors at CrashReset, autovectors at it too
;  - a6 = GLOBALS, USP = GLOBALS (user mode stack lives below it)
;  - load file $7F9C (tracks 33-36): Arthur sprite graphics, interleave
;    and convert into the 8 sprite planes at $1DE34-$26E34
;  - build HUD sprite data, load the remaining common files
;  - initialise hi-score table, copper lists, screen buffers
;  - install interrupts (InitHardware), show the FAST copyright
;    warning screen for 10 s, then drop
;    to user mode and spin: the whole game runs in interrupts.
; ==================================================================
;---------------------------------------------------------------------------
Start:
        lea.l   $8.w,a1                         ; 05A80
        lea.l   CrashReset(pc),a0               ; 05A84
        move.l  a0,(a1)+                        ; 05A88
        move.l  a0,(a1)+                        ; 05A8A
        move.l  a0,(a1)+                        ; 05A8C
        move.l  a0,(a1)+                        ; 05A8E
        move.l  a0,(a1)+                        ; 05A90
        move.l  a0,(a1)+                        ; 05A92
        move.l  a0,(a1)+                        ; 05A94
        move.l  a0,(a1)+                        ; 05A96
        move.l  a0,(VEC_UNINIT).w               ; 05A98  Line-A/Line-F slots ($28/$2C) left free: the loader uses them as variables
        move.l  a0,d0                           ; 05A9C
        move.l  a0,d1                           ; 05A9E
        move.l  a0,d2                           ; 05AA0
        move.l  (VEC_LEVEL3).w,d3               ; 05AA2  autovectors $60-$7C -> CrashReset, except level 3 (kept for now)
        move.l  a0,d4                           ; 05AA6
        move.l  a0,d5                           ; 05AA8
        move.l  a0,d6                           ; 05AAA
        move.l  a0,d7                           ; 05AAC
        lea.l   (VEC_SPURIOUS).w,a0             ; 05AAE
        movem.l d0-d7,(a0)                      ; 05AB2
        lea.l   FileTable(pc),a1                ; 05AB6  << 512K build has 2 more instruction(s) here (at $05B24), removed in the 1MB build >>
        bsr.w   LoadFile                        ; 05ABA  load Arthur sprite file (tracks 33-36) to $37468

;---------------------------------------------------------------------------
; Arthur's sprite graphics (file tracks 33-36, 42 frames of 32x32, 4 planes).
; Source rows are 8 words: [L-p0 R-p0 L-p1 R-p1 L-p2 R-p2 L-p3 R-p3].
; They are split into four sprite banks $2900 apart: sprites 0+1 = left 16
; pixels (attached pair, 16 colours from COLOR16), sprites 2+3 = right half.
; Frames: 0-14 armoured poses, 15 frog, 16-31 the same poses without armour (+$10),
; 32-36 skeleton (death), 37-39 frog, 40 sitting in his underwear (opening scene),
; 41 arms raised (end of level, ending). The second loop builds mirrored copies
; (bit-reversed, halves swapped) of frames 0-39 only - 40 and 41 always face right.
;---------------------------------------------------------------------------
        lea.l   FileTable(pc),a5                ; 05ABE
        movea.l (a5),a5                         ; 05AC2
        movea.l g_BaseAddr(a6),a0               ; 05AC4  [1MB] the sprite banks move with the load address  << 1MB only: 1 instruction(s) not in the 512K build >>
        lea.l   (ARTHUR_SPR_GFX).l,a1           ; 05AC8
        lea.l   (SPR_GFX_A1).l,a2               ; 05ACE
        lea.l   (SPR_GFX_A2).l,a3               ; 05AD4
        lea.l   (SPR_GFX_A3).l,a4               ; 05ADA
        adda.l  a0,a1                           ; 05AE0  [1MB]   << 1MB only: 4 instruction(s) not in the 512K build >>
        adda.l  a0,a2                           ; 05AE2  [1MB] 
        adda.l  a0,a3                           ; 05AE4  [1MB] 
        adda.l  a0,a4                           ; 05AE6  [1MB] 
        moveq   #$29,d7                         ; 05AE8
l_05AEA:
        moveq   #$1f,d6                         ; 05AEA
l_05AEC:
        move.w  (a5)+,(a1)+                     ; 05AEC
        move.w  (a5)+,(a3)+                     ; 05AEE
        move.w  (a5)+,(a1)+                     ; 05AF0
        move.w  (a5)+,(a3)+                     ; 05AF2
        move.w  (a5)+,(a2)+                     ; 05AF4
        move.w  (a5)+,(a4)+                     ; 05AF6
        move.w  (a5)+,(a2)+                     ; 05AF8
        move.w  (a5)+,(a4)+                     ; 05AFA
        dbra    d6,l_05AEC                      ; 05AFC
        dbra    d7,l_05AEA                      ; 05B00
        lea.l   FileTable(pc),a5                ; 05B04  second pass: build the mirrored frames
        movea.l (a5),a5                         ; 05B08
        lea.l   (SPR_GFX_B0).l,a3               ; 05B0A
        lea.l   (SPR_GFX_B1).l,a4               ; 05B10
        lea.l   (SPR_GFX_B2).l,a1               ; 05B16
        lea.l   (SPR_GFX_B3).l,a2               ; 05B1C
        adda.l  a0,a3                           ; 05B22  [1MB]   << 1MB only: 4 instruction(s) not in the 512K build >>
        adda.l  a0,a4                           ; 05B24  [1MB] 
