;---------------------------------------------------------------------------
; RedrawEntry - the VBL handler patches the return PC to here when a
; full redraw is pending (g_RedrawPending). Runs in user mode, outside the interrupt:
;   bsr.w RedrawScreen / clr.b g_SkipLogic(a6) (lets the logic run again) / bra *
; (kept as bytes: the code is only reached through the patched return address)
;---------------------------------------------------------------------------
RedrawEntry:
	dc.b	$61,$00,$60,$6E,$42,$2E,$00,$22,$60,$FE

;---------------------------------------------------------------------------
; ==================================================================
; Level1Logic - LEVEL 1 (SOFTINT) handler = the game's main loop
; The VBL handler raises SOFTINT each frame unless the previous frame's
; logic is still running, so this runs at most once per frame at IPL 1,
; letting the VBL/keyboard interrupts pre-empt it.
; Dispatches on g_GameState:
;    0 -> InGame        1 -> AttractTitle      2 -> AttractHiScores
; ==================================================================
;---------------------------------------------------------------------------
Level1Logic:
        move.w  #INTF_SOFTINT,CUSTOM+INTREQ     ; 05F0C
        movem.l d0-d7/a0-a5,-(a7)               ; 05F14
        move.b  g_GameState(a6),d0              ; 05F18
        ext.w   d0                              ; 05F1C
        add.w   d0,d0                           ; 05F1E
        add.w   d0,d0                           ; 05F20
        jmp     GameStateTable(pc,d0.w)         ; 05F22
GameStateTable:
        bra.w   InGame                          ; 05F26
        bra.w   AttractTitle                    ; 05F2A
        bra.w   AttractHiScores                 ; 05F2E

;---------------------------------------------------------------------------
; Attract state 1: credits/title text, 400 frames
;---------------------------------------------------------------------------
AttractTitle:
        tst.b   g_SubState(a6)                  ; 05F32
        bne.b   l_05F6C                         ; 05F36
        tst.b   g_RedrawDone(a6)                ; 05F38
        beq.b   l_05F82                         ; 05F3C
        clr.w   g_RawKey(a6)                    ; 05F3E
        bsr.w   SwapScreens                     ; 05F42
        bsr.w   DrawCreditsScreen               ; 05F46
        clr.b   g_ArthurVisible(a6)             ; 05F4A
        clr.b   g_Spr47Visible(a6)              ; 05F4E
        bsr.w   ArthurSpritePos                 ; 05F52
        bsr.w   SetBitplanePtrs                 ; 05F56
        bsr.w   ShowBackBuffer                  ; 05F5A
        st.b    g_RedrawPending(a6)             ; 05F5E
        move.w  g_VblCount(a6),g_FrameStamp(a6) ; 05F62
        addq.b  #SS_PLAYLEVEL,g_SubState(a6)    ; 05F68
l_05F6C:
        move.w  g_VblCount(a6),d0               ; 05F6C
        sub.w   g_FrameStamp(a6),d0             ; 05F70
        cmp.w   #$190,d0                        ; 05F74
        bcs.b   l_05F82                         ; 05F78
        addq.b  #GS_TITLE,g_GameState(a6)       ; 05F7A
        clr.b   g_SubState(a6)                  ; 05F7E
l_05F82:
        bra.b   CheckGameStart                  ; 05F82

;---------------------------------------------------------------------------
; Attract state 2: high-score table, 200 frames
;---------------------------------------------------------------------------
AttractHiScores:
        tst.b   g_SubState(a6)                  ; 05F84
        bne.b   l_05FB2                         ; 05F88
        tst.b   g_RedrawDone(a6)                ; 05F8A
        beq.b   CheckGameStart                  ; 05F8E
        bsr.w   SwapScreens                     ; 05F90
        bsr.w   DrawHiScoreTable                ; 05F94
        bsr.w   ArthurSpritePos                 ; 05F98
        bsr.w   SetBitplanePtrs                 ; 05F9C
        bsr.w   ShowBackBuffer                  ; 05FA0
        st.b    g_RedrawPending(a6)             ; 05FA4
        move.w  g_VblCount(a6),g_FrameStamp(a6) ; 05FA8
        addq.b  #SS_PLAYLEVEL,g_SubState(a6)    ; 05FAE
l_05FB2:
        move.w  g_VblCount(a6),d0               ; 05FB2
        sub.w   g_FrameStamp(a6),d0             ; 05FB6
        cmp.w   #$c8,d0                         ; 05FBA
        bcs.b   CheckGameStart                  ; 05FBE
        move.b  #GS_TITLE,g_GameState(a6)       ; 05FC0
        clr.b   g_SubState(a6)                  ; 05FC6

;---------------------------------------------------------------------------
; Start a game: fire (CIA-A PRA bit 7) starts with the current mode,
; F1 = one player, F2 = two players.  Resets both player blocks
; (level 0, weapon 1 = lance, 7 lives, intro cut-scene pending).
;---------------------------------------------------------------------------
CheckGameStart:
        btst    #$7,$bfe001.l                   ; 05FCA
        beq.b   l_05FF0                         ; 05FD2
        cmpi.b  #$50,g_RawKey(a6)               ; 05FD4  F1 pressed?
        bne.b   l_05FE2                         ; 05FDA
        clr.b   g_TwoPlayer(a6)                 ; 05FDC
        bra.b   l_05FF0                         ; 05FE0
l_05FE2:
        cmpi.b  #$51,g_RawKey(a6)               ; 05FE2  F2 pressed?
        bne.w   LogicExit                       ; 05FE8
        st.b    g_TwoPlayer(a6)                 ; 05FEC
l_05FF0:
        clr.w   g_RawKey(a6)                    ; 05FF0
        clr.b   g_Paused(a6)                    ; 05FF4
        clr.b   g_GameState(a6)                 ; 05FF8
        clr.b   g_SubState(a6)                  ; 05FFC
        clr.b   g_SubState2(a6)                 ; 06000
        clr.b   g_SubState3(a6)                 ; 06004
        clr.b   g_CurPlayer(a6)                 ; 06008
        move.b  #$7,g_Lives(a6)                 ; 0600C  lives = 7
        move.w  #$1,g_Weapon(a6)                ; 06012  weapon = 1 (lance)
        clr.w   g_Level(a6)                     ; 06018
        clr.l   g_Score(a6)                     ; 0601C
        clr.b   g_ExtraLives(a6)                ; 06020
        st.b    g_ShowIntro(a6)                 ; 06024  play opening cut-scene
        clr.b   g_Checkpoint(a6)                ; 06028
        clr.b   g_PlayerDied(a6)                ; 0602C
        tst.b   g_TwoPlayer(a6)                 ; 06030
        beq.b   StartGame                       ; 06034
        lea.l   (GLOBALS_P2).l,a0               ; 06036
        adda.l  g_BaseAddr(a6),a0               ; 0603C  [1MB]   << 1MB only: 1 instruction(s) not in the 512K build >>
        move.b  #$7,$aa(a0)                     ; 06040
        move.w  #$1,$a0(a0)                     ; 06046
        clr.w   $9e(a0)                         ; 0604C
        clr.l   $a2(a0)                         ; 06050
        clr.b   $ac(a0)                         ; 06054
        st.b    $ad(a0)                         ; 06058
        clr.b   $ab(a0)                         ; 0605C
StartGame:
        bsr.w   ClearHudArea                    ; 06060
        move.b  #$1f,g_TextShadow(a6)           ; 06064
        move.b  #$1b,g_TextInk(a6)              ; 0606A
        move.b  #$5,g_TextPaper(a6)             ; 06070
        lea.l   TxtPlayer(pc),a3                ; 06076
        moveq   #$1,d1                          ; 0607A
        moveq   #$0,d2                          ; 0607C
        bsr.w   PrintString                     ; 0607E
        move.b  #$31,d0                         ; 06082
        bsr.w   PrintChar                       ; 06086
        moveq   #$1,d1                          ; 0608A
        moveq   #$8,d2                          ; 0608C
        moveq   #$0,d6                          ; 0608E
        bsr.w   PrintBCD                        ; 06090
        tst.b   g_TwoPlayer(a6)                 ; 06094
        beq.b   l_060CA                         ; 06098
        move.b  #$1f,g_TextShadow(a6)           ; 0609A
        move.b  #$1b,g_TextInk(a6)              ; 060A0
        move.b  #$5,g_TextPaper(a6)             ; 060A6
        lea.l   TxtPlayer(pc),a3                ; 060AC
        moveq   #$17,d1                         ; 060B0
        moveq   #$0,d2                          ; 060B2
        bsr.w   PrintString                     ; 060B4
        move.b  #$32,d0                         ; 060B8
        bsr.w   PrintChar                       ; 060BC
        moveq   #$16,d1                         ; 060C0
        moveq   #$8,d2                          ; 060C2
        moveq   #$0,d6                          ; 060C4
        bsr.w   PrintBCD                        ; 060C6
l_060CA:
        move.b  #$1f,g_TextShadow(a6)           ; 060CA
        move.b  #$1,g_TextInk(a6)               ; 060D0
        move.b  #$18,g_TextPaper(a6)            ; 060D6
        lea.l   TxtTopScore(pc),a3              ; 060DC
        moveq   #$b,d1                          ; 060E0
        moveq   #$0,d2                          ; 060E2
        bsr.w   PrintString                     ; 060E4
        moveq   #$c,d1                          ; 060E8
        moveq   #$8,d2                          ; 060EA
        move.l  g_HiScores(a6),d6               ; 060EC
        bsr.w   PrintBCD                        ; 060F0
        clr.b   g_GameState(a6)                 ; 060F4
        clr.b   g_SubState(a6)                  ; 060F8
        bra.w   LogicExit                       ; 060FC

;---------------------------------------------------------------------------
; Draw the 13 x 5 letter grid for name entry, d5 = the cursor's cell (shown in
; white on odd frames, so it flashes), then 'INITIAL' and the three letters so far
;---------------------------------------------------------------------------
DrawNameGrid:
        moveq   #$0,d4                          ; 06100
        moveq   #$4,d7                          ; 06102
        moveq   #$38,d2                         ; 06104
        lea.l   NameGridLetters(pc),a0          ; 06106
l_0610A:
        moveq   #$4,d1                          ; 0610A
        moveq   #$c,d6                          ; 0610C
l_0610E:
        cmp.w   d4,d5                           ; 0610E
        bne.b   l_06128                         ; 06110
        btst    #$0,g_GameFrame+1(a6)           ; 06112
        bne.b   l_06128                         ; 06118
        move.b  #$1,g_TextInk(a6)               ; 0611A
        move.b  #$18,g_TextPaper(a6)            ; 06120
        bra.b   l_06134                         ; 06126
l_06128:
        move.b  #$3,g_TextInk(a6)               ; 06128
        move.b  #$6,g_TextPaper(a6)             ; 0612E
l_06134:
        move.b  (a0)+,d0                        ; 06134
        bsr.w   PrintChar                       ; 06136
        addq.w  #$1,d4                          ; 0613A
        addq.b  #$1,d3                          ; 0613C
        addq.w  #$1,d1                          ; 0613E
        dbra    d6,l_0610E                      ; 06140
        addi.w  #$10,d2                         ; 06144
        dbra    d7,l_0610A                      ; 06148
        move.b  #$3,g_TextInk(a6)               ; 0614C
        move.b  #$6,g_TextPaper(a6)             ; 06152
        lea.l   TxtInitial(pc),a3               ; 06158
        moveq   #$8,d1                          ; 0615C
        move.w  #$d8,d2                         ; 0615E
        bsr.w   PrintString                     ; 06162
        move.b  #$1,g_TextInk(a6)               ; 06166
        move.b  #$18,g_TextPaper(a6)            ; 0616C
        lea.l   g_Crouching(a6),a0              ; 06172
        addq.w  #$1,d1                          ; 06176
        move.b  (a0)+,d0                        ; 06178
        bsr.w   PrintChar                       ; 0617A
        move.b  (a0)+,d0                        ; 0617E
        bsr.w   PrintChar                       ; 06180
        move.b  (a0)+,d0                        ; 06184
        bsr.w   PrintChar                       ; 06186
        addq.w  #$1,g_GameFrame(a6)             ; 0618A
        rts                                     ; 0618E

;---------------------------------------------------------------------------
; Replacement initials '504' used when the player leaves the name blank
;---------------------------------------------------------------------------
NameBlank:
	dc.b	$35,$30,$31

;---------------------------------------------------------------------------
; Initials stored when the cheat is entered
;---------------------------------------------------------------------------
NameCheat:
	dc.b	$60,$60,$60

;---------------------------------------------------------------------------
; High-score name entry (GameOver step 1/1), at most every 2 frames.
; Joystick moves the cursor over the 13 x 5 grid (NameGridLetters); fire on a letter adds
; it (up to 3), cell 62 adds a space, 63 rubs out, 64 (END) stores the name:
;  ')!(' sets g_CheatOn (lives never decrease, and once his armour is gone nothing can
;        hit Arthur) and stores NameCheat instead;
;  blank initials are stored as '504' (NameBlank).
; A new top score is copied to the HUD's TOP SCORE; the 1MB build plays tune 11 (6 for a
; new top score). Then 200 frames to GameOver step 1/2.
;---------------------------------------------------------------------------
NameEntry:
        moveq   #$2,d0                          ; 06196
        add.w   g_FrameStamp(a6),d0             ; 06198
        cmp.w   g_VblCount(a6),d0               ; 0619C
        bhi.w   LogicExit                       ; 061A0
l_061A4:
        move.w  g_Joy(a6),d0                    ; 061A4
        and.w   g_JoyPrev(a6),d0                ; 061A8
        btst    #$1,d0                          ; 061AC  right
        bne.w   l_0629C                         ; 061B0
        btst    #$9,d0                          ; 061B4  left
        bne.w   l_062AC                         ; 061B8
        btst    #$0,d0                          ; 061BC  down
        bne.w   l_062BA                         ; 061C0
        btst    #$8,d0                          ; 061C4  up
        bne.w   l_062CA                         ; 061C8
        btst    #$f,d0                          ; 061CC  fire
        beq.w   l_0627A                         ; 061D0
        move.w  g_ArthurY(a6),d5                ; 061D4  cell = row * 13 + column
        mulu.w  #$d,d5                          ; 061D8
        add.w   g_ArthurX(a6),d5                ; 061DC
        cmp.w   #$40,d5                         ; 061E0  END
        beq.b   l_06216                         ; 061E4
        cmp.w   #$3f,d5                         ; 061E6  rub out
        beq.w   l_0627C                         ; 061EA
        cmp.w   #$3e,d5                         ; 061EE  space
        beq.w   l_06296                         ; 061F2
        lea.l   NameGridLetters(pc),a0          ; 061F6
        move.b  (a0,d5.w),d0                    ; 061FA
l_061FE:
        move.w  g_ArthurAux(a6),d1              ; 061FE  three letters already?
        cmp.w   #$3,d1                          ; 06202
        beq.b   l_0627A                         ; 06206
        lea.l   g_Crouching(a6),a0              ; 06208
        move.b  d0,(a0,d1.w)                    ; 0620C
        addq.w  #$1,g_ArthurAux(a6)             ; 06210
        bra.b   l_0627A                         ; 06214
l_06216:
        moveq   #$0,d0                          ; 06216
        lea.l   g_Crouching(a6),a0              ; 06218
        move.b  (a0),d0                         ; 0621C
        lsl.l   #$8,d0                          ; 0621E
        move.b  $1(a0),d0                       ; 06220
        lsl.l   #$8,d0                          ; 06224
        move.b  $2(a0),d0                       ; 06226
        cmp.l   #$292128,d0                     ; 0622A  initials == ')!(' ?
        seq.b   g_CheatOn(a6)                   ; 06230  g_CheatOn = result
        bne.b   l_0623C                         ; 06234
        lea.l   NameCheat(pc),a0                ; 06236
        bra.b   l_06248                         ; 0623A
l_0623C:
        cmp.l   #$202020,d0                     ; 0623C  initials blank?
        bne.b   l_06248                         ; 06242
        lea.l   NameBlank(pc),a0                ; 06244
l_06248:
        movea.l g_ShownScore(a6),a1             ; 06248  store the initials
        move.b  (a0)+,(a1)+                     ; 0624C
        move.b  (a0)+,(a1)+                     ; 0624E
        move.b  (a0)+,(a1)+                     ; 06250
        moveq   #$b,d0                          ; 06252  1MB build: tune 11 ...
        move.l  g_Score(a6),d1                  ; 06254
        cmp.l   g_HiScores(a6),d1               ; 06258  new top score: update the HUD
        bne.b   l_0626C                         ; 0625C  [1MB]   << changed from the 512K build ($06202: bne.b $6212) >>
        moveq   #$c,d1                          ; 0625E
        moveq   #$8,d2                          ; 06260
        move.l  g_HiScores(a6),d6               ; 06262
        bsr.w   PrintBCD                        ; 06266
        moveq   #TUNE_NAME_TOP,d0               ; 0626A  ... or 6
l_0626C:
        bsr.w   PlayMusic                       ; 0626C  [1MB]   << 1MB only: 1 instruction(s) not in the 512K build >>
        addq.b  #$1,g_SubState3(a6)             ; 06270
        move.b  #$c8,g_StateTimer(a6)           ; 06274
l_0627A:
        bra.b   l_062D6                         ; 0627A
l_0627C:
        tst.w   g_ArthurAux(a6)                 ; 0627C
        beq.b   l_0627A                         ; 06280
        subq.w  #$1,g_ArthurAux(a6)             ; 06282
        lea.l   g_Crouching(a6),a0              ; 06286
        move.w  g_ArthurAux(a6),d1              ; 0628A
        move.b  #$20,(a0,d1.w)                  ; 0628E
        bra.b   l_0627A                         ; 06294
l_06296:
        moveq   #$20,d0                         ; 06296
        bra.w   l_061FE                         ; 06298
l_0629C:
        cmpi.w  #$c,g_ArthurX(a6)               ; 0629C
        bcc.w   l_061A4                         ; 062A2
        addq.w  #$1,g_ArthurX(a6)               ; 062A6
        bra.b   l_062D6                         ; 062AA
l_062AC:
        tst.w   g_ArthurX(a6)                   ; 062AC
        beq.w   l_061A4                         ; 062B0
        subq.w  #$1,g_ArthurX(a6)               ; 062B4
        bra.b   l_062D6                         ; 062B8
l_062BA:
        cmpi.w  #$4,g_ArthurY(a6)               ; 062BA
        bcc.w   l_061A4                         ; 062C0
        addq.w  #$1,g_ArthurY(a6)               ; 062C4
        bra.b   l_062D6                         ; 062C8
l_062CA:
        tst.w   g_ArthurY(a6)                   ; 062CA
        beq.w   l_061A4                         ; 062CE
        subq.w  #$1,g_ArthurY(a6)               ; 062D2
l_062D6:
        clr.b   g_RedrawPending(a6)             ; 062D6  redraw the screen and the grid
        bsr.w   RedrawScreen                    ; 062DA
        bsr.w   SwapScreens                     ; 062DE
        move.w  g_ArthurY(a6),d5                ; 062E2
        mulu.w  #$d,d5                          ; 062E6
        add.w   g_ArthurX(a6),d5                ; 062EA
        bsr.w   DrawNameGrid                    ; 062EE
        bsr.w   SetBitplanePtrs                 ; 062F2
        bsr.w   ShowBackBuffer                  ; 062F6
        move.w  g_VblCount(a6),g_FrameStamp(a6) ; 062FA
        bra.w   LogicExit                       ; 06300

;---------------------------------------------------------------------------
