        moveq   #$6,d1                          ; 06364
        move.w  #$68,d2                         ; 06366
        bsr.w   PrintString                     ; 0636A
        move.b  #$1f,g_TextShadow(a6)           ; 0636E
        move.b  #$1,g_TextInk(a6)               ; 06374
