        moveq   #$6,d1                          ; 063F4
        movea.l a0,a3                           ; 063F6
        bsr.w   PrintString                     ; 063F8
        movea.l a3,a0                           ; 063FC
        moveq   #$17,d1                         ; 063FE
        movea.l a1,a3                           ; 06400
        bsr.w   PrintString                     ; 06402
        move.b  #$1f,g_TextShadow(a6)           ; 06406
        move.b  #$3,g_TextInk(a6)               ; 0640C
        move.b  #$14,g_TextPaper(a6)            ; 06412
        addi.w  #$10,d2                         ; 06418
        dbra    d7,l_063F4                      ; 0641C
