        move.b  (a0)+,d0                        ; 06440
        bsr.w   PrintChar                       ; 06442
        move.b  (a0)+,d0                        ; 06446
        bsr.w   PrintChar                       ; 06448
        move.b  (a0)+,d0                        ; 0644C
        bsr.w   PrintChar                       ; 0644E
        addq.w  #$1,d1                          ; 06452
        move.l  (a1)+,d6                        ; 06454
        bsr.w   PrintBCD                        ; 06456
        addi.w  #$10,d2                         ; 0645A
        dbra    d7,l_0642C                      ; 0645E
DrawCopyright:
