        move.b  #$6,g_TextInk(a6)               ; 06468
        move.b  #$1f,g_TextPaper(a6)            ; 0646E
        lea.l   TxtCopyright(pc),a3             ; 06474
        moveq   #$4,d1                          ; 06478
