;---------------------------------------------------------------------------
; ==================================================================
; InGame - dispatch on g_SubState:
;   0 LoadLevel     load the level's files            -> 1
;   1 PlayLevel     g_SubState2: 0 progress map, 1 SetupLevel, 2 start music -> 2
;   2 InPlay        PlayFrame every frame; after a death or a finished level decides
;                   what comes next
;   3 GameOver      'GAME OVER', high-score insertion and name entry
;   4 LevelComplete walk off, bonus                   -> 2 (g_LevelDone) -> 0
;   5 IntroCutscene once per game, before the first level
;   6 Ending        after Astaroth
;   7 WeaponUseless Astaroth's guard beaten without the cross
; ==================================================================
;---------------------------------------------------------------------------
InGame:
        move.b  g_SubState(a6),d0               ; 064BC
        add.w   d0,d0                           ; 064C0
        add.w   d0,d0                           ; 064C2
        jmp     InGameStateTable(pc,d0.w)       ; 064C4
InGameStateTable:
        bra.w   LoadLevel                       ; 064C8
        bra.w   PlayLevel                       ; 064CC
        bra.w   InPlay                          ; 064D0
        bra.w   GameOver                        ; 064D4
        bra.w   LevelComplete                   ; 064D8
        bra.w   IntroCutscene                   ; 064DC
        bra.w   Ending                          ; 064E0
        bra.w   WeaponUseless                   ; 064E4

;---------------------------------------------------------------------------
; LevelComplete - sub state 4 (after taking the key). Steps (g_SubState2):
;  0 Arthur stands just past the right edge facing right
;  1 walks right for 32 frames,
;  2 raises his arms (frame 41) for 64 frames while 'BONUS' and the amount are shown
;    (5000 for levels 0-1, 10000 for 2-3, 15000 for 4-5); then the bonus is added and
;    his armour is restored
;  3 walks on for 70 frames; then g_Level + 1 (wrapping after 6), g_LevelDone, and
;    sub state 2 -> InPlay loads the next level.
;---------------------------------------------------------------------------
LevelComplete:
        move.b  g_SubState2(a6),d0              ; 064E8
        ext.w   d0                              ; 064EC
        add.w   d0,d0                           ; 064EE
        add.w   d0,d0                           ; 064F0
        jmp     LevelComplete_Jumps(pc,d0.w)    ; 064F2
LevelComplete_Jumps:
        bra.w   Bonus_Setup                     ; 064F6
        bra.w   Bonus_Walk                      ; 064FA
        bra.w   Bonus_Show                      ; 064FE
        bra.w   Bonus_WalkOff                   ; 06502
Bonus_Setup:
        clr.b   g_Jumping(a6)                   ; 06506
        clr.b   g_Crouching(a6)                 ; 0650A
        clr.b   g_ArthurState(a6)               ; 0650E
        move.b  #$1,g_ArthurFacing(a6)          ; 06512
        move.b  #$1,g_ArthurDir(a6)             ; 06518
        moveq   #$25,d0                         ; 0651E  37 px past the right edge
        add.w   g_LevelWidth(a6),d0             ; 06520
        move.w  d0,g_ArthurX(a6)                ; 06524
        lea.l   ArthurAnims(pc),a1              ; 06528
        bsr.w   ArthurSetAnim                   ; 0652C
        move.b  #$20,g_StateTimer(a6)           ; 06530
        addq.b  #$1,g_SubState2(a6)             ; 06536
        bra.w   l_06E0E                         ; 0653A
Bonus_Walk:
        subq.b  #$1,g_StateTimer(a6)            ; 0653E
        beq.b   l_06554                         ; 06542
        addi.l  #$12000,g_ArthurX(a6)           ; 06544
        bsr.w   ArthurAnimate                   ; 0654C
        bra.w   l_06E0E                         ; 06550
l_06554:
        move.b  #$29,g_ArthurFrame(a6)          ; 06554  arms raised
        clr.b   g_ArthurAnimTimer(a6)           ; 0655A
        move.b  #$40,g_StateTimer(a6)           ; 0655E
        moveq   #$3b,d0                         ; 06564  [1MB]   << 1MB only: 1 instruction(s) not in the 512K build >>
        addq.b  #$1,g_SubState2(a6)             ; 06566
        bra.w   l_06E0E                         ; 0656A
Bonus_Show:
        subq.b  #$1,g_StateTimer(a6)            ; 0656E
        beq.b   l_065B8                         ; 06572
        move.b  #$1f,g_TextShadow(a6)           ; 06574
        move.b  #$1b,g_TextInk(a6)              ; 0657A
        move.b  #$5,g_TextPaper(a6)             ; 06580
        lea.l   TxtBonus(pc),a3                 ; 06586
        moveq   #$18,d1                         ; 0658A
        move.w  #$b8,d2                         ; 0658C  lower on levels 4-6
        cmpi.w  #$4,g_Level(a6)                 ; 06590
        bcs.b   l_0659C                         ; 06596
        move.w  #$80,d2                         ; 06598
l_0659C:
        bsr.w   PrintString                     ; 0659C
        move.w  g_Level(a6),d0                  ; 065A0
        mulu.w  #$6,d0                          ; 065A4
        lea.l   TxtBonusAmounts(pc,d0.w),a3     ; 065A8
        moveq   #$18,d1                         ; 065AC
        addq.w  #$8,d2                          ; 065AE
        bsr.w   PrintString                     ; 065B0
        bra.w   l_06E0E                         ; 065B4
l_065B8:
        move.w  g_Level(a6),d0                  ; 065B8  add the bonus
        move.b  LevelBonusIndex(pc,d0.w),d0     ; 065BC
        bsr.w   AddScore                        ; 065C0
        clr.b   g_NoArmour(a6)                  ; 065C4  armour back on for the next level
        lea.l   ArthurAnims(pc),a1              ; 065C8
        bsr.w   ArthurSetAnim                   ; 065CC
        move.b  #$46,g_StateTimer(a6)           ; 065D0
        addq.b  #$1,g_SubState2(a6)             ; 065D6
        bra.w   l_06E0E                         ; 065DA

;---------------------------------------------------------------------------
; score-table index of the bonus per level
;---------------------------------------------------------------------------
LevelBonusIndex:
	dc.b	$0D,$0D,$12,$12,$17,$17
TxtBonus:
	dc.b	$42,$4F,$4E,$55,$53,$00

;---------------------------------------------------------------------------
; 5000,5000,10000,10000,15000,15000 per level
;---------------------------------------------------------------------------
TxtBonusAmounts:
	dc.b	$35,$30,$30,$30,$20,$00,$35,$30,$30,$30,$20,$00,$31,$30,$30,$30
	dc.b	$30,$00,$31,$30,$30,$30,$30,$00,$31,$35,$30,$30,$30,$00,$31,$35
	dc.b	$30,$30,$30,$00
Bonus_WalkOff:
        subq.b  #$1,g_StateTimer(a6)            ; 0660E
        beq.b   l_06624                         ; 06612
        addi.l  #$12000,g_ArthurX(a6)           ; 06614
        bsr.w   ArthurAnimate                   ; 0661C
        bra.w   l_06E0E                         ; 06620
l_06624:
        clr.b   g_Checkpoint(a6)                ; 06624  next level
        addq.w  #$1,g_Level(a6)                 ; 06628
        cmpi.w  #$7,g_Level(a6)                 ; 0662C
        bcs.b   l_06638                         ; 06632
        clr.w   g_Level(a6)                     ; 06634
l_06638:
        st.b    g_LevelDone(a6)                 ; 06638
        move.b  #SS_INPLAY,g_SubState(a6)       ; 0663C
        clr.b   g_SubState2(a6)                 ; 06642
        clr.b   g_SubState3(a6)                 ; 06646
        bra.w   LogicExit                       ; 0664A

;---------------------------------------------------------------------------
; GameOver - sub state 3. Steps (g_SubState2 / g_SubState3):
;  0     'GAME OVER PLAYER ONE' (or TWO) for 200 frames
;  1/0   not in the top 10 -> step 2. Otherwise insert the score and three blank initials
;        (the lower entries move down), redraw the screen where the camera was and show
;        the letter grid; the 1MB build plays tune 3 (1 for a new top score)
;  1/1   NameEntry
;  1/2   200 frames, then
;  2     back to InPlay (g_GameState 0, sub state 2), which switches to the other player
;        or returns to the attract screens.
; Name entry borrows Arthur's variables: g_ArthurX/Y = cursor column (0-12) / row (0-4),
; g_ArthurAux = letters entered, g_Crouching/g_Jumping/g_Falling = the three initials,
; g_ShownScore = pointer to the name's slot in g_HiNames.
;---------------------------------------------------------------------------
GameOver:
        cmpi.b  #$1,g_SubState2(a6)             ; 0664E
        beq.b   l_066A8                         ; 06654
        bhi.w   l_0679A                         ; 06656
        move.b  #$c8,g_StateTimer(a6)           ; 0665A  200 frames
        move.b  #$1f,g_TextShadow(a6)           ; 06660
        move.b  #$1b,g_TextInk(a6)              ; 06666
        move.b  #$5,g_TextPaper(a6)             ; 0666C
        moveq   #$6,d1                          ; 06672
        move.w  #$88,d2                         ; 06674
        lea.l   TxtGameOver(pc),a3              ; 06678
        bsr.w   PrintString                     ; 0667C
        tst.b   g_CurPlayer(a6)                 ; 06680
        bne.b   l_0668C                         ; 06684
        lea.l   TxtOne(pc),a3                   ; 06686
        bra.b   l_06690                         ; 0668A
l_0668C:
        lea.l   TxtTwo(pc),a3                   ; 0668C
l_06690:
        bsr.w   PrintString                     ; 06690
        bsr.w   ArthurSpritePos                 ; 06694
        bsr.w   SetBitplanePtrs                 ; 06698
        bsr.w   ShowBackBuffer                  ; 0669C
        addq.b  #$1,g_SubState2(a6)             ; 066A0
        bra.w   LogicExit                       ; 066A4
l_066A8:
        cmpi.b  #$1,g_SubState3(a6)             ; 066A8
        beq.w   NameEntry                       ; 066AE
        bhi.w   l_0678A                         ; 066B2
        subq.b  #$1,g_StateTimer(a6)            ; 066B6  wait
        bne.w   LogicExit                       ; 066BA
        move.w  g_ScrollFineX(a6),d0            ; 066BE  redraw origin = where the camera is
        asr.w   #$4,d0                          ; 066C2
        add.w   g_ScrollTileX(a6),d0            ; 066C4
        move.w  d0,g_NewTileX(a6)               ; 066C8
        clr.w   g_ScrollFineX(a6)               ; 066CC
        move.w  g_ScrollFineY(a6),d0            ; 066D0
        asr.w   #$4,d0                          ; 066D4
        add.w   g_ScrollTileY(a6),d0            ; 066D6
        move.w  d0,g_NewTileY(a6)               ; 066DA
        clr.w   g_ScrollFineY(a6)               ; 066DE
        clr.b   g_ArthurVisible(a6)             ; 066E2
        clr.b   g_Spr47Visible(a6)              ; 066E6
        lea.l   g_HiScores(a6),a0               ; 066EA  rank: first entry the score beats
        moveq   #$0,d7                          ; 066EE
        move.l  g_Score(a6),d0                  ; 066F0
l_066F4:
        cmp.l   (a0)+,d0                        ; 066F4
        bhi.b   l_06704                         ; 066F6
        addq.w  #$1,d7                          ; 066F8
        cmp.w   #$a,d7                          ; 066FA
        bne.b   l_066F4                         ; 066FE
        bra.w   l_0679A                         ; 06700
l_06704:
        lea.l   g_HiScores+36(a6),a0            ; 06704  shift the lower scores down and insert
        move.w  d7,d6                           ; 06708
l_0670A:
        addq.w  #$1,d7                          ; 0670A
        cmp.w   #$a,d7                          ; 0670C
        beq.b   l_06718                         ; 06710
        move.l  -(a0),$4(a0)                    ; 06712
        bra.b   l_0670A                         ; 06716
l_06718:
        move.l  d0,(a0)                         ; 06718
        lea.l   g_HiNames+27(a6),a0             ; 0671A  and the names (3 bytes each)
l_0671E:
        addq.w  #$1,d6                          ; 0671E
        cmp.w   #$a,d6                          ; 06720
        beq.b   l_06734                         ; 06724
        move.b  -(a0),$3(a0)                    ; 06726
        move.b  -(a0),$3(a0)                    ; 0672A
        move.b  -(a0),$3(a0)                    ; 0672E
        bra.b   l_0671E                         ; 06732
l_06734:
        move.l  a0,g_ShownScore(a6)             ; 06734  remember where the initials go
        moveq   #$3,d0                          ; 06738  1MB build: tune 3, or 1 for a new top score
        move.l  g_Score(a6),d1                  ; 0673A
        cmp.l   g_HiScores(a6),d1               ; 0673E
        bne.b   l_06746                         ; 06742  [1MB]   << changed from the 512K build ($066E2: bne.b $66e6) >>
        moveq   #TUNE_HISCORE_TOP,d0            ; 06744
l_06746:
        bsr.w   PlayMusic                       ; 06746  [1MB]   << 1MB only: 1 instruction(s) not in the 512K build >>
        clr.b   g_RedrawPending(a6)             ; 0674A
        bsr.w   RedrawScreen                    ; 0674E
        bsr.w   SwapScreens                     ; 06752
        clr.w   g_ArthurAux(a6)                 ; 06756  no letters yet; initials = spaces
        moveq   #$20,d0                         ; 0675A
        move.b  d0,g_Crouching(a6)              ; 0675C
        move.b  d0,g_Jumping(a6)                ; 06760
        move.b  d0,g_Falling(a6)                ; 06764
        move.w  #$c,g_ArthurX(a6)               ; 06768  cursor on END
        move.w  #$4,g_ArthurY(a6)               ; 0676E
        moveq   #$40,d5                         ; 06774
        bsr.w   DrawNameGrid                    ; 06776
        bsr.w   SetBitplanePtrs                 ; 0677A
        bsr.w   ShowBackBuffer                  ; 0677E
        addq.b  #$1,g_SubState3(a6)             ; 06782
        bra.w   LogicExit                       ; 06786
l_0678A:
        subq.b  #$1,g_StateTimer(a6)            ; 0678A  200 frames after the name
        bne.w   LogicExit                       ; 0678E
        addq.b  #$1,g_SubState2(a6)             ; 06792
        bra.w   LogicExit                       ; 06796
l_0679A:
        clr.b   g_GameState(a6)                 ; 0679A  -> InPlay: next player or attract mode
        move.b  #SS_INPLAY,g_SubState(a6)       ; 0679E
        clr.b   g_SubState2(a6)                 ; 067A4
        clr.b   g_SubState3(a6)                 ; 067A8
        bra.w   LogicExit                       ; 067AC

;---------------------------------------------------------------------------
; Sub state 2 - the normal 'playing' state. Each frame:
;   no death and no finished level -> PlayFrame
;   level finished (g_LevelDone)   -> sub state 0, load the next level
;   Arthur died (g_PlayerDied):
;     two players and the other one still has lives -> SwapPlayers; reload the level
;       if the other player is on a different one, else straight to sub state 1
;     else lives left -> sub state 1 (progress map, set-up) on the same level
;     else -> attract mode (g_GameState 1)
;---------------------------------------------------------------------------
InPlay:
        tst.b   g_PlayerDied(a6)                ; 067B0
        beq.b   l_0681C                         ; 067B4
        tst.b   g_TwoPlayer(a6)                 ; 067B6  2 players: does the other player have lives left?
        beq.b   l_067CC                         ; 067BA
        lea.l   (GLOBALS_P2).l,a0               ; 067BC
        adda.l  g_BaseAddr(a6),a0               ; 067C2  [1MB]   << 1MB only: 1 instruction(s) not in the 512K build >>
        tst.b   $aa(a0)                         ; 067C6
        bne.b   l_067EC                         ; 067CA
l_067CC:
        tst.b   g_Lives(a6)                     ; 067CC  no lives: back to the attract screens
        bne.b   l_0680A                         ; 067D0
        move.b  #GS_TITLE,g_GameState(a6)       ; 067D2
        clr.b   g_SubState(a6)                  ; 067D8
        clr.b   g_SubState2(a6)                 ; 067DC
        clr.b   g_SubState3(a6)                 ; 067E0
        st.b    g_RedrawPending(a6)             ; 067E4
        bra.w   LogicExit                       ; 067E8
l_067EC:
        bsr.w   SwapPlayers                     ; 067EC  switch to the other player
        clr.b   g_SubState(a6)                  ; 067F0
        lea.l   (GLOBALS_P2).l,a0               ; 067F4
        adda.l  g_BaseAddr(a6),a0               ; 067FA  [1MB]   << 1MB only: 1 instruction(s) not in the 512K build >>
        move.w  $9e(a0),d0                      ; 067FE
        cmp.w   g_Level(a6),d0                  ; 06802
        bne.w   LogicExit                       ; 06806
l_0680A:
        move.b  #SS_PLAYLEVEL,g_SubState(a6)    ; 0680A  progress map and level set-up
        clr.b   g_SubState2(a6)                 ; 06810
        clr.b   g_SubState3(a6)                 ; 06814
        bra.w   LogicExit                       ; 06818
l_0681C:
        tst.b   g_LevelDone(a6)                 ; 0681C  normal frame: no level change pending
        beq.w   PlayFrame                       ; 06820
        clr.b   g_LevelDone(a6)                 ; 06824  level finished: load the next one (g_Level already advanced)
        clr.b   g_SubState(a6)                  ; 06828
        bra.w   LogicExit                       ; 0682C

;---------------------------------------------------------------------------
; 21 words: byte size of each BOB graphics set (see BobSetOffsets)
;---------------------------------------------------------------------------
BobSetSizes:
	dc.b	$10,$E0,$08,$98,$11,$80,$04,$60,$10,$D6,$3F,$C0,$2F,$3A,$0B,$E0
	dc.b	$3B,$88,$06,$D6,$20,$58,$15,$2C,$13,$92,$50,$00,$08,$52,$07,$94
	dc.b	$00,$00,$0B,$68,$0D,$C0,$08,$20,$08,$98
SmallBobSetSizes:
	dc.b	$00,$82,$00,$96,$01,$40,$01,$40,$01,$90,$01,$90,$01,$90,$01,$A4
	dc.b	$01,$A4,$01,$90

;---------------------------------------------------------------------------
; Per-level long bitmask of the BOB sets LoadLevel copies out of the big
; graphics file (only the enemies used on that level are kept in memory).
;---------------------------------------------------------------------------
LevelBobSetMask:
	dc.b	$00,$02,$89,$EB,$00,$12,$05,$36,$00,$0C,$18,$B1,$00,$00,$50,$24
	dc.b	$00,$08,$06,$65,$00,$00,$17,$61,$00,$00,$A0,$00
LevelSmallBobMask:
	dc.b	$00,$EB,$02,$07,$00,$13,$01,$03,$01,$01,$00,$02,$00,$01

;---------------------------------------------------------------------------
; Sub state 0: load the level (1MB build).
; Only the per-level file is loaded (tracks 84-109): the enemy graphics are already cached,
; so BuildFrameTable points the frame tables into the cache (BobSetOffsetsCached) instead.
;---------------------------------------------------------------------------
LoadLevel:
        lea.l   LevelFileIndex(pc),a1           ; 06898  [1MB]   << changed from the 512K build ($0682C: lea.l $7fa6(pc), a1) >>
        move.w  g_Level(a6),d0                  ; 0689C  << 512K build has 5 more instruction(s) here (at $06830), removed in the 1MB build >>
        add.w   d0,d0                           ; 068A0
        adda.w  d0,a1                           ; 068A2
        adda.w  (a1),a1                         ; 068A4
        bsr.w   LoadFile                        ; 068A6  load per-level file (tracks 84-109)
        move.l  a5,g_LevelFileEnd(a6)           ; 068AA
        move.w  g_Level(a6),d0                  ; 068AE
        lsl.w   #$2,d0                          ; 068B2
        move.l  LevelBobSetMask(pc,d0.w),d0     ; 068B4
        lea.l   g_BobSets(a6),a0                ; 068B8
        movea.l g_LevelFileEnd(a6),a2           ; 068BC
        lea.l   BobSetSizes(pc),a3              ; 068C0
        lea.l   BobSetOffsetsCached(pc),a4      ; 068C4  [1MB]   << changed from the 512K build ($0686E: lea.l $53aa(pc), a4) >>
        lea.l   (ENEMY_GFX_CACHE).l,a5          ; 068C8
        adda.l  g_BaseAddr(a6),a5               ; 068CE  [1MB]   << 1MB only: 1 instruction(s) not in the 512K build >>
        moveq   #$14,d7                         ; 068D2
        bsr.w   BuildFrameTable                 ; 068D4
        move.w  g_Level(a6),d0                  ; 068D8
        add.w   d0,d0                           ; 068DC
        move.w  LevelSmallBobMask(pc,d0.w),d0   ; 068DE
        lea.l   g_SmallBobSets(a6),a0           ; 068E2
        lea.l   SmallBobSetSizes(pc),a3         ; 068E6
        lea.l   SmallBobSetOffsets(pc),a4       ; 068EA
        lea.l   (BOB_GFX_A).l,a5                ; 068EE
        adda.l  g_BaseAddr(a6),a5               ; 068F4  [1MB]   << 1MB only: 1 instruction(s) not in the 512K build >>
        moveq   #$9,d7                          ; 068F8
        bsr.w   BuildFrameTable                 ; 068FA
        clr.b   g_LevelDone(a6)                 ; 068FE
        addq.b  #SS_PLAYLEVEL,g_SubState(a6)    ; 06902
        clr.b   g_SubState2(a6)                 ; 06906
        clr.b   g_SubState3(a6)                 ; 0690A
        tst.b   g_ShowIntro(a6)                 ; 0690E  first level of a game: skip the progress map (the opening scene comes instead)
        beq.w   LogicExit                       ; 06912
