        adda.w  (a1),a1                         ; 06B34
        lea.l   g_Items(a6),a2                  ; 06B36
        lea.l   EnemyBoxClass(pc),a3            ; 06B3A
        move.w  (a1)+,d7                        ; 06B3E
        subq.w  #$1,d7                          ; 06B40
l_06B42:
