        clr.w   d1                              ; 06B44
        move.b  (a1)+,d1                        ; 06B46
        move.b  d1,$1a(a2)                      ; 06B48
        clr.b   $1b(a2)                         ; 06B4C
        cmp.b   #$1,d1                          ; 06B50  type 1 (shootable scenery): 15 hits (the Magician appears)
        bne.b   l_06B5C                         ; 06B54
        move.b  #$f,$1b(a2)                     ; 06B56
l_06B5C:
