        move.b  (a1)+,$2(a2)                    ; 06B62
        move.w  (a1)+,d1                        ; 06B66  world position -> level coordinates
        sub.w   g_LevelOriginX(a6),d1           ; 06B68
        move.w  d1,$6(a2)                       ; 06B6C
        move.w  (a1)+,d1                        ; 06B70
        sub.w   g_LevelOriginY(a6),d1           ; 06B72
        move.w  d1,$a(a2)                       ; 06B76
        clr.b   $18(a2)                         ; 06B7A
        clr.b   $3(a2)                          ; 06B7E
        clr.b   $4(a2)                          ; 06B82
        clr.b   $5(a2)                          ; 06B86
        lea.l   $1c(a2),a2                      ; 06B8A
        dbra    d7,l_06B42                      ; 06B8E
        lea.l   LevelEnemyLists(pc),a1          ; 06B92  place the enemies of LevelEnemyLists
        move.w  g_Level(a6),d0                  ; 06B96
        add.w   d0,d0                           ; 06B9A
        adda.w  d0,a1                           ; 06B9C
        adda.w  (a1),a1                         ; 06B9E
        lea.l   g_Enemies(a6),a2                ; 06BA0
        move.w  (a1)+,d7                        ; 06BA4
        subq.w  #$1,d7                          ; 06BA6
l_06BA8:
