        clr.b   $1(a2)                          ; 06BAC
        move.b  (a1)+,$1a(a2)                   ; 06BB0
        move.b  (a1)+,$2(a2)                    ; 06BB4
        move.w  (a1)+,d1                        ; 06BB8
        sub.w   g_LevelOriginX(a6),d1           ; 06BBA
        move.w  d1,$6(a2)                       ; 06BBE
        move.w  (a1)+,d1                        ; 06BC2
        sub.w   g_LevelOriginY(a6),d1           ; 06BC4
