LogicExit:
        movem.l (a7)+,d0-d7/a0-a5               ; 06C50
        rte                                     ; 06C54

;---------------------------------------------------------------------------
; world X of the half-way checkpoint per level
;---------------------------------------------------------------------------
LevelCheckpointX:
	dc.w	$0700,$0400,$0400,$0500,$1A00,$1D00,$1F00	; levels 0-6

;---------------------------------------------------------------------------
; LevelMusic - tune number per level. Only the 1MB build uses it: there it is
; passed to PlayMusic (player command 1). In this 512K build the lookup
; is still done but the call was removed, so there is no in-game music.
;---------------------------------------------------------------------------
LevelMusic:
	dc.b	2,2,13,13,13,12,12,0	; levels 0-6 (1MB tune numbers), pad
l_06C6C:
        moveq   #$0,d0                          ; 06C6C  PlayLevel step 2: the level tune (1MB build only), then play (sub state 2)
        move.w  g_Level(a6),d0                  ; 06C6E
        move.b  LevelMusic(pc,d0.w),d0          ; 06C72
        bsr.w   PlayMusic                       ; 06C76  [1MB]   << 1MB only: 1 instruction(s) not in the 512K build >>
        move.b  #SS_INPLAY,g_SubState(a6)       ; 06C7A
        bra.b   LogicExit                       ; 06C80

;---------------------------------------------------------------------------
; ==================================================================
; PlayFrame - one frame of play (sub state 2):
;  1 Esc: abandon the game (attract mode). Space: pause until fire is pressed.
;  2 ArthurUpdate; then either the boss-key sequence (g_KeyState: 'TAKE A KEY FOR COMING
;    IN !' for 36 frames, then EndOfLevelKey - enemies and shots are frozen from here on)
;    or all the objects and their collisions, the map zone and the spawners.
;  3 Level timer: one 'second' every 64 frames (BCD minutes:seconds in g_TimeLeft).
;    At 0:00 Arthur dies; at 0:15 the 1MB build plays a warning tune. Passing
;    LevelCheckpointX sets g_Checkpoint and resets the time to LevelTimeCheckpoint.
;  4 Every 8 frames the extra-life check; the HUD score when it changed.
;  5 Camera (see below), falling off the bottom of the map (death), then - on every
;    second frame only - the vertical camera, the redraw decisions and the drawing:
;    RestoreBackground, DrawBobs, Arthur's sprite, bitplane pointers, show the buffer.
;    So the screen is updated at 25 frames a second while the logic runs at up to 50.
;  6 Death: a life is lost (not with the cheat); none left -> sub state 3 (game over).
;  7 g_GameFrame++.
; Camera. The playfield is a buffer drawn around a tile origin (g_ScrollTileX/Y) and
; scrolled by up to 16 px either way (g_ScrollFineX/Y). The camera aims at Arthur - $80
; in X (clamped to g_CamMinX..g_LevelWidth) and, vertically, Arthur - $8E (his take-off
; height while jumping, so jumps do not scroll). Measured in the emulator: upwards it
; moves at most 2 px per camera step (4 while falling); downwards it moves to the target
; minus (distance - 2), overshooting by the distance less 2 px - probably a sign slip. When
; Arthur falls the view alternates between on target and up to 8 px past it.
; Scrolling works by full redraws: the buffer is redrawn around a new tile origin (outside
; the interrupts) and then switched to, while the fine scroll covers up to 16 px either way
; (rules below, at $6EF2). If the camera would need more than that before the next redraw
; is ready, g_SkipLogic stops the game logic until RedrawEntry clears it.
; Scrolling back is limited: levels 0, 1 and 3 keep the camera within 256 px of the
; furthest point reached (g_CamMinX); levels 4-6 (climbing) within 512 px vertically
; (g_CamMinY); level 2 has no limit.
; ==================================================================
;---------------------------------------------------------------------------
PlayFrame:
        cmpi.b  #$45,g_RawKey(a6)               ; 06C82  Esc = abort game
        bne.b   l_06CD0                         ; 06C88
        moveq   #TUNE_GAME_OVER,d0              ; 06C8A
        bsr.w   PlayMusic                       ; 06C8C  [1MB]   << 1MB only: 1 instruction(s) not in the 512K build >>
        clr.w   g_RawKey(a6)                    ; 06C90
        move.b  #GS_TITLE,g_GameState(a6)       ; 06C94  back to the attract screens, redrawing at the current camera position
        clr.b   g_SubState(a6)                  ; 06C9A
        clr.b   g_SubState2(a6)                 ; 06C9E
        clr.b   g_SubState3(a6)                 ; 06CA2
        move.w  g_ScrollFineX(a6),d0            ; 06CA6
        asr.w   #$4,d0                          ; 06CAA
        add.w   g_ScrollTileX(a6),d0            ; 06CAC
        move.w  d0,g_NewTileX(a6)               ; 06CB0
        clr.w   g_ScrollFineX(a6)               ; 06CB4
        move.w  g_ScrollFineY(a6),d0            ; 06CB8
        asr.w   #$4,d0                          ; 06CBC
        add.w   g_ScrollTileY(a6),d0            ; 06CBE
        move.w  d0,g_NewTileY(a6)               ; 06CC2
        clr.w   g_ScrollFineY(a6)               ; 06CC6
        st.b    g_RedrawPending(a6)             ; 06CCA
        bra.b   LogicExit                       ; 06CCE
l_06CD0:
        tst.b   g_Paused(a6)                    ; 06CD0  paused: wait for fire
        beq.b   l_06CEA                         ; 06CD4
        btst    #$7,$bfe001.l                   ; 06CD6
        bne.w   LogicExit                       ; 06CDE
        clr.w   g_RawKey(a6)                    ; 06CE2
        clr.b   g_Paused(a6)                    ; 06CE6
l_06CEA:
        cmpi.b  #$20,g_AsciiKey(a6)             ; 06CEA  Space = pause
        bne.b   l_06CFA                         ; 06CF0
        st.b    g_Paused(a6)                    ; 06CF2
        bra.w   LogicExit                       ; 06CF6
l_06CFA:
        bsr.w   ArthurUpdate                    ; 06CFA  Arthur control / state machine
        lea.l   g_SaveBufA(a6),a0               ; 06CFE  start a new draw list
        move.l  a0,g_BlitListPtr(a6)            ; 06D02
        tst.b   g_KeyState(a6)                  ; 06D06  boss beaten? (g_KeyState < 0: message, > 0: the key)
        beq.b   l_06D42                         ; 06D0A
        bpl.b   l_06D3C                         ; 06D0C
        subq.b  #$1,g_StateTimer(a6)            ; 06D0E
        bne.b   l_06D18                         ; 06D12
        neg.b   g_KeyState(a6)                  ; 06D14
l_06D18:
        move.b  #$1f,g_TextShadow(a6)           ; 06D18  'TAKE A KEY FOR COMING IN !' for 36 frames
        move.b  #$18,g_TextInk(a6)              ; 06D1E
        move.b  #$19,g_TextPaper(a6)            ; 06D24
        lea.l   TxtTakeKey(pc),a3               ; 06D2A
        moveq   #$3,d1                          ; 06D2E
        move.w  #$88,d2                         ; 06D30
        bsr.w   PrintString                     ; 06D34
        bra.w   l_0719A                         ; 06D38
l_06D3C:
        bsr.w   EndOfLevelKey                   ; 06D3C  only the key moves now
        bra.b   l_06D6E                         ; 06D40
l_06D42:
        bsr.w   UpdateSpecialObjs               ; 06D42  bonus prizes and cut-scene objects
        bsr.w   UpdateShots                     ; 06D46  Arthur weapon shots
        bsr.w   UpdateEnemyShots                ; 06D4A  enemy projectiles
        bsr.w   UpdateEnemies                   ; 06D4E  enemies
        bsr.w   UpdateItems                     ; 06D52  items (moving platforms, triggers, scenery)
        bsr.w   EnemyVsArthur                   ; 06D56  enemies vs Arthur
        bsr.w   ShotsVsScenery                  ; 06D5A  shots vs shootable scenery (gravestones)
