        move.w  g_ScrollTileX(a6),d0            ; 07130
        move.w  g_ScrollTileY(a6),d1            ; 07134
        move.w  g_CamDeltaY(a6),d2              ; 07138
        moveq   #$7,d4                          ; 0713C
        cmp.w   d4,d2                           ; 0713E
        ble.b   l_0714C                         ; 07140
        move.w  d2,d4                           ; 07142
        asr.w   #$4,d4                          ; 07144
        add.w   d4,d1                           ; 07146
        addq.w  #$1,d1                          ; 07148
        bra.b   l_07160                         ; 0714A
l_0714C:
        moveq   #-8,d4                          ; 0714C
        tst.b   g_Falling(a6)                   ; 0714E  falling: any downward offset
        beq.b   l_07156                         ; 07152
        moveq   #$0,d4                          ; 07154
l_07156:
        cmp.w   d4,d2                           ; 07156
        bge.b   l_07160                         ; 07158
        move.w  d2,d4                           ; 0715A
        asr.w   #$4,d4                          ; 0715C
        add.w   d4,d1                           ; 0715E
l_07160:
        cmp.w   g_ScrollTileY(a6),d1            ; 07160
        sne.b   d4                              ; 07164
        move.w  g_CamDeltaX(a6),d2              ; 07166
        cmp.w   #$7,d2                          ; 0716A
        ble.b   l_07174                         ; 0716E
        addq.w  #$1,d0                          ; 07170
        bra.b   l_07180                         ; 07172
l_07174:
        move.w  g_CamDeltaX(a6),d2              ; 07174
        cmp.w   #$fff8,d2                       ; 07178
        bge.b   l_07180                         ; 0717C
        subq.w  #$1,d0                          ; 0717E
l_07180:
        cmp.w   g_ScrollTileX(a6),d0            ; 07180
        sne.b   d3                              ; 07184
        or.b    d3,d4                           ; 07186
        beq.b   l_0719A                         ; 07188
l_0718A:
        move.w  d0,g_NewTileX(a6)               ; 0718A  request a redraw at the new origin (RedrawEntry, outside the interrupts)
        move.w  d1,g_NewTileY(a6)               ; 0718E
