        lsl.w   #$4,d0                          ; 0719E
        add.w   g_ScrollFineX(a6),d0            ; 071A0
        move.w  d0,g_CameraX(a6)                ; 071A4
        move.w  g_ScrollTileY(a6),d1            ; 071A8
        lsl.w   #$4,d1                          ; 071AC
        add.w   g_ScrollFineY(a6),d1            ; 071AE
        move.w  d1,g_CameraY(a6)                ; 071B2
        move.w  g_Level(a6),d2                  ; 071B6  scrolling-back limit (none on level 2)
        cmpi.w  #$2,g_Level(a6)                 ; 071BA
        beq.b   l_071E6                         ; 071C0
        cmp.w   #$4,d2                          ; 071C2
        bcc.b   l_071D8                         ; 071C6
        subi.w  #$100,d0                        ; 071C8  levels 0, 1, 3: at most 256 px back from the furthest point
        cmp.w   g_CamMinX(a6),d0                ; 071CC
        ble.b   l_071D8                         ; 071D0
        move.w  d0,g_CamMinX(a6)                ; 071D2
        bra.b   l_071E6                         ; 071D6
l_071D8:
