;---------------------------------------------------------------------------
; ==================================================================
; Ending - sub state 6, entered when Astaroth is beaten with the cross (BossKilled).
; Steps (g_SubState2):
;  0 Arthur (armour on) faces right at Y $4E; the princess (type 15, g_Enemy1) starts at
;    X $F3. They meet a third of the way from Arthur: g_ArthurAux = his stop X, the
;    princess stops 16 px to its right.
;  1 both walk towards each other at 1.125 px/frame; Arthur raises his arms (frame 41)
;    when he arrives.
;  2 the princess takes frame 5 (size 3); hold for 550 frames.
;  3 'CONGRATULATIONS !' / 'THIS STORY HAS A HAPPY ENDING.'; when the timer runs out,
;    award 50000 (AddScore 21), print the score, and end the game: no lives left,
;    sub state 3 (game over and high-score entry).
; ===================================================================
;---------------------------------------------------------------------------
Ending:
        lea.l   g_Enemy1(a6),a5                 ; 07254
        move.b  g_SubState2(a6),d0              ; 07258
        ext.w   d0                              ; 0725C
        add.w   d0,d0                           ; 0725E
        add.w   d0,d0                           ; 07260
        jmp     Ending_Jumps(pc,d0.w)           ; 07262
Ending_Jumps:
        bra.w   Ending_Setup                    ; 07266
        bra.w   Ending_Walk                     ; 0726A
        bra.w   Ending_Embrace                  ; 0726E
        bra.w   Ending_Message                  ; 07272
Ending_Setup:
        move.w  #$f3,d0                         ; 07276  meet a third of the way from Arthur to the princess
        sub.w   g_ArthurX(a6),d0                ; 0727A
        ext.l   d0                              ; 0727E
        divs.w  #$3,d0                          ; 07280
        add.w   g_ArthurX(a6),d0                ; 07284
        move.w  d0,g_ArthurAux(a6)              ; 07288
        addi.w  #$10,d0                         ; 0728C  the princess stops 16 px to Arthur's right
        move.w  d0,Scn_Target(a5)               ; 07290
        move.w  #$4e,g_ArthurY(a6)              ; 07294
        move.b  #$1,g_ArthurDir(a6)             ; 0729A
        move.b  #$1,g_ArthurFacing(a6)          ; 072A0
        clr.b   g_NoArmour(a6)                  ; 072A6  armour on
        lea.l   ArthurAnims(pc),a1              ; 072AA
        bsr.w   ArthurSetAnim                   ; 072AE
        move.b  #$1,(a5)                        ; 072B2  princess: active, at ($F3,$4E), type 15, size 1
        move.w  #$f3,O_X(a5)                    ; 072B6
        move.w  #$4e,O_Y(a5)                    ; 072BC
        move.b  #E_PRINCESS,O_Type(a5)          ; 072C2
        move.b  #$1,O_Size(a5)                  ; 072C8
        lea.l   Princess_AnimWalk(pc),a0        ; 072CE
        bsr.w   SetAnim                         ; 072D2
        addq.b  #$1,g_SubState2(a6)             ; 072D6
        bra.w   Ending_Draw                     ; 072DA
Ending_Walk:
        move.w  g_ArthurX(a6),d0                ; 072DE
        cmp.w   g_ArthurAux(a6),d0              ; 072E2
        bcc.b   l_072F6                         ; 072E6
        addi.l  #$12000,g_ArthurX(a6)           ; 072E8  Arthur walks right 1.125 px/frame
        bsr.w   ArthurAnimate                   ; 072F0
        bra.b   l_072FC                         ; 072F4
l_072F6:
        move.b  #$29,g_ArthurFrame(a6)          ; 072F6  arrived: arms raised (frame 41)
l_072FC:
        move.w  Scn_Target(a5),d0               ; 072FC
        cmp.w   O_X(a5),d0                      ; 07300
        bcc.b   l_07316                         ; 07304
        subi.l  #$12000,O_X(a5)                 ; 07306  princess walks left 1.125 px/frame
        bsr.w   Animate                         ; 0730E
        bra.w   Ending_Draw                     ; 07312
l_07316:
        addq.b  #$1,g_SubState2(a6)             ; 07316
        bra.b   Ending_Draw                     ; 0731A
Ending_Embrace:
        move.b  #$5,O_Frame(a5)                 ; 0731C  princess frame 5, size 3 - together
        move.b  #$3,O_Size(a5)                  ; 07322
        move.w  #$226,Scn_Target(a5)            ; 07328  550 frames (about 11 seconds)
        addq.b  #$1,g_SubState2(a6)             ; 0732E
        bra.b   Ending_Draw                     ; 07332
Ending_Message:
        move.b  #$1,g_TextInk(a6)               ; 07334  white on the background colour
        move.b  #$18,g_TextPaper(a6)            ; 0733A
        lea.l   TxtCongratulations(pc),a3       ; 07340
        moveq   #$7,d1                          ; 07344
        move.w  #$70,d2                         ; 07346
        bsr.w   PrintString                     ; 0734A
        lea.l   TxtHappyEnding(pc),a3           ; 0734E
        moveq   #$1,d1                          ; 07352
        move.w  #$a0,d2                         ; 07354
        bsr.w   PrintString                     ; 07358
        subq.w  #$1,Scn_Target(a5)              ; 0735C
        bne.b   Ending_Draw                     ; 07360
        moveq   #PTS_50000,d0                   ; 07362
        bsr.w   AddScore                        ; 07364
        moveq   #$1,d1                          ; 07368  print the score in the player's HUD position
        tst.b   g_CurPlayer(a6)                 ; 0736A
        beq.b   l_07372                         ; 0736E
        moveq   #$16,d1                         ; 07370
l_07372:
        moveq   #$8,d2                          ; 07372
        move.l  g_Score(a6),d6                  ; 07374
        bsr.w   PrintBCD                        ; 07378
        st.b    g_PlayerDied(a6)                ; 0737C  game over: lives gone, sub state 3 (high-score table / name entry)
        clr.b   g_Lives(a6)                     ; 07380
        move.b  #SS_GAMEOVER,g_SubState(a6)     ; 07384
        clr.b   g_SubState2(a6)                 ; 0738A
        clr.b   g_SubState3(a6)                 ; 0738E
        bra.w   LogicExit                       ; 07392

;---------------------------------------------------------------------------
; Queue the princess, then the shared scene exit (redraw and show the screen)
;---------------------------------------------------------------------------
Ending_Draw:
        lea.l   g_SaveBufA(a6),a0               ; 07396
        move.l  a0,g_BlitListPtr(a6)            ; 0739A
        bsr.w   QueueEnemyDraw                  ; 0739E
        bra.w   l_06E0E                         ; 073A2

;---------------------------------------------------------------------------
; Princess walking: frames 3, 4
