        move.b  #$d,g_TextInk(a6)               ; 0741C  ink 13 on paper 6
        move.b  #$6,g_TextPaper(a6)             ; 07422
        lea.l   TxtWeaponUseless(pc),a3         ; 07428
        moveq   #$3,d1                          ; 0742C
        move.w  #$58,d2                         ; 0742E
        bsr.w   PrintString                     ; 07432
        move.b  #$1,g_TextInk(a6)               ; 07436
        move.b  #$18,g_TextPaper(a6)            ; 0743C
        lea.l   TxtGetCrucifix(pc),a3           ; 07442
        moveq   #$1,d1                          ; 07446
        move.w  #$68,d2                         ; 07448
        bsr.w   PrintString                     ; 0744C
        subq.b  #$1,g_StateTimer(a6)            ; 07450  g_StateTimer set by BossKilled
        bne.w   l_0719A                         ; 07454
        move.w  #$4,g_Level(a6)                 ; 07458  back to level index 4 (the start of the last two levels)
        clr.b   g_SubState(a6)                  ; 0745E
        clr.b   g_SubState2(a6)                 ; 07462
        clr.b   g_SubState3(a6)                 ; 07466

;---------------------------------------------------------------------------
; ==================================================================
; IntroCutscene - sub state 5, the opening scene (shown once per game: g_ShowIntro).
; Objects: the princess in g_Enemy1 (type 15), the demon in g_Enemies slot 0 (type 6, the
; Satan graphics and animations), and Arthur's armour on the ground in special object 0.
; Steps (g_SubState3):
;   0 Arthur sits with the princess in his underwear (frame 40) at X $60; his armour
;     lies at X $50. Draw both screens; wait 60 frames. (1MB build: tune 14.)
;   1 the demon appears top right ($C5,$A0), the princess changes to frame 0; wait 20 frames.
;   2 the demon flaps for 64 frames,
;   3 then turns to dive (the 1MB build stops the music: tune 0).
;   4 it dives down-left at (-0.33, -6) px/frame until it reaches the floor; it grabs the
;     princess and Arthur is hit (ArthurState 1, pushed left).
;   5 Arthur is knocked back by the normal ArthurUpdate (g_NoArmour is clear, so it takes
;     the 'armour flies off' path; the pieces are never drawn here) while the demon carries the princess up and
;     right at (+1.125, +4.19) until Y $A0, where the princess is removed.
;   6-7 32 frames, then the demon is removed.
;   8 Arthur walks to his armour at X $50 and puts it on (g_NoArmour cleared),
;   9 walks on to X $60, stands (frame 4) for 30 frames,
;  10 and the game starts: sub state 1, progress map skipped (g_SubState2 = 1).
; ===================================================================
;---------------------------------------------------------------------------
IntroCutscene:
        lea.l   g_Enemies(a6),a5                ; 0746A
        move.b  g_SubState3(a6),d0              ; 0746E
        ext.w   d0                              ; 07472
        add.w   d0,d0                           ; 07474
        add.w   d0,d0                           ; 07476
        jmp     IntroCutscene_Jumps(pc,d0.w)    ; 07478
IntroCutscene_Jumps:
        bra.w   Intro_Setup                     ; 0747C
        bra.w   Intro_DemonAppears              ; 07480
        bra.w   Intro_DemonWait                 ; 07484
        bra.w   Intro_DemonHover                ; 07488
        bra.w   Intro_DemonSwoop                ; 0748C
        bra.w   Intro_Abduction                 ; 07490
        bra.w   Intro_Pause                     ; 07494
        bra.w   Intro_DemonGone                 ; 07498
        bra.w   Intro_WalkToArmour              ; 0749C
        bra.w   Intro_WalkOn                    ; 074A0
        bra.w   Intro_Finish                    ; 074A4
Intro_Setup:
        moveq   #TUNE_INTRO,d0                  ; 074A8
        bsr.w   PlayMusic                       ; 074AA  [1MB]   << 1MB only: 1 instruction(s) not in the 512K build >>
        clr.b   g_NoArmour(a6)                  ; 074AE
        move.w  #$60,g_ArthurX(a6)              ; 074B2  Arthur at ($60,$40), sitting (frame 40), facing right
        move.w  #$40,g_ArthurY(a6)              ; 074B8
        move.b  #$28,g_ArthurFrame(a6)          ; 074BE
        move.b  #$1,g_ArthurDir(a6)             ; 074C4
        move.b  #$1,g_ArthurFacing(a6)          ; 074CA
        clr.b   g_OnLadder(a6)                  ; 074D0
        clr.b   g_OnPlatform(a6)                ; 074D4
        st.b    g_ArthurVisible(a6)             ; 074D8
        clr.b   g_Spr47Visible(a6)              ; 074DC
        move.b  #$3c,g_StateTimer(a6)           ; 074E0  60 frames
        clr.b   (a5)                            ; 074E6  demon slot free for now
        lea.l   $3c(a5),a5                      ; 074E8
        move.b  #$1,(a5)                        ; 074EC  g_Enemy1 = princess: active, on screen, state 1, size 1, type 15, at ($70,$40)
        move.b  #$1,O_OnScreen(a5)              ; 074F0
        move.b  #ST_ACTIVE,O_State(a5)          ; 074F6
        move.b  #$1,O_Size(a5)                  ; 074FC
        move.b  #E_PRINCESS,O_Type(a5)          ; 07502
        move.w  #$70,O_X(a5)                    ; 07508
        move.w  #$40,O_Y(a5)                    ; 0750E
        lea.l   Princess_AnimSit(pc),a0         ; 07514
        bsr.w   SetAnim                         ; 07518
        lea.l   g_SpecialObjs(a6),a5            ; 0751C  special object 0 = the armour on the ground: at ($50,$38), frame 2
        move.b  #$1,(a5)                        ; 07520
        move.b  #$1,O_OnScreen(a5)              ; 07524
        clr.b   O_Size(a5)                      ; 0752A
        move.w  #$50,O_X(a5)                    ; 0752E
        move.w  #$38,O_Y(a5)                    ; 07534
        move.b  #$2,O_Frame(a5)                 ; 0753A
        clr.b   g_RedrawPending(a6)             ; 07540  draw and show both screen buffers before the scene starts
        bsr.w   RedrawScreen                    ; 07544
        bsr.w   SwapScreens                     ; 07548
        bsr.w   ArthurSpritePos                 ; 0754C
        bsr.w   SetBitplanePtrs                 ; 07550
        bsr.w   ShowBackBuffer                  ; 07554
        clr.b   g_RedrawPending(a6)             ; 07558  << 512K build has 1 more instruction(s) here (at $074EC), removed in the 1MB build >>
        bsr.w   RedrawScreen                    ; 0755C
        bsr.w   SwapScreens                     ; 07560
        bsr.w   ArthurSpritePos                 ; 07564
        bsr.w   SetBitplanePtrs                 ; 07568
        bsr.w   ShowBackBuffer                  ; 0756C
        addq.b  #$1,g_SubState3(a6)             ; 07570
        bra.w   Intro_Draw                      ; 07574

