        move.b  #ST_ACTIVE,O_State(a5)          ; 07590
        move.b  #$4,O_Size(a5)                  ; 07596
        move.w  #$c5,O_X(a5)                    ; 0759C
        move.w  #$a0,O_Y(a5)                    ; 075A2
        move.b  #E_SATAN,O_Type(a5)             ; 075A8
        move.b  #$14,Scn_Timer(a5)              ; 075AE  wait 20 frames
        lea.l   Satan_AnimWings(pc),a0          ; 075B4  Satan anim: wings spread
        bsr.w   SetAnim                         ; 075B8
        lea.l   $3c(a5),a5                      ; 075BC
        lea.l   Princess_AnimStand(pc),a0       ; 075C0  princess frame 0
        bsr.w   SetAnim                         ; 075C4
        addq.b  #$1,g_SubState3(a6)             ; 075C8
        bra.w   Intro_Draw                      ; 075CC
Intro_DemonWait:
        subq.b  #$1,Scn_Timer(a5)               ; 075D0
        bne.w   Intro_Draw                      ; 075D4
        lea.l   Satan_AnimFlap(pc),a0           ; 075D8  flap
