        move.b  #$40,Scn_Timer(a5)              ; 075E0  for 64 frames
        addq.b  #$1,g_SubState3(a6)             ; 075E6
        bra.w   Intro_Draw                      ; 075EA
Intro_DemonHover:
        subq.b  #$1,Scn_Timer(a5)               ; 075EE
        beq.b   l_075FC                         ; 075F2
        bsr.w   Animate                         ; 075F4
        bra.w   Intro_Draw                      ; 075F8
l_075FC:
        moveq   #TUNE_START,d0                  ; 075FC
