        addq.b  #$1,g_SubState3(a6)             ; 0760A
        bra.w   Intro_Draw                      ; 0760E
Intro_DemonSwoop:
        addi.l  #$fffac000,O_X(a5)              ; 07612  dive: X -0.33, Y -6 px/frame
