        move.b  #$1,g_ArthurFacing(a6)          ; 07664
        lea.l   ArthurAnims(pc),a1              ; 0766A
        bsr.w   ArthurSetAnim                   ; 0766E
        addq.b  #$1,g_SubState3(a6)             ; 07672
        bra.w   Intro_Draw                      ; 07676
l_0767A:
