        bcc.w   Intro_Draw                      ; 07680
        addi.l  #$12000,O_X(a5)                 ; 07684
        addi.l  #$43000,O_Y(a5)                 ; 0768C
        bsr.w   Animate                         ; 07694
        lea.l   $3c(a5),a5                      ; 07698
        addi.l  #$12000,O_X(a5)                 ; 0769C
        addi.l  #$43000,O_Y(a5)                 ; 076A4
        lea.l   -$3c(a5),a5                     ; 076AC
        cmpi.w  #$a0,O_Y(a5)                    ; 076B0  off the top (Y >= $A0)?
        bcs.w   Intro_Draw                      ; 076B6
        lea.l   Satan_AnimWings(pc),a0          ; 076BA
        bsr.w   SetAnim                         ; 076BE
        lea.l   $3c(a5),a5                      ; 076C2  princess gone
        clr.b   (a5)                            ; 076C6
        bra.w   Intro_Draw                      ; 076C8
Intro_Pause:
