;---------------------------------------------------------------------------
; ==================================================================
; ProgressMap - sub state 1 / g_SubState2 0, before each level (and after a life lost).
;  0 load FileProgressMap and unpack it into the spare screen: 80 lines x 5 planes,
;    each plane line RLE-packed to $2C bytes (n >= 0: copy n+1 bytes; n < 0: repeat the
;    next byte -n+1 times; -128: nothing), with blank borders. Point the map copper list
;    ($1A250) at it, and place a flashing Arthur marker from ProgressMapMarkers.
;  1 scroll the map 144 px to the left, one pixel a frame; the marker stops flashing.
;  2 hold for 100 frames, then on to level set-up (g_SubState2 = 1).
; The 1MB build stops the music and unpacks the copy kept at PROGRESS_MAP_CACHE instead
; of loading the file.
; ===================================================================
;---------------------------------------------------------------------------
ProgressMap:
        cmpi.b  #$1,g_SubState3(a6)             ; 0779E
        beq.w   ProgressMap_Scroll              ; 077A4
        bhi.w   ProgressMap_Wait                ; 077A8
        moveq   #TUNE_START,d0                  ; 077AC  [1MB]   << differs from the 512K build: 1 instruction(s) here replace 1 at $07744 >>
        bsr.w   PlayMusic                       ; 077AE  [1MB]   << changed from the 512K build ($07748: bsr.w $c476) >>
        lea.l   (PROGRESS_MAP_CACHE).l,a0       ; 077B2  [1MB]   << differs from the 512K build: 2 instruction(s) here replace 3 at $0774C >>
        adda.l  g_BaseAddr(a6),a0               ; 077B8  [1MB] 
        movea.l g_ScreenSpare1(a6),a1           ; 077BC
        movea.l g_ScreenSpare2(a6),a2           ; 077C0
        cmpa.l  a1,a2                           ; 077C4
        bhi.b   l_077CA                         ; 077C6
        movea.l a2,a1                           ; 077C8
l_077CA:
        move.l  a1,g_ArthurAnim(a6)             ; 077CA
        move.w  #$1f3f,d7                       ; 077CE  clear $7D00 bytes
l_077D2:
        clr.l   (a1)+                           ; 077D2
        dbra    d7,l_077D2                      ; 077D4
        moveq   #$2c,d5                         ; 077D8  $2C bytes per plane line; 80 lines
        moveq   #$4f,d7                         ; 077DA
l_077DC:
        moveq   #$4,d6                          ; 077DC  5 planes
l_077DE:
        clr.w   d4                              ; 077DE
        clr.l   (a1)+                           ; 077E0  4 blank bytes at the left
l_077E2:
        clr.w   d0                              ; 077E2
        move.b  (a0)+,d0                        ; 077E4
        bmi.b   l_077F2                         ; 077E6  n < 0: run
l_077E8:
        move.b  (a0)+,(a1)+                     ; 077E8  n >= 0: n+1 literal bytes
        addq.w  #$1,d4                          ; 077EA
        dbra    d0,l_077E8                      ; 077EC
        bra.b   l_07800                         ; 077F0
l_077F2:
        neg.b   d0                              ; 077F2  -n+1 copies of the next byte (-128: none)
        bvs.b   l_07800                         ; 077F4
        move.b  (a0)+,d1                        ; 077F6
l_077F8:
        move.b  d1,(a1)+                        ; 077F8
        addq.w  #$1,d4                          ; 077FA
        dbra    d0,l_077F8                      ; 077FC
l_07800:
        cmp.w   d5,d4                           ; 07800
        bcs.b   l_077E2                         ; 07802
        clr.w   (a1)+                           ; 07804  2 blank bytes at the right (line = $32 bytes)
        dbra    d6,l_077DE                      ; 07806
        dbra    d7,l_077DC                      ; 0780A
        move.w  #$3e7,d7                        ; 0780E  blank area below the picture
l_07812:
        clr.l   (a1)+                           ; 07812
        dbra    d7,l_07812                      ; 07814
        bsr.w   SetMapBitplanePtrs              ; 07818
        lea.l   CUSTOM,a0                       ; 0781C
        move.l  #$2e29c,COP2LCH(a0)             ; 07822  [1MB]   << changed from the 512K build ($077BA: move.l #$1a250, $84(a0)) >>
        bsr.w   SwapScreens                     ; 0782A
        move.w  g_Level(a6),d0                  ; 0782E  marker = ProgressMapMarkers[level][checkpoint]
        lsl.w   #$3,d0                          ; 07832
        tst.b   g_Checkpoint(a6)                ; 07834
        beq.b   l_0783C                         ; 07838
        addq.w  #$4,d0                          ; 0783A
l_0783C:
        lea.l   ProgressMapMarkers(pc,d0.w),a1  ; 0783C
        move.w  (a1)+,g_ArthurX(a6)             ; 07840
        move.w  (a1)+,g_ArthurY(a6)             ; 07844
        addq.w  #$8,g_ArthurX(a6)               ; 07848
        subq.w  #$8,g_ArthurY(a6)               ; 0784C
        st.b    g_ArthurVisible(a6)             ; 07850
        clr.b   g_Spr47Visible(a6)              ; 07854
        clr.b   g_ArthurFrame(a6)               ; 07858
        clr.w   g_ScrollFineX(a6)               ; 0785C
        clr.w   g_ScrollFineY(a6)               ; 07860
        clr.w   g_ScrollTileX(a6)               ; 07864
        clr.w   g_ScrollTileY(a6)               ; 07868
        st.b    g_ArthurFlash(a6)               ; 0786C  marker flashes while the map scrolls
        addq.b  #$1,g_SubState3(a6)             ; 07870
        bra.w   LogicExit                       ; 07874

;---------------------------------------------------------------------------
; ProgressMapMarkers - per level, two (x.w, y.w) points on the map: level start and
; checkpoint (used when g_Checkpoint is set). The marker is drawn 8 px right and 8 px
; higher. Levels 4-6 use the same point for both.
;---------------------------------------------------------------------------
ProgressMapMarkers:
	dc.b	$00,$18,$00,$40,$00,$45,$00,$40,$00,$56,$00,$40,$00,$6E,$00,$40
	dc.b	$00,$9F,$00,$40,$00,$B5,$00,$40,$00,$D1,$00,$40,$00,$EC,$00,$40
	dc.b	$01,$19,$00,$40,$01,$19,$00,$40,$01,$35,$00,$50,$01,$35,$00,$50
	dc.b	$01,$35,$00,$63,$01,$35,$00,$63
ProgressMap_Scroll:
        bsr.w   SetMapBitplanePtrs              ; 078B0
        bsr.w   ArthurSpritePos                 ; 078B4
        addq.w  #$1,g_GameFrame(a6)             ; 078B8  drives the marker flash  << 512K build has 1 more instruction(s) here (at $07850), removed in the 1MB build >>
        addq.w  #$1,g_ScrollFineX(a6)           ; 078BC  scroll 1 px a frame up to 144 px
        cmpi.w  #$90,g_ScrollFineX(a6)          ; 078C0
        bne.w   LogicExit                       ; 078C6
        clr.b   g_ArthurFlash(a6)               ; 078CA
        bsr.w   SetMapBitplanePtrs              ; 078CE
        bsr.w   ArthurSpritePos                 ; 078D2
        move.b  #$64,g_StateTimer(a6)           ; 078D6  then hold for 100 frames
        addq.b  #$1,g_SubState3(a6)             ; 078DC
ProgressMap_Wait:
        subq.b  #$1,g_StateTimer(a6)            ; 078E0
        bne.w   LogicExit                       ; 078E4
        clr.w   g_ScrollFineX(a6)               ; 078E8
        clr.b   g_SubState3(a6)                 ; 078EC
        move.b  #$1,g_SubState2(a6)             ; 078F0
        bra.w   LogicExit                       ; 078F6

;---------------------------------------------------------------------------
; Write bitplane pointers + BPLCON1 fine scroll into the back copper list
;---------------------------------------------------------------------------
SetBitplanePtrs:
        move.l  g_ScreenFront(a6),d2            ; 078FA  front screen
        move.w  g_ScrollFineX(a6),d0            ; 078FE  + the scroll in words
        subq.w  #$1,d0                          ; 07902
        asr.w   #$4,d0                          ; 07904
        add.w   d0,d0                           ; 07906
        addq.w  #$2,d0                          ; 07908
        ext.l   d0                              ; 0790A
        add.l   d0,d2                           ; 0790C
        moveq   #$10,d0                         ; 0790E  + (16 - fine Y) lines of 180 bytes
        sub.w   g_ScrollFineY(a6),d0            ; 07910
        mulu.w  #$b4,d0                         ; 07914
        add.l   d0,d2                           ; 07918
        movea.l g_CopperBack(a6),a1             ; 0791A
        moveq   #$24,d0                         ; 0791E  5 planes, 36 bytes apart (line-interleaved)
        addq.l  #$2,a1                          ; 07920
        swap    d2                              ; 07922
        move.w  d2,(a1)+                        ; 07924
        addq.l  #$2,a1                          ; 07926
        swap    d2                              ; 07928
        move.w  d2,(a1)+                        ; 0792A
        add.l   d0,d2                           ; 0792C
        addq.l  #$2,a1                          ; 0792E
        swap    d2                              ; 07930
        move.w  d2,(a1)+                        ; 07932
        addq.l  #$2,a1                          ; 07934
        swap    d2                              ; 07936
        move.w  d2,(a1)+                        ; 07938
        add.l   d0,d2                           ; 0793A
        addq.l  #$2,a1                          ; 0793C
        swap    d2                              ; 0793E
        move.w  d2,(a1)+                        ; 07940
        addq.l  #$2,a1                          ; 07942
        swap    d2                              ; 07944
        move.w  d2,(a1)+                        ; 07946
        add.l   d0,d2                           ; 07948
        addq.l  #$2,a1                          ; 0794A
        swap    d2                              ; 0794C
        move.w  d2,(a1)+                        ; 0794E
        addq.l  #$2,a1                          ; 07950
        swap    d2                              ; 07952
        move.w  d2,(a1)+                        ; 07954
        add.l   d0,d2                           ; 07956
        addq.l  #$2,a1                          ; 07958
        swap    d2                              ; 0795A
        move.w  d2,(a1)+                        ; 0795C
        addq.l  #$2,a1                          ; 0795E
        swap    d2                              ; 07960
        move.w  d2,(a1)+                        ; 07962
        moveq   #$f,d1                          ; 07964
        and.w   g_ScrollFineX(a6),d1            ; 07966
        beq.b   l_07978                         ; 0796A
        moveq   #$10,d0                         ; 0796C
        sub.w   d1,d0                           ; 0796E
        move.w  d0,d1                           ; 07970
        lsl.w   #$4,d1                          ; 07972
        or.w    d1,d0                           ; 07974
        bra.b   l_0797A                         ; 07976
l_07978:
        clr.w   d0                              ; 07978
l_0797A:
        addq.l  #$2,a1                          ; 0797A
        move.w  d0,(a1)+                        ; 0797C
        rts                                     ; 0797E

;---------------------------------------------------------------------------
; Same for the progress-map copper list
;---------------------------------------------------------------------------
SetMapBitplanePtrs:
        move.l  g_ArthurAnim(a6),d2             ; 07980  the unpacked map picture (address kept in g_ArthurAnim)
        move.w  g_ScrollFineX(a6),d0            ; 07984  + the scroll in words
        subq.w  #$1,d0                          ; 07988
        asr.w   #$4,d0                          ; 0798A
        add.w   d0,d0                           ; 0798C
        ext.l   d0                              ; 0798E
        add.l   d0,d2                           ; 07990
        lea.l   (COPPER_MAP).l,a1               ; 07992
        moveq   #$32,d0                         ; 07998  5 planes, $32 bytes apart (one map line is $32 x 5 bytes)
        addq.l  #$2,a1                          ; 0799A
        swap    d2                              ; 0799C
        move.w  d2,(a1)+                        ; 0799E
        addq.l  #$2,a1                          ; 079A0
        swap    d2                              ; 079A2
        move.w  d2,(a1)+                        ; 079A4
        add.l   d0,d2                           ; 079A6
        addq.l  #$2,a1                          ; 079A8
        swap    d2                              ; 079AA
        move.w  d2,(a1)+                        ; 079AC
        addq.l  #$2,a1                          ; 079AE
        swap    d2                              ; 079B0
        move.w  d2,(a1)+                        ; 079B2
        add.l   d0,d2                           ; 079B4
        addq.l  #$2,a1                          ; 079B6
        swap    d2                              ; 079B8
        move.w  d2,(a1)+                        ; 079BA
        addq.l  #$2,a1                          ; 079BC
        swap    d2                              ; 079BE
        move.w  d2,(a1)+                        ; 079C0
        add.l   d0,d2                           ; 079C2
        addq.l  #$2,a1                          ; 079C4
        swap    d2                              ; 079C6
        move.w  d2,(a1)+                        ; 079C8
        addq.l  #$2,a1                          ; 079CA
        swap    d2                              ; 079CC
        move.w  d2,(a1)+                        ; 079CE
        add.l   d0,d2                           ; 079D0
        addq.l  #$2,a1                          ; 079D2
        swap    d2                              ; 079D4
        move.w  d2,(a1)+                        ; 079D6
        addq.l  #$2,a1                          ; 079D8
        swap    d2                              ; 079DA
        move.w  d2,(a1)+                        ; 079DC
        moveq   #$f,d1                          ; 079DE
        and.w   g_ScrollFineX(a6),d1            ; 079E0
        beq.b   l_079F2                         ; 079E4
        moveq   #$10,d0                         ; 079E6
        sub.w   d1,d0                           ; 079E8
        move.w  d0,d1                           ; 079EA
        lsl.w   #$4,d1                          ; 079EC
        or.w    d1,d0                           ; 079EE
        bra.b   l_079F4                         ; 079F0
l_079F2:
        clr.w   d0                              ; 079F2
l_079F4:
