TxtTakeKey:
	dc.b	'TAKE A KEY FOR COMING IN !'
	dc.b	$00,$00

;---------------------------------------------------------------------------
; The key that drops when the boss is beaten (after 'TAKE A KEY FOR COMING IN !').
; Runs instead of the enemies and shots, so everything else on screen freezes. Steps
; (g_SubState2, the key is special object 0):
;  0 wait until Arthur reaches the end of the level (levels 0-3: within 48 px of the
;    right edge; 4-6: above the top), then place the key 37 px past the right edge at
;    KeyDropY[level]; the 1MB build plays tune 5
;  1 30 frames spinning in the air
;  2 fall at 1.24 px/frame until it reaches the floor
;  3 when Arthur is within 8 px: sound 28, 1000 points, sub state 4 (LevelComplete)
;---------------------------------------------------------------------------
EndOfLevelKey:
        lea.l   g_SpecialObjs(a6),a5            ; 07A16
        move.b  g_SubState2(a6),d0              ; 07A1A
        ext.w   d0                              ; 07A1E
        add.w   d0,d0                           ; 07A20
        add.w   d0,d0                           ; 07A22
        jsr     EndOfLevelKey_Jumps(pc,d0.w)    ; 07A24
        tst.b   O_OnScreen(a5)                  ; 07A28
        bne.w   QueueObjectDraw                 ; 07A2C
        rts                                     ; 07A30
EndOfLevelKey_Jumps:
        bra.w   Key_Wait                        ; 07A32
        bra.w   Key_Spin                        ; 07A36
        bra.w   Key_Fall                        ; 07A3A
        bra.w   Key_Take                        ; 07A3E
Key_Wait:
        moveq   #TUNE_BOSS_BEATEN,d0            ; 07A42
        bsr.w   PlayMusic                       ; 07A44  [1MB]   << 1MB only: 1 instruction(s) not in the 512K build >>
        move.b  #$1,(a5)                        ; 07A48
        clr.b   O_OnScreen(a5)                  ; 07A4C
        clr.b   O_State(a5)                     ; 07A50
        clr.b   O_Step(a5)                      ; 07A54
        clr.b   O_Size(a5)                      ; 07A58
        move.b  #$1e,Key_Timer(a5)              ; 07A5C  spin for 30 frames
        cmpi.w  #$4,g_Level(a6)                 ; 07A62  levels 4-6 end at the top
        bcc.b   l_07AA6                         ; 07A68
        moveq   #-48,d0                         ; 07A6A  within 48 px of the right edge?
        add.w   g_LevelWidth(a6),d0             ; 07A6C
        cmp.w   g_ArthurX(a6),d0                ; 07A70
        bhi.b   l_07AA4                         ; 07A74
l_07A76:
        moveq   #$25,d0                         ; 07A76  key: 37 px right of the edge, at KeyDropY
        add.w   g_LevelWidth(a6),d0             ; 07A78
        move.w  d0,O_X(a5)                      ; 07A7C
        move.w  g_Level(a6),d0                  ; 07A80
        add.w   d0,d0                           ; 07A84
        move.w  KeyDropY(pc,d0.w),d0            ; 07A86
        sub.w   g_LevelOriginY(a6),d0           ; 07A8A
        move.w  d0,O_Y(a5)                      ; 07A8E
        lea.l   Key_AnimSpin(pc),a0             ; 07A92
        bsr.w   SetAnim                         ; 07A96
        bsr.w   CheckOnScreen                   ; 07A9A
        moveq   #$3e,d0                         ; 07A9E  [1MB]   << 1MB only: 1 instruction(s) not in the 512K build >>
        addq.b  #$1,g_SubState2(a6)             ; 07AA0
l_07AA4:
        rts                                     ; 07AA4
l_07AA6:
        moveq   #$20,d0                         ; 07AA6  above the top?
        add.w   g_LevelHeight(a6),d0            ; 07AA8
        cmp.w   g_ArthurY(a6),d0                ; 07AAC
        bhi.b   l_07AA4                         ; 07AB0
        bra.b   l_07A76                         ; 07AB2

;---------------------------------------------------------------------------
