;---------------------------------------------------------------------------
; Look up the map zone of the cell under the camera (g_ScrollTileX/Y >> 4, in MapZoneTable). On a change, stop the spawners
; (except those flagged to keep running) and start the zone's list from ZoneSpawners:
; count.b, then per spawner two bytes: hi nibble of byte 1 = enemy type (= spawner slot),
; lo nibble of byte 1 / lo nibble of byte 2 = script number, hi nibble of byte 2 = flags
; (bit 0 world coordinates, bit 1 run once). Types with ZoneFlags = 0 only spawn in a zone
; further on than any reached before (no respawns when walking back).
;---------------------------------------------------------------------------
UpdateMapZone:
        move.w  g_ScrollTileX(a6),d0            ; 07B4C  map cell under the camera: column ...
        asr.w   #$4,d0                          ; 07B50
        bpl.b   l_07B56                         ; 07B52
        clr.w   d0                              ; 07B54
l_07B56:
        move.w  g_ScrollTileY(a6),d1            ; 07B56  ... and row (32 cells a row)
        asr.w   #$4,d1                          ; 07B5A
        asl.w   #$5,d1                          ; 07B5C
        bpl.b   l_07B62                         ; 07B5E
        clr.w   d1                              ; 07B60
l_07B62:
        add.w   d0,d1                           ; 07B62  -> offset into WorldMap -> zone from MapZoneTable
        add.l   g_MapPtr(a6),d1                 ; 07B64
        lea.l   WorldMap(pc),a1                 ; 07B68
        sub.l   a1,d1                           ; 07B6C
        lea.l   MapZoneTable(pc),a1             ; 07B6E
        move.b  (a1,d1.w),d0                    ; 07B72
        cmp.b   g_MapZone(a6),d0                ; 07B76  same zone as last frame: nothing to do
        beq.w   l_07C26                         ; 07B7A
        move.b  d0,g_MapZone(a6)                ; 07B7E
        lea.l   g_Spawners(a6),a5               ; 07B82  zone changed: stop every spawner not flagged to keep running
        moveq   #$f,d7                          ; 07B86
l_07B88:
        btst    #$2,Spn_Flags(a5)               ; 07B88
        bne.b   l_07B92                         ; 07B8E
        clr.b   (a5)                            ; 07B90
l_07B92:
        lea.l   $c(a5),a5                       ; 07B92
        dbra    d7,l_07B88                      ; 07B96
        lea.l   ZoneSpawners(pc),a2             ; 07B9A  the zone's spawner list (ZoneSpawners: byte offset to count + entries)
        ext.w   d0                              ; 07B9E
        adda.w  d0,a2                           ; 07BA0
        move.b  (a2),d0                         ; 07BA2
        adda.w  d0,a2                           ; 07BA4
        move.b  (a2)+,d7                        ; 07BA6
        ext.w   d7                              ; 07BA8
        subq.w  #$1,d7                          ; 07BAA
        bmi.b   l_07C18                         ; 07BAC
l_07BAE:
        clr.w   d1                              ; 07BAE  entry: type (high nibble of byte 1), script number, flags (high nibble of byte 2)
        move.b  (a2)+,d1                        ; 07BB0
        move.b  (a2)+,d2                        ; 07BB2
        move.w  d1,d0                           ; 07BB4
        lsr.w   #$4,d0                          ; 07BB6
        lsl.b   #$4,d1                          ; 07BB8
        moveq   #$f,d3                          ; 07BBA
        and.b   d2,d3                           ; 07BBC
        or.b    d3,d1                           ; 07BBE
        lea.l   SpawnScripts(pc),a1             ; 07BC0  SpawnScripts: per type a byte offset to a word-offset table of scripts
        adda.w  d0,a1                           ; 07BC4
        move.b  (a1),d3                         ; 07BC6
        adda.w  d3,a1                           ; 07BC8
        add.w   d1,d1                           ; 07BCA
        adda.w  d1,a1                           ; 07BCC
        adda.w  (a1),a1                         ; 07BCE
        move.w  (a1),d6                         ; 07BD0  empty script: skip
        beq.b   l_07C14                         ; 07BD2
        move.w  d0,d1                           ; 07BD4  start the spawner of this type: active, first spawn in 10 frames,
        mulu.w  #$c,d1                          ; 07BD6
        lea.l   g_Spawners(a6),a0               ; 07BDA
        adda.w  d1,a0                           ; 07BDE
        st.b    (a0)                            ; 07BE0
        move.b  #$a,$a(a0)                      ; 07BE2
        move.l  a1,$6(a0)                       ; 07BE8  script start and position, entries left, flags
        addq.l  #$2,a1                          ; 07BEC
        move.l  a1,$2(a0)                       ; 07BEE
        move.b  d6,$1(a0)                       ; 07BF2
        lsr.b   #$4,d2                          ; 07BF6
        move.b  d2,$b(a0)                       ; 07BF8
        lea.l   ZoneFlags(pc,d0.w),a1           ; 07BFC  types with ZoneFlags = 0 (bosses, Red Arremer, Big Man) keep running and only
        tst.b   (a1)                            ; 07C00
        bne.b   l_07C14                         ; 07C02
        bset    #$2,$b(a0)                      ; 07C04  start in a zone beyond any reached before
        move.b  g_MapZone(a6),d0                ; 07C0A
        cmp.b   g_MaxMapZone(a6),d0             ; 07C0E
        sgt.b   (a0)                            ; 07C12
l_07C14:
        dbra    d7,l_07BAE                      ; 07C14
l_07C18:
        move.b  g_MapZone(a6),d0                ; 07C18
        cmp.b   g_MaxMapZone(a6),d0             ; 07C1C
        ble.b   l_07C26                         ; 07C20
        move.b  d0,g_MaxMapZone(a6)             ; 07C22
l_07C26:
        rts                                     ; 07C26
ZoneFlags:
	dc.b	$01,$01,$01,$01,$01,$00,$00,$01,$00,$01,$00,$01,$00,$00,$01,$01

