	dc.b	$02,$82,$42,$C2,$22,$A2,$62,$E2,$12,$92,$52,$D2,$32,$B2,$72,$F2
	dc.b	$0A,$8A,$4A,$CA,$2A,$AA,$6A,$EA,$1A,$9A,$5A,$DA,$3A,$BA,$7A,$FA
	dc.b	$06,$86,$46,$C6,$26,$A6,$66,$E6,$16,$96,$56,$D6,$36,$B6,$76,$F6
	dc.b	$0E,$8E,$4E,$CE,$2E,$AE,$6E,$EE,$1E,$9E,$5E,$DE,$3E,$BE,$7E,$FE
	dc.b	$01,$81,$41,$C1,$21,$A1,$61,$E1,$11,$91,$51,$D1,$31,$B1,$71,$F1
	dc.b	$09,$89,$49,$C9,$29,$A9,$69,$E9,$19,$99,$59,$D9,$39,$B9,$79,$F9
	dc.b	$05,$85,$45,$C5,$25,$A5,$65,$E5,$15,$95,$55,$D5,$35,$B5,$75,$F5
	dc.b	$0D,$8D,$4D,$CD,$2D,$AD,$6D,$ED,$1D,$9D,$5D,$DD,$3D,$BD,$7D,$FD
	dc.b	$03,$83,$43,$C3,$23,$A3,$63,$E3,$13,$93,$53,$D3,$33,$B3,$73,$F3
	dc.b	$0B,$8B,$4B,$CB,$2B,$AB,$6B,$EB,$1B,$9B,$5B,$DB,$3B,$BB,$7B,$FB
	dc.b	$07,$87,$47,$C7,$27,$A7,$67,$E7,$17,$97,$57,$D7,$37,$B7,$77,$F7
	dc.b	$0F,$8F,$4F,$CF,$2F,$AF,$6F,$EF,$1F,$9F,$5F,$DF,$3F,$BF,$7F,$FF
ClearHudArea:
        lea.l   (CLEAR_AREA).l,a0               ; 07D38
        move.w  #$2cf,d7                        ; 07D3E
l_07D42:
        clr.l   (a0)+                           ; 07D42
        dbra    d7,l_07D42                      ; 07D44
        rts                                     ; 07D48

;---------------------------------------------------------------------------
; Display, audio and interrupt set-up:
;  BPLCON0 $5200 (5 planes), DDF $40-$C0, DIW $34A1-$24A1, modulos $92
;  all audio channels silent, vector $60 = MUSIC_PLAYER
;  CIA-A: serial (keyboard) interrupt only
;  vectors: $64 L1 = Level1Logic, $68 L2 = KeyboardIRQ, $6C L3 = VblIRQ
;  INTENA = SOFTINT|PORTS|VERTB, waits for line $12C before returning
;---------------------------------------------------------------------------
InitHardware:
        lea.l   CUSTOM,a0                       ; 07D4A
        move.w  #DMAF_MASTER,DMACON(a0)         ; 07D50  bitplane DMA off while setting up
        move.w  #$5200,BPLCON0(a0)              ; 07D56  5 bitplanes, lores
        move.w  #$0,BPLCON1(a0)                 ; 07D5C
        move.w  #$24,BPLCON2(a0)                ; 07D62
        move.w  #$92,BPL1MOD(a0)                ; 07D68  modulo 146: 180-byte interleaved lines, 34 bytes fetched
        move.w  #$92,BPL2MOD(a0)                ; 07D6E
        move.w  #$40,DDFSTRT(a0)                ; 07D74  fetch 17 words (272 px: one more than shown, for the scroll)
        move.w  #$c0,DDFSTOP(a0)                ; 07D7A
        move.w  #$34a1,DIWSTRT(a0)              ; 07D80  display window: 240 lines from line 52, 256 px wide
        move.w  #$24a1,DIWSTOP(a0)              ; 07D86
        moveq   #$7f,d0                         ; 07D8C  audio: silent, period 1
        move.w  d0,AUD0LEN(a0)                  ; 07D8E
        move.w  d0,AUD1LEN(a0)                  ; 07D92
        move.w  d0,AUD2LEN(a0)                  ; 07D96
        move.w  d0,AUD3LEN(a0)                  ; 07D9A
        moveq   #$1,d0                          ; 07D9E
        move.w  d0,AUD0PER(a0)                  ; 07DA0
        move.w  d0,AUD1PER(a0)                  ; 07DA4
        move.w  d0,AUD2PER(a0)                  ; 07DA8
        move.w  d0,AUD3PER(a0)                  ; 07DAC
        moveq   #$0,d0                          ; 07DB0
        move.w  d0,AUD0VOL(a0)                  ; 07DB2
        move.w  d0,AUD1VOL(a0)                  ; 07DB6
        move.w  d0,AUD2VOL(a0)                  ; 07DBA
        move.w  d0,AUD3VOL(a0)                  ; 07DBE
        move.w  #$ff,ADKCON(a0)                 ; 07DC2  << 512K build has 2 more instruction(s) here (at $07D62), removed in the 1MB build >>
        move.w  #DMAF_SETCLR|DMAF_AUD3|DMAF_AUD2|DMAF_AUD1|DMAF_AUD0,DMACON(a0); 07DC8
        lea.l   $bfe001.l,a1                    ; 07DCE
        move.b  #$7f,$d00(a1)                   ; 07DD4  CIA-A: all interrupts off, then the keyboard (SP) on
        move.b  #$88,$d00(a1)                   ; 07DDA
        andi.b  #$80,$e00(a1)                   ; 07DE0  CIA-A CRA: keep only bit 7
        move.w  #$aaaa,g_RandSeed(a6)           ; 07DE6
        clr.w   g_FrameStamp(a6)                ; 07DEC
        clr.w   g_VblCount(a6)                  ; 07DF0
        clr.w   g_GameFrame(a6)                 ; 07DF4
        clr.b   g_ArthurVisible(a6)             ; 07DF8
        clr.b   g_Spr47Visible(a6)              ; 07DFC
        clr.b   g_RedrawPending(a6)             ; 07E00
        st.b    g_SkipLogic(a6)                 ; 07E04
        move.l  g_CopperFront(a6),COP2LCH(a0)   ; 07E08  copper: COP1 = the init list at COPPER_INIT, COP2 = the front list
        move.l  #$2e164,COP1LCH(a0)             ; 07E0E  [1MB]   << changed from the 512K build ($07DB8: move.l #$1a118, $80(a0)) >>
        move.w  COPJMP1(a0),d0                  ; 07E16
        move.w  #INTF_INTEN|INTF_EXTER|INTF_DSKSYNC|INTF_RBF|INTF_AUD3|INTF_AUD2|INTF_AUD1|INTF_AUD0|INTF_BLIT|INTF_VERTB|INTF_COPER|INTF_PORTS|INTF_SOFTINT|INTF_DSKBLK|INTF_TBE,INTENA(a0); 07E1A  all interrupts off before installing the vectors
        lea.l   Level1Logic(pc),a1              ; 07E20  level 1 autovector
        move.l  a1,(VEC_LEVEL1).w               ; 07E24
        lea.l   KeyboardIRQ(pc),a1              ; 07E28  level 2 autovector
        move.l  a1,(VEC_LEVEL2).w               ; 07E2C
        lea.l   VblIRQ(pc),a1                   ; 07E30  level 3 autovector
        move.l  a1,(VEC_LEVEL3).w               ; 07E34
        clr.l   $2e160.l                        ; 07E38  clear the long before COPPER_INIT
        move.w  #DMAF_SETCLR|DMAF_BLITHOG|DMAF_MASTER|DMAF_RASTER|DMAF_COPPER|DMAF_BLITTER|DMAF_SPRITE|DMAF_DISK,DMACON(a0); 07E3E  DMA on: blitter priority, master, bitplanes, copper, blitter, sprites, disk
        move.w  #INTF_INTEN|INTF_EXTER|INTF_DSKSYNC|INTF_RBF|INTF_AUD3|INTF_AUD2|INTF_AUD1|INTF_AUD0|INTF_BLIT|INTF_VERTB|INTF_COPER|INTF_PORTS|INTF_SOFTINT|INTF_DSKBLK|INTF_TBE,INTREQ(a0); 07E44
        move.w  #INTF_SETCLR|INTF_INTEN|INTF_VERTB|INTF_PORTS|INTF_SOFTINT,INTENA(a0); 07E4A  INTENA = SET|INTEN|VERTB|PORTS|SOFTINT
l_07E50:
        move.l  VPOSR(a0),d0                    ; 07E50  wait for raster line 300
        andi.l  #$1ffff,d0                      ; 07E54
        cmp.l   #$12c00,d0                      ; 07E5A
        bcs.b   l_07E50                         ; 07E60
        rts                                     ; 07E62

;---------------------------------------------------------------------------
; CopperTemplate - $180 bytes copied to COPPER_INIT at start-up. First the COP1 list: the
; 16 lines above line $44 from $64468, the eight sprite pointers, then at line $44 the copper
; interrupt and a jump to COP2. Then the four playfield lists that COP2 rotates through
; (g_CopperFront / g_CopperBack / spares; their plane pointers are rewritten for the scroll) and
; the progress-map list. Bitplanes are line-interleaved: 5 planes of 36 bytes per 180-byte line.
;---------------------------------------------------------------------------
; COPPER_INIT (COP1): before line $44 the 16-line strip at $64468, all eight sprites,
; then the copper interrupt and a jump to COP2 (the front list)
CopperTemplate:
	dc.w	BPLCON1,$0000	; no fine scroll
	dc.w	BPL1PTH,$0002,BPL1PTL,$D080	; BPL1PT = $2D080
	dc.w	BPL2PTH,$0002,BPL2PTL,$D0A4	; BPL2PT = $2D0A4
	dc.w	BPL3PTH,$0002,BPL3PTL,$D0C8	; BPL3PT = $2D0C8
	dc.w	BPL4PTH,$0002,BPL4PTL,$D0EC	; BPL4PT = $2D0EC
	dc.w	BPL5PTH,$0002,BPL5PTL,$D110	; BPL5PT = $2D110
	dc.w	SPR0PTH,$0002,SPR0PTL,$E5E4	; SPR0PT = $2E5E4
	dc.w	SPR1PTH,$0002,SPR1PTL,$E6B0	; SPR1PT = $2E6B0
	dc.w	SPR2PTH,$0002,SPR2PTL,$E77C	; SPR2PT = $2E77C
	dc.w	SPR3PTH,$0002,SPR3PTL,$E848	; SPR3PT = $2E848
	dc.w	SPR4PTH,$0002,SPR4PTL,$E2E4	; SPR4PT = $2E2E4
	dc.w	SPR5PTH,$0002,SPR5PTL,$E3A4	; SPR5PT = $2E3A4
	dc.w	SPR6PTH,$0002,SPR6PTL,$E464	; SPR6PT = $2E464
	dc.w	SPR7PTH,$0002,SPR7PTL,$E524	; SPR7PT = $2E524
	dc.w	$4401,$FF00	; WAIT line $44
	dc.w	INTREQ,$8010	; set COPER: the copper interrupt (level 3)
	dc.w	COPJMP2,$0000	; jump to COP2LC (the front list)
; COPPER_A1: playfield planes in SCREEN_0 (one of the four lists COP2 points at)
	dc.w	BPL1PTH,$0000,BPL1PTL,$0082	; BPL1PT = $00082
	dc.w	BPL2PTH,$0000,BPL2PTL,$00A6	; BPL2PT = $000A6
	dc.w	BPL3PTH,$0000,BPL3PTL,$00CA	; BPL3PT = $000CA
	dc.w	BPL4PTH,$0000,BPL4PTL,$00EE	; BPL4PT = $000EE
	dc.w	BPL5PTH,$0000,BPL5PTL,$0112	; BPL5PT = $00112
	dc.w	BPLCON1,$0000	; no fine scroll
	dc.w	$FFFF,$FFFE	; end of list
; COPPER_A2: SCREEN_1
	dc.w	BPL1PTH,$0000,BPL1PTL,$B482	; BPL1PT = $0B482
	dc.w	BPL2PTH,$0000,BPL2PTL,$B4A6	; BPL2PT = $0B4A6
	dc.w	BPL3PTH,$0000,BPL3PTL,$B4CA	; BPL3PT = $0B4CA
	dc.w	BPL4PTH,$0000,BPL4PTL,$B4EE	; BPL4PT = $0B4EE
	dc.w	BPL5PTH,$0000,BPL5PTL,$B512	; BPL5PT = $0B512
	dc.w	BPLCON1,$0000	; no fine scroll
	dc.w	$FFFF,$FFFE	; end of list
; COPPER_B1: SCREEN_2
	dc.w	BPL1PTH,$0001,BPL1PTL,$6882	; BPL1PT = $16882
	dc.w	BPL2PTH,$0001,BPL2PTL,$68A6	; BPL2PT = $168A6
	dc.w	BPL3PTH,$0001,BPL3PTL,$68CA	; BPL3PT = $168CA
	dc.w	BPL4PTH,$0001,BPL4PTL,$68EE	; BPL4PT = $168EE
	dc.w	BPL5PTH,$0001,BPL5PTL,$6912	; BPL5PT = $16912
	dc.w	BPLCON1,$0000	; no fine scroll
	dc.w	$FFFF,$FFFE	; end of list
; COPPER_B2: SCREEN_3
	dc.w	BPL1PTH,$0002,BPL1PTL,$1C82	; BPL1PT = $21C82
	dc.w	BPL2PTH,$0002,BPL2PTL,$1CA6	; BPL2PT = $21CA6
	dc.w	BPL3PTH,$0002,BPL3PTL,$1CCA	; BPL3PT = $21CCA
	dc.w	BPL4PTH,$0002,BPL4PTL,$1CEE	; BPL4PT = $21CEE
	dc.w	BPL5PTH,$0002,BPL5PTL,$1D12	; BPL5PT = $21D12
	dc.w	BPLCON1,$0000	; no fine scroll
	dc.w	$FFFF,$FFFE	; end of list
; COPPER_MAP: the between-level progress map (50-byte lines, modulo $D8 then $92)
	dc.w	BPL1PTH,$0001,BPL1PTL,$6882	; BPL1PT = $16882
	dc.w	BPL2PTH,$0001,BPL2PTL,$68B4	; BPL2PT = $168B4
	dc.w	BPL3PTH,$0001,BPL3PTL,$68E6	; BPL3PT = $168E6
	dc.w	BPL4PTH,$0001,BPL4PTL,$6918	; BPL4PT = $16918
	dc.w	BPL5PTH,$0001,BPL5PTL,$694A	; BPL5PT = $1694A
	dc.w	BPLCON1,$0000	; no fine scroll
	dc.w	BPL1MOD,$00D8
	dc.w	BPL2MOD,$00D8
	dc.w	$FFE1,$FFFE	; WAIT line $FF, x $E0 (the PAL wrap: later waits are lines $100+)
	dc.w	$2401,$FF00	; WAIT line $24 ($124 after the wrap)
	dc.w	BPL1MOD,$0092
	dc.w	BPL2MOD,$0092
	dc.w	$FFFF,$FFFE	; end of list

;---------------------------------------------------------------------------
; LevelFileIndex - per level a word offset, from the entry, to its tile file in FileTable
; (LoadLevel).
;---------------------------------------------------------------------------
LevelFileIndex:
	dc.w	FileLevel0-*	; level 0
	dc.w	FileLevel1-*	; level 1
	dc.w	FileLevel2-*	; level 2
	dc.w	FileLevel3-*	; level 3
	dc.w	FileLevel4-*	; level 4
	dc.w	FileLevel5-*	; level 5
	dc.w	FileLevel6-*	; level 6

;---------------------------------------------------------------------------
; FileTable - every file the program loads (FENTRY: load address, length in bytes, first
; track; a1 points at an entry for LoadFile, which reads length / 6,312 tracks, rounded up).
; The bootblock loads the rest: the loading screen and the main program. tools/disk/mkdisk.py
; reads this table (from the assembled binaries of both builds) to lay out the disk.
;---------------------------------------------------------------------------
FileTable:
	FENTRY	$00080,$05400,33	; tracks 33-36: Arthur's sprite frames
FileSmallBobs:
	FENTRY	$00080,$00D20,37	; track 37: small item / scenery BOBs
FileEnemyBobs:
	FENTRY	$00080,$1D042,38	; tracks 38-56: enemy BOB sets
FileItemGfx2:
	FENTRY	$00080,$00EA6,57	; track 57: weapon / effect BOBs, tail
FileEnemyShotGfx:
	FENTRY	$00080,$01234,58	; track 58: enemy shot BOBs
FileItemGfx:
	FENTRY	$00080,$01AC2,59	; tracks 59-60: weapon / pickup / effect BOBs
FileFont:
	FENTRY	$00080,$01840,61	; track 61: font
FileProgressMap:
	FENTRY	$00080,$01D5C,62	; tracks 62-63: progress map (RLE)
FileMusic:
	FENTRY	$3604C,$1B394,64	; tracks 64-81: sound driver, music and effects (1MB)
FileCopyrightScreen:
	FENTRY	$16880,$025FE,82	; tracks 82-83: copyright warning screen (RLE)
FileLevel0:
	FENTRY	$573E0,$07440,84	; tracks 84-88: level 0 tiles
FileLevel1:
	FENTRY	$573E0,$0C120,89	; tracks 89-96: level 1 tiles
FileLevel2:
	FENTRY	$573E0,$05460,97	; tracks 97-100: level 2 tiles
FileLevel3:
	FENTRY	$573E0,$04880,101	; tracks 101-103: level 3 tiles
FileLevel4:
	FENTRY	$573E0,$02760,104	; tracks 104-105: level 4 tiles
FileLevel5:
	FENTRY	$573E0,$029E0,106	; tracks 106-107: level 5 tiles
FileLevel6:
	FENTRY	$573E0,$019A0,108	; tracks 108-109: level 6 tiles

;---------------------------------------------------------------------------
; Switch to the screen RedrawScreen has just drawn at g_NewTileX/Y: the pending
; offsets become the current ones (fine scroll clamped to -16..15), then the buffers
; are rotated (falls into SwapScreens)
;---------------------------------------------------------------------------
CameraJump:
        move.w  g_PendFineX(a6),d0              ; 0809C
        move.w  d0,g_CamDeltaX(a6)              ; 080A0
        cmp.w   #$f,d0                          ; 080A4
        ble.b   l_080AE                         ; 080A8
        moveq   #$f,d0                          ; 080AA
        bra.b   l_080B6                         ; 080AC
l_080AE:
        cmp.w   #$fff0,d0                       ; 080AE
        bge.b   l_080B6                         ; 080B2
        moveq   #-16,d0                         ; 080B4
l_080B6:
        move.w  d0,g_ScrollFineX(a6)            ; 080B6
        move.w  g_PendFineY(a6),d0              ; 080BA
        move.w  d0,g_CamDeltaY(a6)              ; 080BE
        cmp.w   #$f,d0                          ; 080C2
        ble.b   l_080CC                         ; 080C6
        moveq   #$f,d0                          ; 080C8
        bra.b   l_080D4                         ; 080CA
l_080CC:
        cmp.w   #$fff0,d0                       ; 080CC
        bge.b   l_080D4                         ; 080D0
        moveq   #-16,d0                         ; 080D2
l_080D4:
        move.w  d0,g_ScrollFineY(a6)            ; 080D4

;---------------------------------------------------------------------------
; SwapScreens - adopt the new tile origin (g_NewTileX/Y) and rotate the four screen
; buffers and copper lists: the two just redrawn become the working pair, the old pair
; the spares for the next redraw. Both restore lists are emptied.
;---------------------------------------------------------------------------
SwapScreens:
        move.w  g_NewTileX(a6),g_ScrollTileX(a6); 080D8
        move.w  g_NewTileY(a6),g_ScrollTileY(a6); 080DE
        movea.l g_ScreenBack(a6),a1             ; 080E4
        movea.l g_ScreenFront(a6),a2            ; 080E8
        move.l  g_ScreenSpare1(a6),g_ScreenBack(a6); 080EC
        move.l  g_ScreenSpare2(a6),g_ScreenFront(a6); 080F2
        move.l  a1,g_ScreenSpare1(a6)           ; 080F8
        move.l  a2,g_ScreenSpare2(a6)           ; 080FC
        movea.l g_CopperFront(a6),a1            ; 08100
        movea.l g_CopperBack(a6),a2             ; 08104
        move.l  g_CopperSpare1(a6),g_CopperFront(a6); 08108
        move.l  g_CopperSpare2(a6),g_CopperBack(a6); 0810E
        move.l  a1,g_CopperSpare1(a6)           ; 08114
        move.l  a2,g_CopperSpare2(a6)           ; 08118
        lea.l   g_RestoreBufB(a6),a1            ; 0811C
        clr.w   -(a1)                           ; 08120
        move.l  a1,g_RestoreListA(a6)           ; 08122
        lea.l   g_SpawnQuota(a6),a1             ; 08126
        clr.w   -(a1)                           ; 0812A
        move.l  a1,g_RestoreListB(a6)           ; 0812C
        rts                                     ; 08130

;---------------------------------------------------------------------------
; ShowBackBuffer - wait for the copper interrupt (INTREQ bit 4, raised by the copper
; list), point COP2LC at the copper list just built, then swap front and back screens,
; save areas, restore lists and save pointers for the next frame
;---------------------------------------------------------------------------
ShowBackBuffer:
        lea.l   CUSTOM,a0                       ; 08132
        movea.l g_CopperBack(a6),a1             ; 08138
        move.l  g_CopperFront(a6),g_CopperBack(a6); 0813C
        move.l  a1,g_CopperFront(a6)            ; 08142
l_08146:
        moveq   #$10,d0                         ; 08146  wait for the copper interrupt
        and.w   INTREQR(a0),d0                  ; 08148
        beq.b   l_08146                         ; 0814C
        move.l  a1,COP2LCH(a0)                  ; 0814E
        move.w  #INTF_COPER,INTREQ(a0)          ; 08152
        movea.l g_ScreenFront(a6),a1            ; 08158
        move.l  g_ScreenBack(a6),g_ScreenFront(a6); 0815C
        move.l  a1,g_ScreenBack(a6)             ; 08162
        movea.l g_SavePtr(a6),a1                ; 08166  swap the save-area pointers, restore lists and save areas
        move.l  g_SavePtrB(a6),g_SavePtr(a6)    ; 0816A
        move.l  a1,g_SavePtrB(a6)               ; 08170
        movea.l g_RestoreListA(a6),a1           ; 08174
        move.l  g_RestoreListB(a6),g_RestoreListA(a6); 08178
        move.l  a1,g_RestoreListB(a6)           ; 0817E
        movea.l g_SaveBufA(a6),a1               ; 08182
        move.l  g_SaveBufB(a6),g_SaveBufA(a6)   ; 08186
        move.l  a1,g_SaveBufB(a6)               ; 0818C
        rts                                     ; 08190

;---------------------------------------------------------------------------
; Compute SPRxPOS/CTL for Arthur's two attached sprite pairs (hidden while flashing)
;---------------------------------------------------------------------------
ArthurSpritePos:
        moveq   #$0,d0                          ; 08192
        moveq   #$20,d1                         ; 08194
        move.w  g_ScrollTileY(a6),d0            ; 08196
        lsl.w   #$4,d0                          ; 0819A
        add.w   g_ScrollFineY(a6),d0            ; 0819C
        sub.w   g_ArthurY(a6),d0                ; 081A0
        moveq   #-16,d2                         ; 081A4
        cmp.w   d2,d0                           ; 081A6
        ble.b   l_081AC                         ; 081A8
        move.l  d2,d0                           ; 081AA
l_081AC:
        addi.w  #$124,d0                        ; 081AC
        add.w   d0,d1                           ; 081B0
        moveq   #$0,d2                          ; 081B2
        sub.w   g_ScrollTileX(a6),d2            ; 081B4
        asl.w   #$4,d2                          ; 081B8
        sub.w   g_ScrollFineX(a6),d2            ; 081BA
        addi.w  #$90,d2                         ; 081BE
        add.w   g_ArthurX(a6),d2                ; 081C2
        tst.b   g_ArthurFlash(a6)               ; 081C6
        beq.b   l_081D8                         ; 081CA
        btst    #$2,g_VblCount+1(a6)            ; 081CC
        beq.b   l_081D8                         ; 081D2
        move.w  #$1a1,d2                        ; 081D4
l_081D8:
        swap    d0                              ; 081D8
        rol.l   #$8,d0                          ; 081DA
        lsl.w   #$2,d0                          ; 081DC
        lsr.w   #$1,d2                          ; 081DE
        swap    d2                              ; 081E0
        roxl.w  #$1,d2                          ; 081E2
        rol.w   #$8,d1                          ; 081E4
        lsl.b   #$1,d1                          ; 081E6
        or.l    d1,d0                           ; 081E8
        or.l    d2,d0                           ; 081EA
        move.l  d0,d1                           ; 081EC
        bset    #$7,d1                          ; 081EE
        move.l  #$80000,d2                      ; 081F2
        move.l  d0,g_ArthurSprCtl(a6)           ; 081F8
        move.l  d1,g_ArthurSprCtl+4(a6)         ; 081FC
        add.l   d2,d0                           ; 08200
        add.l   d2,d1                           ; 08202
        move.l  d0,g_ArthurSprCtl+8(a6)         ; 08204
        move.l  d1,g_ArthurSprCtl+12(a6)        ; 08208
        rts                                     ; 0820C

;---------------------------------------------------------------------------
; Exchange the two 16-byte per-player blocks and toggle g_CurPlayer
;---------------------------------------------------------------------------
SwapPlayers:
        lea.l   g_OtherPlayer(a6),a1            ; 0820E
        moveq   #$7,d7                          ; 08212
        lea.l   g_Level(a6),a0                  ; 08214
l_08218:
        move.w  (a1),d0                         ; 08218
        move.w  (a0),(a1)+                      ; 0821A
        move.w  d0,(a0)+                        ; 0821C
        dbra    d7,l_08218                      ; 0821E
        not.b   g_CurPlayer(a6)                 ; 08222
        rts                                     ; 08226

;---------------------------------------------------------------------------
; Probe the map under Arthur's feet; snaps Y to the floor. Out: N set = in the air
;---------------------------------------------------------------------------
ArthurFloorCheck:
        moveq   #-8,d6                          ; 08228  probe 8 px left of centre, 16 px below
        add.w   g_ArthurX(a6),d6                ; 0822A
        moveq   #-16,d7                         ; 0822E
        add.w   g_ArthurY(a6),d7                ; 08230
        bsr.w   MapTileAt                       ; 08234
        move.b  $4(a1),d0                       ; 08238
        andi.b  #$c0,d0                         ; 0823C
        bne.b   l_08258                         ; 08240
        move.b  (a1),d0                         ; 08242
        ext.w   d0                              ; 08244
        lea.l   FloorProfile(pc),a1             ; 08246
        adda.w  d0,a1                           ; 0824A
        move.b  (a1),d1                         ; 0824C
        beq.b   l_08258                         ; 0824E
        moveq   #$f,d0                          ; 08250
        and.b   d7,d0                           ; 08252
        sub.b   d0,d1                           ; 08254
        bcc.b   l_0828C                         ; 08256
l_08258:
        moveq   #$8,d6                          ; 08258  then 8 px right
        add.w   g_ArthurX(a6),d6                ; 0825A
        moveq   #-16,d7                         ; 0825E
        add.w   g_ArthurY(a6),d7                ; 08260
        bsr.w   MapTileAt                       ; 08264
        move.b  $4(a1),d0                       ; 08268
        andi.b  #$c0,d0                         ; 0826C
        bne.b   l_08288                         ; 08270
        move.b  (a1),d0                         ; 08272
        ext.w   d0                              ; 08274
        lea.l   FloorProfile(pc),a1             ; 08276
        adda.w  d0,a1                           ; 0827A
        move.b  (a1),d1                         ; 0827C
        beq.b   l_08288                         ; 0827E
        moveq   #$f,d0                          ; 08280
        and.w   d7,d0                           ; 08282
        sub.b   d0,d1                           ; 08284
        bcc.b   l_0828C                         ; 08286
l_08288:
        moveq   #-1,d0                          ; 08288
        rts                                     ; 0828A
l_0828C:
        ext.w   d1                              ; 0828C
        add.w   d1,g_ArthurY(a6)                ; 0828E
        moveq   #$0,d0                          ; 08292
        rts                                     ; 08294

;---------------------------------------------------------------------------
; Per item type 1-5 (shootable scenery, then the platforms): width Arthur can stand on
;---------------------------------------------------------------------------
PlatformSizes:
	dc.b	$18,$1E,$3E,$20,$34

;---------------------------------------------------------------------------
; Per item type 1-5: height (Arthur stands on the top). Item type 1 - gravestones and
; other shootable scenery - is solid too; only types 2-5 carry him (Itm_Rider).
;---------------------------------------------------------------------------
PlatformHeights:
	dc.b	$26,$30,$30,$2E,$2A

;---------------------------------------------------------------------------
; d3,d4 = probe point. Out: Z clear if standing on a moving platform/item
;---------------------------------------------------------------------------
ArthurOnPlatform:
        lea.l   g_Items(a6),a5                  ; 082A0
        moveq   #$1d,d7                         ; 082A4
l_082A6:
        tst.b   O_OnScreen(a5)                  ; 082A6  each on-screen item of type 1-5
        beq.w   l_08338                         ; 082AA
        clr.w   d0                              ; 082AE
        move.b  O_Type(a5),d0                   ; 082B0
        beq.w   l_08338                         ; 082B4
        subq.w  #$1,d0                          ; 082B8  width and height of this item type
        lea.l   PlatformSizes(pc,d0.w),a1       ; 082BA
        lea.l   PlatformHeights(pc,d0.w),a2     ; 082BE
        clr.w   d1                              ; 082C2
        move.b  (a1),d1                         ; 082C4
        move.w  d1,d2                           ; 082C6  probe X within the width?
        lsr.w   #$1,d2                          ; 082C8
        add.w   d3,d2                           ; 082CA
        sub.w   O_X(a5),d2                      ; 082CC
        cmp.w   d1,d2                           ; 082D0
        bhi.b   l_08338                         ; 082D2
        clr.w   d1                              ; 082D4
        move.b  (a2),d1                         ; 082D6
        move.w  d1,d2                           ; 082D8  probe Y within the height?
        lsr.w   #$1,d2                          ; 082DA
        add.w   d4,d2                           ; 082DC
        sub.w   O_Y(a5),d2                      ; 082DE
        cmp.w   d1,d2                           ; 082E2
        bhi.b   l_08338                         ; 082E4
        tst.b   g_Falling(a6)                   ; 082E6  falling: only when he is above its middle
        beq.b   l_082F6                         ; 082EA
        move.w  g_ArthurY(a6),d1                ; 082EC
        sub.w   O_Y(a5),d1                      ; 082F0
        bmi.b   l_08338                         ; 082F4
l_082F6:
        move.w  g_ArthurY(a6),d2                ; 082F6  within 3 px of the top: snap onto it
        sub.w   O_Y(a5),d2                      ; 082FA
        addq.w  #$3,d2                          ; 082FE
        cmp.w   #$6,d2                          ; 08300
        bcs.b   l_08314                         ; 08304
        clr.w   d1                              ; 08306
        move.b  (a2),d1                         ; 08308
        lsr.w   #$1,d1                          ; 0830A
        add.w   O_Y(a5),d1                      ; 0830C
        move.w  d1,g_ArthurY(a6)                ; 08310
l_08314:
        cmpi.b  #$2,O_Type(a5)                  ; 08314  type 2-5 (moving): it carries him - mark it as his platform
        bcs.b   l_08334                         ; 0831A
        move.l  g_ArthurPlatform(a6),d0         ; 0831C
        beq.b   l_08328                         ; 08320
        movea.l d0,a0                           ; 08322
        clr.b   $18(a0)                         ; 08324
l_08328:
        move.l  a5,g_ArthurPlatform(a6)         ; 08328
        st.b    Itm_Rider(a5)                   ; 0832C
        st.b    g_OnPlatform(a6)                ; 08330
l_08334:
        moveq   #-1,d0                          ; 08334
        rts                                     ; 08336
l_08338:
        lea.l   $1c(a5),a5                      ; 08338
        dbra    d7,l_082A6                      ; 0833C
        moveq   #$0,d0                          ; 08340
        rts                                     ; 08342

;---------------------------------------------------------------------------
; a1 = animation table (two variants selected by facing)
;---------------------------------------------------------------------------
ArthurSetAnim:
        tst.b   g_ArthurFacing(a6)              ; 08344
        bpl.b   l_0834C                         ; 08348
        addq.l  #$2,a1                          ; 0834A
l_0834C:
        adda.w  (a1),a1                         ; 0834C

;---------------------------------------------------------------------------
; Start Arthur's animation script a1 as it is (no facing table) and show its first frame
;---------------------------------------------------------------------------
ArthurSetScript:
        move.l  a1,g_ArthurAnim(a6)             ; 0834E
        clr.b   g_ArthurAnimTimer(a6)           ; 08352
        bra.b   l_0835E                         ; 08356

;---------------------------------------------------------------------------
; Step Arthur's animation script; armour-less frames are +$10
;---------------------------------------------------------------------------
ArthurAnimate:
        subq.b  #$1,g_ArthurAnimTimer(a6)       ; 08358
        bne.b   l_0839C                         ; 0835C
l_0835E:
        movea.l g_ArthurAnim(a6),a1             ; 0835E
        move.b  (a1)+,g_ArthurFrame(a6)         ; 08362
        move.b  (a1)+,d0                        ; 08366
        bpl.b   l_0836E                         ; 08368
        neg.b   d0                              ; 0836A
        adda.w  (a1),a1                         ; 0836C
l_0836E:
        move.b  d0,g_ArthurAnimTimer(a6)        ; 0836E
        move.l  a1,g_ArthurAnim(a6)             ; 08372
        tst.b   g_ArthurState(a6)               ; 08376
        bne.b   l_0839C                         ; 0837A
        tst.b   g_FrogTimer(a6)                 ; 0837C
        bne.b   l_0839C                         ; 08380
        tst.b   g_NoArmour(a6)                  ; 08382
        beq.b   l_0839C                         ; 08386
        tst.b   g_ArthurFrame(a6)               ; 08388
        bmi.b   l_08396                         ; 0838C
        addi.b  #$10,g_ArthurFrame(a6)          ; 0838E
        rts                                     ; 08394
l_08396:
        subi.b  #$10,g_ArthurFrame(a6)          ; 08396
l_0839C:
        rts                                     ; 0839C
ArmourDebris:
	dc.b	$01,$08,$08,$02,$08,$F8,$03,$F8,$F8,$04,$F8,$08

;---------------------------------------------------------------------------
; State 1. With armour: it flies off as 4 pieces (shot type 5, sound 1) and he is knocked
; back. Without: he dies (the 1MB build plays tune 8, or 7 on the last life).
;---------------------------------------------------------------------------
ArthurHit:
        clr.b   g_FrogTimer(a6)                 ; 083AA  no longer a frog
        tst.b   g_NoArmour(a6)                  ; 083AE
        bne.b   l_08404                         ; 083B2
        lea.l   ArmourDebris(pc),a1             ; 083B4
        lea.l   g_Shots(a6),a5                  ; 083B8
        moveq   #$3,d7                          ; 083BC
l_083BE:
        clr.b   O_State(a5)                     ; 083BE
        clr.b   O_Step(a5)                      ; 083C2
        clr.b   O_Step2(a5)                     ; 083C6
        move.b  #$2,(a5)                        ; 083CA
        clr.b   O_OnScreen(a5)                  ; 083CE
        move.b  (a1)+,O_Dir(a5)                 ; 083D2
        move.b  (a1)+,d0                        ; 083D6
        ext.w   d0                              ; 083D8
        add.w   g_ArthurX(a6),d0                ; 083DA
        move.w  d0,O_X(a5)                      ; 083DE
        move.b  (a1)+,d0                        ; 083E2
        ext.w   d0                              ; 083E4
        add.w   g_ArthurY(a6),d0                ; 083E6
        move.w  d0,O_Y(a5)                      ; 083EA
        move.b  #$5,O_Type(a5)                  ; 083EE  shot type 5: a piece of armour
        lea.l   $26(a5),a5                      ; 083F4
        dbra    d7,l_083BE                      ; 083F8
        moveq   #SFX_ARTHUR_HIT,d0              ; 083FC
        bsr.w   PlaySfx                         ; 083FE
        bra.b   l_08414                         ; 08402
l_08404:
        moveq   #$8,d0                          ; 08404  no armour: dying. d0 = tune for the 1MB build: 8, or 7 (game over) on the last life
        cmpi.b  #$1,g_Lives(a6)                 ; 08406
        bne.b   l_08410                         ; 0840C  [1MB]   << changed from the 512K build ($083B6: bne.b $83ba) >>
        moveq   #TUNE_GAME_OVER,d0              ; 0840E
l_08410:
        bsr.w   PlayMusic                       ; 08410  [1MB]   << 1MB only: 1 instruction(s) not in the 512K build >>
l_08414:
        addq.b  #AS_HIT,g_ArthurState(a6)       ; 08414
        rts                                     ; 08418

;---------------------------------------------------------------------------
; State 2: thrown up and away from the enemy (the same launch as a jump: 4.25 up,
; 0.5 across), facing it
;---------------------------------------------------------------------------
ArthurKnockback:
        move.b  g_ArthurDir(a6),g_ArthurFacing(a6); 0841A  face the enemy (the opposite of the way he is pushed)
        neg.b   g_ArthurFacing(a6)              ; 08420
        st.b    g_Jumping(a6)                   ; 08424
        move.w  g_ArthurY(a6),g_ArthurAux(a6)   ; 08428
        clr.b   g_Falling(a6)                   ; 0842E
        clr.b   g_FireCooldown(a6)              ; 08432
        clr.b   g_LadderDir(a6)                 ; 08436
        move.l  #$8000,g_ArthurVelX(a6)         ; 0843A  0.5 px/frame away
        move.l  #$44000,g_ArthurVelY(a6)        ; 08442  4.25 px/frame up
        lea.l   ArthurAnimKnockback(pc),a1      ; 0844A
        tst.b   g_NoArmour(a6)                  ; 0844E
        beq.b   l_08458                         ; 08452
        lea.l   ArthurAnimKnockbackBare(pc),a1  ; 08454
l_08458:
        bsr.w   ArthurSetAnim                   ; 08458
        addq.b  #AS_HIT,g_ArthurState(a6)       ; 0845C
        rts                                     ; 08460

;---------------------------------------------------------------------------
; State 3: fly until he lands
;---------------------------------------------------------------------------
ArthurKnockFly:
        bsr.w   ArthurJump                      ; 08462
        tst.b   g_Jumping(a6)                   ; 08466
        bne.b   l_08470                         ; 0846A
        addq.b  #AS_HIT,g_ArthurState(a6)       ; 0846C
l_08470:
        rts                                     ; 08470

;---------------------------------------------------------------------------
; State 4: landed. Armour lost now: flash (invulnerable) for 120 frames and carry on in
; his underwear; already without armour: start dying (20 + 40 + 225 frames)
;---------------------------------------------------------------------------
ArthurLand:
        bsr.w   ArthurFall                      ; 08472
        tst.b   g_Falling(a6)                   ; 08476
        bne.b   l_084AA                         ; 0847A
        tst.b   g_NoArmour(a6)                  ; 0847C
        beq.b   l_084AC                         ; 08480
        tst.b   g_OnPlatform(a6)                ; 08482
        beq.b   l_08498                         ; 08486
        move.l  g_ArthurPlatform(a6),d0         ; 08488
        beq.b   l_08498                         ; 0848C
        movea.l d0,a0                           ; 0848E
        clr.b   $18(a0)                         ; 08490
        clr.b   g_OnPlatform(a6)                ; 08494
l_08498:
        lea.l   ArthurAnimDie1(pc),a1           ; 08498
        bsr.w   ArthurSetAnim                   ; 0849C
        move.b  #$14,g_StateTimer(a6)           ; 084A0
        addq.b  #AS_HIT,g_ArthurState(a6)       ; 084A6
l_084AA:
        rts                                     ; 084AA
l_084AC:
        move.b  #$78,g_ArthurFlash(a6)          ; 084AC  flash for 120 frames: enemies cannot hurt him
        neg.b   g_ArthurFacing(a6)              ; 084B2
        st.b    g_NoArmour(a6)                  ; 084B6  armour gone
        lea.l   ArthurAnims(pc),a1              ; 084BA
        bsr.w   ArthurSetAnim                   ; 084BE
        clr.b   g_ArthurDir(a6)                 ; 084C2
        clr.b   g_ArthurState(a6)               ; 084C6
        clr.b   g_Jumping(a6)                   ; 084CA
        clr.b   g_Falling(a6)                   ; 084CE
        clr.b   g_OnLadder(a6)                  ; 084D2
        rts                                     ; 084D6
ArthurDie1:
        subq.b  #$1,g_StateTimer(a6)            ; 084D8
        bne.w   ArthurAnimate                   ; 084DC
        clr.b   g_FrogTimer(a6)                 ; 084E0
        move.b  #$28,g_StateTimer(a6)           ; 084E4
        lea.l   ArthurAnimDie2(pc),a1           ; 084EA
        bsr.w   ArthurSetAnim                   ; 084EE
        addq.b  #AS_HIT,g_ArthurState(a6)       ; 084F2
        rts                                     ; 084F6
ArthurDie2:
        subq.b  #$1,g_StateTimer(a6)            ; 084F8
        bne.w   ArthurAnimate                   ; 084FC
        move.b  #$e1,g_StateTimer(a6)           ; 08500  225 frames
        addq.b  #AS_HIT,g_ArthurState(a6)       ; 08506
