;---------------------------------------------------------------------------
; Sets g_PlayerDied when the death animation finishes
;---------------------------------------------------------------------------
ArthurDie3:
        subq.b  #$1,g_StateTimer(a6)            ; 0850C
        bne.b   l_0851A                         ; 08510
        clr.b   g_ArthurState(a6)               ; 08512
        st.b    g_PlayerDied(a6)                ; 08516  tell the game loop
l_0851A:
        rts                                     ; 0851A

;---------------------------------------------------------------------------
; ==================================================================
; ArthurUpdate - Arthur's state machine (g_ArthurState):
;  0 normal (walk / jump / fall / crouch / ladder / frog)   1 hit
;  2 knockback start   3 knockback flight   4 landed after the knockback
;  5-7 death animation
; Positions and speeds are 16.16 fixed point, Y increasing upwards.
;   walk     1.125 px/frame (ArthurWalk)
;   jump     up 4.25 px/frame, gravity 0.24 px/frame^2 (falls at up to 5 px/frame):
;            rises for 17 frames, about 39 px high; forward jumps start at 0.5 px/frame and
;            speed up by 0.06 px/frame while rising - about 44 px over a 35-frame jump.
;            Direction is fixed for the whole jump.
;   ladder   1.375 px/frame up or down
;   frog     g_FrogTimer x 64 frames (8 = 512 frames); can walk and jump, not climb or fire
; ===================================================================
;---------------------------------------------------------------------------
ArthurUpdate:
        clr.w   d0                              ; 0851C
        move.b  g_ArthurState(a6),d0            ; 0851E
        add.w   d0,d0                           ; 08522
        add.w   d0,d0                           ; 08524
        jmp     ArthurUpdate_Jumps(pc,d0.w)     ; 08526
ArthurUpdate_Jumps:
        bra.w   ArthurNormal                    ; 0852A
        bra.w   ArthurHit                       ; 0852E
        bra.w   ArthurKnockback                 ; 08532
        bra.w   ArthurKnockFly                  ; 08536
        bra.w   ArthurLand                      ; 0853A
        bra.w   ArthurDie1                      ; 0853E
        bra.w   ArthurDie2                      ; 08542
        bra.w   ArthurDie3                      ; 08546

;---------------------------------------------------------------------------
; State 0: frog / jumping / falling / crouching / ladder / walking. Order: up or down
; (ladder, jump, crouch), climb, fire, left / right, then the floor test (walking off an
; edge starts a fall) and the platform test.
;---------------------------------------------------------------------------
ArthurNormal:
        tst.b   g_FrogTimer(a6)                 ; 0854A
        bne.w   ArthurFrog                      ; 0854E
        tst.b   g_ArthurFlash(a6)               ; 08552
        beq.b   l_0855C                         ; 08556
        subq.b  #$1,g_ArthurFlash(a6)           ; 08558  invulnerable flash counting down
l_0855C:
        tst.b   g_Jumping(a6)                   ; 0855C
        bne.w   ArthurJump                      ; 08560
        tst.b   g_Falling(a6)                   ; 08564
        bne.w   ArthurFall                      ; 08568
        tst.b   g_Crouching(a6)                 ; 0856C
        bne.w   ArthurCrouch                    ; 08570
        bsr.w   ArthurReadUpDown                ; 08574
        tst.b   d0                              ; 08578
        beq.b   l_08582                         ; 0857A
        tst.b   g_OnLadder(a6)                  ; 0857C
        bne.b   l_085D0                         ; 08580
l_08582:
        tst.b   g_OnLadder(a6)                  ; 08582
        bne.w   ArthurClimb                     ; 08586
        bsr.w   ArthurFire                      ; 0858A  fire (ArthurFire) before moving
        tst.b   g_Jumping(a6)                   ; 0858E
        bne.b   l_085D0                         ; 08592
        bsr.w   ArthurReadLeftRight             ; 08594
        tst.b   g_ArthurDir(a6)                 ; 08598
        beq.b   l_085A2                         ; 0859C
        bsr.w   ArthurWalk                      ; 0859E
l_085A2:
        tst.b   g_OnPlatform(a6)                ; 085A2
        beq.b   l_085B4                         ; 085A6
        movea.l g_ArthurPlatform(a6),a0         ; 085A8
        clr.b   $18(a0)                         ; 085AC
        clr.b   g_OnPlatform(a6)                ; 085B0
l_085B4:
        bsr.w   ArthurFloorCheck                ; 085B4  floor under his feet? no: start falling
        smi.b   g_Falling(a6)                   ; 085B8
        move.w  g_ArthurX(a6),d3                ; 085BC
        move.w  g_ArthurY(a6),d4                ; 085C0
        subq.w  #$1,d4                          ; 085C4
        bsr.w   ArthurOnPlatform                ; 085C6
        beq.b   l_085D0                         ; 085CA
        clr.b   g_Falling(a6)                   ; 085CC
l_085D0:
        tst.b   g_Falling(a6)                   ; 085D0
        bpl.b   l_085DA                         ; 085D4
        clr.b   g_ArthurDir(a6)                 ; 085D6
l_085DA:
        rts                                     ; 085DA

;---------------------------------------------------------------------------
; Normal state while transformed into a frog (g_FrogTimer)
;---------------------------------------------------------------------------
ArthurFrog:
        tst.b   g_ArthurFlash(a6)               ; 085DC
        beq.b   l_085E6                         ; 085E0
        subq.b  #$1,g_ArthurFlash(a6)           ; 085E2
l_085E6:
        moveq   #$3f,d0                         ; 085E6
        and.w   g_GameFrame(a6),d0              ; 085E8
        bne.b   l_085FC                         ; 085EC
        subq.b  #$1,g_FrogTimer(a6)             ; 085EE  every 64 frames
        bne.b   l_085FC                         ; 085F2
        lea.l   ArthurAnims(pc),a1              ; 085F4  back to normal
        bra.w   ArthurSetAnim                   ; 085F8
l_085FC:
        tst.b   g_Jumping(a6)                   ; 085FC
        bne.b   l_08664                         ; 08600
        tst.b   g_Falling(a6)                   ; 08602
        bne.w   l_08706                         ; 08606
        bsr.w   ArthurReadUpDown                ; 0860A
        bne.w   ArthurClimb                     ; 0860E
        bsr.w   ArthurReadLeftRight             ; 08612
        tst.b   g_ArthurDir(a6)                 ; 08616
        beq.b   l_08620                         ; 0861A
        bsr.w   ArthurWalk                      ; 0861C
l_08620:
        tst.b   g_OnPlatform(a6)                ; 08620
        beq.b   l_08632                         ; 08624
        movea.l g_ArthurPlatform(a6),a0         ; 08626
        clr.b   $18(a0)                         ; 0862A
        clr.b   g_OnPlatform(a6)                ; 0862E
l_08632:
        bsr.w   ArthurFloorCheck                ; 08632
        smi.b   g_Falling(a6)                   ; 08636
        move.w  g_ArthurX(a6),d3                ; 0863A
        move.w  g_ArthurY(a6),d4                ; 0863E
        subq.w  #$1,d4                          ; 08642
        bsr.w   ArthurOnPlatform                ; 08644
        beq.b   l_0864E                         ; 08648
        clr.b   g_Falling(a6)                   ; 0864A
l_0864E:
        tst.b   g_Falling(a6)                   ; 0864E
        bpl.b   l_08658                         ; 08652
        clr.b   g_ArthurDir(a6)                 ; 08654
l_08658:
        rts                                     ; 08658

;---------------------------------------------------------------------------
; Jump (and knockback) physics. Rising: X += vx (if moving), Y += vy, vx += $FA0,
; vy -= $3D90; below $3DFF it starts to fall: Y -= vy, vy += $3D90 up to 5 px/frame.
; Walls stop the horizontal part. Leaving a platform drops it.
;---------------------------------------------------------------------------
ArthurJump:
        tst.b   g_ArthurState(a6)               ; 0865A
        bne.b   l_08664                         ; 0865E
        bsr.w   ArthurFire                      ; 08660
l_08664:
        bsr.w   ArthurAnimate                   ; 08664
        tst.b   g_ArthurDir(a6)                 ; 08668
        beq.b   l_0868E                         ; 0866C
        bpl.b   l_08680                         ; 0866E
        bsr.w   WallCheckLeft                   ; 08670  jumping left
        bne.b   l_0868E                         ; 08674
        move.l  g_ArthurVelX(a6),d0             ; 08676
        sub.l   d0,g_ArthurX(a6)                ; 0867A
        bra.b   l_0868E                         ; 0867E
l_08680:
        bsr.w   WallCheckRight                  ; 08680
        bne.b   l_0868E                         ; 08684
        move.l  g_ArthurVelX(a6),d0             ; 08686
        add.l   d0,g_ArthurX(a6)                ; 0868A
l_0868E:
        tst.b   g_Falling(a6)                   ; 0868E
        bne.b   l_086D4                         ; 08692
        move.l  g_ArthurVelY(a6),d0             ; 08694
        add.l   d0,g_ArthurY(a6)                ; 08698
        addi.l  #$fa0,g_ArthurVelX(a6)          ; 0869C  vx grows while rising
        subi.l  #$3d90,g_ArthurVelY(a6)         ; 086A4  gravity
        cmpi.l  #$3dff,g_ArthurVelY(a6)         ; 086AC
        bcc.b   l_086BA                         ; 086B4
        st.b    g_Falling(a6)                   ; 086B6  top of the jump: falling from now on
l_086BA:
        tst.b   g_OnPlatform(a6)                ; 086BA
        beq.b   l_086D2                         ; 086BE
        move.l  g_ArthurPlatform(a6),d0         ; 086C0
        beq.w   l_0890C                         ; 086C4
        movea.l d0,a0                           ; 086C8
        clr.b   $18(a0)                         ; 086CA
        clr.b   g_OnPlatform(a6)                ; 086CE
l_086D2:
        rts                                     ; 086D2
l_086D4:
        move.l  g_ArthurVelY(a6),d0             ; 086D4
        sub.l   d0,g_ArthurY(a6)                ; 086D8
        cmpi.w  #$5,g_ArthurVelY(a6)            ; 086DC  fall speed limit 5 px/frame
        scs.b   g_Jumping(a6)                   ; 086E2
        bcc.b   l_08742                         ; 086E6
        addi.l  #$3d90,g_ArthurVelY(a6)         ; 086E8
        bra.b   l_08742                         ; 086F0

;---------------------------------------------------------------------------
; Falling (off an edge or after a jump's top): sideways at vx (growing), down at vy
; (up to 5 px/frame); lands on a platform or the floor (sound 5)
;---------------------------------------------------------------------------
ArthurFall:
        tst.b   g_ArthurState(a6)               ; 086F2
        bne.b   l_08706                         ; 086F6
        bsr.w   ArthurFire                      ; 086F8
        tst.b   g_FireCooldown(a6)              ; 086FC
        bne.b   l_08706                         ; 08700
        bsr.w   ArthurAnimate                   ; 08702
l_08706:
        move.l  g_ArthurVelX(a6),d0             ; 08706
        tst.b   g_ArthurDir(a6)                 ; 0870A
        beq.b   l_08718                         ; 0870E
        bpl.b   l_08714                         ; 08710
        neg.l   d0                              ; 08712
l_08714:
        add.l   d0,g_ArthurX(a6)                ; 08714
l_08718:
        move.l  g_ArthurVelY(a6),d0             ; 08718
        sub.l   d0,g_ArthurY(a6)                ; 0871C
        move.l  g_ArthurVelX(a6),d0             ; 08720
        addi.l  #$fa0,d0                        ; 08724
        tst.w   d0                              ; 0872A
        bmi.b   l_08732                         ; 0872C
        move.l  d0,g_ArthurVelX(a6)             ; 0872E
l_08732:
        cmpi.w  #$5,g_ArthurVelY(a6)            ; 08732
        bcc.b   l_08742                         ; 08738
        addi.l  #$3d90,g_ArthurVelY(a6)         ; 0873A
l_08742:
        move.w  g_ArthurX(a6),d3                ; 08742
        move.w  g_ArthurY(a6),d4                ; 08746
        subq.w  #$1,d4                          ; 0874A
        bsr.w   ArthurOnPlatform                ; 0874C
        bne.b   l_08780                         ; 08750
        bsr.w   ArthurFloorCheck                ; 08752
        smi.b   g_Falling(a6)                   ; 08756
        bmi.b   l_0877E                         ; 0875A
        clr.l   g_ArthurVelX(a6)                ; 0875C  landed
        clr.b   g_Jumping(a6)                   ; 08760
        tst.b   g_FrogTimer(a6)                 ; 08764
        beq.b   l_08770                         ; 08768
        lea.l   ArthurAnimFrog(pc),a1           ; 0876A
        bra.b   l_08774                         ; 0876E
l_08770:
        lea.l   ArthurAnims(pc),a1              ; 08770
l_08774:
        bsr.w   ArthurSetAnim                   ; 08774
        moveq   #SFX_LAND,d0                    ; 08778
        bsr.w   PlaySfx                         ; 0877A
l_0877E:
        rts                                     ; 0877E
l_08780:
        clr.b   g_Falling(a6)                   ; 08780
        clr.b   g_Jumping(a6)                   ; 08784
        lea.l   ArthurAnims(pc),a1              ; 08788
        tst.b   g_Crouching(a6)                 ; 0878C
        beq.b   l_08796                         ; 08790
        lea.l   ArthurAnimCrouch(pc),a1         ; 08792
l_08796:
        bsr.w   ArthurSetAnim                   ; 08796
        bra.w   ArthurAnimate                   ; 0879A

;---------------------------------------------------------------------------
; Crouching: no walking; up / down and fire still read
;---------------------------------------------------------------------------
ArthurCrouch:
        clr.b   g_ArthurDir(a6)                 ; 0879E
        bsr.w   ArthurReadUpDown                ; 087A2
        bsr.w   ArthurFire                      ; 087A6
        bsr.w   ArthurAnimate                   ; 087AA
        tst.b   g_OnPlatform(a6)                ; 087AE
        beq.b   l_087CA                         ; 087B2
        bsr.w   ArthurOnPlatform                ; 087B4
        seq.b   g_Falling(a6)                   ; 087B8
        bne.b   l_087CA                         ; 087BC
        clr.b   g_OnPlatform(a6)                ; 087BE
        movea.l g_ArthurPlatform(a6),a0         ; 087C2
        clr.b   $18(a0)                         ; 087C6
l_087CA:
        rts                                     ; 087CA

;---------------------------------------------------------------------------
; Left / right held: face that way and walk; neither: stand (or keep crouching)
;---------------------------------------------------------------------------
ArthurReadLeftRight:
        move.w  g_Joy(a6),d0                    ; 087CC
        and.w   g_JoyPrev(a6),d0                ; 087D0
        btst    #$1,d0                          ; 087D4  right held (bit 1)
        bne.b   l_08810                         ; 087D8
        btst    #$9,d0                          ; 087DA  left held (bit 9)
        bne.b   l_08816                         ; 087DE
        tst.b   g_FrogTimer(a6)                 ; 087E0
        beq.b   l_087EC                         ; 087E4
        lea.l   ArthurAnimFrog(pc),a1           ; 087E6
        bra.b   l_08806                         ; 087EA
l_087EC:
        tst.b   g_FireCooldown(a6)              ; 087EC
        bne.b   l_0880A                         ; 087F0
        tst.b   g_Crouching(a6)                 ; 087F2
        beq.b   l_08802                         ; 087F6
        lea.l   ArthurAnimCrouch(pc),a1         ; 087F8
        bsr.w   ArthurSetAnim                   ; 087FC
        bra.b   l_0880A                         ; 08800
l_08802:
        lea.l   ArthurAnims(pc),a1              ; 08802
l_08806:
        bsr.w   ArthurSetAnim                   ; 08806
l_0880A:
        clr.b   g_ArthurDir(a6)                 ; 0880A
        rts                                     ; 0880E
l_08810:
        move.b  #$1,d1                          ; 08810
        bra.b   l_08818                         ; 08814
l_08816:
        st.b    d1                              ; 08816
l_08818:
        move.b  d1,g_ArthurFacing(a6)           ; 08818
        cmp.b   g_ArthurDir(a6),d1              ; 0881C
        bne.b   l_08826                         ; 08820
        clr.b   d1                              ; 08822
        rts                                     ; 08824
l_08826:
        move.b  d1,g_ArthurDir(a6)              ; 08826
        tst.b   g_FrogTimer(a6)                 ; 0882A
        beq.b   l_08836                         ; 0882E
        lea.l   ArthurAnimFrog(pc),a1           ; 08830
        bra.b   l_0883A                         ; 08834
l_08836:
        lea.l   ArthurAnims(pc),a1              ; 08836
l_0883A:
        bsr.w   ArthurSetAnim                   ; 0883A
        rts                                     ; 0883E

;---------------------------------------------------------------------------
; Up: climb a ladder he stands at (or carry on climbing / step off at the top), else
; jump (sound 4). Down: step onto a ladder 18 px below his feet (moving 14 px down), carry
; on down, else crouch. Out: d0 nonzero = up or down was acted on.
;---------------------------------------------------------------------------
ArthurReadUpDown:
        clr.b   g_Crouching(a6)                 ; 08840  up / down only count when held for two VBL samples
        move.w  g_Joy(a6),d0                    ; 08844
        and.w   g_JoyPrev(a6),d0                ; 08848
        btst    #$8,d0                          ; 0884C  up held (bit 8)
        bne.b   l_08862                         ; 08850
        btst    #$0,d0                          ; 08852  down held (bit 0)
        bne.w   l_08940                         ; 08856
        clr.b   g_LadderDir(a6)                 ; 0885A  neither: not on a ladder move
        st.b    d0                              ; 0885E
        rts                                     ; 08860
l_08862:
        tst.b   g_FrogTimer(a6)                 ; 08862  up: a frog cannot climb, he jumps
        bne.b   l_088DE                         ; 08866
        move.w  g_ArthurX(a6),d6                ; 08868
        move.w  g_ArthurY(a6),d7                ; 0886C
        bsr.w   LadderCheck                     ; 08870  ladder here?
        beq.b   l_0889A                         ; 08874
        tst.b   g_LadderDir(a6)                 ; 08876  already climbing up: carry on
        bgt.b   l_08896                         ; 0887A
        st.b    g_OnLadder(a6)                  ; 0887C  start climbing up
        clr.b   g_ArthurDir(a6)                 ; 08880
        lea.l   ArthurAnimClimb(pc),a1          ; 08884
        bsr.w   ArthurSetScript                 ; 08888
        move.b  #$1,g_LadderDir(a6)             ; 0888C
        st.b    d0                              ; 08892
        rts                                     ; 08894
l_08896:
        clr.b   d0                              ; 08896
        rts                                     ; 08898
l_0889A:
        tst.b   g_OnLadder(a6)                  ; 0889A  no ladder at his feet: at the top of one?
        beq.b   l_088DE                         ; 0889E
        move.b  g_StateTimer(a6),d0             ; 088A0  at the top of a ladder: getting-off animation steps (0, 10, 17)
        beq.b   l_088B4                         ; 088A4
        cmp.b   #$a,d0                          ; 088A6
        beq.b   l_088BA                         ; 088AA
        cmp.b   #$11,d0                         ; 088AC
        beq.b   l_088CA                         ; 088B0
        bra.b   l_088C2                         ; 088B2
l_088B4:
        lea.l   ArthurAnimLadderTop1(pc),a1     ; 088B4
        bra.b   l_088BE                         ; 088B8
l_088BA:
        lea.l   ArthurAnimLadderTop2(pc),a1     ; 088BA
l_088BE:
        bsr.w   ArthurSetScript                 ; 088BE
l_088C2:
        addq.b  #$1,g_StateTimer(a6)            ; 088C2
        st.b    d0                              ; 088C6
        rts                                     ; 088C8
l_088CA:
        clr.b   g_OnLadder(a6)                  ; 088CA  off the ladder: standing
        clr.b   g_StateTimer(a6)                ; 088CE
        lea.l   ArthurAnims(pc),a1              ; 088D2
        bsr.w   ArthurSetAnim                   ; 088D6
        clr.b   d0                              ; 088DA
        rts                                     ; 088DC
l_088DE:
        tst.b   g_LadderDir(a6)                 ; 088DE  up and not on a ladder: jump (not while climbing)
        bhi.b   l_08896                         ; 088E2
        st.b    g_Jumping(a6)                   ; 088E4  jump
        tst.b   g_FrogTimer(a6)                 ; 088E8
        beq.b   l_088F4                         ; 088EC
        lea.l   ArthurAnimFrogJump(pc),a1       ; 088EE
        bra.b   l_08902                         ; 088F2
l_088F4:
        lea.l   ArthurAnimJump(pc),a1           ; 088F4
        tst.b   g_ArthurDir(a6)                 ; 088F8
        beq.b   l_08902                         ; 088FC
        lea.l   ArthurAnimJumpFwd(pc),a1        ; 088FE
l_08902:
        bsr.w   ArthurSetAnim                   ; 08902
        moveq   #SFX_JUMP,d0                    ; 08906
        bsr.w   PlaySfx                         ; 08908
l_0890C:
        move.w  g_ArthurY(a6),g_ArthurAux(a6)   ; 0890C
        clr.l   g_ArthurVelX(a6)                ; 08912
        move.l  #$8000,g_ArthurVelX(a6)         ; 08916  0.5 px/frame forward if he is moving, else straight up
        tst.b   g_ArthurDir(a6)                 ; 0891E
        bne.b   l_08928                         ; 08922
        clr.l   g_ArthurVelX(a6)                ; 08924
l_08928:
        move.l  #$44000,g_ArthurVelY(a6)        ; 08928  4.25 px/frame up
        clr.b   g_FireCooldown(a6)              ; 08930
        clr.b   g_LadderDir(a6)                 ; 08934
        tst.b   g_ArthurDir(a6)                 ; 08938
        st.b    d0                              ; 0893C
        rts                                     ; 0893E
l_08940:
        tst.b   g_FrogTimer(a6)                 ; 08940  down: a frog cannot climb
        bne.b   l_08980                         ; 08944
        move.w  g_ArthurX(a6),d6                ; 08946
        moveq   #-18,d7                         ; 0894A  ladder 18 px below his feet?
        add.w   g_ArthurY(a6),d7                ; 0894C
        bsr.w   LadderCheck                     ; 08950
        beq.b   l_089C6                         ; 08954
        tst.b   g_LadderDir(a6)                 ; 08956  already on a ladder going down: carry on
        bmi.b   l_08976                         ; 0895A
        tst.b   g_OnLadder(a6)                  ; 0895C
        bne.b   l_08976                         ; 08960
        st.b    g_LadderDir(a6)                 ; 08962
        subi.w  #$e,g_ArthurY(a6)               ; 08966  step down onto it
        st.b    g_OnLadder(a6)                  ; 0896C
        clr.b   g_ArthurDir(a6)                 ; 08970
        bra.b   l_08984                         ; 08974
l_08976:
        st.b    g_LadderDir(a6)                 ; 08976  stepping down from the top: run the getting-on poses
        tst.b   g_StateTimer(a6)                ; 0897A
        bne.b   l_08984                         ; 0897E
l_08980:
        clr.b   d0                              ; 08980
        rts                                     ; 08982
l_08984:
        tst.b   g_StateTimer(a6)                ; 08984
        bne.b   l_08992                         ; 08988
        move.b  #$11,g_StateTimer(a6)           ; 0898A
        bra.b   l_089A2                         ; 08990
l_08992:
        cmpi.b  #$11,g_StateTimer(a6)           ; 08992  BUG: compares d0 ($FF from LadderCheck) instead of g_StateTimer, so the
        beq.b   l_089A2                         ; 08998
        cmp.b   #$a,d0                          ; 0899A  second pose (ArthurAnimLadderTop1 at step 10) never shows going down
        beq.b   l_089A8                         ; 0899E
        bra.b   l_089B0                         ; 089A0
l_089A2:
        lea.l   ArthurAnimLadderTop2(pc),a1     ; 089A2
        bra.b   l_089AC                         ; 089A6
l_089A8:
        lea.l   ArthurAnimLadderTop1(pc),a1     ; 089A8
l_089AC:
        bsr.w   ArthurSetScript                 ; 089AC
l_089B0:
        subq.b  #$1,g_StateTimer(a6)            ; 089B0
        beq.b   l_089BA                         ; 089B4
        st.b    d0                              ; 089B6
        rts                                     ; 089B8
l_089BA:
        lea.l   ArthurAnimClimb(pc),a1          ; 089BA  poses done: climbing
        bsr.w   ArthurSetScript                 ; 089BE
        clr.b   d0                              ; 089C2
        rts                                     ; 089C4
l_089C6:
        st.b    g_Crouching(a6)                 ; 089C6  crouch
        clr.b   g_OnLadder(a6)                  ; 089CA
        tst.b   g_FireCooldown(a6)              ; 089CE
        bne.b   l_089E2                         ; 089D2
        tst.b   g_LadderDir(a6)                 ; 089D4
        bmi.b   l_089E2                         ; 089D8
        lea.l   ArthurAnimCrouch(pc),a1         ; 089DA
        bsr.w   ArthurSetAnim                   ; 089DE
l_089E2:
        st.b    d0                              ; 089E2
        rts                                     ; 089E4

;---------------------------------------------------------------------------
; torch 2, lance 3, axe 2, cross 3, dagger 3
;---------------------------------------------------------------------------
MaxShotsPerWeapon:
	dc.b	$02,$03,$02,$03,$03,$00

;---------------------------------------------------------------------------
; On fire press: spawn a shot of type g_Weapon if a slot is free (sfx 6)
;---------------------------------------------------------------------------
ArthurFire:
        tst.b   g_PlayerDied(a6)                ; 089EC
        bne.w   l_08ABC                         ; 089F0
        cmpi.b  #$5,g_FireCooldown(a6)          ; 089F4  can fire again once the cooldown is down to 5
        bhi.w   l_08A9A                         ; 089FA
        move.w  g_JoyPrev(a6),d0                ; 089FE  fire newly pressed?
        not.w   d0                              ; 08A02
        and.w   g_Joy(a6),d0                    ; 08A04
        bpl.w   l_08A9A                         ; 08A08
        lea.l   g_Shots(a6),a0                  ; 08A0C
        move.w  g_Weapon(a6),d0                 ; 08A10
        move.b  MaxShotsPerWeapon(pc,d0.w),d0   ; 08A14  slots this weapon may use
        moveq   #$26,d1                         ; 08A18
l_08A1A:
        tst.b   (a0)                            ; 08A1A
        beq.b   l_08A26                         ; 08A1C
        adda.w  d1,a0                           ; 08A1E
        subq.b  #$1,d0                          ; 08A20
        bne.b   l_08A1A                         ; 08A22
        bra.b   l_08A9A                         ; 08A24
l_08A26:
        move.b  #$1,(a0)                        ; 08A26
        move.b  #$1,$1(a0)                      ; 08A2A
        clr.b   $13(a0)                         ; 08A30
        clr.b   $5(a0)                          ; 08A34
        clr.b   $4(a0)                          ; 08A38
        clr.b   $3(a0)                          ; 08A3C
        move.b  g_Weapon+1(a6),$1a(a0)          ; 08A40  shot type = g_Weapon (low byte)
        moveq   #$9,d0                          ; 08A46  from 9 px above his feet, or 3 below when crouching
        tst.b   g_Crouching(a6)                 ; 08A48
        beq.b   l_08A50                         ; 08A4C
        moveq   #-3,d0                          ; 08A4E
l_08A50:
        add.w   g_ArthurY(a6),d0                ; 08A50
        move.w  d0,$a(a0)                       ; 08A54
        tst.b   g_ArthurFacing(a6)              ; 08A58
        bpl.b   l_08A6C                         ; 08A5C
        move.w  g_ArthurX(a6),$6(a0)            ; 08A5E
        move.b  #$2,$12(a0)                     ; 08A64  facing left: from his X, direction 2
        bra.b   l_08A7C                         ; 08A6A
l_08A6C:
        moveq   #$f,d0                          ; 08A6C  facing right: 15 px ahead, direction 1
        add.w   g_ArthurX(a6),d0                ; 08A6E
        move.w  d0,$6(a0)                       ; 08A72
        move.b  #$1,$12(a0)                     ; 08A76
l_08A7C:
        move.b  #$f,g_FireCooldown(a6)          ; 08A7C  15-frame cooldown with the throw animation
        lea.l   ArthurAnimThrow(pc),a1          ; 08A82
        tst.b   g_Crouching(a6)                 ; 08A86
        beq.b   l_08A90                         ; 08A8A
        lea.l   ArthurAnimThrowCrouch(pc),a1    ; 08A8C
l_08A90:
        bsr.w   ArthurSetAnim                   ; 08A90
        moveq   #SFX_THROW,d0                   ; 08A94
        bsr.w   PlaySfx                         ; 08A96
l_08A9A:
        tst.b   g_FireCooldown(a6)              ; 08A9A
        beq.b   l_08ABC                         ; 08A9E
        bsr.w   ArthurAnimate                   ; 08AA0
        subq.b  #$1,g_FireCooldown(a6)          ; 08AA4
        bne.b   l_08ABC                         ; 08AA8
        lea.l   ArthurAnims(pc),a1              ; 08AAA
        tst.b   g_Crouching(a6)                 ; 08AAE
        beq.b   l_08AB8                         ; 08AB2
        lea.l   ArthurAnimCrouch(pc),a1         ; 08AB4
l_08AB8:
        bsr.w   ArthurSetAnim                   ; 08AB8
l_08ABC:
        rts                                     ; 08ABC

;---------------------------------------------------------------------------
; Walk 1.125 px/frame unless firing; stopped by platforms and walls
;---------------------------------------------------------------------------
ArthurWalk:
        tst.b   g_FireCooldown(a6)              ; 08ABE
        bne.w   ArthurAnimate                   ; 08AC2
        tst.b   g_ArthurDir(a6)                 ; 08AC6
        bmi.b   l_08AF2                         ; 08ACA
        move.w  g_ArthurX(a6),d3                ; 08ACC
        move.w  g_ArthurY(a6),d4                ; 08AD0
        addq.w  #$1,d3                          ; 08AD4
        addq.w  #$1,d4                          ; 08AD6
        bsr.w   ArthurOnPlatform                ; 08AD8
        bne.w   ArthurAnimate                   ; 08ADC
        bsr.b   WallCheckRight                  ; 08AE0
        bne.w   ArthurAnimate                   ; 08AE2
        addi.l  #$12000,g_ArthurX(a6)           ; 08AE6  1.125 px/frame right
        bra.w   ArthurAnimate                   ; 08AEE
l_08AF2:
        move.w  g_ArthurX(a6),d3                ; 08AF2
        move.w  g_ArthurY(a6),d4                ; 08AF6
        subq.w  #$1,d3                          ; 08AFA
        addq.w  #$1,d4                          ; 08AFC
        bsr.w   ArthurOnPlatform                ; 08AFE
        bne.w   ArthurAnimate                   ; 08B02
        bsr.b   WallCheckLeft                   ; 08B06
        bne.w   ArthurAnimate                   ; 08B08
        subi.l  #$12000,g_ArthurX(a6)           ; 08B0C  1.125 px/frame left
        bra.w   ArthurAnimate                   ; 08B14

;---------------------------------------------------------------------------
; Wall 16 px to the right at knee height (Y - 7)? Push him out of it (WallProfileR);
; if that leaves him within 10 px of the right edge of the screen he stops walking.
; Out: Z clear = wall.
;---------------------------------------------------------------------------
WallCheckRight:
        moveq   #$10,d6                         ; 08B18
        add.w   g_ArthurX(a6),d6                ; 08B1A
        moveq   #-7,d7                          ; 08B1E
        add.w   g_ArthurY(a6),d7                ; 08B20
        bsr.w   MapTileAt                       ; 08B24
        move.b  $4(a1),d0                       ; 08B28
        andi.b  #$c0,d0                         ; 08B2C
        bne.b   l_08B4A                         ; 08B30
        move.b  (a1),d0                         ; 08B32
        ext.w   d0                              ; 08B34
        lea.l   WallProfileR(pc),a1             ; 08B36
        adda.w  d0,a1                           ; 08B3A
        move.b  (a1),d0                         ; 08B3C
        beq.b   l_08B4A                         ; 08B3E
        moveq   #$f,d1                          ; 08B40
        and.w   g_ArthurX(a6),d1                ; 08B42
        sub.b   d0,d1                           ; 08B46
        bcc.b   l_08B4E                         ; 08B48
l_08B4A:
        moveq   #$0,d0                          ; 08B4A
        rts                                     ; 08B4C
l_08B4E:
        sub.w   d1,g_ArthurX(a6)                ; 08B4E
        clr.w   g_ArthurX+2(a6)                 ; 08B52
        move.w  g_CameraX(a6),d0                ; 08B56
        addi.w  #$100,d0                        ; 08B5A
        sub.w   g_ArthurX(a6),d0                ; 08B5E
l_08B62:
        cmp.w   #$a,d0                          ; 08B62
        bhi.b   l_08B6C                         ; 08B66
        clr.b   g_ArthurDir(a6)                 ; 08B68
l_08B6C:
        moveq   #-1,d0                          ; 08B6C
        rts                                     ; 08B6E

;---------------------------------------------------------------------------
; The same to the left (WallProfileL) and the left edge of the screen
;---------------------------------------------------------------------------
WallCheckLeft:
        moveq   #-16,d6                         ; 08B70
        add.w   g_ArthurX(a6),d6                ; 08B72
        moveq   #-7,d7                          ; 08B76
        add.w   g_ArthurY(a6),d7                ; 08B78
        bsr.w   MapTileAt                       ; 08B7C
        move.b  $4(a1),d0                       ; 08B80
        andi.b  #$c0,d0                         ; 08B84
        bne.b   l_08BA4                         ; 08B88
        move.b  (a1),d0                         ; 08B8A
        ext.w   d0                              ; 08B8C
        lea.l   WallProfileL(pc),a1             ; 08B8E
        adda.w  d0,a1                           ; 08B92
        move.b  (a1),d0                         ; 08B94
        beq.b   l_08BA4                         ; 08B96
        ext.w   d0                              ; 08B98
        moveq   #$f,d1                          ; 08B9A
        and.w   g_ArthurX(a6),d1                ; 08B9C
        sub.w   d1,d0                           ; 08BA0
        bcc.b   l_08BA8                         ; 08BA2
l_08BA4:
        moveq   #$0,d0                          ; 08BA4
        rts                                     ; 08BA6
l_08BA8:
        add.w   d0,g_ArthurX(a6)                ; 08BA8
        move.w  g_ArthurX(a6),d0                ; 08BAC
        sub.w   g_CameraX(a6),d0                ; 08BB0
        bra.b   l_08B62                         ; 08BB4

;---------------------------------------------------------------------------
; 1.375 px/frame up (g_LadderDir > 0) or down
;---------------------------------------------------------------------------
ArthurClimb:
        bsr.w   ArthurAnimate                   ; 08BB6
        move.l  #$16000,d0                      ; 08BBA  1.375 px/frame
        tst.b   g_LadderDir(a6)                 ; 08BC0
        bpl.b   l_08BC8                         ; 08BC4
        neg.l   d0                              ; 08BC6
l_08BC8:
        add.l   d0,g_ArthurY(a6)                ; 08BC8
        rts                                     ; 08BCC

;---------------------------------------------------------------------------
; Ladder tile at d6, d7 (profile $40-$7D, not background)? Snap X to its 16-px column
; (the profile's bit 0 says which half).
;---------------------------------------------------------------------------
LadderCheck:
        bsr.w   MapTileAt                       ; 08BCE
        move.b  $4(a1),d0                       ; 08BD2
        andi.b  #$c0,d0                         ; 08BD6
        bne.b   l_08C02                         ; 08BDA
        move.b  (a1),d0                         ; 08BDC
        subi.b  #$40,d0                         ; 08BDE
        cmp.b   #$3d,d0                         ; 08BE2
        bhi.b   l_08C02                         ; 08BE6
        btst    #$0,d0                          ; 08BE8
        bne.b   l_08BF4                         ; 08BEC
        addi.w  #$10,g_ArthurX(a6)              ; 08BEE
l_08BF4:
        moveq   #-15,d0                         ; 08BF4
        and.w   g_ArthurX(a6),d0                ; 08BF6
        move.w  d0,g_ArthurX(a6)                ; 08BFA
        st.b    d0                              ; 08BFE
        rts                                     ; 08C00
l_08C02:
        clr.b   d0                              ; 08C02
        rts                                     ; 08C04

;---------------------------------------------------------------------------
; Arthur's animations. Each table has offsets to the facing-right and facing-left scripts;
; ArthurSetAnim picks one by g_ArthurFacing. Frame numbers (sprite frames, tracks 33-36):
;   0-3 walk  4 stand  5 jump forward  6 jump up  7 crouch  8-9 throw  10-11 throw crouching
;   12 climb  13-14 top of a ladder  15 and 37-39 frog  31 knocked back (armour gone)
;   32-36 skeleton (dying)
; ~n is the mirrored copy of frame n (built at start-up). ArthurAnimate adds 16 to frames
; 0-15 when he has lost his armour (the frames in his underwear).
;---------------------------------------------------------------------------
ArthurAnims:
	dc.w	ArthurAnims_R-*,ArthurAnims_L-*	; facing right, facing left
ArthurAnims_R:
	AFRAME	4,4
ArthurAnims_R_2:
	AFRAME	0,4
	AFRAME	1,4
	AFRAME	2,4
	AFRAME	3,4
	AFRAME	2,4
	ALOOP	1,4,ArthurAnims_R_2
ArthurAnims_L:
	AFRAME	~4,4
ArthurAnims_L_2:
	AFRAME	~0,4
	AFRAME	~1,4
	AFRAME	~2,4
	AFRAME	~3,4
	AFRAME	~2,4
	ALOOP	~1,4,ArthurAnims_L_2
ArthurAnimFrog:
	dc.w	ArthurAnimFrog_R-*,ArthurAnimFrog_L-*	; facing right, facing left
ArthurAnimFrog_R:
	AFRAME	37,5
	AFRAME	38,4
	AFRAME	39,4
	ALOOP	15,5,ArthurAnimFrog_R
ArthurAnimFrog_L:
	AFRAME	~37,5
	AFRAME	~38,4
	AFRAME	~39,4
	ALOOP	~15,5,ArthurAnimFrog_L
ArthurAnimJump:
	dc.w	ArthurAnimJump_R-*,ArthurAnimJump_L-*	; facing right, facing left
ArthurAnimJump_R:
	ALOOP	6,127,ArthurAnimJump_R
ArthurAnimJump_L:
	ALOOP	~6,127,ArthurAnimJump_L
ArthurAnimJumpFwd:
	dc.w	ArthurAnimJumpFwd_R-*,ArthurAnimJumpFwd_L-*	; facing right, facing left
ArthurAnimJumpFwd_R:
	ALOOP	5,127,ArthurAnimJumpFwd_R
ArthurAnimJumpFwd_L:
	ALOOP	~5,127,ArthurAnimJumpFwd_L
ArthurAnimFrogJump:
	dc.w	ArthurAnimFrogJump_R-*,ArthurAnimFrogJump_L-*	; facing right, facing left
ArthurAnimFrogJump_R:
	AFRAME	39,18
	AFRAME	38,5
	ALOOP	37,127,ArthurAnimFrogJump_R
ArthurAnimFrogJump_L:
	AFRAME	~39,18
	AFRAME	~38,5
	ALOOP	~37,127,ArthurAnimFrogJump_L
ArthurAnimCrouch:
	dc.w	ArthurAnimCrouch_R-*,ArthurAnimCrouch_L-*	; facing right, facing left
ArthurAnimCrouch_R:
	ALOOP	7,127,ArthurAnimCrouch_R
ArthurAnimCrouch_L:
	ALOOP	~7,127,ArthurAnimCrouch_L
ArthurAnimThrow:
	dc.w	ArthurAnimThrow_R-*,ArthurAnimThrow_L-*	; facing right, facing left
ArthurAnimThrow_R:
	AFRAME	8,3
	ALOOP	9,127,ArthurAnimThrow_R
ArthurAnimThrow_L:
	AFRAME	~8,3
	ALOOP	~9,127,ArthurAnimThrow_L
ArthurAnimThrowCrouch:
	dc.w	ArthurAnimThrowCrouch_R-*,ArthurAnimThrowCrouch_L-*	; facing right, facing left
ArthurAnimThrowCrouch_R:
	AFRAME	10,3
	ALOOP	11,127,ArthurAnimThrowCrouch_R
ArthurAnimThrowCrouch_L:
	AFRAME	~10,3
	ALOOP	~11,127,ArthurAnimThrowCrouch_L
ArthurAnimClimb:
	AFRAME	12,4
	ALOOP	~12,4,ArthurAnimClimb
ArthurAnimLadderTop1:
	ALOOP	13,127,ArthurAnimLadderTop1
ArthurAnimLadderTop2:
	ALOOP	14,127,ArthurAnimLadderTop2
ArthurAnimKnockback:
	dc.w	ArthurAnimKnockback_R-*,ArthurAnimKnockback_L-*	; facing right, facing left
ArthurAnimKnockback_R:
	ALOOP	31,127,ArthurAnimKnockback_R
ArthurAnimKnockback_L:
	ALOOP	~31,127,ArthurAnimKnockback_L
ArthurAnimKnockbackBare:
	dc.w	ArthurAnimKnockbackBare_R-*,ArthurAnimKnockbackBare_L-*	; facing right, facing left
ArthurAnimKnockbackBare_R:
	AFRAME	31,2
	ALOOP	32,2,ArthurAnimKnockbackBare_R
ArthurAnimKnockbackBare_L:
	AFRAME	~31,2
	ALOOP	~32,2,ArthurAnimKnockbackBare_L
ArthurAnimDie1:
	dc.w	ArthurAnimDie1_R-*,ArthurAnimDie1_L-*	; facing right, facing left
ArthurAnimDie1_R:
	AFRAME	33,8
	ALOOP	34,127,ArthurAnimDie1_R
ArthurAnimDie1_L:
	AFRAME	~33,8
	ALOOP	~34,127,ArthurAnimDie1_L
ArthurAnimDie2:
	dc.w	ArthurAnimDie2_R-*,ArthurAnimDie2_L-*	; facing right, facing left
ArthurAnimDie2_R:
	AFRAME	35,32
	ALOOP	36,127,ArthurAnimDie2_R
ArthurAnimDie2_L:
	AFRAME	~35,32
	ALOOP	~36,127,ArthurAnimDie2_L

;---------------------------------------------------------------------------
; Award a life at 20000, 70000, then every 70000 (BCD compare)
;---------------------------------------------------------------------------
ExtraLifeCheck:
        move.l  g_Score(a6),d0                  ; 08CE4
        cmpi.b  #$1,g_ExtraLives(a6)            ; 08CE8
        beq.b   l_08D0E                         ; 08CEE
        bcs.b   l_08D04                         ; 08CF0
        cmp.l   g_NextExtraLife(a6),d0          ; 08CF2
        blt.b   l_08D02                         ; 08CF6
        addi.l  #$70000,g_NextExtraLife(a6)     ; 08CF8
        bra.b   l_08D22                         ; 08D00
l_08D02:
        rts                                     ; 08D02
l_08D04:
        cmp.l   #$20000,d0                      ; 08D04
        bge.b   l_08D22                         ; 08D0A
        rts                                     ; 08D0C
l_08D0E:
        cmp.l   #$70000,d0                      ; 08D0E
        blt.b   l_08D20                         ; 08D14
        move.l  #$140000,g_NextExtraLife(a6)    ; 08D16
        bra.b   l_08D22                         ; 08D1E
l_08D20:
        rts                                     ; 08D20
l_08D22:
        addq.b  #$1,g_ExtraLives(a6)            ; 08D22
        addq.b  #$1,g_Lives(a6)                 ; 08D26
        bsr.w   DrawLives                       ; 08D2A
        moveq   #SFX_EXTRA_LIFE,d0              ; 08D2E  [1MB]   << changed from the 512K build ($08CD4: moveq #$37, d0) >>
        bsr.w   PlaySfx                         ; 08D30  [1MB] effect 14: extra life  << 1MB only: 1 instruction(s) not in the 512K build >>
        rts                                     ; 08D34

;---------------------------------------------------------------------------
; Per enemy type, 8 bytes: x offset, width, y offset, height (standing)
;---------------------------------------------------------------------------
EnemyContactBoxes:
	dc.w	14,28,14,28	; E_WOODYPIG
	dc.w	10,20,8,16	; E_CROW
	dc.w	9,18,10,20	; E_PETITEDEVIL
	dc.w	10,20,20,40	; E_FLYINGKNIGHT
	dc.w	10,20,8,16	; E_BLUEKILLER
	dc.w	16,32,19,38	; E_REDARREMER
	dc.w	23,46,27,54	; E_SATAN
	dc.w	30,60,30,60	; E_MAGICIAN
	dc.w	23,46,30,60	; E_UNICORN
	dc.w	18,36,17,34	; E_SKELETON
	dc.w	14,28,17,34	; E_BIGMAN
	dc.w	9,18,19,38	; E_ZOMBIE
	dc.w	17,34,11,22	; E_DRAGON
	dc.w	30,60,38,76	; E_ASTAROTH
	dc.w	8,16,34,68	; E_FIRE
	dc.w	0,0,0,0	; E_PRINCESS
	dc.w	10,20,14,28	; E_TYPE16
	dc.w	10,20,14,28	; E_PLANT
	dc.w	18,36,40,80	; E_FIREPILLAR

;---------------------------------------------------------------------------
; The same while Arthur crouches
;---------------------------------------------------------------------------
EnemyContactBoxesCrouch:
	dc.w	15,30,15,24	; E_WOODYPIG
	dc.w	11,22,9,12	; E_CROW
	dc.w	9,18,10,14	; E_PETITEDEVIL
	dc.w	11,22,21,36	; E_FLYINGKNIGHT
	dc.w	11,22,9,12	; E_BLUEKILLER
	dc.w	17,34,19,32	; E_REDARREMER
	dc.w	25,50,28,50	; E_SATAN
	dc.w	31,62,31,56	; E_MAGICIAN
	dc.w	24,48,31,56	; E_UNICORN
	dc.w	19,38,18,30	; E_SKELETON
	dc.w	15,30,18,30	; E_BIGMAN
	dc.w	9,18,19,32	; E_ZOMBIE
	dc.w	18,36,16,26	; E_DRAGON
	dc.w	31,62,39,72	; E_ASTAROTH
	dc.w	8,16,34,62	; E_FIRE
	dc.w	0,0,0,-6	; E_PRINCESS
	dc.w	10,20,14,22	; E_TYPE16
	dc.w	10,20,14,22	; E_PLANT
	dc.w	18,36,40,74	; E_FIREPILLAR

;---------------------------------------------------------------------------
; Enemy bodies against Arthur (boxes per enemy type: EnemyContactBoxes, smaller when he
; crouches). Skipped while he flashes or is already hit. Fire (type 14) only hurts at its full
; flare (size class 10). A touch knocks him back (g_ArthurState 1, pushed away from the enemy),
; except with the cheat on once his armour is gone.
;---------------------------------------------------------------------------
EnemyVsArthur:
        tst.b   g_ArthurFlash(a6)               ; 08E66
        bne.b   l_08EEA                         ; 08E6A
        tst.b   g_ArthurState(a6)               ; 08E6C
