;---------------------------------------------------------------------------
; Enemy shots against Arthur. Shot type 0 (the Magician's spell) turns him into a frog
; (g_FrogTimer = 8); any other hits him (g_ArthurState 1), except when the cheat is on
; and g_NoArmour is set. A shot that hits is removed. Skipped while Arthur flashes or is
; already hit; crouching uses the smaller box table.
;---------------------------------------------------------------------------
EnemyShotsVsArthur:
        tst.b   g_ArthurFlash(a6)               ; 08FAC  not while flashing or already hit
        bne.w   l_0905E                         ; 08FB0
        tst.b   g_ArthurState(a6)               ; 08FB4
        bne.w   l_0905E                         ; 08FB8
        lea.l   EnemyShotBoxes(pc),a1           ; 08FBC  boxes by enemy-shot type (smaller set while crouching)
        tst.b   g_Crouching(a6)                 ; 08FC0
        beq.b   l_08FCA                         ; 08FC4
        lea.l   EnemyShotBoxesCrouch(pc),a1     ; 08FC6
l_08FCA:
        lea.l   g_EnemyShots(a6),a5             ; 08FCA
        moveq   #$5,d7                          ; 08FCE
l_08FD0:
        move.b  (a5),d0                         ; 08FD0  each active, on-screen enemy shot
        and.b   O_OnScreen(a5),d0               ; 08FD2
        beq.b   l_09056                         ; 08FD6
        move.b  O_Type(a5),d0                   ; 08FD8
        ext.w   d0                              ; 08FDC
        lsl.w   #$3,d0                          ; 08FDE
        lea.l   (a1,d0.w),a0                    ; 08FE0
        move.w  O_X(a5),d0                      ; 08FE4  X inside the box? d1 = side it came from (knock-back direction)
        sub.w   g_ArthurX(a6),d0                ; 08FE8
        add.w   (a0)+,d0                        ; 08FEC
        cmp.w   (a0)+,d0                        ; 08FEE
        bhi.b   l_09056                         ; 08FF0
        moveq   #-1,d1                          ; 08FF2
        sub.w   -$4(a0),d0                      ; 08FF4
        bmi.b   l_08FFC                         ; 08FF8
        moveq   #$1,d1                          ; 08FFA
l_08FFC:
        move.w  O_Y(a5),d0                      ; 08FFC  Y inside the box?
        sub.w   g_ArthurY(a6),d0                ; 09000
        add.w   (a0)+,d0                        ; 09004
        cmp.w   (a0)+,d0                        ; 09006
        bhi.b   l_09056                         ; 09008
        tst.b   O_Type(a5)                      ; 0900A  type 0: the frog spell
        bne.b   l_0902C                         ; 0900E
        move.b  #$8,g_FrogTimer(a6)             ; 09010
        clr.b   g_OnLadder(a6)                  ; 09016
        clr.b   g_FireCooldown(a6)              ; 0901A
        clr.b   g_Crouching(a6)                 ; 0901E
        lea.l   ArthurAnimFrog(pc),a1           ; 09022
        bsr.w   ArthurSetAnim                   ; 09026
        bra.b   l_09042                         ; 0902A
l_0902C:
        tst.b   g_CheatOn(a6)                   ; 0902C  cheat on and no armour: no harm
        beq.b   l_09038                         ; 09030
        tst.b   g_NoArmour(a6)                  ; 09032
        bne.b   l_09056                         ; 09036
l_09038:
        move.b  #AS_HIT,g_ArthurState(a6)       ; 09038  hit: knocked back away from the shot
        move.b  d1,g_ArthurDir(a6)              ; 0903E
l_09042:
        move.b  #$2,(a5)                        ; 09042  the shot is used up
        move.b  #ST_KILLED,O_State(a5)          ; 09046
        clr.b   O_Step(a5)                      ; 0904C
        clr.b   O_Step2(a5)                     ; 09050
        bra.b   l_0905E                         ; 09054
l_09056:
        lea.l   $1c(a5),a5                      ; 09056
        dbra    d7,l_08FD0                      ; 0905A
l_0905E:
        rts                                     ; 0905E

