        bne.b   l_093BC                         ; 093B6
        addq.b  #$1,O_Step(a5)                  ; 093B8
l_093BC:
        rts                                     ; 093BC

;---------------------------------------------------------------------------
; Ballistic fall (torch, axe): X += vx (slowing by $BA1 a frame to 0), Y -= vy
; (vy growing by $FF0 a frame up to 5 px). Ends with ObjectMapCollide: Z set = landed.
;---------------------------------------------------------------------------
ShotArcMove:
        move.l  Shot_VX(a5),d0                  ; 093BE
        cmpi.b  #$1,O_Dir(a5)                   ; 093C2
        beq.b   l_093CC                         ; 093C8
        neg.l   d0                              ; 093CA
l_093CC:
        add.l   d0,O_X(a5)                      ; 093CC
        move.l  Shot_VY(a5),d0                  ; 093D0
        sub.l   d0,O_Y(a5)                      ; 093D4
        subi.l  #$ba1,Shot_VX(a5)               ; 093D8
        bpl.b   l_093E6                         ; 093E0
        clr.l   Shot_VX(a5)                     ; 093E2
l_093E6:
        cmpi.l  #$50000,Shot_VY(a5)             ; 093E6
        bcc.b   l_093F8                         ; 093EE
        addi.l  #$ff0,Shot_VY(a5)               ; 093F0
l_093F8:
        bsr.w   Animate                         ; 093F8
        bra.w   ObjectMapCollide                ; 093FC
