;---------------------------------------------------------------------------
; Per enemy type, 8 bytes: x offset.w, width.w, y offset.w, height.w
;---------------------------------------------------------------------------
EnemyHitboxes:
	dc.w	12,24,16,32	; E_WOODYPIG
	dc.w	12,24,16,24	; E_CROW
	dc.w	12,24,10,20	; E_PETITEDEVIL
	dc.w	12,24,16,32	; E_FLYINGKNIGHT
	dc.w	12,24,8,16	; E_BLUEKILLER
	dc.w	10,20,13,26	; E_REDARREMER
	dc.w	16,32,16,32	; E_SATAN
	dc.w	12,24,13,26	; E_MAGICIAN
	dc.w	16,32,21,42	; E_UNICORN
	dc.w	12,24,12,24	; E_SKELETON
	dc.w	14,28,14,28	; E_BIGMAN
	dc.w	12,24,18,28	; E_ZOMBIE
	dc.w	12,24,10,20	; E_DRAGON
	dc.w	10,20,9,18	; E_ASTAROTH
	dc.w	12,24,8,16	; E_FIRE
	dc.w	12,24,8,16	; E_PRINCESS
	dc.w	12,24,8,16	; E_TYPE16
	dc.w	12,24,16,32	; E_PLANT
	dc.w	12,24,24,48	; E_FIREPILLAR

;---------------------------------------------------------------------------
; Per enemy type: bitmask of weapon types that can hurt it (bit n = weapon n). Astaroth: cross only; Fire: nothing.
;---------------------------------------------------------------------------
EnemyVulnerability:
	dc.b	%00011111	; E_WOODYPIG: torch, lance, axe, cross, dagger
	dc.b	%00011111	; E_CROW: torch, lance, axe, cross, dagger
	dc.b	%00011111	; E_PETITEDEVIL: torch, lance, axe, cross, dagger
	dc.b	%00011111	; E_FLYINGKNIGHT: torch, lance, axe, cross, dagger
	dc.b	%00011111	; E_BLUEKILLER: torch, lance, axe, cross, dagger
	dc.b	%00011111	; E_REDARREMER: torch, lance, axe, cross, dagger
	dc.b	%00011111	; E_SATAN: torch, lance, axe, cross, dagger
	dc.b	%00011111	; E_MAGICIAN: torch, lance, axe, cross, dagger
	dc.b	%00011111	; E_UNICORN: torch, lance, axe, cross, dagger
	dc.b	%00011111	; E_SKELETON: torch, lance, axe, cross, dagger
	dc.b	%00011111	; E_BIGMAN: torch, lance, axe, cross, dagger
	dc.b	%00011111	; E_ZOMBIE: torch, lance, axe, cross, dagger
	dc.b	%00011111	; E_DRAGON: torch, lance, axe, cross, dagger
	dc.b	%00001000	; E_ASTAROTH: cross
	dc.b	%00000000	; E_FIRE: nothing
	dc.b	%00011111	; E_PRINCESS: torch, lance, axe, cross, dagger
	dc.b	%00011111	; E_TYPE16: torch, lance, axe, cross, dagger
	dc.b	%00011111	; E_PLANT: torch, lance, axe, cross, dagger
	dc.b	%00011111	; E_FIREPILLAR: torch, lance, axe, cross, dagger
	dc.b	31	; pad

;---------------------------------------------------------------------------
; EnemyHitByShot - test Arthur's shots against enemy a5.
; Hitbox from EnemyHitboxes; Astaroth (type 13) can only be hit within +-9 px of his
; centre line. If the weapon's bit is clear in EnemyVulnerability the shot bounces off.
; Otherwise O_HP is decremented; at 0 the enemy dies (state 2) and EnemyPoints is
; awarded. The CROSS (weapon 3) is not used up when it kills an enemy - it carries on.
;---------------------------------------------------------------------------
EnemyHitByShot:
        lea.l   EnemyVulnerability(pc),a1       ; 09638  weapon bitmask and hit box of this enemy type
        clr.w   d0                              ; 0963C
        move.b  O_Type(a5),d0                   ; 0963E
        adda.w  d0,a1                           ; 09642
        lea.l   EnemyHitboxes(pc),a0            ; 09644
        lsl.w   #$3,d0                          ; 09648
        adda.w  d0,a0                           ; 0964A
        lea.l   g_Shots(a6),a4                  ; 0964C
        moveq   #$3,d6                          ; 09650
l_09652:
        move.b  (a4),d0                         ; 09652  each of Arthur's active, on-screen shots
        and.b   $1(a4),d0                       ; 09654
        beq.w   l_0974A                         ; 09658
        cmpi.b  #E_ASTAROTH,O_Type(a5)          ; 0965C  Astaroth: within 32 px, and only a 9-px band either side of his centre
        bne.b   l_096A0                         ; 09662
        move.w  O_X(a5),d0                      ; 09664
        sub.w   $6(a4),d0                       ; 09668
        addi.w  #$20,d0                         ; 0966C
        cmp.w   #$40,d0                         ; 09670
        bhi.w   l_0974A                         ; 09674
        move.w  O_Y(a5),d0                      ; 09678
        sub.w   $a(a4),d0                       ; 0967C
        addi.w  #$20,d0                         ; 09680
        cmp.w   #$40,d0                         ; 09684
        bhi.w   l_0974A                         ; 09688
        move.w  O_Y(a5),d0                      ; 0968C  outside the band: deflected
        sub.w   $a(a4),d0                       ; 09690
        addi.w  #$9,d0                          ; 09694
        cmp.w   #$12,d0                         ; 09698
        bcc.w   l_09736                         ; 0969C
l_096A0:
        move.w  O_X(a5),d0                      ; 096A0  inside the hit box?
        sub.w   $6(a4),d0                       ; 096A4
        add.w   (a0),d0                         ; 096A8
        cmp.w   $2(a0),d0                       ; 096AA
        bhi.w   l_0974A                         ; 096AE
        move.w  O_Y(a5),d0                      ; 096B2
        sub.w   $a(a4),d0                       ; 096B6
        add.w   $4(a0),d0                       ; 096BA
        cmp.w   $6(a0),d0                       ; 096BE
        bhi.w   l_0974A                         ; 096C2
        moveq   #$0,d0                          ; 096C6  weapon bit set in EnemyVulnerability?
        move.b  $1a(a4),d0                      ; 096C8
        btst    d0,(a1)                         ; 096CC
        beq.b   l_09736                         ; 096CE
        tst.b   (a5)                            ; 096D0  active byte bit 7: shots pass through (deflected)
        bmi.b   l_09736                         ; 096D2
        tst.b   O_HP(a5)                        ; 096D4  hit points (0 counts as 1)
        beq.b   l_096E8                         ; 096D8
        subq.b  #$1,O_HP(a5)                    ; 096DA
        beq.b   l_096E8                         ; 096DE
        move.b  #$1,O_Param(a5)                 ; 096E0  hurt, not dead: O_Param = 1 (hit reaction)
        bra.b   l_09716                         ; 096E6
l_096E8:
        move.b  O_Type(a5),d0                   ; 096E8  killed: points, state 2
        move.b  EnemyPoints(pc,d0.w),d0         ; 096EC
        bsr.w   AddScore                        ; 096F0
        move.b  #$2,(a5)                        ; 096F4
        move.b  #ST_KILLED,O_State(a5)          ; 096F8
        clr.b   O_Step(a5)                      ; 096FE
        clr.b   O_Step2(a5)                     ; 09702
        cmpi.b  #E_ASTAROTH,O_Type(a5)          ; 09706
        beq.b   l_09716                         ; 0970C
        cmpi.b  #$3,$1a(a4)                     ; 0970E  the cross carries on after a kill (except on Astaroth)
        beq.b   l_0974A                         ; 09714
l_09716:
        move.b  #$2,(a4)                        ; 09716  the shot ends: step 0 normally, 3 (a hit spark) if the enemy survived
        move.b  #$2,$3(a4)                      ; 0971A
        clr.b   $4(a4)                          ; 09720
        clr.b   $5(a4)                          ; 09724
        tst.b   O_HP(a5)                        ; 09728
        beq.b   l_0974A                         ; 0972C
        move.b  #$3,$4(a4)                      ; 0972E
        bra.b   l_0974A                         ; 09734
l_09736:
        move.b  #$2,(a4)                        ; 09736  deflected: the enemy is immune to this weapon or shots pass through it
        move.b  #$2,$3(a4)                      ; 0973A
        move.b  #$1,$4(a4)                      ; 09740
        clr.b   $5(a4)                          ; 09746
l_0974A:
        lea.l   $26(a4),a4                      ; 0974A
        dbra    d6,l_09652                      ; 0974E
        rts                                     ; 09752

;---------------------------------------------------------------------------
; Per enemy type: AddScore index awarded when its hit points run out
;---------------------------------------------------------------------------
EnemyPoints:
	dc.b	3	; E_WOODYPIG: 100
	dc.b	3	; E_CROW: 100
	dc.b	3	; E_PETITEDEVIL: 100
	dc.b	3	; E_FLYINGKNIGHT: 100
	dc.b	3	; E_BLUEKILLER: 100
	dc.b	9	; E_REDARREMER: 1000
	dc.b	11	; E_SATAN: 3000
	dc.b	10	; E_MAGICIAN: 2000
	dc.b	10	; E_UNICORN: 2000
	dc.b	3	; E_SKELETON: 100
	dc.b	7	; E_BIGMAN: 500
	dc.b	4	; E_ZOMBIE: 200
	dc.b	4	; E_DRAGON: 200
	dc.b	18	; E_ASTAROTH: 10000
	dc.b	3	; E_FIRE: 100
	dc.b	3	; E_PRINCESS: 100
	dc.b	3	; E_TYPE16: 100
	dc.b	3	; E_PLANT: 100
	dc.b	3	; E_FIREPILLAR: 100
	dc.b	0	; pad

;---------------------------------------------------------------------------
; ShotsVsEnemyShots - Arthur's shots against enemy shots.
;  Without the cross only fire-pillar shots (type 5) collide, and only Arthur's shot is
;  stopped. With the cross every enemy shot except the frog spell (0) and Astaroth's (10)
;  collides, and both shots are destroyed.
;  BUG: the box pointer a0 is set once per enemy shot and advanced by each test, so after
;  a miss the next of Arthur's shots is tested against the following words of the table
;  (another type's box). With one shot on screen it makes no difference.
;---------------------------------------------------------------------------
ShotsVsEnemyShots:
        lea.l   g_EnemyShots(a6),a1             ; 09768
        moveq   #$5,d7                          ; 0976C
l_0976E:
        move.b  (a1),d0                         ; 0976E
        and.b   $1(a1),d0                       ; 09770
        beq.w   l_09804                         ; 09774
        moveq   #$0,d1                          ; 09778  d1 = 0 no collision, 1 Arthur's shot stops, 2 both destroyed
        move.b  $1a(a1),d0                      ; 0977A
        cmpi.w  #$3,g_Weapon(a6)                ; 0977E
        beq.b   l_09790                         ; 09784
        cmp.b   #$5,d0                          ; 09786  not the cross: only fire-pillar shots
        bne.b   l_0979C                         ; 0978A
        moveq   #$1,d1                          ; 0978C
        bra.b   l_0979C                         ; 0978E
l_09790:
        tst.b   d0                              ; 09790  cross: all but the frog spell and Astaroth's shots
        beq.b   l_0979C                         ; 09792
        cmp.b   #$a,d0                          ; 09794
        beq.b   l_0979C                         ; 09798
        moveq   #$2,d1                          ; 0979A
l_0979C:
        tst.b   d1                              ; 0979C
        beq.b   l_09804                         ; 0979E
        ext.w   d0                              ; 097A0  box for this enemy-shot type (a0 advances through it below)
        lsl.w   #$3,d0                          ; 097A2
        lea.l   EnemyShotBlockBoxes(pc,d0.w),a0 ; 097A4
        lea.l   g_Shots(a6),a2                  ; 097A8
        moveq   #$3,d6                          ; 097AC
l_097AE:
        move.b  (a2),d0                         ; 097AE
        and.b   $1(a2),d0                       ; 097B0
        beq.b   l_097FC                         ; 097B4
        move.w  $6(a1),d0                       ; 097B6  X test
        sub.w   $6(a2),d0                       ; 097BA
        add.w   (a0)+,d0                        ; 097BE
        cmp.w   (a0)+,d0                        ; 097C0
        bhi.b   l_097FC                         ; 097C2
        move.w  $a(a1),d0                       ; 097C4  Y test
        sub.w   $a(a2),d0                       ; 097C8
        add.w   (a0)+,d0                        ; 097CC
        cmp.w   (a0)+,d0                        ; 097CE
        bhi.b   l_097FC                         ; 097D0
        subq.b  #$1,d1                          ; 097D2
        beq.b   l_097E8                         ; 097D4
        move.b  #$2,(a1)                        ; 097D6  cross: the enemy shot is destroyed too
        move.b  #$2,$3(a1)                      ; 097DA
        clr.b   $4(a1)                          ; 097E0
        clr.b   $5(a1)                          ; 097E4
l_097E8:
        move.b  #$2,(a2)                        ; 097E8  Arthur's shot: state 2, step 1
        move.b  #$2,$3(a2)                      ; 097EC
        move.b  #$1,$4(a2)                      ; 097F2
        clr.b   $5(a2)                          ; 097F8
l_097FC:
        lea.l   $26(a2),a2                      ; 097FC
        dbra    d6,l_097AE                      ; 09800
l_09804:
        lea.l   $1c(a1),a1                      ; 09804
        dbra    d7,l_0976E                      ; 09808
        rts                                     ; 0980C

;---------------------------------------------------------------------------
; Boxes for Arthur's shots against enemy shots, per enemy-shot type (ShotsVsEnemyShots).
; Only types 0-11 exist; entries 12-18 are never used.
;---------------------------------------------------------------------------
EnemyShotBlockBoxes:
	dc.w	12,24,8,16	; enemy shot type 0
	dc.w	12,24,8,16	; enemy shot type 1
	dc.w	12,24,8,16	; enemy shot type 2
	dc.w	12,24,8,16	; enemy shot type 3
	dc.w	12,24,8,16	; enemy shot type 4
	dc.w	12,24,13,24	; enemy shot type 5
	dc.w	16,32,16,32	; enemy shot type 6
	dc.w	12,24,13,26	; enemy shot type 7
	dc.w	16,32,16,32	; enemy shot type 8
	dc.w	12,24,12,24	; enemy shot type 9
	dc.w	5,10,5,10	; enemy shot type 10
	dc.w	12,24,12,24	; enemy shot type 11
	dc.w	12,24,8,16	; enemy shot type 12
	dc.w	10,20,8,16	; enemy shot type 13
	dc.w	12,24,8,16	; enemy shot type 14
	dc.w	12,24,8,16	; enemy shot type 15
	dc.w	12,24,8,16	; enemy shot type 16
	dc.w	12,24,8,16	; enemy shot type 17
	dc.w	12,24,24,48	; enemy shot type 18

;---------------------------------------------------------------------------
; Arthur's shots against shootable scenery (item type 1, gravestones): the shot is
; stopped (deflected), and every hit counts down the item's counter (+$1B, 15 at level
; start). When it runs out, the Magician's spawner is started at the gravestone
; (g_SceneryHitX/Y, 16 px higher).
;---------------------------------------------------------------------------
ShotsVsScenery:
        lea.l   g_Items(a6),a1                  ; 098A6
        moveq   #$1d,d7                         ; 098AA
l_098AC:
        move.b  (a1),d0                         ; 098AC
        and.b   $1(a1),d0                       ; 098AE
        beq.w   l_09954                         ; 098B2
        cmpi.b  #$1,$1a(a1)                     ; 098B6
        bne.w   l_09954                         ; 098BC
        tst.b   $1b(a1)                         ; 098C0
        beq.w   l_09954                         ; 098C4
        lea.l   g_Shots(a6),a2                  ; 098C8
        moveq   #$3,d6                          ; 098CC
l_098CE:
        move.b  (a2),d0                         ; 098CE
        and.b   $1(a2),d0                       ; 098D0
        beq.b   l_0994C                         ; 098D4
        move.w  $6(a1),d0                       ; 098D6
        sub.w   $6(a2),d0                       ; 098DA
        addi.w  #$e,d0                          ; 098DE
