;---------------------------------------------------------------------------
; QueueExplosionDraw - a dying enemy's explosion. While the frame is below $1B the frame
; from EffectFrames ($1B4CC graphics) is queued as a grid of 16 x 16 tiles around the
; enemy, by size class: below 4 a 2 x 2 square, 4 a 3 x 3, above 4 a 4 x 4 (walked as a
; snake, each step moving the last position by 16 px). From frame $1B on (the final puff,
; EnemyDie_Anim) it is drawn once, as a normal object.
;---------------------------------------------------------------------------
QueueExplosionDraw:
        cmpi.b  #$1b,O_Frame(a5)                ; 0A020  the final puff: one BOB
        bcc.w   QueueObjectDraw                 ; 0A026
        lea.l   BoxSizeTable(pc),a1             ; 0A02A  (BoxSizeTable is looked up but not used)
        clr.w   d0                              ; 0A02E
        move.b  O_Size(a5),d0                   ; 0A030
        add.w   d0,d0                           ; 0A034
        adda.w  d0,a1                           ; 0A036
        move.w  O_X(a5),d1                      ; 0A038
        move.w  O_Y(a5),d2                      ; 0A03C
        move.w  #$10,d3                         ; 0A040  one 16 x 16 tile, centred on the enemy
        moveq   #$10,d4                         ; 0A044
        move.w  d3,d0                           ; 0A046
        lsr.w   #$1,d0                          ; 0A048
        sub.w   d0,d1                           ; 0A04A
        move.w  d4,d0                           ; 0A04C
        lsr.w   #$1,d0                          ; 0A04E
        sub.w   d0,d2                           ; 0A050
        lea.l   (ITEM_GFX_BUF).l,a1             ; 0A052  explosion graphics + this frame
        lea.l   EffectFrames(pc),a2             ; 0A058
        move.b  O_Frame(a5),d0                  ; 0A05C
        ext.w   d0                              ; 0A060
        add.w   d0,d0                           ; 0A062
        add.w   d0,d0                           ; 0A064
        adda.w  d0,a2                           ; 0A066
        adda.w  (a2),a1                         ; 0A068
        moveq   #$10,d0                         ; 0A06A  grid step 16 px
        cmpi.b  #$4,O_Size(a5)                  ; 0A06C  size class 4: 3 x 3; above: 4 x 4
        beq.b   l_0A0B8                         ; 0A072
        bhi.w   l_0A148                         ; 0A074
        movea.l g_BlitListPtr(a6),a0            ; 0A078  2 x 2
        move.l  a1,-(a0)                        ; 0A07C
        movem.w d1-d4,-(a0)                     ; 0A07E
        move.l  a0,g_BlitListPtr(a6)            ; 0A082
