;---------------------------------------------------------------------------
; QueueEnemyDraw - queue enemy a5 for DrawBobs.
; Dying enemies (state 2) are drawn as an explosion (QueueExplosionDraw) during the step
; that shows it; removed ones (state 3) not at all. Position = O_X/O_Y less half the
; BoxSizeTable size; graphics = g_BobSets[type] (the Crow / bat uses the bat or red-crow
; set by O_Param) + the frame's offset from BobFrameDescs, whose entries are
; (offset.w, y adjust.b, height.b). The Unicorn (type 8) is two BOBs: body
; (48 x 32, frame / 8 + 8) and legs (48 x 16, frame & 7).
;---------------------------------------------------------------------------
QueueEnemyDraw:
        cmpi.b  #ST_KILLED,O_State(a5)          ; 0A248  dying: explosion; removed: nothing
        bcs.b   l_0A27E                         ; 0A24E
        bhi.b   l_0A27C                         ; 0A250
        cmpi.b  #E_DRAGON,O_Type(a5)            ; 0A252  Dragon: during its steps 2 and 5
        bne.b   l_0A26C                         ; 0A258
        cmpi.b  #$2,O_Step(a5)                  ; 0A25A
        beq.b   l_0A274                         ; 0A260
        cmpi.b  #$5,O_Step(a5)                  ; 0A262
        beq.b   l_0A274                         ; 0A268
        bra.b   l_0A27C                         ; 0A26A
l_0A26C:
        cmpi.b  #$1,O_Step(a5)                  ; 0A26C
        bne.b   l_0A27C                         ; 0A272
l_0A274:
        tst.b   O_Step2(a5)                     ; 0A274
        bne.w   QueueExplosionDraw              ; 0A278
l_0A27C:
        rts                                     ; 0A27C
l_0A27E:
        cmpi.b  #E_UNICORN,O_Type(a5)           ; 0A27E  Unicorn: two BOBs
        beq.w   l_0A31A                         ; 0A284
        lea.l   BoxSizeTable(pc),a1             ; 0A288  box size: the BOB is centred on O_X / O_Y
