;---------------------------------------------------------------------------
; Item handlers by O_Type (placed from LevelItemLists):
;   0  touch item. Param 0 and 1 are invisible trigger points: param 0 calls a special
;      object (type 1) 100 px ahead - only if Arthur has lost his armour; param 1 calls one
;      100 px ahead and 128 px up. Param 2 / 3 are point pickups (sound 28, 200 / 500 points).
;   1  shootable scenery (gravestones etc.) - nothing to do here; see ShotsVsScenery
;   2  moving platform on a scripted path (ItemPaths / ItemPathScripts)
;   3  platform that starts moving once Arthur stands on it, until it is below the level
;   4  platform that waits until Arthur reaches X $980, then moves
;   5  solid moving block: pushes Arthur sideways and stops him jumping up through it
; A platform carries Arthur while he stands on it (its O_Frame byte is used as the rider flag, Itm_Rider, set by ArthurOnPlatform).
;---------------------------------------------------------------------------
ItemTypeTable:
        bra.w   Item_Touch                      ; 0A4A8
        bra.w   Item_Scenery                    ; 0A4AC
        bra.w   Item_Platform                   ; 0A4B0
        bra.w   Item_RidePlatform               ; 0A4B4
        bra.w   Item_WaitPlatform               ; 0A4B8
        bra.w   Item_Block                      ; 0A4BC

;---------------------------------------------------------------------------
; Arthur within 12 px across and 8 px vertically: collect / trigger
;---------------------------------------------------------------------------
Item_Touch:
        tst.b   O_State(a5)                     ; 0A4C0
        bne.b   l_0A4EE                         ; 0A4C4
        move.w  O_X(a5),d0                      ; 0A4C6
        sub.w   g_ArthurX(a6),d0                ; 0A4CA
        addi.w  #$c,d0                          ; 0A4CE
        cmp.w   #$18,d0                         ; 0A4D2
        bhi.b   l_0A4EC                         ; 0A4D6
        move.w  O_Y(a5),d0                      ; 0A4D8
        sub.w   g_ArthurY(a6),d0                ; 0A4DC
        addq.w  #$8,d0                          ; 0A4E0
        cmp.w   #$10,d0                         ; 0A4E2
        bhi.b   l_0A4EC                         ; 0A4E6
        addq.b  #$1,O_State(a5)                 ; 0A4E8
l_0A4EC:
        rts                                     ; 0A4EC
l_0A4EE:
        clr.w   d0                              ; 0A4EE
        move.b  O_Param(a5),d0                  ; 0A4F0
        add.w   d0,d0                           ; 0A4F4
        add.w   d0,d0                           ; 0A4F6
        jmp     Item_Touch_Jumps(pc,d0.w)       ; 0A4F8
Item_Touch_Jumps:
        bra.w   Item_TriggerArmour              ; 0A4FC
        bra.w   Item_TriggerCall                ; 0A500
        bra.w   Item_Coin                       ; 0A504
        bra.w   Item_MoneyBag                   ; 0A508

;---------------------------------------------------------------------------
; Param 0: no armour? call special object type 1 at X + 100
;---------------------------------------------------------------------------
Item_TriggerArmour:
        clr.b   (a5)                            ; 0A50C
        tst.b   g_NoArmour(a6)                  ; 0A50E
        beq.b   l_0A542                         ; 0A512
        lea.l   g_SpecialObjs+32(a6),a4         ; 0A514
        moveq   #$64,d0                         ; 0A518
        add.w   O_X(a5),d0                      ; 0A51A
        move.w  d0,$6(a4)                       ; 0A51E
        move.w  O_Y(a5),$a(a4)                  ; 0A522
        move.b  #$1,$1a(a4)                     ; 0A528
        clr.b   $2(a4)                          ; 0A52E
        clr.b   $3(a4)                          ; 0A532
        clr.b   $4(a4)                          ; 0A536
        clr.b   $5(a4)                          ; 0A53A
        move.b  #$1,(a4)                        ; 0A53E
l_0A542:
        rts                                     ; 0A542

;---------------------------------------------------------------------------
