	ISTEP	2,100
	ISTEP	2,110
	ISTEP	4,100
	ISTEP	4,90
	ISTEP	2,100
	ISTEP	2,60
	ISTEP	4,110
	ISTEP	2,100
	ISTEP	2,50
	ISTEP	4,80
	ILOOP	2,60,ItemScript4_0
ItemScript4_1:
