	ISTEP	4,100
	ISTEP	4,40
	ISTEP	2,90
	ISTEP	4,80
	ISTEP	4,100
	ISTEP	2,100
	ISTEP	2,110
	ISTEP	4,80
	ISTEP	2,90
	ISTEP	4,100
	ISTEP	4,80
	ISTEP	2,100
	ISTEP	4,120
	ISTEP	2,100
	ILOOP	2,80,ItemScript4_1
ItemScript4_2:
	ISTEP	4,120
	ISTEP	2,60
	ISTEP	2,70
	ISTEP	4,90
	ISTEP	2,110
	ISTEP	4,100
	ISTEP	4,90
	ISTEP	2,100
	ISTEP	2,60
	ISTEP	4,100
	ISTEP	4,100
	ISTEP	2,100
	ISTEP	2,90
	ISTEP	4,100
	ILOOP	2,110,ItemScript4_2
ItemScript4_3:
	ISTEP	2,10
	ISTEP	4,70
	ISTEP	2,90
	ISTEP	4,110
	ISTEP	4,120
	ISTEP	2,80
	ISTEP	2,110
	ISTEP	4,100
	ISTEP	4,60
