ItemScript5_0:
	ISTEP	3,71
	ISTEP	1,71
	ISTEP	1,80
	ILOOP	3,80,ItemScript5_0
ItemScript5_1:
	ISTEP	1,48
	ISTEP	3,48
	ISTEP	3,73
	ISTEP	3,73
	ISTEP	1,73
	ILOOP	1,73,ItemScript5_1
ItemScript5_2:
