;---------------------------------------------------------------------------
; Queue an item/scenery BOB: image = ItemImageTable[type][param] -> SmallBobSets
;---------------------------------------------------------------------------
DrawItem:
        lea.l   EnemyBoxClass(pc),a1            ; 0A980
        move.b  O_Type(a5),d0                   ; 0A984
        ext.w   d0                              ; 0A988
        move.b  (a1,d0.w),d0                    ; 0A98A
        lea.l   BoxSizeTable(pc),a1             ; 0A98E
        add.w   d0,d0                           ; 0A992
        adda.w  d0,a1                           ; 0A994
        clr.w   d3                              ; 0A996
        clr.w   d4                              ; 0A998
        move.b  (a1)+,d3                        ; 0A99A
        move.b  (a1)+,d4                        ; 0A99C
        move.w  O_X(a5),d1                      ; 0A99E
        move.w  d3,d0                           ; 0A9A2
        lsr.w   #$1,d0                          ; 0A9A4
        sub.w   d0,d1                           ; 0A9A6
        move.w  O_Y(a5),d2                      ; 0A9A8
        move.w  d4,d0                           ; 0A9AC
        lsr.w   #$1,d0                          ; 0A9AE
        sub.w   d0,d2                           ; 0A9B0
        lea.l   ItemImageTable(pc),a1           ; 0A9B2
        move.b  O_Type(a5),d0                   ; 0A9B6
        add.w   d0,d0                           ; 0A9BA
        adda.w  d0,a1                           ; 0A9BC
        adda.w  (a1),a1                         ; 0A9BE
        move.b  O_Param(a5),d0                  ; 0A9C0
        adda.w  d0,a1                           ; 0A9C4
        move.b  (a1),d0                         ; 0A9C6
        bmi.b   l_0A9F4                         ; 0A9C8
        lea.l   g_SmallBobSets(a6),a1           ; 0A9CA
        add.w   d0,d0                           ; 0A9CE
        add.w   d0,d0                           ; 0A9D0
        adda.w  d0,a1                           ; 0A9D2
        movea.l (a1),a1                         ; 0A9D4
        lsr.w   #$1,d0                          ; 0A9D6
        lea.l   SmallBobSizes(pc,d0.w),a2       ; 0A9D8
        add.w   d4,d2                           ; 0A9DC
        move.b  (a2)+,d0                        ; 0A9DE
        sub.w   d0,d2                           ; 0A9E0
        move.b  (a2)+,d4                        ; 0A9E2
        sub.w   d4,d2                           ; 0A9E4
        movea.l g_BlitListPtr(a6),a0            ; 0A9E6
        move.l  a1,-(a0)                        ; 0A9EA
        movem.w d1-d4,-(a0)                     ; 0A9EC
        move.l  a0,g_BlitListPtr(a6)            ; 0A9F0
l_0A9F4:
        rts                                     ; 0A9F4

;---------------------------------------------------------------------------
; y-adjust.b, height.b for each of the 10 small BOB images
;---------------------------------------------------------------------------
SmallBobSizes:
	dc.b	$03,$0D,$01,$0F,$00,$10,$00,$10,$0C,$14,$0C,$14,$0C,$14,$0B,$15
	dc.b	$02,$0E,$00,$0A

;---------------------------------------------------------------------------
; Enemy spawners (16 slots x $C at g_Spawners, slot = enemy type).
; Slot: +0 active, +1 entries left, +2 script pointer, +6 script start, +$A frames to the
; next spawn, +$B flags (bit 0 world coords, bit 1 run once, bit 2 new zones only).
; Script (SpawnScripts): count.w, then per entry x.w, y.w (camera-relative unless flag
; bit 0), param.b, delay.b. A spawn needs a free enemy slot and g_SpawnQuota[type] > 0.
; Type 7 (the Magician) appears at the last shootable scenery hit instead; zombies 128 px further
; right. Every 6th spawned enemy carries a bonus (special object 0) - see BonusKinds.
;---------------------------------------------------------------------------
UpdateSpawners:
        lea.l   g_Spawners(a6),a2               ; 0AA0A  a2 = spawner slot ($C bytes), d7 = its enemy type
        clr.w   d7                              ; 0AA0E
l_0AA10:
        tst.b   (a2)                            ; 0AA10
        beq.w   l_0AB40                         ; 0AA12
        tst.b   $1(a2)                          ; 0AA16  entries left?
        bhi.b   l_0AA4C                         ; 0AA1A
        btst    #$1,$b(a2)                      ; 0AA1C  script finished: a 'run once' spawner stops, the others start again
        seq.b   (a2)                            ; 0AA22
        bne.w   l_0AB40                         ; 0AA24
        bra.b   l_0AA3E                         ; 0AA28
	dc.b	$4A,$2A,$00,$1D,$67,$0E,$08,$2A,$00,$02,$00,$0B,$66,$06,$42,$12
	dc.b	$60,$00,$01,$04
l_0AA3E:
        movea.l $6(a2),a1                       ; 0AA3E  restart the script: count and first entry
        move.w  (a1)+,d0                        ; 0AA42
        move.b  d0,$1(a2)                       ; 0AA44
        move.l  a1,$2(a2)                       ; 0AA48
l_0AA4C:
        subq.b  #$1,$a(a2)                      ; 0AA4C  count down to the next spawn
        bne.w   l_0AB40                         ; 0AA50
        lea.l   g_Enemies(a6),a5                ; 0AA54  find a free enemy slot (none: stop for this frame)
        moveq   #$3c,d2                         ; 0AA58
        moveq   #$27,d1                         ; 0AA5A
l_0AA5C:
        tst.b   (a5)                            ; 0AA5C
        beq.b   l_0AA6A                         ; 0AA5E
        adda.w  d2,a5                           ; 0AA60
        dbra    d1,l_0AA5C                      ; 0AA62
        bra.w   l_0AB4E                         ; 0AA66
l_0AA6A:
        lea.l   g_SpawnQuota(a6),a0             ; 0AA6A  quota for this enemy type used up?
        adda.w  d7,a0                           ; 0AA6E
        tst.b   (a0)                            ; 0AA70
        beq.w   l_0AB40                         ; 0AA72
        subq.b  #$1,(a0)                        ; 0AA76
        move.b  #$1,(a5)                        ; 0AA78  new enemy: active, state 0, type = spawner number
        clr.b   O_OnScreen(a5)                  ; 0AA7C
        clr.b   O_Step2(a5)                     ; 0AA80
        clr.b   O_Step(a5)                      ; 0AA84
        clr.b   O_State(a5)                     ; 0AA88
        clr.b   O_Size(a5)                      ; 0AA8C
        clr.b   O_HP(a5)                        ; 0AA90
        clr.l   O_Anim(a5)                      ; 0AA94
        move.b  d7,O_Type(a5)                   ; 0AA98
        movea.l $2(a2),a1                       ; 0AA9C  script entry: x, y, param, frames to the next spawn
        move.w  (a1)+,d1                        ; 0AAA0
        move.w  (a1)+,d2                        ; 0AAA2
        move.b  (a1)+,O_Param(a5)               ; 0AAA4
        move.b  (a1)+,$a(a2)                    ; 0AAA8
        cmp.w   #$7,d7                          ; 0AAAC  type 7 (Magician): at the last scenery hit, spawner stops
        bne.b   l_0AABE                         ; 0AAB0
        move.w  g_SceneryHitX(a6),d1            ; 0AAB2
        move.w  g_SceneryHitY(a6),d2            ; 0AAB6
        clr.b   (a2)                            ; 0AABA
        bra.b   l_0AAE2                         ; 0AABC
l_0AABE:
        btst    #$0,$b(a2)                      ; 0AABE  flag bit 0: world coordinates; otherwise relative to the camera
        bne.b   l_0AADA                         ; 0AAC4
        cmp.b   #$b,d7                          ; 0AAC6  zombies (11): 128 px further right
        bne.b   l_0AAD0                         ; 0AACA
        addi.w  #$80,d1                         ; 0AACC
l_0AAD0:
        add.w   g_CameraX(a6),d1                ; 0AAD0
        add.w   g_CameraY(a6),d2                ; 0AAD4
        bra.b   l_0AAE2                         ; 0AAD8
l_0AADA:
        sub.w   g_LevelOriginX(a6),d1           ; 0AADA
        sub.w   g_LevelOriginY(a6),d2           ; 0AADE
l_0AAE2:
        move.w  d1,O_X(a5)                      ; 0AAE2
        move.w  d2,O_Y(a5)                      ; 0AAE6
        subq.b  #$1,g_BonusEvery(a6)            ; 0AAEA  every 6th spawn carries a bonus
        bgt.b   l_0AB38                         ; 0AAEE
        move.b  #$6,g_BonusEvery(a6)            ; 0AAF0
        lea.l   g_SpecialObjs(a6),a4            ; 0AAF6  special object 0 free? it becomes the bonus this enemy carries
        tst.b   (a4)                            ; 0AAFA
        bne.b   l_0AB38                         ; 0AAFC
        clr.b   $3(a4)                          ; 0AAFE
        clr.b   $4(a4)                          ; 0AB02
        clr.b   $5(a4)                          ; 0AB06
        move.b  #$1,(a4)                        ; 0AB0A
        clr.b   $1a(a4)                         ; 0AB0E
        move.l  a5,$e(a4)                       ; 0AB12  special object 0 follows the new enemy
