        cmp.b   #$7,d0                          ; 0AB1E
        bcs.b   l_0AB2A                         ; 0AB22
        clr.b   d0                              ; 0AB24
        clr.b   g_BonusCycle(a6)                ; 0AB26
l_0AB2A:
