        add.w   d0,d0                           ; 0AB2C
        add.w   d0,d0                           ; 0AB2E
        jsr     BonusKinds(pc,d0.w)             ; 0AB30
        move.b  d0,$2(a4)                       ; 0AB34
l_0AB38:
