;---------------------------------------------------------------------------
; Kind of bonus for the next carrier, cycling 0-6: treasure, treasure, weapon,
; treasure, kind 13, treasure, weapon. Treasure = 6 + level (kind 12 when g_BonusRoll
; carries); weapon = 1 + weapon number, picked by adding the level's weights (WeaponOddsTable) to
; the five g_WeaponOdds accumulators: the first that carries and is not Arthur's weapon.
;---------------------------------------------------------------------------
BonusKinds:
        bra.w   l_0AB6C                         ; 0AB50
        bra.w   l_0AB6C                         ; 0AB54
        bra.w   l_0AB7E                         ; 0AB58
        bra.w   l_0AB6C                         ; 0AB5C
        bra.w   l_0ABB8                         ; 0AB60
        bra.w   l_0AB6C                         ; 0AB64
        bra.w   l_0AB7E                         ; 0AB68
l_0AB6C:
        moveq   #$c,d0                          ; 0AB6C  treasure: 6 + level, or kind 12 when g_BonusRoll carries (+21 a time)
        addi.b  #$15,g_BonusRoll(a6)            ; 0AB6E
        bcs.b   l_0AB7C                         ; 0AB74
        moveq   #$6,d0                          ; 0AB76
        add.w   g_Level(a6),d0                  ; 0AB78
l_0AB7C:
        rts                                     ; 0AB7C
l_0AB7E:
        move.w  g_Level(a6),d0                  ; 0AB7E  weapon: add the level's weights to the five g_WeaponOdds accumulators
        add.w   d0,d0                           ; 0AB82
        lea.l   WeaponOddsTable(pc,d0.w),a0     ; 0AB84
        adda.w  (a0),a0                         ; 0AB88
        addq.l  #$5,a0                          ; 0AB8A
        lea.l   g_BossCountdown(a6),a3          ; 0AB8C
        clr.b   d1                              ; 0AB90
        moveq   #$4,d6                          ; 0AB92
l_0AB94:
        move.b  -(a0),d0                        ; 0AB94
        add.b   d0,-(a3)                        ; 0AB96
        addx.b  d1,d1                           ; 0AB98
        dbra    d6,l_0AB94                      ; 0AB9A
        moveq   #$0,d0                          ; 0AB9E
l_0ABA0:
        btst    d0,d1                           ; 0ABA0  the first weapon whose accumulator carried ...
        bne.b   l_0ABAE                         ; 0ABA2
        addq.w  #$1,d0                          ; 0ABA4
        cmp.w   #$5,d0                          ; 0ABA6
        bne.b   l_0ABA0                         ; 0ABAA
        bra.b   l_0AB7E                         ; 0ABAC
l_0ABAE:
        cmp.w   g_Weapon(a6),d0                 ; 0ABAE  ... unless it is Arthur's weapon: then try again
        beq.b   l_0AB7E                         ; 0ABB2
        addq.b  #$1,d0                          ; 0ABB4
        rts                                     ; 0ABB6
l_0ABB8:
        moveq   #$d,d0                          ; 0ABB8
        add.w   g_Level(a6),d0                  ; 0ABBA
        rts                                     ; 0ABBE

;---------------------------------------------------------------------------
