        bcc.b   l_0AE6C                         ; 0AE52
        lea.l   DirTab45(pc),a0                 ; 0AE54
        cmp.w   #$4b,d2                         ; 0AE58
        bcc.b   l_0AE6C                         ; 0AE5C
        lea.l   DirTabFlat(pc),a0               ; 0AE5E
