        move.b  g_RandSeed(a6),d1               ; 0AE90
        eor.b   d1,d0                           ; 0AE94
        not.b   d0                              ; 0AE96
        lsl.b   #$2,d0                          ; 0AE98
        rol.w   g_RandSeed(a6)                  ; 0AE9A
        move.w  (a7)+,d1                        ; 0AE9E
        move.b  g_RandSeed+1(a6),d0             ; 0AEA0
        rts                                     ; 0AEA4

