;---------------------------------------------------------------------------
; RestoreBackground - undo last time's BOBs in this buffer: copy each saved rectangle
; back (A->D blits) from the restore list, then reset the list
;---------------------------------------------------------------------------
RestoreBackground:
        movea.l g_RestoreListA(a6),a5           ; 0BA58
        tst.w   (a5)                            ; 0BA5C
        beq.b   l_0BAA8                         ; 0BA5E
        lea.l   CUSTOM,a2                       ; 0BA60
l_0BA66:
        btst    #$6,DMACONR(a2)                 ; 0BA66  A->D copy, no masking
        bne.b   l_0BA66                         ; 0BA6C
        move.l  #$9f00000,BLTCON0(a2)           ; 0BA6E
        moveq   #-1,d0                          ; 0BA76
        move.l  d0,BLTAFWM(a2)                  ; 0BA78
        moveq   #$0,d0                          ; 0BA7C
l_0BA7E:
        move.w  (a5)+,d4                        ; 0BA7E  entry: BLTSIZE (0 = end), modulo, screen address, save address
        beq.b   l_0BAA2                         ; 0BA80
        move.w  (a5)+,d0                        ; 0BA82
        movea.l (a5)+,a0                        ; 0BA84
        movea.l (a5)+,a1                        ; 0BA86
l_0BA88:
        btst    #$6,DMACONR(a2)                 ; 0BA88
        bne.b   l_0BA88                         ; 0BA8E
        move.l  d0,BLTAMOD(a2)                  ; 0BA90
        move.l  a1,BLTAPTH(a2)                  ; 0BA94
        move.l  a0,BLTDPTH(a2)                  ; 0BA98
        move.w  d4,BLTSIZE(a2)                  ; 0BA9C
        bra.b   l_0BA7E                         ; 0BAA0
l_0BAA2:
        subq.l  #$2,a5                          ; 0BAA2
        move.l  a5,g_RestoreListA(a6)           ; 0BAA4
l_0BAA8:
        rts                                     ; 0BAA8

;---------------------------------------------------------------------------
; DrawBobs - draw this frame's BOB list. The Queue*Draw routines push 12-byte entries
; (x.w, y.w, width.w, height.w, graphics.l) downwards from g_SaveBufA's address in the
; globals; this walks them from g_BlitListPtr back up, so the last queued is drawn first
; and the first queued ends up on top. g_SavePtr restarts at g_SaveBufA.
;---------------------------------------------------------------------------
DrawBobs:
        move.l  g_SaveBufA(a6),g_SavePtr(a6)    ; 0BAAA  rewind the save area
        movea.l g_BlitListPtr(a6),a3            ; 0BAB0  walk the draw list up to its top
        lea.l   g_SaveBufA(a6),a5               ; 0BAB4
l_0BAB8:
        cmpa.l  a5,a3                           ; 0BAB8
        beq.b   l_0BAC6                         ; 0BABA
        movem.w (a3)+,d1-d4                     ; 0BABC
        movea.l (a3)+,a1                        ; 0BAC0
        bsr.b   DrawBob                         ; 0BAC2
        bra.b   l_0BAB8                         ; 0BAC4
l_0BAC6:
        rts                                     ; 0BAC6

;---------------------------------------------------------------------------
; DrawBob - masked blit of one BOB (1MB build).
; In: a1 = frame graphics, d1,d2 = level x,y (y up), d3 = width, d4 = height.
; Same clipping, background save and $3000-byte save limit as the 512K build, but the
; graphics were converted at start-up (BuildMaskedGfx) so that every plane line is
; followed by its mask line. One cookie-cut blit (A = mask, B = BOB, C/D = screen) then
; draws all 5 planes: 5 x height blitter lines, with the A/B modulo skipping the other
; line and the C/D modulo stepping through the interleaved screen. The 512K build needs
; two mask-building blits and five plane blits.
;---------------------------------------------------------------------------
DrawBob:
        move.w  g_ScrollTileX(a6),d0            ; 0BAC8  level -> buffer coordinates (16-px left margin)
        lsl.w   #$4,d0                          ; 0BACC
        sub.w   d0,d1                           ; 0BACE
        addi.w  #$10,d1                         ; 0BAD0
        move.w  g_ScrollTileY(a6),d0            ; 0BAD4
        lsl.w   #$4,d0                          ; 0BAD8
        sub.w   d0,d2                           ; 0BADA
        moveq   #$f,d7                          ; 0BADC  d6 = width in words; d0 = words touched at this X
        add.w   d3,d7                           ; 0BADE
        lsr.w   #$4,d7                          ; 0BAE0
        move.l  d7,d6                           ; 0BAE2
        moveq   #$f,d0                          ; 0BAE4
        and.w   d1,d0                           ; 0BAE6
        add.w   d3,d0                           ; 0BAE8
        addi.w  #$f,d0                          ; 0BAEA
        lsr.w   #$4,d0                          ; 0BAEE
        moveq   #-1,d5                          ; 0BAF0  last-word mask: all ones unless the shift needs an extra word
        cmp.w   d6,d0                           ; 0BAF2
        seq.b   d5                              ; 0BAF4
        ext.w   d5                              ; 0BAF6
        move.w  d1,d7                           ; 0BAF8  off the left edge: skip whole words of graphics, mask the first
        bpl.b   l_0BB18                         ; 0BAFA
        neg.w   d7                              ; 0BAFC
        moveq   #$f,d3                          ; 0BAFE
        and.w   d7,d3                           ; 0BB00
        lsr.w   #$4,d7                          ; 0BB02
        sub.w   d7,d0                           ; 0BB04
        ble.w   l_0BC38                         ; 0BB06
        adda.w  d7,a1                           ; 0BB0A
        adda.w  d7,a1                           ; 0BB0C
        swap    d5                              ; 0BB0E
        lsr.w   d3,d5                           ; 0BB10
        swap    d5                              ; 0BB12
        move.w  d3,d1                           ; 0BB14
        neg.w   d1                              ; 0BB16
l_0BB18:
        add.w   d3,d7                           ; 0BB18  off the right edge (288 px)?
        subi.w  #$120,d7                        ; 0BB1A
        bls.b   l_0BB38                         ; 0BB1E
        addi.w  #$f,d7                          ; 0BB20
        lsr.w   #$4,d7                          ; 0BB24
        sub.w   d7,d0                           ; 0BB26
        bls.w   l_0BC38                         ; 0BB28
        move.w  #$ffff,d5                       ; 0BB2C
        moveq   #$f,d3                          ; 0BB30
        and.w   d1,d3                           ; 0BB32
        beq.b   l_0BB38                         ; 0BB34
        lsl.w   d3,d5                           ; 0BB36
l_0BB38:
        neg.w   d2                              ; 0BB38  Y: line = 256 - y - height; clip at the top ...
        ble.b   l_0BB4C                         ; 0BB3A
        move.b  d4,d3                           ; 0BB3C
        sub.w   d2,d4                           ; 0BB3E
        bls.w   l_0BC38                         ; 0BB40
        addi.w  #$100,d2                        ; 0BB44
        sub.w   d3,d2                           ; 0BB48
        bra.b   l_0BB6A                         ; 0BB4A
l_0BB4C:
        addi.w  #$100,d2                        ; 0BB4C  ... and at the bottom (skip graphics lines)
        sub.w   d4,d2                           ; 0BB50
        bpl.b   l_0BB6A                         ; 0BB52
        add.w   d2,d4                           ; 0BB54
        ble.w   l_0BC38                         ; 0BB56
        neg.w   d2                              ; 0BB5A
        move.w  d6,d7                           ; 0BB5C
        add.w   d7,d7                           ; 0BB5E
        mulu.w  d7,d2                           ; 0BB60
        mulu.w  #$a,d2                          ; 0BB62
        adda.w  d2,a1                           ; 0BB66
        clr.w   d2                              ; 0BB68
l_0BB6A:
        moveq   #$f,d3                          ; 0BB6A  X shift for BLTCON0/1
        and.w   d1,d3                           ; 0BB6C
        ror.w   #$4,d3                          ; 0BB6E
        movea.l g_ScreenFront(a6),a0            ; 0BB70  screen address of the top-left word
        asr.w   #$4,d1                          ; 0BB74
        add.w   d1,d1                           ; 0BB76
        adda.w  d1,a0                           ; 0BB78
        mulu.w  #$b4,d2                         ; 0BB7A
        adda.l  d2,a0                           ; 0BB7E
        add.w   d6,d6                           ; 0BB80
        lea.l   (a1,d6.w),a4                    ; 0BB82  [1MB] a4 = mask line: in the 1MB build every plane line is followed by its mask (BuildMaskedGfx)  << differs from the 512K build: 1 instruction(s) here replace 4 at $0BB16 >>
        mulu.w  #$5,d4                          ; 0BB86
        move.w  d4,d7                           ; 0BB8A
        lsl.w   #$6,d4                          ; 0BB8C
        or.w    d0,d4                           ; 0BB8E
        add.w   d0,d0                           ; 0BB90
        moveq   #$24,d1                         ; 0BB92  screen modulo = 36 - width
        sub.w   d0,d1                           ; 0BB94
        add.w   d6,d6                           ; 0BB96  [1MB] mask lines interleave the plane lines: the A/B modulo skips the other line  << 1MB only: 3 instruction(s) not in the 512K build >>
        sub.w   d0,d6                           ; 0BB98  [1MB] 
        movea.l g_RestoreListA(a6),a2           ; 0BB9A  [1MB] 
        mulu.w  d0,d7                           ; 0BB9E
        move.l  g_SavePtr(a6),d2                ; 0BBA0  room in the save area ($3000 bytes)?
        add.l   d7,d2                           ; 0BBA4
        sub.l   g_SaveBufA(a6),d2               ; 0BBA6
        cmp.l   #$3000,d2                       ; 0BBAA
        bhi.w   l_0BC38                         ; 0BBB0  [1MB]   << differs from the 512K build: 1 instruction(s) here replace 3 at $0BB40 >>
        move.l  g_SavePtr(a6),d2                ; 0BBB4
        move.l  d2,-(a2)                        ; 0BBB8  << 512K build has 1 more instruction(s) here (at $0BB4C), removed in the 1MB build >>
        move.l  a0,-(a2)                        ; 0BBBA
        move.w  d1,-(a2)                        ; 0BBBC
        move.w  d4,-(a2)                        ; 0BBBE
        move.l  a2,g_RestoreListA(a6)           ; 0BBC0
        add.l   d7,g_SavePtr(a6)                ; 0BBC4
        swap    d1                              ; 0BBC8
        lea.l   CUSTOM,a2                       ; 0BBCA
l_0BBD0:
        btst    #$6,DMACONR(a2)                 ; 0BBD0  save the background (A->D copy)
        bne.b   l_0BBD0                         ; 0BBD6
        move.w  #$9f0,BLTCON0(a2)               ; 0BBD8
        move.w  d1,BLTCON1(a2)                  ; 0BBDE
        move.l  d1,BLTAMOD(a2)                  ; 0BBE2
        move.l  #$ffffffff,BLTAFWM(a2)          ; 0BBE6
        move.l  a0,BLTAPTH(a2)                  ; 0BBEE
        move.l  d2,BLTDPTH(a2)                  ; 0BBF2
        move.w  d4,BLTSIZE(a2)                  ; 0BBF6
        swap    d1                              ; 0BBFA  [1MB]   << differs from the 512K build: 1 instruction(s) here replace 33 at $0BB92 >>
l_0BBFC:
        btst    #$6,DMACONR(a2)                 ; 0BBFC
        bne.b   l_0BBFC                         ; 0BC02
        move.w  d3,BLTCON1(a2)                  ; 0BC04
        ori.w   #$fca,d3                        ; 0BC08
        move.w  d3,BLTCON0(a2)                  ; 0BC0C
        move.w  d1,BLTCMOD(a2)                  ; 0BC10  [1MB] one blit draws all 5 planes: 5 x height lines, one plane line each  << differs from the 512K build: 4 instruction(s) here replace 2 at $0BC18 >>
        move.w  d6,BLTBMOD(a2)                  ; 0BC14  [1MB] 
        move.w  d6,BLTAMOD(a2)                  ; 0BC18  [1MB] 
        move.w  d1,BLTDMOD(a2)                  ; 0BC1C  [1MB] 
        move.l  d5,BLTAFWM(a2)                  ; 0BC20
        move.l  a4,BLTAPTH(a2)                  ; 0BC24  A = stored mask, B = BOB, C/D = screen: no mask-building blit needed  << 512K build has 36 more instruction(s) here (at $0BC24), removed in the 1MB build >>
        move.l  a1,BLTBPTH(a2)                  ; 0BC28
        move.l  a0,BLTCPTH(a2)                  ; 0BC2C
        move.l  a0,BLTDPTH(a2)                  ; 0BC30
        move.w  d4,BLTSIZE(a2)                  ; 0BC34
l_0BC38:
        rts                                     ; 0BC38

