WaitBlitIRQ:	; (no references found - unused/debug code)
        lea.l   CUSTOM+INTREQR,a0               ; 0BC3A
l_0BC40:
        moveq   #$10,d0                         ; 0BC40
        and.w   (a0),d0                         ; 0BC42
