;---------------------------------------------------------------------------
; PlayMusic - 1MB build only. d0 = tune number (see sound/SOUND.md): calls the sound
; driver through vector $60 with command 1 (d0.l = tune<<16 | 1).
;---------------------------------------------------------------------------
PlayMusic:
        move.l  a1,-(a7)                        ; 0BC48  [1MB] 
        swap    d0                              ; 0BC4A  [1MB] 
        addq.w  #$1,d0                          ; 0BC4C  [1MB] 
        movea.l (VEC_SPURIOUS).w,a1             ; 0BC4E  [1MB] 
        jsr     (a1)                            ; 0BC52  [1MB] 
        movea.l (a7)+,a1                        ; 0BC54  [1MB] 
        rts                                     ; 0BC56

;---------------------------------------------------------------------------
; PlaySfx - d0 = effect number (0-29). Calls the sound driver through vector $60
; with command 2 (d0.l = number<<16 | 2). Driver source: sound/gng_music_1mb.s.
;---------------------------------------------------------------------------
PlaySfx:
        move.l  a1,-(a7)                        ; 0BC58
        swap    d0                              ; 0BC5A
        addq.w  #$2,d0                          ; 0BC5C
        movea.l (VEC_SPURIOUS).w,a1             ; 0BC5E
        jsr     (a1)                            ; 0BC62
        movea.l (a7)+,a1                        ; 0BC64
        rts                                     ; 0BC66

;---------------------------------------------------------------------------
; Level 2 (PORTS) - CIA-A serial keyboard.
; Reads SDR, handshakes via CRA SPMODE for ~85us, decodes the raw
; keycode (NOT + ROR 1); key-down codes go to g_RawKey and the ASCII
; equivalent from KeyAsciiTable to g_AsciiKey.
;---------------------------------------------------------------------------
KeyboardIRQ:
        movem.l d0-d1/a0,-(a7)                  ; 0BC68
        lea.l   CUSTOM,a0                       ; 0BC6C
        move.w  INTREQR(a0),d0                  ; 0BC72
        and.w   INTENAR(a0),d0                  ; 0BC76
        andi.w  #$8,d0                          ; 0BC7A
        move.w  d0,INTREQ(a0)                   ; 0BC7E
        lea.l   $bfe001.l,a0                    ; 0BC82
        move.b  $d00(a0),d0                     ; 0BC88
        btst    #$3,d0                          ; 0BC8C
        beq.b   l_0BCE4                         ; 0BC90
        clr.w   d0                              ; 0BC92
        move.b  $c00(a0),d0                     ; 0BC94
        ori.b   #$40,$e00(a0)                   ; 0BC98
        andi.b  #$f6,$e00(a0)                   ; 0BC9E
        move.b  #$2,$400(a0)                    ; 0BCA4
        move.b  #$0,$500(a0)                    ; 0BCAA
        ori.b   #$1,$e00(a0)                    ; 0BCB0
        move.b  #$0,$c00(a0)                    ; 0BCB6
l_0BCBC:
        move.b  $d00(a0),d1                     ; 0BCBC
        btst    #$3,d1                          ; 0BCC0
        beq.b   l_0BCBC                         ; 0BCC4
        move.w  #INTF_PORTS,CUSTOM+INTREQ       ; 0BCC6
        andi.b  #$bf,$e00(a0)                   ; 0BCCE
        not.b   d0                              ; 0BCD4
        ror.b   #$1,d0                          ; 0BCD6
        bmi.b   l_0BCE4                         ; 0BCD8
        move.b  d0,g_RawKey(a6)                 ; 0BCDA
        move.b  KeyAsciiTable(pc,d0.w),g_AsciiKey(a6); 0BCDE
l_0BCE4:
        movem.l (a7)+,d0-d1/a0                  ; 0BCE4
        rte                                     ; 0BCE8

;---------------------------------------------------------------------------
; KeyAsciiTable - ASCII for raw key codes $00-$67 (0 = no character): the main block in
; US order, keypad digits at $0F, $1D-$1F, $2D-$2F and '.' at $3C (keypad 7-9 give nothing); $40 space, $41 backspace,
; $42 tab, $43 / $44 enter / return, $45 Esc, $46 Del.
;---------------------------------------------------------------------------
KeyAsciiTable:
	dc.b	'~1234567890-=\'
	dc.b	$00
	dc.b	'0QWERTYUIOP[]'
	dc.b	$00
	dc.b	'123ASDFGHJKL;'
	dc.b	$27,$00,$00,$34,$35,$36,$00
	dc.b	'ZXCVBNM,./'
	dc.b	$00,$2E,$00,$00,$00,$20,$08,$09,$0D,$0D,$1B,$7F,$00,$00,$00,$00
	dc.b	$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00
	dc.b	$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00,$00

;---------------------------------------------------------------------------
; ==================================================================
; VblIRQ - Level 3 vertical blank
;  - removes the interrupted SR from the stack into g_SavedSR
;  - sets HUD sprite (4-7) and Arthur sprite (0-3) control words,
;    copies Arthur's new frame into sprite RAM when it changes
;    (negative frame number = mirrored set at +$2A)
;  - g_VblCount++, reads the joystick into g_Joy (fire = bit 15)
;  - ticks the music player (vector $60, d0 = 0)
;  - if the logic interrupt is not already running and g_SkipLogic is
;    clear, raises SOFTINT -> Level1Logic runs next
;  - if returning to user mode with g_RedrawPending set, rewrites the
;    return address to RedrawEntry so the redraw runs outside IRQs
; ==================================================================
;---------------------------------------------------------------------------
VblIRQ:
        move.w  (a7)+,g_SavedSR(a6)             ; 0BD52  pop the exception SR into the globals (pushed back before RTE)
        movem.l d0-d7/a0-a5,-(a7)               ; 0BD56
        lea.l   CUSTOM,a0                       ; 0BD5A
        move.w  #INTF_VERTB,INTREQ(a0)          ; 0BD60  acknowledge VERTB
        tst.b   g_Spr47Visible(a6)              ; 0BD66  HUD sprites 4-7: the control words, or nothing
        bne.b   l_0BD9E                         ; 0BD6A
        clr.l   (SPRITE4_DATA).l                ; 0BD6C
        clr.l   (SPRITE5_DATA).l                ; 0BD72
