        clr.l   (SPRITE5B_DATA).l               ; 0BD8A
        clr.l   (SPRITE6B_DATA).l               ; 0BD90
        clr.l   (SPRITE7B_DATA).l               ; 0BD96
        bra.b   l_0BDD2                         ; 0BD9C
l_0BD9E:
