        ext.w   d0                              ; 0BE22
        bpl.b   l_0BE2C                         ; 0BE24
        not.w   d0                              ; 0BE26  negative frame ~n: the mirrored copy, stored after the 42 normal frames
        addi.w  #$2a,d0                         ; 0BE28
l_0BE2C:
        mulu.w  #$80,d0                         ; 0BE2C  $80 bytes a frame in each of the four sprite banks ($2900 apart)
        adda.l  d0,a5                           ; 0BE30
        movem.l (a5)+,d0-d7                     ; 0BE32
        movem.l d0-d7,(a1)                      ; 0BE36
        lea.l   $20(a1),a1                      ; 0BE3A
        movem.l (a5)+,d0-d7                     ; 0BE3E
        movem.l d0-d7,(a1)                      ; 0BE42
        lea.l   $20(a1),a1                      ; 0BE46
        movem.l (a5)+,d0-d7                     ; 0BE4A
        movem.l d0-d7,(a1)                      ; 0BE4E
        lea.l   $20(a1),a1                      ; 0BE52
        movem.l (a5)+,d0-d7                     ; 0BE56
        movem.l d0-d7,(a1)                      ; 0BE5A
        lea.l   $2880(a5),a5                    ; 0BE5E
        movem.l (a5)+,d0-d7                     ; 0BE62
        movem.l d0-d7,(a2)                      ; 0BE66
        lea.l   $20(a2),a2                      ; 0BE6A
        movem.l (a5)+,d0-d7                     ; 0BE6E
        movem.l d0-d7,(a2)                      ; 0BE72
        lea.l   $20(a2),a2                      ; 0BE76
        movem.l (a5)+,d0-d7                     ; 0BE7A
        movem.l d0-d7,(a2)                      ; 0BE7E
        lea.l   $20(a2),a2                      ; 0BE82
        movem.l (a5)+,d0-d7                     ; 0BE86
        movem.l d0-d7,(a2)                      ; 0BE8A
        lea.l   $2880(a5),a5                    ; 0BE8E
        movem.l (a5)+,d0-d7                     ; 0BE92
        movem.l d0-d7,(a3)                      ; 0BE96
        lea.l   $20(a3),a3                      ; 0BE9A
        movem.l (a5)+,d0-d7                     ; 0BE9E
        movem.l d0-d7,(a3)                      ; 0BEA2
        lea.l   $20(a3),a3                      ; 0BEA6
        movem.l (a5)+,d0-d7                     ; 0BEAA
        movem.l d0-d7,(a3)                      ; 0BEAE
        lea.l   $20(a3),a3                      ; 0BEB2
        movem.l (a5)+,d0-d7                     ; 0BEB6
        movem.l d0-d7,(a3)                      ; 0BEBA
        lea.l   $2880(a5),a5                    ; 0BEBE
        movem.l (a5)+,d0-d7                     ; 0BEC2
        movem.l d0-d7,(a4)                      ; 0BEC6
        lea.l   $20(a4),a4                      ; 0BECA
        movem.l (a5)+,d0-d7                     ; 0BECE
        movem.l d0-d7,(a4)                      ; 0BED2
        lea.l   $20(a4),a4                      ; 0BED6
        movem.l (a5)+,d0-d7                     ; 0BEDA
        movem.l d0-d7,(a4)                      ; 0BEDE
        lea.l   $20(a4),a4                      ; 0BEE2
        movem.l (a5)+,d0-d7                     ; 0BEE6
        movem.l d0-d7,(a4)                      ; 0BEEA
l_0BEEE:
        addq.w  #$1,g_VblCount(a6)              ; 0BEEE  g_VblCount++
        move.w  g_Joy(a6),g_JoyPrev(a6)         ; 0BEF2  keep previous joystick state for edge detection
