;---------------------------------------------------------------------------
; RedrawScreen - full redraw of the playfield at the new origin g_NewTileX/Y, into
; g_ScreenSpare1, then copied to g_ScreenSpare2 (CameraJump / SwapScreens show them).
; 18 x 16 tiles of 16 x 16, from the bottom row up: cell = map byte (the map is in
; 16 x 16-tile cells), tile = CellTiles[cell][row][col], blitted from the level file
; (160 bytes a tile: 16 lines x 5 planes, BLTSIZE $1401, D modulo 34). Interrupts are
; held off (INTENA) around each blit. Cell $67 always gives tile 0.
; On level 1, map cells $1F and $1D (its tiles 0-9) take their tiles from a second bank
; (tile + 256). Levels 0 (before tile column $70) and 2 (before $40) then draw the
; shootable scenery into the background (DrawSceneryOnRedraw).
; Finally sets g_RedrawDone. Runs outside the interrupts, from RedrawEntry, or directly
; during set-up.
;---------------------------------------------------------------------------
RedrawScreen:
        movea.l g_ScreenSpare1(a6),a1           ; 0BF72
        adda.l  #$a8c0,a1                       ; 0BF76  start at the bottom row: 240 lines down
        lea.l   CUSTOM+INTENA,a2                ; 0BF7C
        movea.l g_MapPtr(a6),a3                 ; 0BF82
        lea.l   CellTiles(pc),a4                ; 0BF86
        movea.l g_LevelFileAddr(a6),a5          ; 0BF8A
        move.w  g_NewTileX(a6),d1               ; 0BF8E
        move.w  g_NewTileY(a6),d2               ; 0BF92
        cmpi.w  #$1,g_Level(a6)                 ; 0BF96  level 1: second tile bank for some cells
        seq.b   d5                              ; 0BF9C
        moveq   #$f,d7                          ; 0BF9E  16 rows
l_0BFA0:
        moveq   #$11,d6                         ; 0BFA0  18 columns
l_0BFA2:
        moveq   #$10,d0                         ; 0BFA2  map cell of this tile; d4 / d3 = column / row within the cell
        sub.w   d6,d0                           ; 0BFA4
        add.w   d1,d0                           ; 0BFA6
        moveq   #$f,d4                          ; 0BFA8
        and.w   d0,d4                           ; 0BFAA
        asr.w   #$4,d0                          ; 0BFAC
        lea.l   (a3,d0.w),a0                    ; 0BFAE
        move.w  d7,d0                           ; 0BFB2
        sub.w   d2,d0                           ; 0BFB4
        moveq   #$f,d3                          ; 0BFB6
        and.w   d0,d3                           ; 0BFB8
        andi.w  #$fff0,d0                       ; 0BFBA
        add.w   d0,d0                           ; 0BFBE
        suba.w  d0,a0                           ; 0BFC0

;---------------------------------------------------------------------------
; cell $67 -> a0 = LEVEL_FILE (tile 0); otherwise look up the tile number.
; Note: tile 0 is still blitted - it is the first tile of the level file.
;---------------------------------------------------------------------------
        move.b  (a0),d0                         ; 0BFC2
        cmp.b   #$67,d0                         ; 0BFC4
        bne.b   l_0BFCE                         ; 0BFC8
        movea.l a5,a0                           ; 0BFCA
        bra.b   l_0C004                         ; 0BFCC
l_0BFCE:
        lsl.w   #$4,d0                          ; 0BFCE  tile = CellTiles[cell][row][col]
        add.w   d3,d0                           ; 0BFD0
        lsl.w   #$4,d0                          ; 0BFD2
        add.w   d4,d0                           ; 0BFD4
        move.b  (a4,d0.w),d3                    ; 0BFD6
        beq.b   l_0C000                         ; 0BFDA
        tst.b   d5                              ; 0BFDC
        beq.b   l_0BFFC                         ; 0BFDE
        move.b  (a0),d0                         ; 0BFE0
        cmp.b   #$1f,d0                         ; 0BFE2
        beq.b   l_0BFF8                         ; 0BFE6
        cmp.b   #$1d,d0                         ; 0BFE8
        bne.b   l_0BFFC                         ; 0BFEC
        cmp.b   #$9,d3                          ; 0BFEE
        bhi.b   l_0BFFC                         ; 0BFF2
        bcs.b   l_0BFF8                         ; 0BFF4
        clr.b   d3                              ; 0BFF6
l_0BFF8:
        addi.w  #$100,d3                        ; 0BFF8
l_0BFFC:
        mulu.w  #$a0,d3                         ; 0BFFC  160 bytes a tile
l_0C000:
        lea.l   (a5,d3.l),a0                    ; 0C000
l_0C004:
        move.w  #$4000,(a2)                     ; 0C004  interrupts off for the blit
l_0C008:
        btst    #$6,-$98(a2)                    ; 0C008
        bne.b   l_0C008                         ; 0C00E
        move.l  #$9f00000,-$5a(a2)              ; 0C010  A->D copy, 80 lines x 1 word, D modulo 34
        moveq   #-1,d0                          ; 0C018
        move.l  d0,-$56(a2)                     ; 0C01A
        moveq   #$22,d0                         ; 0C01E
        move.l  d0,-$36(a2)                     ; 0C020
        move.l  a0,-$4a(a2)                     ; 0C024
        move.l  a1,-$46(a2)                     ; 0C028
        move.w  #$1401,-$42(a2)                 ; 0C02C
        move.w  #$c000,(a2)                     ; 0C032  interrupts back on
        addq.l  #$2,a1                          ; 0C036
        dbra    d6,l_0BFA2                      ; 0C038
        lea.l   -$b64(a1),a1                    ; 0C03C  up one tile row
        dbra    d7,l_0BFA0                      ; 0C040
        move.w  g_Level(a6),d0                  ; 0C044  level 0 (before column $70) or 2 (before $40): draw the scenery items
        bne.b   l_0C052                         ; 0C048
        cmpi.w  #$70,g_NewTileX(a6)             ; 0C04A
        blt.b   l_0C060                         ; 0C050
l_0C052:
        cmp.w   #$2,d0                          ; 0C052
        bne.b   l_0C064                         ; 0C056
        cmpi.w  #$40,g_NewTileX(a6)             ; 0C058
        bge.b   l_0C064                         ; 0C05E
l_0C060:
        bsr.w   DrawSceneryOnRedraw             ; 0C060
l_0C064:
        movea.l g_ScreenSpare1(a6),a4           ; 0C064  copy the whole buffer to the second spare (46080 bytes)
        movea.l g_ScreenSpare2(a6),a5           ; 0C068
        move.w  #$78,-(a7)                      ; 0C06C
l_0C070:
        movem.l (a4)+,d0-d7/a0-a3               ; 0C070
        movem.l d0-d7/a0-a3,(a5)                ; 0C074
        lea.l   $30(a5),a5                      ; 0C078
        movem.l (a4)+,d0-d7/a0-a3               ; 0C07C
        movem.l d0-d7/a0-a3,(a5)                ; 0C080
        lea.l   $30(a5),a5                      ; 0C084
        movem.l (a4)+,d0-d7/a0-a3               ; 0C088
        movem.l d0-d7/a0-a3,(a5)                ; 0C08C
        lea.l   $30(a5),a5                      ; 0C090
        movem.l (a4)+,d0-d7/a0-a3               ; 0C094
        movem.l d0-d7/a0-a3,(a5)                ; 0C098
        lea.l   $30(a5),a5                      ; 0C09C
        movem.l (a4)+,d0-d7/a0-a3               ; 0C0A0
        movem.l d0-d7/a0-a3,(a5)                ; 0C0A4
        lea.l   $30(a5),a5                      ; 0C0A8
        movem.l (a4)+,d0-d7/a0-a3               ; 0C0AC
        movem.l d0-d7/a0-a3,(a5)                ; 0C0B0
        lea.l   $30(a5),a5                      ; 0C0B4
        movem.l (a4)+,d0-d7/a0-a3               ; 0C0B8
        movem.l d0-d7/a0-a3,(a5)                ; 0C0BC
        lea.l   $30(a5),a5                      ; 0C0C0
        movem.l (a4)+,d0-d7/a0-a3               ; 0C0C4
        movem.l d0-d7/a0-a3,(a5)                ; 0C0C8
        lea.l   $30(a5),a5                      ; 0C0CC
        subq.w  #$1,(a7)                        ; 0C0D0
        bne.b   l_0C070                         ; 0C0D2
        addq.l  #$2,a7                          ; 0C0D4
        st.b    g_RedrawDone(a6)                ; 0C0D6  done
        rts                                     ; 0C0DA
CollisionBoxes:
	dc.b	16,16	; size class 0: width, height
	dc.b	16,32	; size class 1: width, height
	dc.b	32,16	; size class 2: width, height
	dc.b	16,32	; size class 3: width, height
	dc.b	48,48	; size class 4: width, height
	dc.b	48,16	; size class 5: width, height
	dc.b	64,64	; size class 6: width, height
	dc.b	64,16	; size class 7: width, height
	dc.b	16,48	; size class 8: width, height
	dc.b	48,32	; size class 9: width, height
	dc.b	16,64	; size class 10: width, height

;---------------------------------------------------------------------------
; Floor test for object a5: looks for floor under the bottom-left, then the bottom-right
; corner of its collision box. Floor found: Y is moved up onto it, d0 = 0 (Z set).
; No floor under either corner: d0 = -1 (Z clear).
;---------------------------------------------------------------------------
ObjectMapCollide:
        move.w  d7,-(a7)                        ; 0C0F2
        move.w  O_X(a5),d6                      ; 0C0F4
        move.w  O_Y(a5),d7                      ; 0C0F8
        clr.w   d0                              ; 0C0FC
        move.b  O_Size(a5),d0                   ; 0C0FE
        add.w   d0,d0                           ; 0C102
        lea.l   CollisionBoxes(pc,d0.w),a1      ; 0C104
        move.b  (a1)+,d0                        ; 0C108
        lsr.w   #$1,d0                          ; 0C10A
        sub.w   d0,d6                           ; 0C10C
        move.b  (a1)+,d0                        ; 0C10E
        lsr.w   #$1,d0                          ; 0C110
        sub.w   d0,d7                           ; 0C112
        bsr.w   MapTileAt                       ; 0C114
        move.b  $4(a1),d0                       ; 0C118
        andi.b  #$c0,d0                         ; 0C11C
        bne.b   l_0C138                         ; 0C120
        move.b  (a1),d0                         ; 0C122
        ext.w   d0                              ; 0C124
        lea.l   FloorProfile(pc),a1             ; 0C126
        adda.w  d0,a1                           ; 0C12A
        move.b  (a1),d1                         ; 0C12C
        beq.b   l_0C138                         ; 0C12E
        moveq   #$f,d0                          ; 0C130
        and.w   d7,d0                           ; 0C132
        sub.b   d0,d1                           ; 0C134
        bcc.b   l_0C184                         ; 0C136
l_0C138:
        move.w  O_X(a5),d6                      ; 0C138
        move.w  O_Y(a5),d7                      ; 0C13C
        lea.l   BoxSizeTable(pc),a1             ; 0C140
        clr.w   d0                              ; 0C144
        move.b  O_Size(a5),d0                   ; 0C146
        add.w   d0,d0                           ; 0C14A
        adda.w  d0,a1                           ; 0C14C
        move.b  (a1)+,d0                        ; 0C14E
        lsr.w   #$1,d0                          ; 0C150
        add.w   d0,d6                           ; 0C152
        move.b  (a1)+,d0                        ; 0C154
        lsr.w   #$1,d0                          ; 0C156
        sub.w   d0,d7                           ; 0C158
        bsr.w   MapTileAt                       ; 0C15A
        move.b  $4(a1),d0                       ; 0C15E
        andi.b  #$c0,d0                         ; 0C162
        bne.b   l_0C17E                         ; 0C166
        move.b  (a1),d0                         ; 0C168
        ext.w   d0                              ; 0C16A
        lea.l   FloorProfile(pc),a1             ; 0C16C
        adda.w  d0,a1                           ; 0C170
        move.b  (a1),d1                         ; 0C172
        beq.b   l_0C17E                         ; 0C174
        moveq   #$f,d0                          ; 0C176
        and.w   d7,d0                           ; 0C178
        sub.b   d0,d1                           ; 0C17A
        bcc.b   l_0C184                         ; 0C17C
l_0C17E:
        move.w  (a7)+,d7                        ; 0C17E
        moveq   #-1,d0                          ; 0C180
        rts                                     ; 0C182
l_0C184:
        ext.w   d1                              ; 0C184
        add.w   d1,O_Y(a5)                      ; 0C186
        move.w  (a7)+,d7                        ; 0C18A
        moveq   #$0,d0                          ; 0C18C
        rts                                     ; 0C18E

;---------------------------------------------------------------------------
; DrawSceneryOnRedraw - draw every active item of type 1 (gravestones and other
; shootable scenery) into the freshly redrawn background, with the same clipping and
; masked blits as DrawBob but without saving the background, so they cost nothing per
; frame (levels 0 and 2)
;---------------------------------------------------------------------------
DrawSceneryOnRedraw:
        lea.l   g_Items(a6),a5                  ; 0C190  every active item of type 1
        moveq   #$1d,d7                         ; 0C194
l_0C196:
        move.w  d7,-(a7)                        ; 0C196
        tst.b   (a5)                            ; 0C198
        beq.w   l_0C2F8                         ; 0C19A
        cmpi.b  #$1,O_Type(a5)                  ; 0C19E
        bne.w   l_0C2F8                         ; 0C1A4
        lea.l   ItemBoxSizes(pc),a1             ; 0C1A8  image and size from ItemBoxSizes / SmallBobSizes
        moveq   #-16,d1                         ; 0C1AC
        add.w   O_X(a5),d1                      ; 0C1AE
        moveq   #$10,d2                         ; 0C1B2
        add.w   O_Y(a5),d2                      ; 0C1B4
        move.b  O_Param(a5),d0                  ; 0C1B8
        ext.w   d0                              ; 0C1BC
        adda.w  d0,a1                           ; 0C1BE
        move.b  (a1),d0                         ; 0C1C0
        lea.l   SmallBobSizes(pc),a1            ; 0C1C2
        add.w   d0,d0                           ; 0C1C6
        adda.w  d0,a1                           ; 0C1C8
        move.b  (a1)+,d3                        ; 0C1CA
        ext.w   d3                              ; 0C1CC
        sub.w   d3,d2                           ; 0C1CE
        moveq   #$20,d3                         ; 0C1D0
