;---------------------------------------------------------------------------
; ==================================================================
; LoadFile - the game's copy of the bootblock trackloader
; In: a1 -> file record: dest.L, length.L, start_track.W
; Out: a5 = end of loaded data
; Track format: one block per track after DSKSYNC $A245 (set by the
; boot loader), track-number word, $62A longs of odd/even MFM data and
; a checksum long = NOT(sum). Reads $1900 words into $33FE8 by DMA.
; Up to 8 retries per track; a bad track number re-seeks via track 0.
; ==================================================================
;---------------------------------------------------------------------------
LoadFile:
        movea.l (a1)+,a5                        ; 0C3AA  a5 = destination
        move.l  (a1)+,d5                        ; 0C3AC  d5 = length in bytes
        move.w  (a1)+,(LDR_TRACK).w             ; 0C3AE  start track
        lea.l   CUSTOM,a0                       ; 0C3B2
        lea.l   $bfe001.l,a1                    ; 0C3B8
        lea.l   CIAB_PRB,a2                     ; 0C3BE
        st.b    (a2)                            ; 0C3C4  select DF0, motor on
        bclr    #$7,(a2)                        ; 0C3C6
        bclr    #$3,(a2)                        ; 0C3CA
        move.l  d5,d7                           ; 0C3CE  tracks = (length + $18A7) / $18A8 (6312 bytes per track)
        addi.l  #$18a7,d7                       ; 0C3D0
        divu.w  #$18a8,d7                       ; 0C3D6
        subq.w  #$1,d7                          ; 0C3DA
l_0C3DC:
        move.w  #$8,(LDR_RETRY).w               ; 0C3DC  8 attempts per track
        bsr.w   SeekTrack                       ; 0C3E2  seek to LDR_TRACK
l_0C3E6:
        bsr.w   ReadTrackDMA                    ; 0C3E6  DMA one track
        bsr.w   DecodeTrack                     ; 0C3EA  decode and checksum
        cmp.l   d4,d1                           ; 0C3EE  checksum ok?
        beq.b   l_0C400                         ; 0C3F0
        subq.w  #$1,(LDR_RETRY).w               ; 0C3F2
        beq.b   l_0C41A                         ; 0C3F6
        addi.l  #$18a8,d5                       ; 0C3F8
        bra.b   l_0C3E6                         ; 0C3FE
l_0C400:
        cmp.w   (LDR_TRACK).w,d2                ; 0C400  right track number?
        bne.b   l_0C426                         ; 0C404
        addq.w  #$1,(LDR_TRACK).w               ; 0C406
        movea.l a4,a5                           ; 0C40A
        dbra    d7,l_0C3DC                      ; 0C40C
        st.b    (a2)                            ; 0C410  deselect, motor off
        bclr    #$3,(a2)                        ; 0C412
        st.b    (a2)                            ; 0C416
        rts                                     ; 0C418
l_0C41A:
        bsr.w   SeekTrack0                      ; 0C41A  too many errors: recalibrate to track 0
        addi.l  #$18a8,d5                       ; 0C41E
        bra.b   l_0C3DC                         ; 0C424
l_0C426:
        bsr.w   SeekTrack0                      ; 0C426
        addi.l  #$18a8,d5                       ; 0C42A
        bra.b   l_0C3DC                         ; 0C430

