        lsl.w   #$8,d0                          ; 0C452
        move.b  $800(a2),d0                     ; 0C454
        lsl.l   #$8,d0                          ; 0C458
        move.b  $700(a2),d0                     ; 0C45A
        cmp.l   d1,d0                           ; 0C45E
        bls.b   l_0C44C                         ; 0C460
        bclr    #$0,(a2)                        ; 0C462
        bset    #$0,(a2)                        ; 0C466
        clr.b   $900(a2)                        ; 0C46A
