;---------------------------------------------------------------------------
; === Woody Pig (type 0, 100 pts) ===
; Flying pig of the level-0 forest; created by the spawners, flies in along a movement table and can drop/fire a projectile (FindFreeEnemyShot).
; Dispatches on O_State: 0 main behaviour, 1 type-specific second phase, 2 killed (set by EnemyHitByShot after scoring), 3 remove.
;
; Behaviour, as coded: flies in 16 directions at 1.55 px/frame (1 in 4 use the faster
; WoodyPigMoveFast table). O_Param 0: flies in from the edge of the screen at double speed;
; 1-2: emerges in place (size class 0 growing to 2). While Arthur is within 128 px it may loop
; the loop (8 turns of 1/16, up to 0-7 loops per pig, more likely the closer he is). When it
; is above Arthur but not over him and no enemy shot is in flight, it picks one up (enemy shot
; type 4, carried in Pig_Bomb) and drops it after a short animation (26 + 10 frames). If it is
; killed while carrying, the shot is let go (state 3).
;---------------------------------------------------------------------------
Enemy_WoodyPig:
        move.b  O_State(a5),d0                  ; 0C58E
        add.w   d0,d0                           ; 0C592
        add.w   d0,d0                           ; 0C594
        jmp     Enemy_WoodyPig_Jumps(pc,d0.w)   ; 0C596
Enemy_WoodyPig_Jumps:
        bra.w   WoodyPig_Init                   ; 0C59A
        bra.w   WoodyPig_Active                 ; 0C59E
        bra.w   WoodyPig_Dying                  ; 0C5A2
        bra.w   WoodyPig_Free                   ; 0C5A6

;---------------------------------------------------------------------------
; State 0. O_Step 0 set up, 1 fly in, 2-3 emerge
;---------------------------------------------------------------------------
WoodyPig_Init:
        clr.w   d0                              ; 0C5AA
        move.b  O_Step(a5),d0                   ; 0C5AC
        add.w   d0,d0                           ; 0C5B0
        add.w   d0,d0                           ; 0C5B2
        jmp     WoodyPig_Init_Jumps(pc,d0.w)    ; 0C5B4
WoodyPig_Init_Jumps:
        bra.w   WoodyPig_Setup                  ; 0C5B8
        bra.w   WoodyPig_FlyIn                  ; 0C5BC
        bra.w   WoodyPig_Emerge                 ; 0C5C0
        bra.w   WoodyPig_Emerge                 ; 0C5C4

;---------------------------------------------------------------------------
; Shots pass through until it is on screen; O_Dir 1 (right) or 9 (left); O_Step = param + 1
;---------------------------------------------------------------------------
WoodyPig_Setup:
        move.b  #$2,(a5)                        ; 0C5C8
        clr.b   Pig_Drop(a5)                    ; 0C5CC
        clr.b   Pig_Unused31(a5)                ; 0C5D0
        clr.b   Pig_Unused32(a5)                ; 0C5D4
        clr.b   Pig_Unused33(a5)                ; 0C5D8
        clr.l   Pig_Bomb(a5)                    ; 0C5DC
        clr.b   Pig_LoopAcc(a5)                 ; 0C5E0
        clr.b   Pig_TurnAcc(a5)                 ; 0C5E4
        move.w  g_GameFrame(a6),d0              ; 0C5E8
        add.w   d7,d0                           ; 0C5EC
        andi.w  #$7,d0                          ; 0C5EE
        move.b  d0,Pig_Loops(a5)                ; 0C5F2
        move.b  #$2,O_Size(a5)                  ; 0C5F6
        move.b  #$1,O_Dir(a5)                   ; 0C5FC
        move.w  O_X(a5),d0                      ; 0C602
        cmp.w   g_ArthurX(a6),d0                ; 0C606
        blt.b   l_0C612                         ; 0C60A
        move.b  #$9,O_Dir(a5)                   ; 0C60C
l_0C612:
        clr.l   O_Anim(a5)                      ; 0C612
        lea.l   WoodyPigMoveTable(pc),a0        ; 0C616
        move.w  g_GameFrame(a6),d0              ; 0C61A
        add.w   d7,d0                           ; 0C61E
        andi.w  #$3,d0                          ; 0C620
        bne.b   l_0C62A                         ; 0C624
        lea.l   WoodyPigMoveFast(pc),a0         ; 0C626
l_0C62A:
        move.l  a0,O_MoveTable(a5)              ; 0C62A
        move.b  O_Param(a5),d0                  ; 0C62E
        addq.b  #$1,d0                          ; 0C632
        move.b  d0,O_Step(a5)                   ; 0C634
        rts                                     ; 0C638

;---------------------------------------------------------------------------
; Double speed until inside the screen (16-240 px from its left edge)
;---------------------------------------------------------------------------
WoodyPig_FlyIn:
        tst.b   O_Step2(a5)                     ; 0C63A
        bne.b   l_0C65A                         ; 0C63E
        lea.l   WoodyPig_AnimFlyB(pc),a0        ; 0C640
        cmpi.b  #$9,O_Dir(a5)                   ; 0C644
        bne.b   l_0C650                         ; 0C64A
        lea.l   WoodyPig_AnimFlyA(pc),a0        ; 0C64C
l_0C650:
        bsr.w   SetAnim                         ; 0C650  start animation
        move.b  #$1,O_Step2(a5)                 ; 0C654
l_0C65A:
        move.w  O_X(a5),d0                      ; 0C65A
        sub.w   g_CameraX(a6),d0                ; 0C65E
        addi.w  #$10,d0                         ; 0C662
        cmp.w   #$e0,d0                         ; 0C666
        bls.b   l_0C678                         ; 0C66A
        bsr.w   Animate                         ; 0C66C  animate
        bsr.w   ApplyMoveTable                  ; 0C670  move by the movement table
        bra.w   ApplyMoveTable                  ; 0C674
l_0C678:
        move.b  #ST_ACTIVE,O_State(a5)          ; 0C678
        clr.b   O_Step(a5)                      ; 0C67E
        clr.b   O_Step2(a5)                     ; 0C682
        rts                                     ; 0C686

;---------------------------------------------------------------------------
; Emerging animation (12-frame delay first); hittable at frame 4
;---------------------------------------------------------------------------
WoodyPig_Emerge:
        tst.b   O_Step2(a5)                     ; 0C688
        bne.b   l_0C6B4                         ; 0C68C
        move.b  #$0,O_Size(a5)                  ; 0C68E
        lea.l   WoodyPig_AnimEmergeB(pc),a0     ; 0C694
        cmpi.b  #$9,O_Dir(a5)                   ; 0C698
        bne.b   l_0C6A4                         ; 0C69E
        lea.l   WoodyPig_AnimEmergeA(pc),a0     ; 0C6A0
l_0C6A4:
        move.b  #$c,Pig_Turns(a5)               ; 0C6A4
        bsr.w   SetAnim                         ; 0C6AA  start animation
        addq.b  #$1,O_Step2(a5)                 ; 0C6AE
        rts                                     ; 0C6B2
l_0C6B4:
        subq.b  #$1,Pig_Turns(a5)               ; 0C6B4
        bne.b   l_0C6E8                         ; 0C6B8
        bsr.w   Animate                         ; 0C6BA  animate
        move.b  #$1,Pig_Turns(a5)               ; 0C6BE
        move.b  O_Frame(a5),d0                  ; 0C6C4
        cmp.b   #$4,d0                          ; 0C6C8
        bcs.b   l_0C6E8                         ; 0C6CC
        move.b  #$2,O_Size(a5)                  ; 0C6CE
        tst.b   O_AnimTimer(a5)                 ; 0C6D4
        bne.b   l_0C6E8                         ; 0C6D8
        move.b  #ST_ACTIVE,O_State(a5)          ; 0C6DA
        clr.b   O_Step(a5)                      ; 0C6E0
        clr.b   O_Step2(a5)                     ; 0C6E4
l_0C6E8:
        rts                                     ; 0C6E8

;---------------------------------------------------------------------------
; 16 directions, 1 = right, 5 = down, 9 = left, 13 = up, 1.55 px/frame (0 = still)
;---------------------------------------------------------------------------
WoodyPigMoveTable:
	dc.b	$00,$00,$00,$00,$01,$8D,$00,$00,$01,$6E,$FF,$69,$01,$18,$FE,$E8
	dc.b	$00,$97,$FE,$92,$00,$00,$FE,$73,$FF,$69,$FE,$92,$FE,$E8,$FE,$E8
	dc.b	$FE,$92,$FF,$69,$FE,$73,$00,$00,$FE,$92,$00,$97,$FE,$E8,$01,$18
	dc.b	$FF,$69,$01,$6E,$00,$00,$01,$8D,$00,$97,$01,$6E,$01,$18,$01,$18
	dc.b	$01,$6E,$00,$97

;---------------------------------------------------------------------------
; The same at 2.25 px/frame
;---------------------------------------------------------------------------
WoodyPigMoveFast:
	dc.b	$00,$00,$00,$00,$02,$40,$00,$00,$01,$6E,$FF,$69,$01,$18,$FE,$E8
	dc.b	$00,$97,$FE,$92,$00,$00,$FE,$73,$FF,$69,$FE,$92,$FE,$E8,$FE,$E8
	dc.b	$FE,$92,$FF,$69,$FD,$C0,$00,$00,$FE,$92,$00,$97,$FE,$E8,$01,$18
	dc.b	$FF,$69,$01,$6E,$00,$00,$01,$8D,$00,$97,$01,$6E,$01,$18,$01,$18
	dc.b	$01,$6E,$00,$97

;---------------------------------------------------------------------------
; Woody Pig animations, one set per facing (A / B): emerge from the tree, fly, turn
; (ends flying the other way), drop pose
