	AF	$01,12
	AF	$02,12
	AL	$07,12,WoodyPig_AnimFlyA
WoodyPig_AnimFlyA:
	AF	$04,5
	AL	$05,5,WoodyPig_AnimFlyA
WoodyPig_AnimTurnA:
	AF	$08,10
	AF	$09,5
	AL	$0E,10,WoodyPig_AnimFlyB
WoodyPig_AnimDropA:
	AF	$04,1
	AF	$05,1
	AL	$06,100,WoodyPig_AnimDropA
WoodyPig_AnimEmergeB:
	AF	$00,12
	AF	$01,12
	AF	$03,12
	AL	$0D,12,WoodyPig_AnimFlyB
WoodyPig_AnimFlyB:
	AF	$0A,5
	AL	$0B,5,WoodyPig_AnimFlyB
WoodyPig_AnimTurnB:
	AF	$0E,10
	AF	$0F,5
	AL	$08,10,WoodyPig_AnimFlyA
WoodyPig_AnimDropB:
	AF	$0A,1
	AF	$0B,1
	AL	$0C,100,WoodyPig_AnimDropB

;---------------------------------------------------------------------------
; State 1. O_Step: 0 fly, 1 loop, 2 drop
