WoodyPig_Active_Jumps:
        bra.w   WoodyPig_Fly                    ; 0C7C0
        bra.w   WoodyPig_Loop                   ; 0C7C4
        bra.w   WoodyPig_Drop                   ; 0C7C8

;---------------------------------------------------------------------------
; Added to Pig_LoopAcc by |dx| / 32 (0-3): $4C, $50, $26, $19; nothing at 128+
;---------------------------------------------------------------------------
WoodyPigLoopOdds:
	dc.b	$4C,$50,$26,$19,$00,$00,$00,$00

