        add.w   d7,d0                           ; 0C7D8
        andi.b  #$75,d0                         ; 0C7DA
        bne.b   l_0C7E6                         ; 0C7DE
        moveq   #SFX_WOODY_PIG,d0               ; 0C7E0  [1MB]   << changed from the 512K build ($0C8AC: moveq #$19, d0) >>
        bsr.w   PlaySfx                         ; 0C7E2  [1MB] effect 18: Woody Pig flying  << 1MB only: 1 instruction(s) not in the 512K build >>
l_0C7E6:
        tst.b   O_Step2(a5)                     ; 0C7E6
        bne.b   l_0C80A                         ; 0C7EA
        move.b  #$1,(a5)                        ; 0C7EC
        lea.l   WoodyPig_AnimFlyB(pc),a0        ; 0C7F0
        cmpi.b  #$9,O_Dir(a5)                   ; 0C7F4
        bne.b   l_0C800                         ; 0C7FA
