        bsr.w   ApplyMoveTable                  ; 0C80E  move by the movement table
        tst.b   Pig_Loops(a5)                   ; 0C812
        beq.b   l_0C850                         ; 0C816
        move.w  g_GameFrame(a6),d0              ; 0C818
        add.w   d7,d0                           ; 0C81C
        andi.w  #$f,d0                          ; 0C81E
        bne.b   l_0C850                         ; 0C822
        move.w  O_X(a5),d0                      ; 0C824
        sub.w   g_ArthurX(a6),d0                ; 0C828
        bpl.b   l_0C830                         ; 0C82C
        neg.w   d0                              ; 0C82E
l_0C830:
        cmp.w   #$100,d0                        ; 0C830
        bcc.b   l_0C850                         ; 0C834
        lsr.w   #$5,d0                          ; 0C836
        move.b  WoodyPigLoopOdds(pc,d0.w),d0    ; 0C838
        add.b   d0,Pig_LoopAcc(a5)              ; 0C83C
        bcc.b   l_0C850                         ; 0C840
        move.b  #$1,O_Step(a5)                  ; 0C842
        clr.b   O_Step2(a5)                     ; 0C848
        subq.b  #$1,Pig_Loops(a5)               ; 0C84C
l_0C850:
        bsr.w   CheckFarAway                    ; 0C850  remove when far off-screen
        tst.b   Pig_Drop(a5)                    ; 0C854
        bne.b   WoodyPig_PickUp                 ; 0C858
        move.w  g_GameFrame(a6),d0              ; 0C85A
        add.b   d7,d0                           ; 0C85E
        addq.b  #$1,d0                          ; 0C860
        andi.b  #$f,d0                          ; 0C862
        bne.b   l_0C8A4                         ; 0C866
        move.w  O_X(a5),d0                      ; 0C868
        sub.w   g_ArthurX(a6),d0                ; 0C86C
        addi.w  #$10,d0                         ; 0C870
        cmp.w   #$20,d0                         ; 0C874
        bls.b   l_0C8A4                         ; 0C878
        move.w  O_Y(a5),d0                      ; 0C87A
