        move.b  #$2,O_Step(a5)                  ; 0C8D6
        clr.b   O_Step2(a5)                     ; 0C8DC
        rts                                     ; 0C8E0

;---------------------------------------------------------------------------
; Frames per 1/16 turn of a loop (two variants, by slot number)
;---------------------------------------------------------------------------
WoodyPigLoopTimes:
	dc.b	$07,$02,$01,$04,$01,$02,$07,$01,$0A,$04,$03,$06,$03,$04,$0A,$01

