        cmp.w   O_Y(a5),d0                      ; 0C944
        bhi.b   l_0C97C                         ; 0C948
        addi.w  #$20,d0                         ; 0C94A
        bhi.b   l_0C958                         ; 0C94E
        addi.b  #$26,Pig_TurnAcc(a5)            ; 0C950
        bcs.b   l_0C97C                         ; 0C956
l_0C958:
