        movea.l Pig_TurnPtr(a5),a0              ; 0C96E
        move.b  (a0),Pig_TurnTime(a5)           ; 0C972
        addq.b  #$1,O_Step2(a5)                 ; 0C976
        rts                                     ; 0C97A
l_0C97C:
        move.b  #$ff,d1                         ; 0C97C
        cmpi.b  #$5,O_Dir(a5)                   ; 0C980
        bcs.b   l_0C964                         ; 0C986
        moveq   #$1,d1                          ; 0C988
        bra.b   l_0C964                         ; 0C98A

;---------------------------------------------------------------------------
; 8 steps of 1/16 turn (directions wrap 16 -> 1)
;---------------------------------------------------------------------------
WoodyPig_Turn:
