;---------------------------------------------------------------------------
; === Petite Devil (type 2, 100 pts) ===
; Small flying devil: homes on Arthur (DirectionToArthur), random changes of direction, fires projectiles.
; Dispatches on O_State: 0 main behaviour, 1 type-specific second phase, 2 killed (set by EnemyHitByShot after scoring), 3 remove.
;
; Behaviour, as coded: flies in for 80-111 frames (shots pass through for the first 32),
; then hunts Arthur in up to 4 legs of 48-111 frames: at the start of each leg it picks a
; direction towards him and a turn rate from the vertical distance, then turns 1/16 at a time
; towards it. It fires one shot only (enemy shot type 8): sideways at Arthur when level with
; him (within 16 px up, 50 px across), or straight down when directly above (5 px across,
; 60 px above), and then recoils in a turning sweep. After its legs it leaves. It never flies
; below Y = 54 (world).
; Bug (checked in the emulator, tools/verify): the turning code (PetiteDevil_TurnCW/CCW)
; works out the new direction in d0 and then stores #1 instead, so once a devil starts
; turning it flies in direction 1 - right and a little down - whatever it was turning to.
;---------------------------------------------------------------------------
Enemy_PetiteDevil:
        move.b  O_State(a5),d0                  ; 0D0A6
        add.w   d0,d0                           ; 0D0AA
        add.w   d0,d0                           ; 0D0AC
        jmp     Enemy_PetiteDevil_Jumps(pc,d0.w)             ; 0D0AE
Enemy_PetiteDevil_Jumps:
        bra.w   PetiteDevil_Init                ; 0D0B2
        bra.w   PetiteDevil_Active              ; 0D0B6
        bra.w   PetiteDevil_Dying               ; 0D0BA
        bra.w   PetiteDevil_Free                ; 0D0BE

;---------------------------------------------------------------------------
; State 0, by O_Param: 0 fly in, 1 fly in (finer turns), 2 random timers
;---------------------------------------------------------------------------
PetiteDevil_Init:
        move.b  O_Param(a5),d0                  ; 0D0C2
        add.w   d0,d0                           ; 0D0C6
        add.w   d0,d0                           ; 0D0C8
        jmp     PetiteDevil_Init_Jumps(pc,d0.w) ; 0D0CA
PetiteDevil_Init_Jumps:
        bra.w   PetiteDevil_Init0               ; 0D0CE
        bra.w   PetiteDevil_Init1               ; 0D0D2
        bra.w   PetiteDevil_Init2               ; 0D0D6
PetiteDevil_Init0:
        tst.b   O_Step(a5)                      ; 0D0DA
        beq.b   l_0D156                         ; 0D0DE
        bsr.w   CheckOnScreen                   ; 0D0E0  visible?
        move.b  (a5),d0                         ; 0D0E4
        add.b   d0,(a5)                         ; 0D0E6
        bsr.b   PetiteDevil_Setup               ; 0D0E8
        lea.l   PetiteDevil_AnimStartA(pc),a0   ; 0D0EA
        clr.b   O_Dir(a5)                       ; 0D0EE
        move.w  O_X(a5),d0                      ; 0D0F2
        cmp.w   g_ArthurX(a6),d0                ; 0D0F6
        ble.b   l_0D106                         ; 0D0FA
        move.b  #$1,O_Dir(a5)                   ; 0D0FC
        lea.l   PetiteDevil_AnimStartB(pc),a0   ; 0D102
l_0D106:
        bsr.w   SetAnim                         ; 0D106  start animation
        clr.b   O_Size(a5)                      ; 0D10A
        lea.l   PetiteDevilMove16(pc),a0        ; 0D10E
        move.l  a0,PD_MoveTable(a5)             ; 0D112
        clr.b   PD_Fine(a5)                     ; 0D116
        move.b  #$1,PD_Shot(a5)                 ; 0D11A
        rts                                     ; 0D120

;---------------------------------------------------------------------------
; Size 0, move table, 4 legs, aim at Arthur's height, go to state 1
;---------------------------------------------------------------------------
PetiteDevil_Setup:
        clr.b   O_Size(a5)                      ; 0D122
        lea.l   PetiteDevilMoveTable(pc),a0     ; 0D126
        move.l  a0,O_MoveTable(a5)              ; 0D12A
        move.b  #$4,PD_Legs(a5)                 ; 0D12E
        move.b  #$2,PD_Turn(a5)                 ; 0D134
        move.w  g_ArthurY(a6),PD_TargetY(a5)    ; 0D13A
        move.b  #$1,PD_EarlyShot(a5)            ; 0D140
        move.b  #ST_ACTIVE,O_State(a5)          ; 0D146
        clr.b   O_Step(a5)                      ; 0D14C
        clr.b   O_Step2(a5)                     ; 0D150
        rts                                     ; 0D154
l_0D156:
        addq.b  #$1,O_Step(a5)                  ; 0D156  next step
        rts                                     ; 0D15A

;---------------------------------------------------------------------------
; Unused: follow a list of map positions (PetiteDevilPath) and appear at the first
; one that is on screen
;---------------------------------------------------------------------------
PetiteDevil_PathUnused:	; (no references found - unused/debug code)
        tst.b   O_Step2(a5)                     ; 0D15C
        bne.b   l_0D1AC                         ; 0D160
        clr.l   O_Anim(a5)                      ; 0D162
        clr.w   O_X(a5)                         ; 0D166
        clr.w   O_Y(a5)                         ; 0D16A
        moveq   #$1,d0                          ; 0D16E
        and.w   g_GameFrame(a6),d0              ; 0D170
        move.b  d0,PD_Time(a5)                  ; 0D174
        lea.l   PetiteDevilPath(pc),a0          ; 0D178
        bsr.b   PetiteDevil_PathNext            ; 0D17C
        move.b  #$9,PD_TurnRate(a5)             ; 0D17E
        addq.b  #$1,O_Step2(a5)                 ; 0D184
        rts                                     ; 0D188
PetiteDevil_PathNext:
        move.w  (a0)+,d0                        ; 0D18A  path list entry: offset to a segment set, then its turn count
        move.l  a0,PD_PathPos(a5)               ; 0D18C
        adda.w  d0,a0                           ; 0D190
        move.w  (a0)+,d0                        ; 0D192
        move.b  d0,PD_TurnWait(a5)              ; 0D194
        move.b  PD_Time(a5),d0                  ; 0D198  PD_Time 0 picks the alternative set (one entry back)
        bne.b   l_0D1A6                         ; 0D19C
        subq.b  #$1,d0                          ; 0D19E
        lsl.b   #$2,d0                          ; 0D1A0
        ext.w   d0                              ; 0D1A2
        adda.w  d0,a0                           ; 0D1A4
l_0D1A6:
        move.l  a0,PD_PathSeg(a5)               ; 0D1A6
        rts                                     ; 0D1AA
l_0D1AC:
        movea.l PD_PathSeg(a5),a0               ; 0D1AC  is the segment start on screen (camera X .. +256, Y + 32 .. + 224)?
        move.w  g_CameraX(a6),d0                ; 0D1B0
        cmp.w   (a0),d0                         ; 0D1B4
        bhi.b   l_0D1EE                         ; 0D1B6
        addi.w  #$100,d0                        ; 0D1B8
        cmp.w   (a0),d0                         ; 0D1BC
        bcs.b   l_0D1EE                         ; 0D1BE
        move.w  g_CameraY(a6),d0                ; 0D1C0
        addi.w  #$20,d0                         ; 0D1C4
        cmp.w   $2(a0),d0                       ; 0D1C8
        bhi.b   l_0D1EE                         ; 0D1CC
        addi.w  #$c0,d0                         ; 0D1CE
        cmp.w   $2(a0),d0                       ; 0D1D2
        bcs.b   l_0D1EE                         ; 0D1D6
        nop                                     ; 0D1D8
        move.w  (a0)+,O_X(a5)                   ; 0D1DA  yes: appear there
        move.w  (a0)+,O_Y(a5)                   ; 0D1DE
        move.b  #$1,O_Step(a5)                  ; 0D1E2
        clr.b   O_Step2(a5)                     ; 0D1E8
        rts                                     ; 0D1EC
l_0D1EE:
        subq.l  #$4,a0                          ; 0D1EE  no: try the next segment (or the alternative)
        tst.b   PD_Time(a5)                     ; 0D1F0
        bne.b   l_0D1F8                         ; 0D1F4
        addq.l  #$8,a0                          ; 0D1F6
l_0D1F8:
        move.l  a0,PD_PathSeg(a5)               ; 0D1F8
        subq.b  #$1,PD_TurnWait(a5)             ; 0D1FC  after PD_TurnWait tries take the next entry; when PD_TurnRate runs out, give up
        bne.b   l_0D214                         ; 0D200
        movea.l PD_PathPos(a5),a0               ; 0D202
        bsr.b   PetiteDevil_PathNext            ; 0D206
        subq.b  #$1,PD_TurnRate(a5)             ; 0D208
        bne.b   l_0D214                         ; 0D20C
        move.b  #ST_REMOVE,O_State(a5)          ; 0D20E
l_0D214:
        rts                                     ; 0D214

;---------------------------------------------------------------------------
; PetiteDevilPath (unused) - nine word offsets, each from its entry to a list: count, then
; that many (x, y) world positions where the devil may appear.
; BUG (in the unused PetiteDevil_PathUnused): PetiteDevil_PathNext adds the offset after
; stepping past it, so it lands 2 bytes on: the first X is taken as the count and the segment
; pointer starts at a Y. The lists only work when read from the entry itself.
;---------------------------------------------------------------------------
PetiteDevilPath:
	dc.w	PetiteDevilPath_0-*	; 0
	dc.w	PetiteDevilPath_1-*	; 1
	dc.w	PetiteDevilPath_2-*	; 2
	dc.w	PetiteDevilPath_3-*	; 3
	dc.w	PetiteDevilPath_4-*	; 4
	dc.w	PetiteDevilPath_5-*	; 5
	dc.w	PetiteDevilPath_6-*	; 6
	dc.w	PetiteDevilPath_7-*	; 7
	dc.w	PetiteDevilPath_8-*	; 8
PetiteDevilPath_8:
	dc.w	2		; points
	dc.w	$0E48,$0098	; world x, y
	dc.w	$0E48,$00F4	; world x, y
PetiteDevilPath_7:
	dc.w	1		; points
	dc.w	$0E98,$0064	; world x, y
PetiteDevilPath_6:
	dc.w	4		; points
	dc.w	$0EF8,$0088	; world x, y
	dc.w	$0EF8,$00E8	; world x, y
	dc.w	$0EF8,$0148	; world x, y
	dc.w	$0EF8,$0188	; world x, y
PetiteDevilPath_5:
	dc.w	2		; points
	dc.w	$0F48,$0194	; world x, y
	dc.w	$0F48,$01C4	; world x, y
PetiteDevilPath_4:
	dc.w	4		; points
	dc.w	$0F78,$0054	; world x, y
	dc.w	$0F78,$0074	; world x, y
	dc.w	$0F78,$0118	; world x, y
	dc.w	$0F78,$0154	; world x, y
PetiteDevilPath_3:
	dc.w	3		; points
	dc.w	$0FD8,$00F4	; world x, y
	dc.w	$0FD8,$0148	; world x, y
	dc.w	$0FD8,$0184	; world x, y
PetiteDevilPath_2:
	dc.w	3		; points
	dc.w	$1008,$0064	; world x, y
	dc.w	$1008,$00A8	; world x, y
	dc.w	$1018,$01A8	; world x, y
PetiteDevilPath_1:
	dc.w	4		; points
	dc.w	$1068,$0058	; world x, y
	dc.w	$1068,$00B8	; world x, y
	dc.w	$1058,$0108	; world x, y
	dc.w	$1068,$0168	; world x, y
PetiteDevilPath_0:
	dc.w	3		; points
	dc.w	$10D8,$00B4	; world x, y
	dc.w	$10D8,$00F4	; world x, y
	dc.w	$10D8,$0168	; world x, y
PetiteDevil_Init1:
        bsr.w   PetiteDevil_Setup               ; 0D2A2
        move.b  #$2,O_Dir(a5)                   ; 0D2A6
        lea.l   PetiteDevil_AnimFly(pc),a0      ; 0D2AC
        bsr.w   SetAnim                         ; 0D2B0  start animation
        lea.l   PetiteDevilMove16Fast(pc),a0    ; 0D2B4
        move.l  a0,PD_MoveTable(a5)             ; 0D2B8
        move.b  #$1,PD_Fine(a5)                 ; 0D2BC
        move.b  #$1,PD_Shot(a5)                 ; 0D2C2
        rts                                     ; 0D2C8

;---------------------------------------------------------------------------
; Random early-shot flag and 64-95 frames before it may fire
;---------------------------------------------------------------------------
PetiteDevil_Init2:
        bsr.w   PetiteDevil_Setup               ; 0D2CA
        move.b  (a5),d0                         ; 0D2CE
        add.b   d0,(a5)                         ; 0D2D0
        lea.l   PetiteDevil_AnimA(pc),a0        ; 0D2D2
        clr.b   O_Dir(a5)                       ; 0D2D6
        move.w  O_X(a5),d0                      ; 0D2DA
        cmp.w   g_ArthurX(a6),d0                ; 0D2DE
        ble.b   l_0D2EE                         ; 0D2E2
        move.b  #$1,O_Dir(a5)                   ; 0D2E4
        lea.l   PetiteDevil_AnimB(pc),a0        ; 0D2EA
l_0D2EE:
        move.l  a0,O_Anim(a5)                   ; 0D2EE
        clr.b   O_Size(a5)                      ; 0D2F2
        lea.l   PetiteDevilMove16(pc),a0        ; 0D2F6
        move.l  a0,PD_MoveTable(a5)             ; 0D2FA
        clr.b   PD_Fine(a5)                     ; 0D2FE
        bsr.w   Random                          ; 0D302  random number
        andi.w  #$f,d0                          ; 0D306
        move.b  PetiteDevilArriveShot(pc,d0.w),PD_EarlyShot(a5); 0D30A
        bsr.w   Random                          ; 0D310  random number
        andi.b  #$1f,d0                         ; 0D314
        addi.b  #$40,d0                         ; 0D318
        move.b  d0,PD_ShotTime(a5)              ; 0D31C
        clr.b   PD_Ready(a5)                    ; 0D320
        clr.b   PD_Shot(a5)                     ; 0D324
        rts                                     ; 0D328
PetiteDevilArriveShot:
	dc.b	$00,$00,$01,$00,$00,$00,$01,$00,$01,$00,$00,$01,$00,$00,$10,$00

;---------------------------------------------------------------------------
; move table after the first 32 frames
;---------------------------------------------------------------------------
PetiteDevilFlyIn:
	dc.b	$01,$65,$00,$00,$FE,$9B,$00,$00,$00,$00,$01,$65

;---------------------------------------------------------------------------
; State 1. O_Step: 0 arrive, 1 hunt, 2 recoil, 3 leave. Param 0: removed when off screen.
;---------------------------------------------------------------------------
PetiteDevil_Active:
        move.w  g_GameFrame(a6),d0              ; 0D346
        add.w   d7,d0                           ; 0D34A
        andi.w  #$1f,d0                         ; 0D34C
        bne.b   l_0D354                         ; 0D350
        moveq   #$b,d0                          ; 0D352  d0 is overwritten at once (a sound call removed in both builds)
l_0D354:
        move.b  O_Step(a5),d0                   ; 0D354
