;---------------------------------------------------------------------------
; === Flying Knight (type 3, 100 pts) ===
; Shielded knight flying in a wave pattern (movement table, random variation). Sound effect 20.
; Dispatches on O_State: 0 main behaviour, 1 type-specific second phase, 2 killed (set by EnemyHitByShot after scoring), 3 remove.
;
; Behaviour, as coded: flies left at 1.06 px/frame in a wave about 50 px up and down from
; where it started (random first half-wave up or down). Its shield makes it immune
; (O_Active $81, shots pass through) until it has flown past Arthur - only then can it be hit
; (from behind).
;---------------------------------------------------------------------------
Enemy_FlyingKnight:
        move.b  O_State(a5),d0                  ; 0D97E
        add.w   d0,d0                           ; 0D982
        add.w   d0,d0                           ; 0D984
        jmp     Enemy_FlyingKnight_Jumps(pc,d0.w)             ; 0D986
Enemy_FlyingKnight_Jumps:
        bra.w   FlyingKnight_Init               ; 0D98A
        bra.w   FlyingKnight_Active             ; 0D98E
        bra.w   FlyingKnight_Dying              ; 0D992
        bra.w   FlyingKnight_Free               ; 0D996

;---------------------------------------------------------------------------
; State 0: size 1, move table, wave
;---------------------------------------------------------------------------
FlyingKnight_Init:
        move.b  #$1,O_Size(a5)                  ; 0D99A
        clr.b   O_Dir(a5)                       ; 0D9A0
        lea.l   FlyingKnight_AnimUp(pc),a0      ; 0D9A4
        bsr.w   SetAnim                         ; 0D9A8  start animation
        lea.l   FlyingKnightMove(pc),a0         ; 0D9AC
        move.l  a0,O_MoveTable(a5)              ; 0D9B0
        addq.b  #ST_ACTIVE,O_State(a5)          ; 0D9B4
        clr.b   O_Step(a5)                      ; 0D9B8
        rts                                     ; 0D9BC
FlyingKnight_AnimUp:
	AF	$00,3
	AL	$01,3,FlyingKnight_AnimUp
FlyingKnight_AnimDown:
	AF	$02,3
	AL	$03,3,FlyingKnight_AnimDown

;---------------------------------------------------------------------------
; -1.06 px/frame for both halves of the wave
;---------------------------------------------------------------------------
FlyingKnightMove:
	dc.b	$FE,$F0,$00,$00,$FE,$F0,$00,$00
FlyingKnightSteps:
        bra.w   FlyingKnight_Start              ; 0D9D2
        bra.w   FlyingKnight_WaveUp             ; 0D9D6
        bra.w   FlyingKnight_WaveDown           ; 0D9DA

;---------------------------------------------------------------------------
; State 1. O_Step: 0 start, 1 upper half-wave, 2 lower half-wave
;---------------------------------------------------------------------------
FlyingKnight_Active:
        clr.w   d0                              ; 0D9DE
        move.b  O_Step(a5),d0                   ; 0D9E0
        add.w   d0,d0                           ; 0D9E4
        add.w   d0,d0                           ; 0D9E6
        jsr     FlyingKnightSteps(pc,d0.w)      ; 0D9E8
        move.w  g_GameFrame(a6),d0              ; 0D9EC
        addq.b  #$1,d0                          ; 0D9F0
        andi.b  #$1f,d0                         ; 0D9F2
        bne.w   CheckFarAway                    ; 0D9F6
        rts                                     ; 0D9FA

;---------------------------------------------------------------------------
; Shielded ($81); random first half-wave
;---------------------------------------------------------------------------
FlyingKnight_Start:
        move.w  O_Y(a5),FK_BaseY(a5)            ; 0D9FC
        clr.b   FK_Phase(a5)                    ; 0DA02
        move.b  #$81,(a5)                       ; 0DA06  shield up: shots pass through
        clr.b   d1                              ; 0DA0A
        bsr.w   Random                          ; 0DA0C  random number
        andi.b  #$1,d0                          ; 0DA10
        beq.b   l_0DA24                         ; 0DA14
        lea.l   FlyingKnight_AnimDown(pc),a0    ; 0DA16
        bsr.w   SetAnim                         ; 0DA1A  start animation
        addq.b  #$1,d1                          ; 0DA1E
        addq.b  #$1,O_Step(a5)                  ; 0DA20  next step
l_0DA24:
        addq.b  #$1,O_Step(a5)                  ; 0DA24  next step
        move.b  d1,O_Dir(a5)                    ; 0DA28
        rts                                     ; 0DA2C
FlyingKnight_WaveUp:
        bsr.b   FlyingKnight_Move               ; 0DA2E
        add.w   FK_BaseY(a5),d0                 ; 0DA30
        move.w  d0,O_Y(a5)                      ; 0DA34
        addq.b  #$6,FK_Phase(a5)                ; 0DA38
        bcc.b   l_0DA4E                         ; 0DA3C
        addq.b  #$1,O_Dir(a5)                   ; 0DA3E
        lea.l   FlyingKnight_AnimDown(pc),a0    ; 0DA42
        bsr.w   SetAnim                         ; 0DA46  start animation
        addq.b  #$1,O_Step(a5)                  ; 0DA4A  next step
l_0DA4E:
        rts                                     ; 0DA4E
FlyingKnight_WaveDown:
        bsr.b   FlyingKnight_Move               ; 0DA50
        neg.w   d0                              ; 0DA52
        add.w   FK_BaseY(a5),d0                 ; 0DA54
        move.w  d0,O_Y(a5)                      ; 0DA58
        addq.b  #$6,FK_Phase(a5)                ; 0DA5C
        bcc.b   l_0DA4E                         ; 0DA60
        clr.b   O_Dir(a5)                       ; 0DA62
        move.b  #$1,O_Step(a5)                  ; 0DA66
        lea.l   FlyingKnight_AnimUp(pc),a0      ; 0DA6C
        bsr.w   SetAnim                         ; 0DA70  start animation
        rts                                     ; 0DA74

;---------------------------------------------------------------------------
; Move, animate; drop the shield once past Arthur; d0 = sin(phase) x 2 x 50 / 256
;---------------------------------------------------------------------------
FlyingKnight_Move:
        bsr.w   ApplyMoveTable                  ; 0DA76  move by the movement table
        bsr.w   Animate                         ; 0DA7A  animate
        tst.b   (a5)                            ; 0DA7E
        bpl.b   l_0DA90                         ; 0DA80
        move.w  O_X(a5),d0                      ; 0DA82
        cmp.w   g_ArthurX(a6),d0                ; 0DA86
        bcc.b   l_0DA90                         ; 0DA8A
        move.b  #$1,(a5)                        ; 0DA8C  past Arthur: can be hit
l_0DA90:
        lea.l   SineTable(pc),a0                ; 0DA90
        clr.w   d0                              ; 0DA94
        move.b  FK_Phase(a5),d0                 ; 0DA96
        move.b  (a0,d0.w),d0                    ; 0DA9A
        lsl.b   #$1,d0                          ; 0DA9E
        mulu.w  #$32,d0                         ; 0DAA0
        lsr.w   #$8,d0                          ; 0DAA4
        rts                                     ; 0DAA6

;---------------------------------------------------------------------------
; State 2: sound 20, EnemyBurst
;---------------------------------------------------------------------------
FlyingKnight_Dying:
        cmpi.b  #$1,O_Step(a5)                  ; 0DAA8
        beq.b   l_0DABE                         ; 0DAAE
        bcc.b   l_0DAC2                         ; 0DAB0
        moveq   #SFX_ENEMY_DIE2,d0              ; 0DAB2
        bsr.w   PlaySfx                         ; 0DAB4  sound effect 20 (enemy event)
        addq.b  #$1,O_Step(a5)                  ; 0DAB8  next step
        rts                                     ; 0DABC
l_0DABE:
        bra.w   EnemyBurst                      ; 0DABE
l_0DAC2:
        move.b  #ST_REMOVE,O_State(a5)          ; 0DAC2
        rts                                     ; 0DAC8

;---------------------------------------------------------------------------
; State 3: free the slot, give the spawn quota back
;---------------------------------------------------------------------------
FlyingKnight_Free:
        clr.b   (a5)                            ; 0DACA  free this enemy slot
        addq.b  #$1,g_SpawnQuota+3(a6)          ; 0DACC
        rts                                     ; 0DAD0

;---------------------------------------------------------------------------
; 256 bytes: 127 x sin(pi x i / 256) - a half sine, 0 up to 127 and back.
; Shared by most flying enemies for their arcs and waves.
;---------------------------------------------------------------------------
SineTable:
	dc.b	$00,$02,$03,$05,$06,$08,$09,$0B,$0C,$0E,$10,$11,$13,$14,$16,$17
	dc.b	$19,$1A,$1C,$1D,$1F
	dc.b	' "#%&()+,./1235689:<=?@ACDEGHIJLMNOQRSTUVXYZ[\]^_`abcdefghijjklmnoopqqrsstuuvvwxxyyzzz{{|||}}}}~~~~~'
	dc.b	$7F,$7F,$7F,$7F,$7F,$7F,$7F

;---------------------------------------------------------------------------
; SineTable + 128 (127 down to 0): used as a cosine for the Red Arremer's dive
;---------------------------------------------------------------------------
SineTableFalling:
	dc.b	$7F,$7F,$7F,$7F,$7F,$7F,$7F,$7F
	dc.b	'~~~~~}}}}|||{{zzzyyxxwvvuutssrqqpoonmlkjjihgfedcba`_^]\[ZYXVUTSRQONMLJIHGEDCA@?=<:9865321/.,+)(&%#" '
	dc.b	$1F,$1D,$1C,$1A,$19,$17,$16,$14,$13,$11,$10,$0E,$0C,$0B,$09,$08
	dc.b	$06,$05,$03,$02

;---------------------------------------------------------------------------
; === Blue Killer (type 4, 100 pts) ===
; Small winged devil that drops/hops along the scenery (map collision), random behaviour. Sound effect 17.
; Dispatches on O_State: 0 main behaviour, 1 type-specific second phase, 2 killed (set by EnemyHitByShot after scoring), 3 remove.
;
; Behaviour, as coded:
;   * Parameter 0: walks in from the edge of the screen. Other parameters: drops from above
;     (shots pass through until it appears), swooping down in a curve towards Arthur, or
;     straight down when it is over him, then lands.
;   * On the floor it walks towards Arthur at 1.43 px/frame for random times (16-180
;     frames), hopping (32 or 48 px, 64 frames) out of the way when one of Arthur's shots
;     comes at it while he is more than 128 px away, and hopping off ledges.
;   * After 3600 frames (72 s) it turns into a Red Arremer (O_Type 5, O_Param 2: the blink-in
;     start mode, which then takes 26,352 frames - see Enemy_RedArremer).
;---------------------------------------------------------------------------
Enemy_BlueKiller:
        move.b  O_State(a5),d0                  ; 0DBD2
        add.w   d0,d0                           ; 0DBD6
        add.w   d0,d0                           ; 0DBD8
        jmp     Enemy_BlueKiller_Jumps(pc,d0.w) ; 0DBDA
Enemy_BlueKiller_Jumps:
        bra.w   BlueKiller_Init                 ; 0DBDE
        bra.w   BlueKiller_Active               ; 0DBE2
        bra.w   BlueKiller_Dying                ; 0DBE6
        bra.w   BlueKiller_Free                 ; 0DBEA

;---------------------------------------------------------------------------
; State 0. Parameter 0: walk in from the screen edge; otherwise drop from above
;---------------------------------------------------------------------------
BlueKiller_Init:
        tst.b   O_Param(a5)                     ; 0DBEE
        bne.b   BlueKiller_DropInit             ; 0DBF2
        tst.b   O_Step(a5)                      ; 0DBF4
        bne.b   BlueKiller_WalkIn               ; 0DBF8
BlueKiller_Setup:
        move.w  O_Y(a5),BK_BaseY(a5)            ; 0DBFA
        move.b  #$10,BK_HopHeight(a5)           ; 0DC00
        clr.b   BK_Unused31(a5)                 ; 0DC06
        clr.w   BK_Phase(a5)                    ; 0DC0A
        clr.b   O_Size(a5)                      ; 0DC0E
        bsr.w   BlueKiller_FaceArthur           ; 0DC12
        lea.l   BlueKiller_AnimWalk(pc),a0      ; 0DC16
        bsr.w   SetAnimIndexed                  ; 0DC1A  start animation for current direction
        lea.l   BlueKillerMoveTable(pc),a0      ; 0DC1E
        move.l  a0,O_MoveTable(a5)              ; 0DC22
        addq.b  #$1,O_Step(a5)                  ; 0DC26  next step
        rts                                     ; 0DC2A

;---------------------------------------------------------------------------
; Animate until 16-240 px inside the screen, then start the 3600-frame timer
;---------------------------------------------------------------------------
BlueKiller_WalkIn:
        move.w  O_X(a5),d0                      ; 0DC2C
        sub.w   g_CameraX(a6),d0                ; 0DC30
        subi.w  #$10,d0                         ; 0DC34
        cmp.w   #$e0,d0                         ; 0DC38
        bls.b   l_0DC42                         ; 0DC3C
        bra.w   Animate                         ; 0DC3E
l_0DC42:
        move.w  #$e10,BK_Morph(a5)              ; 0DC42
        addq.b  #ST_ACTIVE,O_State(a5)          ; 0DC48
        clr.b   O_Step(a5)                      ; 0DC4C
        rts                                     ; 0DC50
BlueKiller_DropInit:
        tst.b   O_Step(a5)                      ; 0DC52
        bne.b   BlueKiller_DropSetup            ; 0DC56
        bsr.w   Random                          ; 0DC58  random number
        andi.b  #$f,d0                          ; 0DC5C
        addi.b  #$a,d0                          ; 0DC60
        move.b  d0,BK_CurveWait(a5)             ; 0DC64
        clr.l   O_Anim(a5)                      ; 0DC68
        addq.b  #$1,O_Step(a5)                  ; 0DC6C  next step
        subq.b  #$1,BK_CurveWait(a5)            ; 0DC70
        bne.b   l_0DC80                         ; 0DC74
        move.b  (a5),d0                         ; 0DC76
        lsr.b   #$1,d0                          ; 0DC78
        move.b  d0,(a5)                         ; 0DC7A
        addq.b  #$1,O_Step(a5)                  ; 0DC7C  next step
l_0DC80:
        rts                                     ; 0DC80

;---------------------------------------------------------------------------
; Shots pass through; curve rate from the height above Arthur; step 4 (param 2: 5)
;---------------------------------------------------------------------------
BlueKiller_DropSetup:
        move.b  (a5),d0                         ; 0DC82
        lsl.b   #$1,d0                          ; 0DC84
        move.b  d0,(a5)                         ; 0DC86
        bsr.w   CheckOnScreen                   ; 0DC88  visible?
        move.w  #$e10,BK_Morph(a5)              ; 0DC8C
        addq.b  #ST_ACTIVE,O_State(a5)          ; 0DC92
        clr.b   O_Step(a5)                      ; 0DC96
        bsr.w   BlueKiller_Setup                ; 0DC9A
        move.w  O_Y(a5),d0                      ; 0DC9E
        move.w  g_ArthurY(a6),d1                ; 0DCA2
        sub.b   d1,d0                           ; 0DCA6
        lsr.b   #$3,d0                          ; 0DCA8
        move.b  d0,BK_CurveRate(a5)             ; 0DCAA
        move.b  d0,BK_CurveWait(a5)             ; 0DCAE
        move.b  #$a,BK_Appear(a5)               ; 0DCB2
        lea.l   BlueKiller_AnimDrop(pc),a0      ; 0DCB8
        move.l  a0,O_Anim(a5)                   ; 0DCBC
        bsr.w   SetAnim                         ; 0DCC0  start animation
        move.b  #ST_ACTIVE,O_State(a5)          ; 0DCC4
        move.b  #$4,O_Step(a5)                  ; 0DCCA
        clr.b   O_Step2(a5)                     ; 0DCD0
        cmpi.b  #$2,O_Param(a5)                 ; 0DCD4
        bne.b   l_0DCE0                         ; 0DCDA
        addq.b  #$1,O_Step(a5)                  ; 0DCDC  next step
l_0DCE0:
        rts                                     ; 0DCE0

;---------------------------------------------------------------------------
; O_Dir 0 if Arthur is to the right, 1 if to the left
;---------------------------------------------------------------------------
BlueKiller_FaceArthur:
        move.w  O_X(a5),d0                      ; 0DCE2
        cmp.w   g_ArthurX(a6),d0                ; 0DCE6
        slt.b   d0                              ; 0DCEA
        addq.b  #$1,d0                          ; 0DCEC
        move.b  d0,O_Dir(a5)                    ; 0DCEE
        rts                                     ; 0DCF2

;---------------------------------------------------------------------------
; State 1. O_Step: 0 walk, 1 walk 2, 2 hop up, 3 hop down, 4 drop, 5 swoop
;---------------------------------------------------------------------------
BlueKiller_Active:
        clr.w   d0                              ; 0DCF4
        move.b  O_Step(a5),d0                   ; 0DCF6
        add.w   d0,d0                           ; 0DCFA
        add.w   d0,d0                           ; 0DCFC
        jsr     BlueKiller_MorphTimer_Jumps(pc,d0.w)             ; 0DCFE
        bsr.w   PetiteDevil_RemoveOffScreen     ; 0DD02
        bsr.b   BlueKiller_MorphTimer           ; 0DD06
        bra.w   CheckFarAway                    ; 0DD08

;---------------------------------------------------------------------------
; After 3600 frames: become a Red Arremer (type 5, parameter 2), from state 0
;---------------------------------------------------------------------------
BlueKiller_MorphTimer:
        subq.w  #$1,BK_Morph(a5)                ; 0DD0C
        bne.b   l_0DD2A                         ; 0DD10
        move.b  #E_REDARREMER,O_Type(a5)        ; 0DD12  turn into a Red Arremer
        move.b  #$2,O_Param(a5)                 ; 0DD18  start mode 2 (blink in)
        clr.b   O_State(a5)                     ; 0DD1E  -> state 0 (spawn)
        clr.b   O_Step(a5)                      ; 0DD22
        clr.b   O_Step2(a5)                     ; 0DD26
l_0DD2A:
