;---------------------------------------------------------------------------
; === Red Arremer (type 5, 1000 pts, 3 hits) ===
; The red gargoyle: walks, takes off and dives at Arthur, hovers and shoots; changes size class between standing and flying. Sound effect 12 when hit.
; Dispatches on O_State: 0 main behaviour, 1 type-specific second phase, 2 killed (set by EnemyHitByShot after scoring), 3 remove.
;
; Behaviour, as coded. O_Param: bits 0-1 = start mode (1 perched, 2 blink in, 0/3 at
; once), bits 2+ = starting aggression.
;   * Perched (mode 1): crouches until Arthur comes within 96 px across and 48 px up or
;     down, or it is shot at, then wakes after 16 frames.
;   * On the ground (O_Step 0) it walks to RedArremerWalkScript, and four timers decide
;     what it does next: shoot (enemy shot type 7) on RedArremerShotTimes, swoop at
;     Arthur on RedArremerSwoopTimes, take off and hover on RedArremerTakeOffTimes (x 8
;     frames), and - once only - rage after 50 x 32 frames: it flashes for 76 frames,
;     then uses the faster tables (RA_Rage 1).
;   * It glides away when Arthur is within 48 px, and towards him when he is 112+ px away.
;   * Dodging: when one of Arthur's shots is flying at it at its height (and Arthur is
;     84+ px away) it jumps up out of the way and hovers.
;   * Swoop: from above, an elliptical dive onto the spot where Arthur stood, then up and
;     away; from level or below, a fast flight past him.
;   * Flying states use size class 9, standing 3. Removed when far above or below the
;     camera.
; Mode 2 (used when a Blue Killer turns into a Red Arremer) counts $F0 down by $61 a frame
; and waits for exactly 0, twice, which takes 2 x 26,352 frames (about 17 minutes) during
; which it blinks and shots pass through it - presumably a bug. The placed Red Arremers use
; mode 1.
;---------------------------------------------------------------------------
Enemy_RedArremer:
        move.b  O_State(a5),d0                  ; 0E140
        add.w   d0,d0                           ; 0E144
        add.w   d0,d0                           ; 0E146
        jmp     Enemy_RedArremer_Jumps(pc,d0.w) ; 0E148
Enemy_RedArremer_Jumps:
        bra.w   RedArremer_Init                 ; 0E14C
        bra.w   RedArremer_Active               ; 0E150
        bra.w   RedArremer_Dying                ; 0E154
        bra.w   RedArremer_Free                 ; 0E158

;---------------------------------------------------------------------------
; State 0. O_Step 0 decode O_Param, 1 perched, 2 blink in, 3 set up
;---------------------------------------------------------------------------
RedArremer_Init:
        move.b  O_Step(a5),d0                   ; 0E15C
        add.w   d0,d0                           ; 0E160
        add.w   d0,d0                           ; 0E162
        jmp     RedArremer_Init_Jumps(pc,d0.w)  ; 0E164
RedArremer_Init_Jumps:
        bra.w   RedArremer_Decode               ; 0E168
        bra.w   RedArremer_Perched              ; 0E16C
        bra.w   RedArremer_BlinkIn              ; 0E170
        bra.w   RedArremer_Setup                ; 0E174
RedArremer_Decode:
        move.b  O_Param(a5),d0                  ; 0E178  starting aggression = O_Param >> 2
        lsr.b   #$2,d0                          ; 0E17C
        move.b  d0,RA_Rage(a5)                  ; 0E17E
        moveq   #$3,d0                          ; 0E182
        and.b   O_Param(a5),d0                  ; 0E184  start mode = O_Param & 3 (0 -> 3)
        bne.b   l_0E18C                         ; 0E188
        moveq   #$3,d0                          ; 0E18A
l_0E18C:
        move.b  d0,O_Step(a5)                   ; 0E18C
        move.b  #$ff,O_HP(a5)                   ; 0E190
        clr.b   O_Param(a5)                     ; 0E196
        rts                                     ; 0E19A
RedArremer_Perched:
        move.b  O_Step2(a5),d0                  ; 0E19C
        add.w   d0,d0                           ; 0E1A0
        add.w   d0,d0                           ; 0E1A2
        jmp     RedArremer_Perched_Jumps(pc,d0.w)             ; 0E1A4
RedArremer_Perched_Jumps:
        bra.w   RedArremer_PerchStart           ; 0E1A8
        bra.w   RedArremer_PerchWait            ; 0E1AC
        bra.w   RedArremer_PerchWake            ; 0E1B0
RedArremer_PerchStart:
        move.b  #$3,O_Size(a5)                  ; 0E1B4
        move.b  #$1,O_Dir(a5)                   ; 0E1BA
        lea.l   RedArremer_AnimPerch(pc),a0     ; 0E1C0
        bsr.w   SetAnim                         ; 0E1C4  start animation
        move.b  #$10,RA_BaseY(a5)               ; 0E1C8
        addq.b  #$1,O_Step2(a5)                 ; 0E1CE
        rts                                     ; 0E1D2

;---------------------------------------------------------------------------
; Wake when Arthur is within +-96 px across and +-48 px vertically, or when hit
; (EnemyHitByShot sets O_Param)
;---------------------------------------------------------------------------
RedArremer_PerchWait:
        move.w  O_Y(a5),d0                      ; 0E1D4
        sub.w   g_ArthurY(a6),d0                ; 0E1D8
        addi.w  #$30,d0                         ; 0E1DC
        cmp.w   #$60,d0                         ; 0E1E0
        bhi.b   l_0E1F8                         ; 0E1E4
        move.w  O_X(a5),d0                      ; 0E1E6
        sub.w   g_ArthurX(a6),d0                ; 0E1EA
        addi.w  #$60,d0                         ; 0E1EE
        cmp.w   #$c0,d0                         ; 0E1F2
        bls.b   l_0E1FE                         ; 0E1F6
l_0E1F8:
        tst.b   O_Param(a5)                     ; 0E1F8
        beq.b   l_0E202                         ; 0E1FC
l_0E1FE:
        addq.b  #$1,O_Step2(a5)                 ; 0E1FE
l_0E202:
        rts                                     ; 0E202

;---------------------------------------------------------------------------
; 16 frames, then set up
;---------------------------------------------------------------------------
RedArremer_PerchWake:
        subq.b  #$1,RA_BaseY(a5)                ; 0E204
        bne.b   l_0E214                         ; 0E208
        move.b  #$3,O_Step(a5)                  ; 0E20A
        clr.b   O_Step2(a5)                     ; 0E210
l_0E214:
        rts                                     ; 0E214

;---------------------------------------------------------------------------
; Mode 2 (a Blue Killer that has turned): shots pass through (O_Active 2) and it
; blinks until RA_CentreX reaches 0, twice
;---------------------------------------------------------------------------
RedArremer_BlinkIn:
        move.b  O_Step2(a5),d0                  ; 0E216
        add.w   d0,d0                           ; 0E21A
        add.w   d0,d0                           ; 0E21C
        jmp     RedArremer_BlinkIn_Jumps(pc,d0.w)             ; 0E21E
RedArremer_BlinkIn_Jumps:
        bra.w   RedArremer_BlinkStart           ; 0E222
        bra.w   RedArremer_Blink                ; 0E226
        bra.w   RedArremer_BlinkSize            ; 0E22A
        bra.w   RedArremer_Blink                ; 0E22E
        bra.w   RedArremer_BlinkDone            ; 0E232
RedArremer_BlinkStart:
        move.b  #$2,(a5)                        ; 0E236  O_Active 2: not hit by shots
        move.w  #$f0,RA_CentreX(a5)             ; 0E23A
        addq.b  #$1,O_Step2(a5)                 ; 0E240

;---------------------------------------------------------------------------
; Blink every 16 frames; RA_CentreX -= $61 until it is exactly 0 (26,352 frames)
;---------------------------------------------------------------------------
RedArremer_Blink:
        moveq   #$f,d0                          ; 0E244
        and.w   g_GameFrame(a6),d0              ; 0E246
        bne.b   l_0E260                         ; 0E24A
        moveq   #$10,d0                         ; 0E24C
        and.w   g_GameFrame(a6),d0              ; 0E24E
        bne.b   l_0E25C                         ; 0E252
        lea.l   RedArremer_AnimWalk(pc),a0      ; 0E254
        bsr.w   SetAnimIndexed                  ; 0E258  start animation for current direction
l_0E25C:
        clr.l   O_Anim(a5)                      ; 0E25C
l_0E260:
        subi.w  #$61,RA_CentreX(a5)             ; 0E260
        bne.b   l_0E26C                         ; 0E266
        addq.b  #$1,O_Step2(a5)                 ; 0E268
l_0E26C:
        rts                                     ; 0E26C
RedArremer_BlinkSize:
        move.w  #$f0,RA_CentreX(a5)             ; 0E26E
        moveq   #$3,d0                          ; 0E274
        bsr.w   SetBoxClass                     ; 0E276  change size class
        lea.l   RedArremer_AnimWalk(pc),a0      ; 0E27A
        bsr.w   SetAnimIndexed                  ; 0E27E  start animation for current direction
        addq.b  #$1,O_Step2(a5)                 ; 0E282
        rts                                     ; 0E286
RedArremer_BlinkDone:
        move.b  #ST_ACTIVE,O_State(a5)          ; 0E288
        clr.b   O_Step(a5)                      ; 0E28E
        clr.b   O_Step2(a5)                     ; 0E292
        rts                                     ; 0E296

;---------------------------------------------------------------------------
; (direction word, frames) pairs; direction -1 = stand; 0 = loop (offset follows)
;---------------------------------------------------------------------------
RedArremerWalkScript:
	dc.b	$00,$14,$00,$1C,$01,$0A,$00,$0C,$FF,$0A,$00,$14,$01,$1E,$00,$05
	dc.b	$FF,$14,$01,$1A,$01,$0A,$00,$0C,$FF,$14,$00,$02,$01,$05,$00,$0F
	dc.b	$00,$00,$FF,$DE,$00

;---------------------------------------------------------------------------
; frames between shots: 90, 100, 220, 130, 160, 180, 200, 120 (0 = loop)
;---------------------------------------------------------------------------
RedArremerShotTimes:
	dc.b	$5A,$64,$DC,$82,$A0,$B4,$C8,$78,$00,$FF,$F7,$00

;---------------------------------------------------------------------------
; frames between swoops: 72, 136, 85, 92, 108, 144, 70, 49
;---------------------------------------------------------------------------
RedArremerSwoopTimes:
	dc.b	$48,$88,$55,$5C,$6C,$90,$46,$31,$00,$FF,$F7,$00

;---------------------------------------------------------------------------
; x 8 frames between take-offs: 10, 20, 30, 40, 50, 60
;---------------------------------------------------------------------------
RedArremerTakeOffTimes:
	dc.b	$0A,$14,$1E,$28,$32,$3C,$00,$FF,$F9

;---------------------------------------------------------------------------
; 3 HP, size 3, face Arthur, start the four scripts, rage in 50 x 32 frames
;---------------------------------------------------------------------------
RedArremer_Setup:
        addq.b  #$1,g_BigEnemyCount(a6)         ; 0E2DE  one more big enemy engaged
        move.b  #$3,O_HP(a5)                    ; 0E2E2
        move.b  #$3,O_Size(a5)                  ; 0E2E8
        move.w  O_X(a5),d0                      ; 0E2EE
        cmp.w   g_ArthurX(a6),d0                ; 0E2F2
        slt.b   O_Dir(a5)                       ; 0E2F6
        addq.b  #$1,O_Dir(a5)                   ; 0E2FA
        lea.l   RedArremerWalkScript(pc),a0     ; 0E2FE
        move.w  (a0)+,RA_WalkDir(a5)            ; 0E302
        move.l  a0,RA_WalkPtr(a5)               ; 0E306
        lea.l   RedArremerShotTimes(pc),a0      ; 0E30A
        move.b  (a0)+,RA_ShotTime(a5)           ; 0E30E
        move.l  a0,RA_ShotPtr(a5)               ; 0E312
        lea.l   RedArremerSwoopTimes(pc),a0     ; 0E316
        move.b  (a0)+,RA_SwoopTime(a5)          ; 0E31A
        move.l  a0,RA_SwoopPtr(a5)              ; 0E31E
        lea.l   RedArremerTakeOffTimes(pc),a0   ; 0E322
        move.b  (a0)+,RA_Phase(a5)              ; 0E326
        move.l  a0,RA_FlyPtr(a5)                ; 0E32A
        move.b  #$32,RA_RageTime(a5)            ; 0E32E
        lea.l   RedArremer_AnimWalk(pc),a0      ; 0E334
        bsr.w   SetAnimIndexed                  ; 0E338  start animation for current direction
        move.b  #ST_ACTIVE,O_State(a5)          ; 0E33C
        clr.b   O_Step(a5)                      ; 0E342
        clr.b   O_Step2(a5)                     ; 0E346
        rts                                     ; 0E34A

;---------------------------------------------------------------------------
; State 1. O_Step: 0 walk, 1 fly, 2 shoot, 3 glide, 4 rage, 5 dodge / hover, 6 swoop.
; Then the hit flinch, and removal when it is far above or below the camera.
;---------------------------------------------------------------------------
RedArremer_Active:
        move.b  O_Step(a5),d0                   ; 0E34C
        add.w   d0,d0                           ; 0E350
        add.w   d0,d0                           ; 0E352
        jsr     RedArremer_Active_Jumps(pc,d0.w)             ; 0E354
        bsr.w   RedArremer_Flinch               ; 0E358
        move.w  O_Y(a5),d0                      ; 0E35C  more than 64 px below or 320 above the camera: remove
        sub.w   g_CameraY(a6),d0                ; 0E360
        addi.w  #$40,d0                         ; 0E364
        cmp.w   #$180,d0                        ; 0E368
        bls.b   l_0E374                         ; 0E36C
        move.b  #ST_REMOVE,O_State(a5)          ; 0E36E
l_0E374:
        rts                                     ; 0E374
RedArremer_Active_Jumps:
        bra.w   RedArremer_Walk                 ; 0E376
        bra.w   RedArremer_Fly                  ; 0E37A
        bra.w   RedArremer_Shoot                ; 0E37E
        bra.w   RedArremer_Glide                ; 0E382
        bra.w   RedArremer_Rage                 ; 0E386
        bra.w   RedArremer_Dodge                ; 0E38A
        bra.w   RedArremer_Swoop                ; 0E38E

;---------------------------------------------------------------------------
; walking: +-0.8 px/frame
;---------------------------------------------------------------------------
RedArremerWalkMove:
	dc.b	$00,$CD,$FF,$33

;---------------------------------------------------------------------------
; Step 0: walk, and check the shot, swoop, take-off, distance, dodge and rage timers
;---------------------------------------------------------------------------
RedArremer_Walk:
        tst.b   O_Step2(a5)                     ; 0E396
        bne.b   l_0E3A0                         ; 0E39A
        bsr.b   RedArremer_WalkStart            ; 0E39C
        bra.b   l_0E3A2                         ; 0E39E
l_0E3A0:
        bsr.b   RedArremer_Walking              ; 0E3A0
l_0E3A2:
        bsr.w   RedArremer_ShotTimer            ; 0E3A2
        bsr.w   RedArremer_SwoopTimer           ; 0E3A6
        bsr.w   RedArremer_TakeOffTimer         ; 0E3AA
        bsr.w   RedArremer_CheckGlide           ; 0E3AE
        bsr.w   RedArremer_CheckDodge           ; 0E3B2
        bra.w   RedArremer_RageTimer            ; 0E3B6
RedArremer_WalkStart:
        lea.l   RedArremerWalkMove(pc),a0       ; 0E3BA
        move.l  a0,O_MoveTable(a5)              ; 0E3BE
        move.b  #$3,O_Size(a5)                  ; 0E3C2
        move.w  g_ArthurX(a6),d0                ; 0E3C8
        cmp.w   O_X(a5),d0                      ; 0E3CC
        shi.b   O_Dir(a5)                       ; 0E3D0
        addq.b  #$1,O_Dir(a5)                   ; 0E3D4
        lea.l   RedArremer_AnimWalk(pc),a0      ; 0E3D8
        bsr.w   SetAnimIndexed                  ; 0E3DC  start animation for current direction
        addq.b  #$1,O_Step2(a5)                 ; 0E3E0
        rts                                     ; 0E3E4

;---------------------------------------------------------------------------
; Walk; if there is no floor under it any more, fly
;---------------------------------------------------------------------------
RedArremer_Walking:
        bsr.w   RedArremer_WalkScriptStep       ; 0E3E6
        bsr.w   RedArremer_MoveX                ; 0E3EA
        subq.w  #$2,O_Y(a5)                     ; 0E3EE
        bsr.w   ObjectMapCollide                ; 0E3F2  on the floor? (Z set = yes, Y snapped onto it)
        beq.b   l_0E402                         ; 0E3F6
        move.b  #$1,O_Step(a5)                  ; 0E3F8
        clr.b   O_Step2(a5)                     ; 0E3FE
l_0E402:
        rts                                     ; 0E402

;---------------------------------------------------------------------------
; Step 1: O_Step2 0 take off, 1 rise, 2 fly to Arthur, 3 fly past him, 4 hover,
; 5 come down, 6 drop. Shoots and swoops while flying.
;---------------------------------------------------------------------------
RedArremer_Fly:
        move.b  O_Step2(a5),d0                  ; 0E404
        add.w   d0,d0                           ; 0E408
        add.w   d0,d0                           ; 0E40A
        jsr     RedArremer_Fly_Jumps(pc,d0.w)   ; 0E40C
        move.b  O_Step2(a5),d0                  ; 0E410
        subq.b  #$2,d0                          ; 0E414
        cmp.b   #$1,d0                          ; 0E416
        bhi.b   l_0E424                         ; 0E41A
        bsr.w   RedArremer_ShotTimer            ; 0E41C
        bra.w   RedArremer_SwoopTimer           ; 0E420
l_0E424:
        rts                                     ; 0E424
RedArremer_Fly_Jumps:
        bra.w   RedArremer_TakeOff              ; 0E426
        bra.w   RedArremer_Rise                 ; 0E42A
        bra.w   RedArremer_FlyToArthur          ; 0E42E
        bra.w   RedArremer_FlyPast              ; 0E432
        bra.w   RedArremer_Hover                ; 0E436
        bra.w   RedArremer_Descend              ; 0E43A
        bra.w   RedArremer_Drop                 ; 0E43E

;---------------------------------------------------------------------------
; +-1.75 px/frame (calm), +-2.0 (after its rage)
;---------------------------------------------------------------------------
RedArremerFlySpeed:
	dc.b	$01,$C0,$FE,$40,$02,$00,$FE,$00

;---------------------------------------------------------------------------
; Random heights of the flight curve: 64, 72, 84, 68, 76, 56, 80, 88
;---------------------------------------------------------------------------
RedArremerFlyHeights:
	dc.b	'@HTDL8PX'
RedArremer_TakeOff:
        move.w  O_X(a5),d0                      ; 0E452
        cmp.w   g_ArthurX(a6),d0                ; 0E456
        sls.b   O_Dir(a5)                       ; 0E45A
        addq.b  #$1,O_Dir(a5)                   ; 0E45E
        clr.w   d0                              ; 0E462
        move.b  RA_Rage(a5),d0                  ; 0E464
        lsl.w   #$2,d0                          ; 0E468
        lea.l   RedArremerFlySpeed(pc,d0.w),a0  ; 0E46A
        move.l  a0,O_MoveTable(a5)              ; 0E46E
        move.w  g_GameFrame(a6),d0              ; 0E472
        add.w   d7,d0                           ; 0E476
        andi.w  #$7,d0                          ; 0E478
        move.b  RedArremerFlyHeights(pc,d0.w),RA_RadiusY(a5); 0E47C
        clr.b   RA_Phase(a5)                    ; 0E482
        move.w  O_Y(a5),RA_BaseY(a5)            ; 0E486
        move.b  #$9,O_Size(a5)                  ; 0E48C  size class 9 while flying
        lea.l   RedArremer_AnimFly(pc),a0       ; 0E492
        bsr.w   SetAnimIndexed                  ; 0E496  start animation for current direction
        move.b  O_Dir(a5),RA_WalkDir(a5)        ; 0E49A
        addq.b  #$1,O_Step2(a5)                 ; 0E4A0

;---------------------------------------------------------------------------
; Rise along the sine curve (phase += 8 up to $A0)
;---------------------------------------------------------------------------
RedArremer_Rise:
        bsr.w   RedArremer_MoveX                ; 0E4A4
        bra.w   RedArremer_CurveUp              ; 0E4A8

;---------------------------------------------------------------------------
; Fly on until it is over Arthur, then turn
;---------------------------------------------------------------------------
RedArremer_FlyToArthur:
        bsr.w   RedArremer_MoveX                ; 0E4AC
        tst.b   RA_WalkDir(a5)                  ; 0E4B0
        beq.b   l_0E4D0                         ; 0E4B4
        move.w  O_X(a5),d0                      ; 0E4B6
        cmp.w   g_ArthurX(a6),d0                ; 0E4BA
        bhi.b   l_0E4EC                         ; 0E4BE
        addq.b  #$1,O_Step2(a5)                 ; 0E4C0
        clr.b   O_Dir(a5)                       ; 0E4C4
        lea.l   RedArremer_AnimFly(pc),a0       ; 0E4C8
        bra.w   SetAnimIndexed                  ; 0E4CC
l_0E4D0:
        move.w  O_X(a5),d0                      ; 0E4D0
        cmp.w   g_ArthurX(a6),d0                ; 0E4D4
        bls.b   l_0E4EC                         ; 0E4D8
        addq.b  #$1,O_Step2(a5)                 ; 0E4DA
        move.b  #$1,O_Dir(a5)                   ; 0E4DE
        lea.l   RedArremer_AnimFly(pc),a0       ; 0E4E4
        bra.w   SetAnimIndexed                  ; 0E4E8
l_0E4EC:
        rts                                     ; 0E4EC

;---------------------------------------------------------------------------
; Fly until 80+ px past him
;---------------------------------------------------------------------------
RedArremer_FlyPast:
        bsr.w   RedArremer_MoveX                ; 0E4EE
        move.w  O_X(a5),d0                      ; 0E4F2
        sub.w   g_ArthurX(a6),d0                ; 0E4F6
        addi.w  #$50,d0                         ; 0E4FA
        cmp.w   #$a0,d0                         ; 0E4FE
        bls.b   l_0E50E                         ; 0E502
        move.b  #$5,RA_Phase(a5)                ; 0E504
        addq.b  #$1,O_Step2(a5)                 ; 0E50A
l_0E50E:
        rts                                     ; 0E50E

;---------------------------------------------------------------------------
; 5 frames
;---------------------------------------------------------------------------
RedArremer_Hover:
        subq.b  #$1,RA_Phase(a5)                ; 0E510
        bne.w   Animate                         ; 0E514
        move.b  #$80,RA_Phase(a5)               ; 0E518
        addq.b  #$1,O_Step2(a5)                 ; 0E51E
        rts                                     ; 0E522

;---------------------------------------------------------------------------
; Come down along the curve; land if there is floor, else drop
;---------------------------------------------------------------------------
RedArremer_Descend:
        bsr.w   RedArremer_CurveDown            ; 0E524
        bsr.w   RedArremer_TooLow               ; 0E528
        bra.w   RedArremer_CheckDodge           ; 0E52C

;---------------------------------------------------------------------------
; Fall 4 px/frame until it lands, then walk
;---------------------------------------------------------------------------
RedArremer_Drop:
        bsr.w   RedArremer_Fall                 ; 0E530
        bsr.w   RedArremer_TooLow               ; 0E534
        bra.w   RedArremer_CheckDodge           ; 0E538

;---------------------------------------------------------------------------
; Step 2: wind up 6 frames, fire enemy shot type 7, 6 frames, then go back
;---------------------------------------------------------------------------
RedArremer_Shoot:
        move.b  O_Step2(a5),d0                  ; 0E53C
        add.w   d0,d0                           ; 0E540
        add.w   d0,d0                           ; 0E542
        jmp     RedArremer_Shoot_Jumps(pc,d0.w) ; 0E544
RedArremer_Shoot_Jumps:
        bra.w   RedArremer_ShootStart           ; 0E548
        bra.w   RedArremer_WindUp               ; 0E54C
        bra.w   RedArremer_Fire                 ; 0E550
        bra.w   RedArremer_ShootEnd             ; 0E554
RedArremer_ShootStart:
        move.b  #$6,RA_ShotTime(a5)             ; 0E558
        lea.l   RedArremer_AnimShoot(pc),a0     ; 0E55E
        cmpi.b  #$3,O_Size(a5)                  ; 0E562
        beq.b   l_0E56C                         ; 0E568
        addq.l  #$2,a0                          ; 0E56A
l_0E56C:
        adda.w  (a0),a0                         ; 0E56C
        bsr.w   SetAnimIndexed                  ; 0E56E  start animation for current direction
        addq.b  #$1,O_Step2(a5)                 ; 0E572
RedArremer_WindUp:
        subq.b  #$1,RA_ShotTime(a5)             ; 0E576
        bne.w   Animate                         ; 0E57A
        addq.b  #$1,O_Step2(a5)                 ; 0E57E
        rts                                     ; 0E582
RedArremer_Fire:
        bsr.w   FindFreeEnemyShot               ; 0E584  find a free enemy-projectile slot (fires a shot)
        bne.b   l_0E5B8                         ; 0E588
        move.b  #$7,$1a(a4)                     ; 0E58A  enemy shot type 7
        move.w  O_X(a5),$6(a4)                  ; 0E590
        move.w  O_Y(a5),$a(a4)                  ; 0E596
        clr.b   $3(a4)                          ; 0E59C
        clr.b   $4(a4)                          ; 0E5A0
        clr.b   $5(a4)                          ; 0E5A4
        move.b  #$1,(a4)                        ; 0E5A8
        move.b  #$6,RA_ShotTime(a5)             ; 0E5AC
        moveq   #$1a,d0                         ; 0E5B2  [1MB]   << 1MB only: 1 instruction(s) not in the 512K build >>
        addq.b  #$1,O_Step2(a5)                 ; 0E5B4
l_0E5B8:
        rts                                     ; 0E5B8

;---------------------------------------------------------------------------
; Next shot time; back to the step it came from (RedArremerResume)
;---------------------------------------------------------------------------
RedArremer_ShootEnd:
        subq.b  #$1,RA_ShotTime(a5)             ; 0E5BA
        bne.w   Animate                         ; 0E5BE
        movea.l RA_ShotPtr(a5),a0               ; 0E5C2
        move.b  (a0),RA_ShotTime(a5)            ; 0E5C6
        move.b  RA_Return(a5),d0                ; 0E5CA
        ext.w   d0                              ; 0E5CE
        add.w   d0,d0                           ; 0E5D0
        lea.l   RedArremerResume(pc,d0.w),a0    ; 0E5D2
        move.b  (a0)+,O_Step(a5)                ; 0E5D6
        move.b  (a0)+,O_Step2(a5)               ; 0E5DA
        rts                                     ; 0E5DE

;---------------------------------------------------------------------------
; (step, step2) to resume after a shot, by the step it came from
;---------------------------------------------------------------------------
RedArremerResume:
	dc.b	$00,$00,$01,$02,$00,$00,$03,$00,$00,$00,$05,$03,$00,$00

;---------------------------------------------------------------------------
; Step 3: glide (no height change) towards Arthur if he is 80+ px away, else away
;---------------------------------------------------------------------------
RedArremer_Glide:
        tst.b   O_Step2(a5)                     ; 0E5EE
        bne.b   l_0E5F8                         ; 0E5F2
        bsr.b   RedArremer_GlideStart           ; 0E5F4
