;---------------------------------------------------------------------------
; === Satan (type 6, 3000 pts, 4 hits (boss)) ===
; Big winged demon boss of levels 4-5: flies at Arthur, fires, and on its last hit calls BossKilled (key drop / weapon check).
; Dispatches on O_State: 0 main behaviour, 1 type-specific second phase, 2 killed (set by EnemyHitByShot after scoring), 3 remove.
;
; Behaviour, as coded:
;   * Sleeps until it is in view (parameter 1: for a further 6 x 64 frames, during which
;     it can be hit; 3 hits wake it, but its HP is then reset to 4).
;   * Hovers for 180 frames, drifting slowly (one of 4 directions, re-chosen every
;     128 frames; always down when Arthur is 64+ pixels below), turning to face Arthur.
;     While hovering it fires (enemy shot type 11, aimed in 16 directions) every 45-65
;     frames, and every 47-90 frames folds its wings for 30 frames, when shots pass
;     through it (O_Active bit 7).
;   * Then attacks: from above, a U-shaped dive (sine curve) down to around Arthur's
;     height and up again while flying across at 2-2.25 px/frame; level with Arthur, it
;     flies across and climbs out of the second half of the dive; from below, it flies
;     straight at him at 3.5 px/frame. Then it hovers again.
;   * If it leaves the screen it flies back in for 16-31 frames, then attacks again.
; Bug: the dying state waits for its timer to reach 0 the wrong way round (beq instead
; of bne), so the 63-frame pause after the explosion is skipped.
;---------------------------------------------------------------------------
Enemy_Satan:
        move.b  O_State(a5),d0                  ; 0ED6A
        add.w   d0,d0                           ; 0ED6E
        add.w   d0,d0                           ; 0ED70
        jmp     Enemy_Satan_Jumps(pc,d0.w)      ; 0ED72
Enemy_Satan_Jumps:
        bra.w   Satan_Init                      ; 0ED76
        bra.w   Satan_Active                    ; 0ED7A
        bra.w   Satan_Dying                     ; 0ED7E
        bra.w   Satan_Free                      ; 0ED82

;---------------------------------------------------------------------------
; State 0: 4 HP, size class 4, face Arthur, then sleep until in view
;---------------------------------------------------------------------------
Satan_Init:
        tst.b   O_Step(a5)                      ; 0ED86
        bne.b   Satan_Sleep                     ; 0ED8A
        move.b  #$4,O_HP(a5)                    ; 0ED8C
        move.b  #$4,O_Size(a5)                  ; 0ED92
        move.w  O_X(a5),d0                      ; 0ED98
        cmp.w   g_ArthurX(a6),d0                ; 0ED9C
        slt.b   O_Dir(a5)                       ; 0EDA0  O_Dir 0 if Arthur is to the right, 1 if to the left
        addq.b  #$1,O_Dir(a5)                   ; 0EDA4
        lea.l   Satan_AnimGuard(pc),a0          ; 0EDA8
        bsr.w   SetAnimIndexed                  ; 0EDAC  start animation for current direction
        clr.b   Sat_Returning(a5)               ; 0EDB0
        clr.b   Sat_Hold(a5)                    ; 0EDB4
        move.b  #$6,Sat_WakeDelay(a5)           ; 0EDB8
        addq.b  #$1,O_Step(a5)                  ; 0EDBE  next step
        rts                                     ; 0EDC2

;---------------------------------------------------------------------------
; Shots pass through while it sleeps ($81). Wake when inside the camera window
; (0-256, 0-240); parameter 1 waits a further Sat_WakeDelay x 64 frames.
;---------------------------------------------------------------------------
Satan_Sleep:
        move.b  #$81,(a5)                       ; 0EDC4  active, shots pass through
        move.w  O_X(a5),d0                      ; 0EDC8
        sub.w   g_CameraX(a6),d0                ; 0EDCC
        cmp.w   #$100,d0                        ; 0EDD0
        bhi.b   l_0EE20                         ; 0EDD4
        move.w  O_Y(a5),d0                      ; 0EDD6
        sub.w   g_CameraY(a6),d0                ; 0EDDA
        cmp.w   #$f0,d0                         ; 0EDDE
        bhi.b   l_0EE20                         ; 0EDE2
        tst.b   O_Param(a5)                     ; 0EDE4
        beq.b   l_0EE08                         ; 0EDE8
        move.b  #$1,(a5)                        ; 0EDEA
        cmpi.b  #$1,O_HP(a5)                    ; 0EDEE  parameter 1 is hittable while it waits: down to 1 HP wakes it at once
        beq.b   l_0EE08                         ; 0EDF4
        moveq   #$3f,d0                         ; 0EDF6  every 64 frames
        and.w   g_GameFrame(a6),d0              ; 0EDF8
        cmp.w   #$3f,d0                         ; 0EDFC
        bne.b   l_0EE20                         ; 0EE00
        subq.b  #$1,Sat_WakeDelay(a5)           ; 0EE02
        bne.b   l_0EE20                         ; 0EE06
l_0EE08:
        move.b  #$4,O_HP(a5)                    ; 0EE08  4 hits (damage taken while waiting is forgotten)
        move.b  #ST_ACTIVE,O_State(a5)          ; 0EE0E
        clr.b   O_Step(a5)                      ; 0EE14
        clr.b   O_Step2(a5)                     ; 0EE18
        move.b  #$1,(a5)                        ; 0EE1C
l_0EE20:
        rts                                     ; 0EE20

;---------------------------------------------------------------------------
; State 1. O_Step 0 = hover (O_Step2 0 count, 1 set up, 2 face, 3 hover),
; O_Step 1 = attack (O_Step2 0 aim, 1 dive, 2 fly to the dive point, 3 fly straight).
;---------------------------------------------------------------------------
Satan_Active:
        tst.b   O_Step(a5)                      ; 0EE22
        bne.w   Satan_Attack                    ; 0EE26
        clr.w   d0                              ; 0EE2A
        move.b  O_Step2(a5),d0                  ; 0EE2C
        add.w   d0,d0                           ; 0EE30
        add.w   d0,d0                           ; 0EE32
        jmp     Satan_Active_Jumps(pc,d0.w)     ; 0EE34
Satan_Active_Jumps:
        bra.w   Satan_Engage                    ; 0EE38
        bra.w   Satan_HoverStart                ; 0EE3C
        bra.w   Satan_Face                      ; 0EE40
        bra.w   Satan_Hover                     ; 0EE44
Satan_Engage:
        addq.b  #$1,g_BigEnemyCount(a6)         ; 0EE48
        addq.b  #$1,O_Step2(a5)                 ; 0EE4C
        rts                                     ; 0EE50

;---------------------------------------------------------------------------
; 180 frames of hovering
;---------------------------------------------------------------------------
Satan_HoverStart:
        move.b  #$b4,Sat_Timer(a5)              ; 0EE52
        clr.b   Sat_FirePhase(a5)               ; 0EE58
        move.b  #$1e,Sat_GuardTime(a5)          ; 0EE5C  guard 30 frames
        bsr.w   Satan_RandomFireTime            ; 0EE62
        move.b  d0,Sat_FireTime(a5)             ; 0EE66
        clr.b   Sat_Swoop(a5)                   ; 0EE6A
        clr.b   Sat_Drift(a5)                   ; 0EE6E
        move.w  g_ArthurX(a6),d0                ; 0EE72
        cmp.w   O_X(a5),d0                      ; 0EE76
        scs.b   O_Dir(a5)                       ; 0EE7A
        addq.b  #$1,O_Dir(a5)                   ; 0EE7E
        addq.b  #$1,O_Step2(a5)                 ; 0EE82
