l_0F316:
        move.b  #$2,O_Size(a5)                  ; 0F316
        subq.b  #$1,Sat_Returning(a5)           ; 0F31C  BUG: beq should be bne - goes to state 3 after one frame
        beq.b   l_0F328                         ; 0F320
        move.b  #ST_REMOVE,O_State(a5)          ; 0F322
l_0F328:
        rts                                     ; 0F328

;---------------------------------------------------------------------------
; State 3: free the slot, BossKilled, give the spawn quota back
;---------------------------------------------------------------------------
Satan_Free:
        clr.b   (a5)                            ; 0F32A  free this enemy slot
        bsr.w   BossKilled                      ; 0F32C  boss defeated
        addq.b  #$1,g_SpawnQuota+6(a6)          ; 0F330
        tst.b   g_BigEnemyCount(a6)             ; 0F334
        beq.b   l_0F33E                         ; 0F338
        subq.b  #$1,g_BigEnemyCount(a6)         ; 0F33A
l_0F33E:
        rts                                     ; 0F33E
Satan_AnimHover:
	dc.w	Satan_AnimHover_0-*	; 0
	dc.w	Satan_AnimFlap-*	; 1
Satan_AnimHover_0:
	AF	$05,10
	AF	$06,10
	AF	$07,10
	AL	$06,10,Satan_AnimHover_0

;---------------------------------------------------------------------------
; Satan flapping: frames 0, 1, 2, 1 (also the opening scene's demon)
;---------------------------------------------------------------------------
Satan_AnimFlap:
	AF	$00,10
	AF	$01,10
	AF	$02,10
	AL	$01,10,Satan_AnimFlap
Satan_AnimDive:
	dc.w	Satan_AnimReturnR-*	; 0
	dc.w	Satan_AnimReturnL-*	; 1
Satan_AnimReturnL:
	AL	$08,5,Satan_AnimReturnL
Satan_AnimReturnR:
	AL	$03,5,Satan_AnimReturnR
Satan_AnimGuard:
	dc.w	Satan_AnimGuard_0-*	; 0
	dc.w	Satan_AnimWings-*	; 1
Satan_AnimGuard_0:
	AL	$04,5,Satan_AnimGuard_0

;---------------------------------------------------------------------------
; Satan, wings spread (frame 4, held)
;---------------------------------------------------------------------------
Satan_AnimWings:
	AL	$04,5,Satan_AnimWings

;---------------------------------------------------------------------------
; === Magician (type 7, 2000 pts) ===
; Rises from a gravestone Arthur has shot (spawned at g_SceneryHitX/Y), throws off its cloak, casts one spell (enemy shot type 0: turns Arthur into a frog) and fades away. Sound effect 17 when killed.
; Dispatches on O_State: 0 main behaviour, 1 type-specific second phase, 2 killed (set by EnemyHitByShot after scoring), 3 remove.
;
; Behaviour, as coded: the spawner puts it where Arthur last shot a gravestone. It rises
; cloaked for 60 + 20 frames (shots pass through: O_Active 2), throws off the cloak and
; becomes hittable (size class 9), casts one spell at Arthur - enemy shot type 0, which turns
; him into a frog (EnemyShotsVsArthur) - waits 20 frames, then cloaks again and blinks out
; over 60 frames. The graphics are the hooded figure (frames 0-1) and the winged figure
; (frames 2-3).
;---------------------------------------------------------------------------
Enemy_Magician:
        move.b  O_State(a5),d0                  ; 0F370
        add.w   d0,d0                           ; 0F374
        add.w   d0,d0                           ; 0F376
        jmp     Enemy_Magician_Jumps(pc,d0.w)   ; 0F378
Enemy_Magician_Jumps:
        bra.w   Magician_Init                   ; 0F37C
        bra.w   Magician_Active                 ; 0F380
        bra.w   Magician_Dying                  ; 0F384
        bra.w   Magician_Free                   ; 0F388

;---------------------------------------------------------------------------
; State 0: shots pass through (O_Active 2), size 3, face Arthur, cloaked
;---------------------------------------------------------------------------
Magician_Init:
        move.b  #$2,(a5)                        ; 0F38C
        move.b  #$3,O_Size(a5)                  ; 0F390
        bsr.b   Magician_FaceArthur             ; 0F396
        lea.l   Magician_AnimCloak(pc),a0       ; 0F398
        bsr.w   SetAnimIndexed                  ; 0F39C  start animation for current direction
        addq.b  #ST_ACTIVE,O_State(a5)          ; 0F3A0
        clr.b   O_Step(a5)                      ; 0F3A4
        clr.b   O_Step2(a5)                     ; 0F3A8
        rts                                     ; 0F3AC

;---------------------------------------------------------------------------
; O_Dir 0 if Arthur is to the right, 1 if to the left
;---------------------------------------------------------------------------
Magician_FaceArthur:
        move.w  g_ArthurX(a6),d0                ; 0F3AE
        cmp.w   O_X(a5),d0                      ; 0F3B2
        scs.b   O_Dir(a5)                       ; 0F3B6
        neg.b   O_Dir(a5)                       ; 0F3BA
        rts                                     ; 0F3BE

;---------------------------------------------------------------------------
; State 1. O_Step: 0 rise, 1 cast, 2 fade
;---------------------------------------------------------------------------
Magician_Active:
        move.b  O_Step(a5),d0                   ; 0F3C0
        add.w   d0,d0                           ; 0F3C4
        add.w   d0,d0                           ; 0F3C6
        jmp     Magician_Active_Jumps(pc,d0.w)  ; 0F3C8
Magician_Active_Jumps:
        bra.w   Magician_Rise                   ; 0F3CC
        bra.w   Magician_Cast                   ; 0F3D0
        bra.w   Magician_Fade                   ; 0F3D4

;---------------------------------------------------------------------------
; 60 frames, turning to face Arthur
;---------------------------------------------------------------------------
Magician_Rise:
        tst.b   O_Step2(a5)                     ; 0F3D8
        bne.b   l_0F3EA                         ; 0F3DC
        move.b  #$3c,Mag_Timer(a5)              ; 0F3DE
        moveq   #$3,d0                          ; 0F3E4  [1MB]   << 1MB only: 1 instruction(s) not in the 512K build >>
        addq.b  #$1,O_Step2(a5)                 ; 0F3E6
l_0F3EA:
        subq.b  #$1,Mag_Timer(a5)               ; 0F3EA
        beq.b   l_0F3F2                         ; 0F3EE
        bra.b   Magician_FaceArthur             ; 0F3F0
l_0F3F2:
        addq.b  #$1,O_Step(a5)                  ; 0F3F2  next step
        clr.b   O_Step2(a5)                     ; 0F3F6
        rts                                     ; 0F3FA
Magician_Cast:
        move.b  O_Step2(a5),d0                  ; 0F3FC
        add.w   d0,d0                           ; 0F400
        add.w   d0,d0                           ; 0F402
        jmp     Magician_Cast_Jumps(pc,d0.w)    ; 0F404
Magician_Cast_Jumps:
        bra.w   Magician_CastStart              ; 0F408
        bra.w   Magician_Reveal                 ; 0F40C
        bra.w   Magician_AfterCast              ; 0F410
Magician_CastStart:
        move.b  #$14,Mag_Cast(a5)               ; 0F414
        addq.b  #$1,O_Step2(a5)                 ; 0F41A

;---------------------------------------------------------------------------
; After 20 frames: hittable, size 9, the winged figure, and cast the spell
;---------------------------------------------------------------------------
Magician_Reveal:
        subq.b  #$1,Mag_Cast(a5)                ; 0F41E
        bne.b   l_0F446                         ; 0F422
        move.b  #$1,(a5)                        ; 0F424  hittable from now on
        move.b  #$9,O_Size(a5)                  ; 0F428
        bsr.w   Magician_FaceArthur             ; 0F42E  [1MB]   << differs from the 512K build: 1 instruction(s) here replace 1 at $0F4DE >>
        lea.l   Magician_AnimReveal(pc),a0      ; 0F432
        bsr.w   SetAnimIndexed                  ; 0F436  start animation for current direction
        bsr.b   Magician_Spell                  ; 0F43A
        move.b  #$14,Mag_Cast(a5)               ; 0F43C
        addq.b  #$1,O_Step2(a5)                 ; 0F442
l_0F446:
        bra.w   Animate                         ; 0F446

;---------------------------------------------------------------------------
; 20 frames, then fade
;---------------------------------------------------------------------------
Magician_AfterCast:
        subq.b  #$1,Mag_Cast(a5)                ; 0F44A
        bne.b   l_0F45A                         ; 0F44E
        move.b  #$2,O_Step(a5)                  ; 0F450
        clr.b   O_Step2(a5)                     ; 0F456
l_0F45A:
        rts                                     ; 0F45A

;---------------------------------------------------------------------------
; Enemy shot type 0 (the frog spell) from 10 px below its centre, the way it faces
;---------------------------------------------------------------------------
Magician_Spell:
        bsr.w   FindFreeEnemyShot               ; 0F45C  find a free enemy-projectile slot (fires a shot)
        bne.b   l_0F48C                         ; 0F460
        move.b  O_Dir(a5),$12(a4)               ; 0F462
        move.w  O_X(a5),$6(a4)                  ; 0F468
        moveq   #-10,d0                         ; 0F46E
        add.w   O_Y(a5),d0                      ; 0F470
        move.w  d0,$a(a4)                       ; 0F474
        clr.b   $3(a4)                          ; 0F478
        clr.b   $4(a4)                          ; 0F47C
        clr.b   $5(a4)                          ; 0F480
        move.b  #$1,(a4)                        ; 0F484
        clr.b   $1a(a4)                         ; 0F488  enemy shot type 0: the frog spell
l_0F48C:
        rts                                     ; 0F48C

;---------------------------------------------------------------------------
; Cloak again, shots pass through, blink for 60 frames, then remove
;---------------------------------------------------------------------------
Magician_Fade:
        tst.b   O_Step2(a5)                     ; 0F48E
        bne.b   l_0F4B6                         ; 0F492
        move.b  #$3c,Mag_Timer(a5)              ; 0F494
        move.b  #$2,(a5)                        ; 0F49A  shots pass through again
        move.b  #$3,O_Size(a5)                  ; 0F49E
        bsr.w   Magician_FaceArthur             ; 0F4A4
        lea.l   Magician_AnimCloak(pc),a0       ; 0F4A8
        bsr.w   SetAnimIndexed                  ; 0F4AC  start animation for current direction
        moveq   #$3,d0                          ; 0F4B0  [1MB]   << 1MB only: 1 instruction(s) not in the 512K build >>
        addq.b  #$1,O_Step2(a5)                 ; 0F4B2
l_0F4B6:
        subq.b  #$1,Mag_Timer(a5)               ; 0F4B6
        bne.b   l_0F4C4                         ; 0F4BA
        move.b  #ST_REMOVE,O_State(a5)          ; 0F4BC
        rts                                     ; 0F4C2
l_0F4C4:
        moveq   #$2,d0                          ; 0F4C4  invisible every other 2 frames
        and.w   g_GameFrame(a6),d0              ; 0F4C6
        beq.b   l_0F4D0                         ; 0F4CA
        clr.l   O_Anim(a5)                      ; 0F4CC
l_0F4D0:
        lea.l   Magician_AnimCloak(pc),a0       ; 0F4D0
        bsr.w   SetAnimIndexed                  ; 0F4D4  start animation for current direction
        bra.w   CheckFarAway                    ; 0F4D8

;---------------------------------------------------------------------------
; State 2: sound 17, EnemyDieFacing, 63 frames
;---------------------------------------------------------------------------
Magician_Dying:
        cmpi.b  #$1,O_Step(a5)                  ; 0F4DC
        beq.b   l_0F4F8                         ; 0F4E2
        bcc.b   l_0F4FC                         ; 0F4E4
        moveq   #SFX_ENEMY_DIE,d0               ; 0F4E6
        bsr.w   PlaySfx                         ; 0F4E8  sound effect 17 (enemy event)
        move.b  #$3f,Mag_Timer(a5)              ; 0F4EC
        addq.b  #$1,O_Step(a5)                  ; 0F4F2  next step
        rts                                     ; 0F4F6
l_0F4F8:
        bra.w   EnemyDieFacing                  ; 0F4F8
l_0F4FC:
        move.b  #$2,O_Size(a5)                  ; 0F4FC
        subq.b  #$1,Mag_Timer(a5)               ; 0F502
        bne.b   l_0F50E                         ; 0F506
        move.b  #ST_REMOVE,O_State(a5)          ; 0F508
l_0F50E:
        rts                                     ; 0F50E

;---------------------------------------------------------------------------
; State 3: give the spawn quota back, free the slot
;---------------------------------------------------------------------------
Magician_Free:
        addq.b  #$1,g_SpawnQuota+7(a6)          ; 0F510
        clr.b   (a5)                            ; 0F514  free this enemy slot
        rts                                     ; 0F516
Magician_AnimCloak:
	dc.w	Magician_AnimCloak_0-*	; 0
	dc.w	Magician_AnimCloak_1-*	; 1
Magician_AnimReveal:
	dc.w	Magician_AnimReveal_0-*	; 0
	dc.w	Magician_AnimReveal_1-*	; 1
Magician_AnimCloak_0:
	AL	$00,1,Magician_AnimCloak_0
Magician_AnimCloak_1:
	AL	$01,1,Magician_AnimCloak_1
Magician_AnimReveal_0:
	AL	$03,1,Magician_AnimReveal_0
Magician_AnimReveal_1:
	AL	$02,1,Magician_AnimReveal_1

;---------------------------------------------------------------------------
; === Unicorn (Cyclops) (type 8, 2000 pts, 10 hits (boss)) ===
; Boss of level 0 (one, at the gate) and level 1 (two); also on level 5. Drawn as two BOBs (legs + body).
; Dispatches on O_State: 0 main behaviour, 1 type-specific second phase, 2 killed (set by EnemyHitByShot after scoring), 3 remove.
;
; Behaviour, as coded:
;   * Waits (Uni_Delay x 16 frames) once Arthur is near its level, then walks to a walk
;     script, turning back at the edges of its arena (Unicorn_ChooseWalkDir).
;   * Fires a shot (enemy shot type 1, straight ahead) whenever Unicorn_ShotScript says so:
;     fire pose for 40 frames, shot, 25 frames recovery.
;   * Jumps over Arthur's weapons: any of Arthur's shots flying towards it within 56 pixels
;     starts a jump (Unicorn_CheckThreats).
;   * Keeps its distance: Uni_Approach asks to walk towards Arthur when he is 120+ pixels away
;     and away from him when closer than 32 (unicorn on the left) / 56 (on the right).
;   * After a random 51-130 frames it gets angry: next it either charges at Arthur
;     (Unicorn_Charge) or jumps at him (Unicorn_JumpAt), 50/50 (always the charge for variant 2).
;---------------------------------------------------------------------------
Enemy_Unicorn:
        move.b  O_State(a5),d0                  ; 0F530
        add.w   d0,d0                           ; 0F534
        add.w   d0,d0                           ; 0F536
        jmp     Enemy_Unicorn_Jumps(pc,d0.w)    ; 0F538
Enemy_Unicorn_Jumps:
        bra.w   Unicorn_Init                    ; 0F53C
        bra.w   Unicorn_Active                  ; 0F540
        bra.w   Unicorn_Dying                   ; 0F544
        bra.w   Unicorn_Free                    ; 0F548

;---------------------------------------------------------------------------
; State 0: set up the slot (10 HP, size class 4, scripts, start delay) then wait
; until it is on screen.
;---------------------------------------------------------------------------
Unicorn_Init:
        tst.b   O_Step(a5)                      ; 0F54C
        bne.w   Unicorn_WaitVisible             ; 0F550
        clr.b   Uni_Timer(a5)                   ; 0F554
        clr.b   Uni_Aiming(a5)                  ; 0F558
        clr.b   Uni_Angry(a5)                   ; 0F55C
        clr.b   Uni_Approach(a5)                ; 0F560
        clr.b   Uni_Gravity(a5)                 ; 0F564
        clr.b   Uni_Delay(a5)                   ; 0F568
        clr.w   Uni_ChargeX(a5)                 ; 0F56C
        clr.b   Uni_JumpNext(a5)                ; 0F570
        move.b  O_Param(a5),Uni_Variant(a5)     ; 0F574  variant from the spawn parameter
        move.b  #$4,O_Size(a5)                  ; 0F57A
        move.w  O_X(a5),d0                      ; 0F580
        cmp.w   g_ArthurX(a6),d0                ; 0F584
        slt.b   O_Dir(a5)                       ; 0F588  face Arthur: O_Dir = 1 (right) if he is to the right, else 2 (left)
        addq.b  #$2,O_Dir(a5)                   ; 0F58C
        lea.l   Unicorn_AnimStand(pc),a0        ; 0F590
        move.l  a0,Uni_AnimSet(a5)              ; 0F594
        bsr.w   SetAnimIndexed                  ; 0F598  start animation for current direction
        clr.b   O_AnimTimer(a5)                 ; 0F59C
        bsr.w   Animate                         ; 0F5A0  animate
        lea.l   Unicorn_ShotScript(pc),a0       ; 0F5A4
        move.b  (a0)+,Uni_ShotWait(a5)          ; 0F5A8
        move.l  a0,Uni_ShotPtr(a5)              ; 0F5AC
        move.b  #$a,O_HP(a5)                    ; 0F5B0  10 hits
        move.b  Uni_Variant(a5),d0              ; 0F5B6
        cmp.b   #$4,d0                          ; 0F5BA  variant 4: becomes variant 0, delay 10
        beq.b   l_0F5D0                         ; 0F5BE
        cmp.b   #$3,d0                          ; 0F5C0  variant 3: becomes variant 2, delay 10
        bne.b   l_0F5D4                         ; 0F5C4
        subq.b  #$1,d0                          ; 0F5C6
l_0F5C8:
        move.b  d0,Uni_Variant(a5)              ; 0F5C8
        moveq   #$a,d0                          ; 0F5CC
        bra.b   l_0F5E6                         ; 0F5CE
l_0F5D0:
        clr.b   d0                              ; 0F5D0
        bra.b   l_0F5C8                         ; 0F5D2
l_0F5D4:
        lea.l   Unicorn_StartDelays(pc),a0      ; 0F5D4  otherwise a delay of 2-4 x 16 frames
        move.w  g_GameFrame(a6),d0              ; 0F5D8
        add.w   d7,d0                           ; 0F5DC
        andi.w  #$3,d0                          ; 0F5DE
        move.b  (a0,d0.w),d0                    ; 0F5E2
l_0F5E6:
        move.b  d0,Uni_Delay(a5)                ; 0F5E6
        addq.b  #$1,O_Step(a5)                  ; 0F5EA  next step
        rts                                     ; 0F5EE
Unicorn_WaitVisible:
        tst.b   O_OnScreen(a5)                  ; 0F5F0
        beq.b   l_0F604                         ; 0F5F4
        move.b  #ST_ACTIVE,O_State(a5)          ; 0F5F6
        clr.b   O_Step(a5)                      ; 0F5FC
        clr.b   O_Step2(a5)                     ; 0F600
l_0F604:
        rts                                     ; 0F604
	dc.b	$00

;---------------------------------------------------------------------------
; Shot timing script: one byte per shot = frames to wait; bit 7 set = last entry,
; followed by a word offset back to the loop point.
;---------------------------------------------------------------------------
Unicorn_ShotScript:
	dc.b	',> GV6H#@'
	dc.b	$16
	dc.b	'/D8TCW'
	dc.b	$CA,$FF,$EF

;---------------------------------------------------------------------------
; Start delay per spawn (x 16 frames), picked with the frame counter
;---------------------------------------------------------------------------
Unicorn_StartDelays:
	dc.b	$02,$03,$04,$03

;---------------------------------------------------------------------------
; State 1. Does nothing while Arthur is 128+ pixels above it (variant != 0).
; O_Step: 0 wait, 1 walk, 2 jump, 3 charge, 4 reposition, 5 fire.
;---------------------------------------------------------------------------
Unicorn_Active:
        move.w  O_Y(a5),d0                      ; 0F61E
        sub.w   g_ArthurY(a6),d0                ; 0F622
        bpl.b   l_0F636                         ; 0F626
        cmp.w   #$ff80,d0                       ; 0F628  Arthur 128+ pixels above it?
        bgt.b   l_0F636                         ; 0F62C
        tst.b   Uni_Variant(a5)                 ; 0F62E
        beq.b   l_0F636                         ; 0F632
        rts                                     ; 0F634
l_0F636:
        clr.w   d0                              ; 0F636
        move.b  O_Step(a5),d0                   ; 0F638
        add.w   d0,d0                           ; 0F63C
        add.w   d0,d0                           ; 0F63E
        jmp     Unicorn_Active_Jumps(pc,d0.w)   ; 0F640
Unicorn_Active_Jumps:
        bra.w   Unicorn_Wait                    ; 0F644
        bra.w   Unicorn_WalkStep                ; 0F648
        bra.w   Unicorn_JumpStep                ; 0F64C
        bra.w   Unicorn_Charge                  ; 0F650
        bra.w   Unicorn_Reposition              ; 0F654
        bra.w   Unicorn_Fire                    ; 0F658

;---------------------------------------------------------------------------
; Step 0: snap onto the floor, then count down Uni_Delay (every 16 frames).
; Level 5: does not start until Arthur is on its level. Starts at once after a hit (HP 6).
;---------------------------------------------------------------------------
Unicorn_Wait:
        tst.b   O_Step2(a5)                     ; 0F65C
        bne.b   l_0F66C                         ; 0F660
        bsr.w   ObjectMapCollide                ; 0F662  first frame: snap onto the floor
        addq.b  #$1,O_Step2(a5)                 ; 0F666
        rts                                     ; 0F66A
l_0F66C:
        cmpi.w  #$5,g_Level(a6)                 ; 0F66C  level 5: wait until Arthur is no more than 16 pixels below it
        bne.b   l_0F682                         ; 0F672
        move.w  g_ArthurY(a6),d0                ; 0F674
        addi.w  #$10,d0                         ; 0F678
        sub.w   O_Y(a5),d0                      ; 0F67C
        bmi.b   l_0F6AA                         ; 0F680
l_0F682:
        cmpi.b  #$6,O_HP(a5)                    ; 0F682  already hit (6 HP left)? start at once
        beq.b   l_0F69C                         ; 0F688
        move.w  g_GameFrame(a6),d0              ; 0F68A
        addq.w  #$1,d0                          ; 0F68E
        andi.w  #$f,d0                          ; 0F690
        bne.b   l_0F6AA                         ; 0F694
        subq.b  #$1,Uni_Delay(a5)               ; 0F696  every 16 frames
        bne.b   l_0F6AA                         ; 0F69A
l_0F69C:
        addq.b  #$1,g_BigEnemyCount(a6)         ; 0F69C  one more big enemy engaged
        move.b  #$1,O_Step(a5)                  ; 0F6A0
        clr.b   O_Step2(a5)                     ; 0F6A6
l_0F6AA:
        rts                                     ; 0F6AA

;---------------------------------------------------------------------------
; Step 1: walk and shoot. Removed if it ends up far off screen.
;---------------------------------------------------------------------------
Unicorn_WalkStep:
        move.w  O_X(a5),d0                      ; 0F6AC  more than 256 px left / 768 right of the camera, or 160 below / 416 above it: remove
        sub.w   g_CameraX(a6),d0                ; 0F6B0
        addi.w  #$100,d0                        ; 0F6B4
        cmp.w   #$400,d0                        ; 0F6B8
        bhi.b   l_0F6D0                         ; 0F6BC
        move.w  O_Y(a5),d0                      ; 0F6BE
        sub.w   g_CameraY(a6),d0                ; 0F6C2
        addi.w  #$a0,d0                         ; 0F6C6
        cmp.w   #$240,d0                        ; 0F6CA
        bls.b   l_0F6DE                         ; 0F6CE
l_0F6D0:
        move.b  #ST_REMOVE,O_State(a5)          ; 0F6D0
        clr.b   O_Step(a5)                      ; 0F6D6
        clr.b   O_Step2(a5)                     ; 0F6DA
l_0F6DE:
        tst.b   O_Step2(a5)                     ; 0F6DE
        bne.b   l_0F6EA                         ; 0F6E2
        bsr.w   Unicorn_WalkStart               ; 0F6E4
        bra.b   l_0F6EE                         ; 0F6E8
l_0F6EA:
        bsr.w   Unicorn_Walk                    ; 0F6EA
l_0F6EE:
        bsr.w   Unicorn_CheckThreats            ; 0F6EE

;---------------------------------------------------------------------------
; Count down to the next shot; then take the fire pose for 40 frames and go to step 5
;---------------------------------------------------------------------------
Unicorn_ShotTimer:
        tst.b   Uni_Aiming(a5)                  ; 0F6F2
        bne.b   l_0F738                         ; 0F6F6
        subq.b  #$1,Uni_ShotWait(a5)            ; 0F6F8
        bne.b   l_0F766                         ; 0F6FC
        movea.l Uni_ShotPtr(a5),a0              ; 0F6FE
        move.b  (a0)+,d0                        ; 0F702
        bpl.b   l_0F70C                         ; 0F704  bit 7: last entry, loop
        adda.w  (a0),a0                         ; 0F706
        andi.b  #$7f,d0                         ; 0F708
l_0F70C:
        move.l  a0,Uni_ShotPtr(a5)              ; 0F70C
        move.b  d0,Uni_ShotWait(a5)             ; 0F710
        move.b  #$1,Uni_Aiming(a5)              ; 0F714
        lea.l   Unicorn_AnimAim(pc),a0          ; 0F71A
        move.l  a0,Uni_AnimSet(a5)              ; 0F71E
        cmpi.b  #$2,Uni_JumpType(a5)            ; 0F722
        bcs.b   l_0F72C                         ; 0F728
        addq.l  #$4,a0                          ; 0F72A
l_0F72C:
        adda.w  (a0),a0                         ; 0F72C
        bsr.w   SetAnim                         ; 0F72E  start animation
        move.b  #$28,Uni_Timer(a5)              ; 0F732  fire pose for 40 frames
l_0F738:
        subq.b  #$1,Uni_Timer(a5)               ; 0F738
        bne.b   l_0F766                         ; 0F73C
        lea.l   Unicorn_AnimFire(pc),a0         ; 0F73E
        cmpi.b  #$2,Uni_JumpType(a5)            ; 0F742
        bcs.b   l_0F74C                         ; 0F748
        addq.l  #$4,a0                          ; 0F74A
l_0F74C:
        adda.w  (a0),a0                         ; 0F74C
        bsr.w   SetAnim                         ; 0F74E  start animation
        move.b  #$19,Uni_Timer(a5)              ; 0F752  25 frames of recovery after the shot
        clr.b   Uni_Aiming(a5)                  ; 0F758
        move.b  #$5,O_Step(a5)                  ; 0F75C
        clr.b   O_Step2(a5)                     ; 0F762
l_0F766:
        rts                                     ; 0F766

;---------------------------------------------------------------------------
; 4 walk scripts (word offsets, picked with the frame counter), each a list of
; (direction, frames) pairs; direction 0 stand, 1 right, 2 left; bit 7 = loop (offset follows)
;---------------------------------------------------------------------------
Unicorn_WalkScripts:
	dc.b	$00,$08,$00,$12,$00,$1E,$00,$28,$01,$28,$00,$23,$02,$1F,$01,$24
	dc.b	$82,$22,$FF,$F6,$00,$14,$02,$25,$01,$14,$02,$1F,$01,$1A,$80,$2B
	dc.b	$FF,$F4,$02,$0F,$01,$23,$00,$28,$02,$22,$81,$14,$FF,$F6,$01,$1E
	dc.b	$02,$2D,$00,$1D,$02,$0A,$01,$1E,$80,$22,$FF,$F4

;---------------------------------------------------------------------------
; Move table for walking: (dx, dy) per direction, 8.8 fixed point (0, +0.53, -0.53)
;---------------------------------------------------------------------------
Unicorn_WalkMove:
	dc.b	$00,$00,$00,$00,$00,$88,$00,$00,$FF,$78,$00,$00

;---------------------------------------------------------------------------
; 8 random delays (frames) before the unicorn gets angry
;---------------------------------------------------------------------------
Unicorn_AngerDelays:
	dc.b	'ZnFcm3Z'
	dc.b	$82

;---------------------------------------------------------------------------
; Start walking: pick a walk script and anger delay, face Arthur.
; Variants other than 0 and 2 jump straight away.
;---------------------------------------------------------------------------
Unicorn_WalkStart:
        move.w  g_GameFrame(a6),d0              ; 0F7B8
        add.w   d7,d0                           ; 0F7BC
        addq.w  #$1,d0                          ; 0F7BE
        andi.w  #$3,d0                          ; 0F7C0
        add.w   d0,d0                           ; 0F7C4
        lea.l   Unicorn_WalkScripts(pc,d0.w),a0 ; 0F7C6
        move.l  a0,Uni_WalkPtr(a5)              ; 0F7CA
        clr.b   Uni_WalkTime(a5)                ; 0F7CE
        bsr.w   Unicorn_ChooseWalkDir           ; 0F7D2
        lea.l   Unicorn_WalkMove(pc),a0         ; 0F7D6
        move.l  a0,O_MoveTable(a5)              ; 0F7DA
        move.b  #$1,Uni_JumpType(a5)            ; 0F7DE
        move.w  O_X(a5),d0                      ; 0F7E4
        cmp.w   g_ArthurX(a6),d0                ; 0F7E8
        blt.b   l_0F7F4                         ; 0F7EC
        move.b  #$2,Uni_JumpType(a5)            ; 0F7EE
l_0F7F4:
        movea.l Uni_AnimSet(a5),a0              ; 0F7F4
        cmpi.b  #$2,Uni_JumpType(a5)            ; 0F7F8
        bcs.b   l_0F802                         ; 0F7FE
        addq.l  #$4,a0                          ; 0F800
l_0F802:
        adda.w  (a0),a0                         ; 0F802
        bsr.w   SetAnim                         ; 0F804  start animation
        bsr.w   Random                          ; 0F808  random number
        andi.w  #$7,d0                          ; 0F80C
        move.b  Unicorn_AngerDelays(pc,d0.w),Uni_AngerTimer(a5); 0F810  random anger delay
        clr.b   Uni_Angry(a5)                   ; 0F816
        clr.b   Uni_Approach(a5)                ; 0F81A
        move.b  Uni_Variant(a5),d0              ; 0F81E  variants 1 and 3 start with a jump
        beq.b   l_0F836                         ; 0F822
        cmp.b   #$2,d0                          ; 0F824
        beq.b   l_0F836                         ; 0F828
        move.b  #$2,O_Step(a5)                  ; 0F82A
        clr.b   O_Step2(a5)                     ; 0F830
        rts                                     ; 0F834
l_0F836:
        addq.b  #$1,O_Step2(a5)                 ; 0F836

;---------------------------------------------------------------------------
; One frame of walking; then work out Uni_Approach from the distance to Arthur
; (only while no scripted walk step is running).
;---------------------------------------------------------------------------
Unicorn_Walk:
        bsr.w   Unicorn_ChooseWalkDir           ; 0F83A
        tst.b   O_Dir(a5)                       ; 0F83E  O_Dir 0 = stand still
        beq.b   l_0F85C                         ; 0F842
        move.w  g_GameFrame(a6),d0              ; 0F844
        addq.w  #$1,d0                          ; 0F848
        andi.b  #$1f,d0                         ; 0F84A
        bne.b   l_0F856                         ; 0F84E  [1MB]   << changed from the 512K build ($0F8FA: bne.b $f8fe) >>
        moveq   #SFX_STOMP,d0                   ; 0F850  [1MB]   << changed from the 512K build ($0F8FC: moveq #$21, d0) >>
        bsr.w   PlaySfx                         ; 0F852  [1MB]   << changed from the 512K build ($0F8FE: bsr.w $ad7e) >>
l_0F856:
        bsr.w   ApplyMoveTable                  ; 0F856  [1MB] effect 24: Unicorn step  << 1MB only: 1 instruction(s) not in the 512K build >>
        bra.b   l_0F872                         ; 0F85A
l_0F85C:
        move.b  Uni_JumpType(a5),O_Dir(a5)      ; 0F85C
        movea.l Uni_AnimSet(a5),a0              ; 0F862
        bsr.w   SetAnimIndexed                  ; 0F866  start animation for current direction
        clr.b   O_Dir(a5)                       ; 0F86A
        clr.b   O_AnimTimer(a5)                 ; 0F86E
l_0F872:
        bsr.w   Animate                         ; 0F872  animate
        subq.b  #$1,Uni_AngerTimer(a5)          ; 0F876  anger timer
        bne.b   l_0F882                         ; 0F87A
        move.b  #$1,Uni_Angry(a5)               ; 0F87C
l_0F882:
        clr.b   Uni_Approach(a5)                ; 0F882
        tst.b   Uni_WalkTime(a5)                ; 0F886  scripted walk running: no approach decision
        bne.b   l_0F8B8                         ; 0F88A
        move.b  #$2,Uni_Approach(a5)            ; 0F88C
        move.w  O_X(a5),d0                      ; 0F892
        cmp.w   g_ArthurX(a6),d0                ; 0F896
        bhi.b   l_0F8BA                         ; 0F89A
        move.w  g_ArthurX(a6),d0                ; 0F89C  Arthur to the right: <= 32 px -> walk away (2), 120+ -> walk to him (1)
        sub.w   O_X(a5),d0                      ; 0F8A0
        cmp.w   #$20,d0                         ; 0F8A4
        bls.b   l_0F8B8                         ; 0F8A8
        subq.b  #$1,Uni_Approach(a5)            ; 0F8AA
        cmp.w   #$78,d0                         ; 0F8AE
        bcc.b   l_0F8B8                         ; 0F8B2
        subq.b  #$1,Uni_Approach(a5)            ; 0F8B4
l_0F8B8:
        rts                                     ; 0F8B8
l_0F8BA:
        sub.w   g_ArthurX(a6),d0                ; 0F8BA  Arthur to the left: 120+ px -> walk to him (2), <= 56 -> walk away (1)
        cmp.w   #$78,d0                         ; 0F8BE
        bcc.b   l_0F8B8                         ; 0F8C2
        subq.b  #$1,Uni_Approach(a5)            ; 0F8C4
        cmp.w   #$38,d0                         ; 0F8C8
        bls.b   l_0F8B8                         ; 0F8CC
        subq.b  #$1,Uni_Approach(a5)            ; 0F8CE
        rts                                     ; 0F8D2

;---------------------------------------------------------------------------
; Keep the unicorn in its arena (world X $1A18-... on level 1, $1D98-$1E48 for
; variant 2 on level 5, the level's right end otherwise): walk back in for 64 frames
; when outside it; otherwise follow the walk script.
;---------------------------------------------------------------------------
Unicorn_ChooseWalkDir:
        cmpi.b  #$2,Uni_Variant(a5)             ; 0F8D4
        beq.b   l_0F900                         ; 0F8DA
        cmpi.w  #$1,g_Level(a6)                 ; 0F8DC
        beq.b   l_0F92E                         ; 0F8E2
        move.w  g_LevelWidth(a6),d0             ; 0F8E4
        addi.w  #$e0,d0                         ; 0F8E8
        sub.w   O_X(a5),d0                      ; 0F8EC
        bpl.b   l_0F94A                         ; 0F8F0
        move.b  #$2,O_Dir(a5)                   ; 0F8F2
        move.b  #$40,Uni_WalkTime(a5)           ; 0F8F8  walk back for 64 frames
        rts                                     ; 0F8FE
l_0F900:
        move.w  O_X(a5),d0                      ; 0F900
        add.w   g_LevelOriginX(a6),d0           ; 0F904
        cmp.w   #$1d98,d0                       ; 0F908
        bhi.b   l_0F91C                         ; 0F90C
        move.b  #$1,O_Dir(a5)                   ; 0F90E
        move.b  #$40,Uni_WalkTime(a5)           ; 0F914
        rts                                     ; 0F91A
l_0F91C:
        cmp.w   #$1e48,d0                       ; 0F91C
        bcs.b   l_0F94A                         ; 0F920
        move.b  #$2,O_Dir(a5)                   ; 0F922
        move.b  #$40,Uni_WalkTime(a5)           ; 0F928
l_0F92E:
        move.w  O_X(a5),d0                      ; 0F92E
        add.w   g_LevelOriginX(a6),d0           ; 0F932
        cmp.w   #$1a18,d0                       ; 0F936
        bhi.b   l_0F94A                         ; 0F93A
        move.b  #$1,O_Dir(a5)                   ; 0F93C
        move.b  #$40,Uni_WalkTime(a5)           ; 0F942
        rts                                     ; 0F948
l_0F94A:
        tst.b   Uni_WalkTime(a5)                ; 0F94A
        bne.b   l_0F970                         ; 0F94E
        movea.l Uni_WalkPtr(a5),a0              ; 0F950
        move.b  (a0)+,d0                        ; 0F954  next (direction, frames) pair
        move.b  (a0)+,d1                        ; 0F956
        tst.b   d0                              ; 0F958
        bpl.b   l_0F962                         ; 0F95A
        andi.b  #$7f,d0                         ; 0F95C
        adda.w  (a0),a0                         ; 0F960
l_0F962:
        move.l  a0,Uni_WalkPtr(a5)              ; 0F962
        move.b  d0,O_Dir(a5)                    ; 0F966
        move.b  d1,Uni_WalkTime(a5)             ; 0F96A
        rts                                     ; 0F96E
l_0F970:
        subq.b  #$1,Uni_WalkTime(a5)            ; 0F970
        rts                                     ; 0F974

;---------------------------------------------------------------------------
; Step 2: jump. O_Step2: 0 take off, 1-2 rise, 3 apex, 4 fall, 5 land, 6 pause,
; 7 take off towards Arthur.
;---------------------------------------------------------------------------
Unicorn_JumpStep:
        clr.w   d0                              ; 0F976
        move.b  O_Step2(a5),d0                  ; 0F978
        add.w   d0,d0                           ; 0F97C
        add.w   d0,d0                           ; 0F97E
        jmp     Unicorn_JumpStep_Jumps(pc,d0.w) ; 0F980
Unicorn_JumpStep_Jumps:
        bra.w   Unicorn_JumpStart               ; 0F984
        bra.w   Unicorn_JumpRise                ; 0F988
        bra.w   Unicorn_JumpApproachApex        ; 0F98C
        bra.w   Unicorn_JumpApex                ; 0F990
        bra.w   Unicorn_JumpFall                ; 0F994
        bra.w   l_0FB8C                         ; 0F998  [1MB]   << changed from the 512K build ($0FA40: bra.w $fc34) >>
        bra.w   Unicorn_LandPause               ; 0F99C
        bra.w   Unicorn_JumpAt                  ; 0F9A0

;---------------------------------------------------------------------------
; Take off at 6 px/frame. Jump type (horizontal speed): variants 1/3 jump the long
; way (types 15/16), after Uni_JumpNext a short hop away from Arthur (5/6), otherwise random from
; Unicorn_JumpChoices (straight up or forward). Jumps that would leave the arena become a standing landing.
;---------------------------------------------------------------------------
Unicorn_JumpStart:
        move.l  #$60000,Uni_VelY(a5)            ; 0F9A4  take-off speed 6 px/frame
        lea.l   Unicorn_AnimJump(pc),a0         ; 0F9AC
        tst.b   Uni_Aiming(a5)                  ; 0F9B0
        beq.b   l_0F9BA                         ; 0F9B4
        lea.l   Unicorn_AnimJumpAim(pc),a0      ; 0F9B6
l_0F9BA:
        move.l  a0,Uni_AnimSet(a5)              ; 0F9BA
        cmpi.b  #$2,Uni_JumpType(a5)            ; 0F9BE  rising script for this jump type (types 2+ use the second entry)
        bcs.b   l_0F9C8                         ; 0F9C4
        addq.l  #$4,a0                          ; 0F9C6
l_0F9C8:
        adda.w  (a0),a0                         ; 0F9C8
        move.l  a0,O_Anim(a5)                   ; 0F9CA
        move.b  Uni_Variant(a5),d0              ; 0F9CE
        beq.b   l_0F9F0                         ; 0F9D2
        cmp.b   #$2,d0                          ; 0F9D4
        beq.b   l_0FA0C                         ; 0F9D8
        subq.b  #$1,Uni_Variant(a5)             ; 0F9DA  variants 1/3: one long jump, then behave as variant 0/2
        moveq   #$10,d0                         ; 0F9DE
        cmpi.b  #$1,Uni_JumpType(a5)            ; 0F9E0
        bne.b   l_0F9EA                         ; 0F9E6
        moveq   #$f,d0                          ; 0F9E8
l_0F9EA:
        move.b  d0,Uni_JumpType(a5)             ; 0F9EA
        bra.b   l_0FA2A                         ; 0F9EE
l_0F9F0:
        tst.b   Uni_JumpNext(a5)                ; 0F9F0
        beq.b   l_0FA0C                         ; 0F9F4
        clr.b   Uni_JumpNext(a5)                ; 0F9F6
        moveq   #$5,d0                          ; 0F9FA
        cmpi.b  #$1,Uni_JumpType(a5)            ; 0F9FC
        bne.b   l_0FA06                         ; 0FA02
        moveq   #$6,d0                          ; 0FA04
l_0FA06:
        move.b  d0,Uni_JumpType(a5)             ; 0FA06
        bra.b   l_0FA2A                         ; 0FA0A
l_0FA0C:
        lea.l   Unicorn_JumpChoices(pc),a0      ; 0FA0C  random next jump type (Unicorn_JumpChoicesAfter1 after a type-1 jump)
        cmpi.b  #$1,Uni_JumpType(a5)            ; 0FA10
        bne.b   l_0FA1C                         ; 0FA16
        lea.l   Unicorn_JumpChoicesAfter1(pc),a0; 0FA18
l_0FA1C:
        bsr.w   Random                          ; 0FA1C  random number
        andi.w  #$3,d0                          ; 0FA20
        move.b  (a0,d0.w),Uni_JumpType(a5)      ; 0FA24
l_0FA2A:
        cmpi.w  #$5,g_Level(a6)                 ; 0FA2A  level 5 / level 1: do not jump out of the arena
        beq.b   l_0FA5E                         ; 0FA30
        cmpi.w  #$1,g_Level(a6)                 ; 0FA32
        bne.b   l_0FA8C                         ; 0FA38
        move.w  O_X(a5),d0                      ; 0FA3A  level 1: left of world X $1A60 an even jump type becomes a standing landing
        add.w   g_LevelOriginX(a6),d0           ; 0FA3E
        cmp.w   #$1a60,d0                       ; 0FA42
        bhi.b   l_0FA8C                         ; 0FA46
        btst    #$0,Uni_JumpType(a5)            ; 0FA48
        bne.b   l_0FA8C                         ; 0FA4E
l_0FA50:
        move.b  #$2,O_Step(a5)                  ; 0FA50  no jump: step 2.5 (land on the spot)
        move.b  #$5,O_Step2(a5)                 ; 0FA56
        rts                                     ; 0FA5C
l_0FA5E:
        move.w  O_X(a5),d0                      ; 0FA5E  level 5: the same left of $1DA8 ...
        add.w   g_LevelOriginX(a6),d0           ; 0FA62
        cmp.w   #$1da8,d0                       ; 0FA66
        bhi.b   l_0FA76                         ; 0FA6A
        btst    #$0,Uni_JumpType(a5)            ; 0FA6C
        bne.b   l_0FA8C                         ; 0FA72
        bra.b   l_0FA50                         ; 0FA74
l_0FA76:
        cmp.w   #$1e38,d0                       ; 0FA76  ... and right of $1E38 an odd type (or type 0)
        bcs.b   l_0FA8C                         ; 0FA7A
        tst.b   Uni_JumpType(a5)                ; 0FA7C
        beq.b   l_0FA50                         ; 0FA80
        btst    #$0,Uni_JumpType(a5)            ; 0FA82
        beq.b   l_0FA8C                         ; 0FA88
        bra.b   l_0FA50                         ; 0FA8A
l_0FA8C:
        addq.b  #$1,O_Step2(a5)                 ; 0FA8C  jump: next step
        rts                                     ; 0FA90
Unicorn_JumpRise:
        bsr.w   Unicorn_MoveX                   ; 0FA92
        clr.b   Uni_Gravity(a5)                 ; 0FA96
        bsr.b   Unicorn_RiseStep                ; 0FA9A
        cmpi.l  #$10000,Uni_VelY(a5)            ; 0FA9C  until the upward speed is below 1 px/frame
        bhi.w   Animate                         ; 0FAA4
        addq.b  #$1,O_Step2(a5)                 ; 0FAA8
        rts                                     ; 0FAAC

;---------------------------------------------------------------------------
; Random jump types: 4 for facing left, 4 for facing right
;---------------------------------------------------------------------------
Unicorn_JumpChoices:
	dc.b	$00,$02,$04,$00

;---------------------------------------------------------------------------
; Next jump type after a type-1 jump (random pick of 4)
;---------------------------------------------------------------------------
Unicorn_JumpChoicesAfter1:
	dc.b	$01,$00,$00,$03

;---------------------------------------------------------------------------
; Gravity pairs (acceleration.w, max fall speed.w in px): $5000 (0.31 px/frame^2) up to
; 6 px/frame for the main rise and fall, $1900 (0.1) up to 1 near the apex
;---------------------------------------------------------------------------
Unicorn_Gravity:
	dc.b	$50,$00,$00,$06,$19,$00,$00,$01

;---------------------------------------------------------------------------
; Y += Uni_VelY, then slow it by the gravity for this phase
;---------------------------------------------------------------------------
Unicorn_RiseStep:
        move.l  Uni_VelY(a5),d0                 ; 0FABE
        add.l   d0,O_Y(a5)                      ; 0FAC2
        lea.l   Unicorn_Gravity(pc),a0          ; 0FAC6
        tst.b   Uni_Gravity(a5)                 ; 0FACA
        beq.b   l_0FAD2                         ; 0FACE
        addq.l  #$4,a0                          ; 0FAD0
l_0FAD2:
        move.w  (a0),d0                         ; 0FAD2
        ext.l   d0                              ; 0FAD4
        sub.l   d0,Uni_VelY(a5)                 ; 0FAD6
        rts                                     ; 0FADA
Unicorn_JumpApproachApex:
        bsr.b   Unicorn_MoveX                   ; 0FADC
        move.b  #$1,Uni_Gravity(a5)             ; 0FADE
        bsr.b   Unicorn_RiseStep                ; 0FAE4
        cmpi.l  #$1900,Uni_VelY(a5)             ; 0FAE6  until it is below 0.1 px/frame
        bhi.w   Animate                         ; 0FAEE
        addq.b  #$1,O_Step2(a5)                 ; 0FAF2
        rts                                     ; 0FAF6
Unicorn_JumpApex:
        bsr.b   Unicorn_MoveX                   ; 0FAF8
        move.b  #$1,Uni_Gravity(a5)             ; 0FAFA
        bsr.b   Unicorn_FallStep                ; 0FB00
        bra.w   Animate                         ; 0FB02

;---------------------------------------------------------------------------
; Y -= Uni_VelY, speeding up to the limit for this phase
;---------------------------------------------------------------------------
Unicorn_FallStep:
        move.l  Uni_VelY(a5),d0                 ; 0FB06
        sub.l   d0,O_Y(a5)                      ; 0FB0A
        lea.l   Unicorn_Gravity(pc),a0          ; 0FB0E
        tst.b   Uni_Gravity(a5)                 ; 0FB12
        beq.b   l_0FB1A                         ; 0FB16
        addq.l  #$4,a0                          ; 0FB18
l_0FB1A:
        move.w  Uni_VelY(a5),d0                 ; 0FB1A
        cmp.w   $2(a0),d0                       ; 0FB1E
        bhi.b   l_0FB2C                         ; 0FB22
        move.w  (a0),d0                         ; 0FB24
        ext.l   d0                              ; 0FB26
        add.l   d0,Uni_VelY(a5)                 ; 0FB28
l_0FB2C:
        tst.b   Uni_Gravity(a5)                 ; 0FB2C
        beq.b   l_0FB36                         ; 0FB30
        addq.b  #$1,O_Step2(a5)                 ; 0FB32
l_0FB36:
        rts                                     ; 0FB36

;---------------------------------------------------------------------------
; X += Unicorn_JumpSpeedX[Uni_JumpType] (8.8)
;---------------------------------------------------------------------------
Unicorn_MoveX:
        lea.l   Unicorn_JumpSpeedX(pc),a0       ; 0FB38
        move.b  Uni_JumpType(a5),d0             ; 0FB3C
        ext.w   d0                              ; 0FB40
        add.w   d0,d0                           ; 0FB42
        adda.w  d0,a0                           ; 0FB44
        move.w  (a0),d0                         ; 0FB46
        ext.l   d0                              ; 0FB48
        asl.l   #$8,d0                          ; 0FB4A
        add.l   d0,O_X(a5)                      ; 0FB4C
        rts                                     ; 0FB50

;---------------------------------------------------------------------------
; Horizontal speed per jump type, 8.8: odd = right, even = left, growing with the type
;---------------------------------------------------------------------------
Unicorn_JumpSpeedX:
	dc.b	$00,$00,$00,$6F,$FF,$91,$00,$F4,$FF,$0C,$01,$3E,$FE,$C2,$01,$6E
	dc.b	$FE,$92,$02,$0E,$FD,$F2,$02,$24,$FD,$DC,$02,$42,$FD,$BE,$04,$A0
	dc.b	$FB,$60

;---------------------------------------------------------------------------
; Fall until there is floor under it
;---------------------------------------------------------------------------
Unicorn_JumpFall:
        bsr.b   Unicorn_MoveX                   ; 0FB74
        clr.b   Uni_Gravity(a5)                 ; 0FB76
        bsr.b   Unicorn_FallStep                ; 0FB7A
        bsr.w   Animate                         ; 0FB7C  animate
        bsr.w   ObjectMapCollide                ; 0FB80  floor under it?
        bne.b   l_0FB8A                         ; 0FB84
        addq.b  #$1,O_Step2(a5)                 ; 0FB86
l_0FB8A:
