;---------------------------------------------------------------------------
; === Skeleton (type 9, 100 pts) ===
; Rises out of the floor (map collision) on the castle levels. Sound effect 17.
; Dispatches on O_State: 0 main behaviour, 1 type-specific second phase, 2 killed (set by EnemyHitByShot after scoring), 3 remove.
;
; Behaviour, as coded: lies as a pile of bones (size class 0) until Arthur comes within
; 32 px of it, then rises out of the floor and hops: two small hops (3 px/frame up, 0.8
; px/frame across), turning towards Arthur when he is 64+ px away, then a big leap that
; lands where Arthur was (dx / 42 per frame, a sine arc about 80 px high), then hops again.
; It does not give its spawn quota back when it is removed (the others do).
;---------------------------------------------------------------------------
Enemy_Skeleton:
        move.b  O_State(a5),d0                  ; 0FFE8
        add.w   d0,d0                           ; 0FFEC
        add.w   d0,d0                           ; 0FFEE
        jmp     Enemy_Skeleton_Jumps(pc,d0.w)   ; 0FFF0
Enemy_Skeleton_Jumps:
        bra.w   Skeleton_Init                   ; 0FFF4
        bra.w   Skeleton_Active                 ; 0FFF8
        bra.w   Skeleton_Dying                  ; 0FFFC
        bra.w   Skeleton_Free                   ; 10000

;---------------------------------------------------------------------------
; State 0: lie dormant until Arthur is within 32 px both ways
;---------------------------------------------------------------------------
Skeleton_Init:
        tst.b   O_Step(a5)                      ; 10004
        bne.b   Skeleton_Dormant                ; 10008
        clr.b   O_Size(a5)                      ; 1000A
        lea.l   Skeleton_AnimBones(pc),a0       ; 1000E
        bsr.w   SetAnim                         ; 10012  start animation
        addq.b  #$1,O_Step(a5)                  ; 10016  next step
        rts                                     ; 1001A
Skeleton_Dormant:
        tst.b   O_OnScreen(a5)                  ; 1001C
        beq.b   l_10054                         ; 10020
        move.w  O_X(a5),d0                      ; 10022
        sub.w   g_ArthurX(a6),d0                ; 10026
        addi.w  #$20,d0                         ; 1002A
        cmp.w   #$40,d0                         ; 1002E
        bhi.b   l_10054                         ; 10032
        move.w  O_Y(a5),d0                      ; 10034
        sub.w   g_ArthurY(a6),d0                ; 10038
        addi.w  #$20,d0                         ; 1003C
        cmp.w   #$40,d0                         ; 10040
        bhi.b   l_10054                         ; 10044
        move.b  #ST_ACTIVE,O_State(a5)          ; 10046
        clr.b   O_Step(a5)                      ; 1004C
        clr.b   O_Step2(a5)                     ; 10050
l_10054:
        rts                                     ; 10054

;---------------------------------------------------------------------------
; State 1. O_Step: 0 rise, 1 hop, 2 leap
;---------------------------------------------------------------------------
Skeleton_Active:
        move.b  O_Step(a5),d0                   ; 10056
        add.w   d0,d0                           ; 1005A
        add.w   d0,d0                           ; 1005C
        jsr     Skeleton_Active_Jumps(pc,d0.w)  ; 1005E
        bra.w   CheckFarAway                    ; 10062
Skeleton_Active_Jumps:
        bra.w   Skeleton_Rise                   ; 10066
        bra.w   Skeleton_Hop                    ; 1006A
        bra.w   Skeleton_Leap                   ; 1006E
Skeleton_Rise:
        move.b  O_Step2(a5),d0                  ; 10072
        add.w   d0,d0                           ; 10076
        add.w   d0,d0                           ; 10078
        jmp     Skeleton_Rise_Jumps(pc,d0.w)    ; 1007A
Skeleton_Rise_Jumps:
        bra.w   Skeleton_RiseStart              ; 1007E
        bra.w   Skeleton_Rising1                ; 10082
        bra.w   Skeleton_Rising2                ; 10086

;---------------------------------------------------------------------------
; Start rising at 3.5 px/frame
;---------------------------------------------------------------------------
Skeleton_RiseStart:
        lea.l   SkeletonMoveTable(pc),a0        ; 1008A
        move.l  a0,O_MoveTable(a5)              ; 1008E
        move.b  #$4,O_Dir(a5)                   ; 10092
        move.b  #$2,O_Size(a5)                  ; 10098
        lea.l   Skeleton_AnimRise(pc),a0        ; 1009E
        bsr.w   SetAnim                         ; 100A2  start animation
        move.l  #$38000,Skl_VelY(a5)            ; 100A6
        addq.b  #$1,O_Step2(a5)                 ; 100AE
        rts                                     ; 100B2
Skeleton_Rising1:
        bsr.b   Skeleton_RiseStep               ; 100B4
        tst.b   O_AnimTimer(a5)                 ; 100B6
        bne.b   l_100C0                         ; 100BA
        addq.b  #$1,O_Step2(a5)                 ; 100BC
l_100C0:
        rts                                     ; 100C0

;---------------------------------------------------------------------------
; when the animation ends: size 3, start hopping
;---------------------------------------------------------------------------
Skeleton_Rising2:
        bsr.b   Skeleton_RiseStep               ; 100C2
        tst.b   O_AnimTimer(a5)                 ; 100C4
        bne.b   l_100DA                         ; 100C8
        move.b  #$3,O_Size(a5)                  ; 100CA
        move.b  #$1,O_Step(a5)                  ; 100D0
        clr.b   O_Step2(a5)                     ; 100D6
l_100DA:
        rts                                     ; 100DA

;---------------------------------------------------------------------------
; Y += speed, speed -= 0.16
;---------------------------------------------------------------------------
Skeleton_RiseStep:
        move.w  Skl_VelY(a5),d0                 ; 100DC
        add.w   d0,O_Y(a5)                      ; 100E0
        subi.l  #$2985,Skl_VelY(a5)             ; 100E4
        bra.w   Animate                         ; 100EC

;---------------------------------------------------------------------------
; O_Step2: 0 start, 1 take off, 2 rise, 3 fall, 4-5 pause and aim
;---------------------------------------------------------------------------
Skeleton_Hop:
        move.b  O_Step2(a5),d0                  ; 100F0
        add.w   d0,d0                           ; 100F4
        add.w   d0,d0                           ; 100F6
        jmp     Skeleton_Hop_Jumps(pc,d0.w)     ; 100F8
Skeleton_Hop_Jumps:
        bra.w   l_10114                         ; 100FC  [1MB]   << changed from the 512K build ($10196: bra.w $101ae) >>
        bra.w   Skeleton_TakeOff                ; 10100
        bra.w   Skeleton_HopRise                ; 10104
        bra.w   Skeleton_HopFall                ; 10108
        bra.w   Skeleton_Land                   ; 1010C
        bra.w   Skeleton_LandPause              ; 10110
l_10114:
        moveq   #SFX_SKELETON_HOP,d0            ; 10114  [1MB] effect 22: skeleton hop  << 1MB only: 2 instruction(s) not in the 512K build >>
        bsr.w   PlaySfx                         ; 10116  [1MB] 

;---------------------------------------------------------------------------
; 2 hops before the leap
