Skeleton_HopStart:
        lea.l   SkeletonMoveTable(pc),a0        ; 1011A
        move.l  a0,O_MoveTable(a5)              ; 1011E
        move.b  #$2,Skl_Hops(a5)                ; 10122
        addq.b  #$1,O_Step2(a5)                 ; 10128
        rts                                     ; 1012C

;---------------------------------------------------------------------------
; 3 px/frame upwards
;---------------------------------------------------------------------------
Skeleton_TakeOff:
        lea.l   Skeleton_AnimHop(pc),a0         ; 1012E
        bsr.w   SetAnim                         ; 10132  start animation
        move.l  #$30000,Skl_VelY(a5)            ; 10136
        addq.b  #$1,O_Step2(a5)                 ; 1013E

;---------------------------------------------------------------------------
; gravity 0.165 px/frame^2 until the top
;---------------------------------------------------------------------------
Skeleton_HopRise:
        bsr.w   Skeleton_HopMove                ; 10142
        subi.l  #$2a16,Skl_VelY(a5)             ; 10146
        tst.w   Skl_VelY(a5)                    ; 1014E
        bne.b   l_10158                         ; 10152
        addq.b  #$1,O_Step2(a5)                 ; 10154
l_10158:
        rts                                     ; 10158

;---------------------------------------------------------------------------
; down to -3 px/frame until it lands
;---------------------------------------------------------------------------
Skeleton_HopFall:
        bsr.b   Skeleton_HopMove                ; 1015A
        cmpi.w  #$fffd,Skl_VelY(a5)             ; 1015C
        blt.b   l_1016C                         ; 10162
        subi.l  #$2a16,Skl_VelY(a5)             ; 10164
l_1016C:
        bsr.w   ObjectMapCollide                ; 1016C  on the floor? (Z set = yes, Y snapped onto it)
        bne.b   l_10176                         ; 10170
        addq.b  #$1,O_Step2(a5)                 ; 10172
l_10176:
        rts                                     ; 10176
Skeleton_Land:
        move.b  #$6,Skl_Pause(a5)               ; 10178
        addq.b  #$1,O_Step2(a5)                 ; 1017E

;---------------------------------------------------------------------------
; 6 frames, aim, then hop again or leap
;---------------------------------------------------------------------------
Skeleton_LandPause:
        subq.b  #$1,Skl_Pause(a5)               ; 10182
        bne.w   Animate                         ; 10186
        bsr.b   Skeleton_Aim                    ; 1018A
        move.b  #$1,O_Step2(a5)                 ; 1018C
        subq.b  #$1,Skl_Hops(a5)                ; 10192
        bne.b   l_101A2                         ; 10196
        move.b  #$2,O_Step(a5)                  ; 10198
        clr.b   O_Step2(a5)                     ; 1019E
l_101A2:
        rts                                     ; 101A2

;---------------------------------------------------------------------------
; Arthur 64+ px away: face him (O_Dir 1 right, 3 left); closer: keep going
;---------------------------------------------------------------------------
Skeleton_Aim:
        move.w  O_X(a5),d0                      ; 101A4
        sub.w   g_ArthurX(a6),d0                ; 101A8
        addi.w  #$40,d0                         ; 101AC
        cmp.w   #$80,d0                         ; 101B0
        bcs.b   l_101CC                         ; 101B4
        move.b  #$3,O_Dir(a5)                   ; 101B6
        move.w  O_X(a5),d0                      ; 101BC
        cmp.w   g_ArthurX(a6),d0                ; 101C0
        bhi.b   l_101CC                         ; 101C4
        move.b  #$1,O_Dir(a5)                   ; 101C6
l_101CC:
        rts                                     ; 101CC

;---------------------------------------------------------------------------
; X += move table dx for O_Dir, Y += Skl_VelY
;---------------------------------------------------------------------------
Skeleton_HopMove:
        movea.l O_MoveTable(a5),a0              ; 101CE
        clr.w   d0                              ; 101D2
        move.b  O_Dir(a5),d0                    ; 101D4
        add.w   d0,d0                           ; 101D8
        add.w   d0,d0                           ; 101DA
        adda.w  d0,a0                           ; 101DC
        move.w  (a0),d0                         ; 101DE
        ext.l   d0                              ; 101E0
        asl.l   #$8,d0                          ; 101E2
        add.l   d0,O_X(a5)                      ; 101E4
        move.l  Skl_VelY(a5),d0                 ; 101E8
        add.l   d0,O_Y(a5)                      ; 101EC
        bra.w   Animate                         ; 101F0

;---------------------------------------------------------------------------
; O_Step2: 0 aim, 1 up, 2 down, 3-4 pause
;---------------------------------------------------------------------------
Skeleton_Leap:
        move.b  O_Step2(a5),d0                  ; 101F4
        add.w   d0,d0                           ; 101F8
        add.w   d0,d0                           ; 101FA
        jmp     Skeleton_Leap_Jumps(pc,d0.w)    ; 101FC
Skeleton_Leap_Jumps:
        bra.w   Skeleton_LeapStart              ; 10200
        bra.w   Skeleton_LeapUp                 ; 10204
        bra.w   Skeleton_LeapDown               ; 10208
        bra.w   Skeleton_LeapLand               ; 1020C
        bra.w   Skeleton_LeapPause              ; 10210

;---------------------------------------------------------------------------
; Skl_LeapDX = (Arthur X - X) / 42: lands on his spot after 42 frames
;---------------------------------------------------------------------------
Skeleton_LeapStart:
        lea.l   Skeleton_AnimLeap(pc),a0        ; 10214
        bsr.w   SetAnim                         ; 10218  start animation
        move.w  O_Y(a5),Skl_BaseY(a5)           ; 1021C
        clr.b   Skl_Phase(a5)                   ; 10222
        move.w  g_ArthurX(a6),d0                ; 10226
        sub.w   O_X(a5),d0                      ; 1022A
        ext.l   d0                              ; 1022E
        asl.l   #$8,d0                          ; 10230
        divs.w  #$2a,d0                         ; 10232
        ext.l   d0                              ; 10236
        asl.l   #$8,d0                          ; 10238
        move.l  d0,Skl_LeapDX(a5)               ; 1023A
        addq.b  #$1,O_Step2(a5)                 ; 1023E
        rts                                     ; 10242

;---------------------------------------------------------------------------
; phase += 6 until the top
;---------------------------------------------------------------------------
Skeleton_LeapUp:
        addq.b  #$6,Skl_Phase(a5)               ; 10244
        bmi.b   l_10256                         ; 10248
        bsr.b   Skeleton_LeapY                  ; 1024A
        move.l  Skl_LeapDX(a5),d0               ; 1024C
        add.l   d0,O_X(a5)                      ; 10250
        rts                                     ; 10254
l_10256:
        addq.b  #$1,O_Step2(a5)                 ; 10256
        rts                                     ; 1025A

;---------------------------------------------------------------------------
; until the phase wraps, or it lands (checked near the end)
;---------------------------------------------------------------------------
Skeleton_LeapDown:
        addq.b  #$6,Skl_Phase(a5)               ; 1025C
        bcs.b   l_10282                         ; 10260
        cmpi.b  #$e0,Skl_Phase(a5)              ; 10262
        bcs.b   l_10270                         ; 10268
        bsr.w   ObjectMapCollide                ; 1026A  on the floor? (Z set = yes, Y snapped onto it)
        beq.b   l_10282                         ; 1026E
l_10270:
        bsr.b   Skeleton_LeapY                  ; 10270
        move.l  Skl_LeapDX(a5),d0               ; 10272
        add.l   d0,O_X(a5)                      ; 10276
        rts                                     ; 1027A
	dc.b	$3B,$6D,$00,$20,$00,$0A
l_10282:
        addq.b  #$1,O_Step2(a5)                 ; 10282
        rts                                     ; 10286
Skeleton_LeapLand:
        move.b  #$6,Skl_Pause(a5)               ; 10288
        addq.b  #$1,O_Step2(a5)                 ; 1028E
Skeleton_LeapPause:
        subq.b  #$1,Skl_Pause(a5)               ; 10292
        bne.w   Animate                         ; 10296
        bsr.w   Skeleton_Aim                    ; 1029A
        move.b  #$1,O_Step(a5)                  ; 1029E
        clr.b   O_Step2(a5)                     ; 102A4
        rts                                     ; 102A8

;---------------------------------------------------------------------------
; Y = Skl_BaseY + sin(phase) x 2 x 80 / 256
;---------------------------------------------------------------------------
Skeleton_LeapY:
        lea.l   SineTable(pc),a0                ; 102AA
        clr.w   d0                              ; 102AE
        move.b  Skl_Phase(a5),d0                ; 102B0
        move.b  (a0,d0.w),d0                    ; 102B4
        add.w   d0,d0                           ; 102B8
        mulu.w  #$50,d0                         ; 102BA
        lsr.w   #$8,d0                          ; 102BE
        add.w   Skl_BaseY(a5),d0                ; 102C0
        move.w  d0,O_Y(a5)                      ; 102C4
        rts                                     ; 102C8

;---------------------------------------------------------------------------
; State 2: sound 17, EnemyDieFacing
;---------------------------------------------------------------------------
Skeleton_Dying:
        cmpi.b  #$1,O_Step(a5)                  ; 102CA
        beq.b   l_102E0                         ; 102D0
        bcc.b   l_102E4                         ; 102D2
        moveq   #SFX_ENEMY_DIE,d0               ; 102D4
        bsr.w   PlaySfx                         ; 102D6  sound effect 17 (enemy event)
        addq.b  #$1,O_Step(a5)                  ; 102DA  next step
        rts                                     ; 102DE
l_102E0:
        bra.w   EnemyDieFacing                  ; 102E0
l_102E4:
        move.b  #ST_REMOVE,O_State(a5)          ; 102E4
        rts                                     ; 102EA

;---------------------------------------------------------------------------
; State 3: free the slot (no spawn quota given back)
;---------------------------------------------------------------------------
Skeleton_Free:
        clr.b   (a5)                            ; 102EC  free this enemy slot
        rts                                     ; 102EE

;---------------------------------------------------------------------------
; (dx, dy) 8.8: 0 still, 1 right 0.8, 2 down, 3 left 0.8, 4 up (only dx is used)
;---------------------------------------------------------------------------
SkeletonMoveTable:
	dc.b	$00,$00,$00,$00,$00,$CC,$00,$00,$00,$00,$FF,$34,$FF,$34,$00,$00
	dc.b	$00,$00,$00,$CC
Skeleton_AnimBones:
	AL	$00,3,Skeleton_AnimBones
Skeleton_AnimRise:
	AF	$01,1
	AL	$02,1,Skeleton_AnimRise
Skeleton_AnimHop:
	AF	$01,6
	AF	$02,6
	AF	$03,24
	AF	$02,3
	AL	$01,4,Skeleton_AnimHop
Skeleton_AnimLeap:
	AF	$01,6
	AF	$02,6
	AF	$03,24
	AF	$02,3
	AL	$01,3,Skeleton_AnimLeap

;---------------------------------------------------------------------------
; === Big Man (type 10, 500 pts, 10 hits) ===
; Ogre that walks and charges along the floor, pauses at random and throws projectiles.
; Dispatches on O_State: 0 main behaviour, 1 type-specific second phase, 2 killed (set by EnemyHitByShot after scoring), 3 remove.
;
; Behaviour, as coded:
;   * Walks at 0.53 px/frame, turning back at the edge of a floor, and pauses (70 or 100
;     frames, random) after each walk time in BigManWalkTimes, then picks a random direction.
;   * When Arthur is on its level (10 px below to 45 px above), it fights: paces to and
;     fro across him (turning 40 px past him), charges at 2 px/frame, and throws enemy
;     shot type 3 on BigManShotTimes (10-frame wind-up).
;   * When Arthur is directly below (within 10 px across) it crouches and throws down
;     every 30 frames.
;   * Each hit makes it flinch for 6 frames. Only acts while on screen.
;---------------------------------------------------------------------------
Enemy_BigMan:
        move.b  O_State(a5),d0                  ; 10326
        add.w   d0,d0                           ; 1032A
        add.w   d0,d0                           ; 1032C
        jmp     Enemy_BigMan_Jumps(pc,d0.w)     ; 1032E
Enemy_BigMan_Jumps:
        bra.w   BigMan_Init                     ; 10332
        bra.w   BigMan_Active                   ; 10336
        bra.w   BigMan_Dying                    ; 1033A
        bra.w   BigMan_Free                     ; 1033E

;---------------------------------------------------------------------------
; State 0: 10 HP, size 3, face Arthur, start the scripts; wait until on screen
;---------------------------------------------------------------------------
BigMan_Init:
        tst.b   O_Step(a5)                      ; 10342
        bne.b   BigMan_WaitVisible              ; 10346
        move.b  O_Param(a5),BM_Crouched(a5)     ; 10348
        clr.b   O_Param(a5)                     ; 1034E
        move.w  O_X(a5),d0                      ; 10352
        cmp.w   g_ArthurX(a6),d0                ; 10356
        slt.b   O_Dir(a5)                       ; 1035A
        addq.b  #$1,O_Dir(a5)                   ; 1035E
        move.b  #$3,O_Size(a5)                  ; 10362
        lea.l   BigMan_AnimWalk(pc),a0          ; 10368
        bsr.w   SetAnimIndexed                  ; 1036C  start animation for current direction
        move.b  #$a,O_HP(a5)                    ; 10370
        clr.b   BM_Timer(a5)                    ; 10376
        clr.b   BM_EdgeDir(a5)                  ; 1037A
        clr.b   BM_AtEdge(a5)                   ; 1037E
        clr.b   BM_EdgeTurn(a5)                 ; 10382
        lea.l   BigManShotTimes(pc),a0          ; 10386
        move.b  (a0)+,BM_ShotTime(a5)           ; 1038A
        move.l  a0,BM_ShotPtr(a5)               ; 1038E
        lea.l   BigManWalkTimes(pc),a0          ; 10392
        move.b  (a0)+,BM_WalkTime(a5)           ; 10396
        move.l  a0,BM_WalkPtr(a5)               ; 1039A
        lea.l   BigManMoveTable(pc),a0          ; 1039E
        move.l  a0,O_MoveTable(a5)              ; 103A2
        addq.b  #$1,O_Step(a5)                  ; 103A6  next step
        rts                                     ; 103AA
BigMan_WaitVisible:
        tst.b   O_OnScreen(a5)                  ; 103AC
        beq.b   l_103BE                         ; 103B0
        addq.b  #ST_ACTIVE,O_State(a5)          ; 103B2
        clr.b   O_Step(a5)                      ; 103B6
        clr.b   O_Step2(a5)                     ; 103BA
l_103BE:
        rts                                     ; 103BE
	dc.b	$00

;---------------------------------------------------------------------------
; frames between shots: 45, 35, 20, 20, 42, 60, 35, 50, 28 (bit 7 = loop)
;---------------------------------------------------------------------------
BigManShotTimes:
	dc.b	$2D,$23,$14,$14,$2A,$3C,$23,$32,$9C,$FF,$F7

;---------------------------------------------------------------------------
; frames of walking between pauses: 190, 100, 163, 230, 98, 156, 120, 160, 120
;---------------------------------------------------------------------------
BigManWalkTimes:
	dc.b	$BE,$64,$A3,$E6,$62,$9C,$78,$A0,$78,$00,$FF,$F6

;---------------------------------------------------------------------------
; O_Dir 0/1: +-0.53 walking; 2/3: +-2.0 charging
;---------------------------------------------------------------------------
BigManMoveTable:
	dc.b	$00,$88,$00,$00,$FF,$78,$00,$00,$02,$00,$00,$00,$FE,$00,$00,$00

;---------------------------------------------------------------------------
; State 1 (on screen only). O_Step: 0 walk, 1 fight, 2 shoot down, 3 flinch
;---------------------------------------------------------------------------
BigMan_Active:
        tst.b   O_OnScreen(a5)                  ; 103E8
        beq.b   l_10416                         ; 103EC
        move.b  O_Step(a5),d0                   ; 103EE
        add.w   d0,d0                           ; 103F2
        add.w   d0,d0                           ; 103F4
        jsr     BigMan_Active_Jumps(pc,d0.w)    ; 103F6
        tst.b   O_Param(a5)                     ; 103FA
        beq.b   l_10416                         ; 103FE
        clr.b   O_Param(a5)                     ; 10400  hit (EnemyHitByShot set O_Param): flinch
        move.b  #$3,O_Step(a5)                  ; 10404
        clr.b   O_Step2(a5)                     ; 1040A
        lea.l   BigMan_AnimFlinch(pc),a0        ; 1040E
        bra.w   SetAnimIndexed                  ; 10412
l_10416:
        rts                                     ; 10416
BigMan_Active_Jumps:
        bra.w   BigMan_Walk                     ; 10418
        bra.w   BigMan_Fight                    ; 1041C
        bra.w   BigMan_ShootDown                ; 10420
        bra.w   BigMan_Flinch                   ; 10424

;---------------------------------------------------------------------------
; 6 frames after a hit, then walk
;---------------------------------------------------------------------------
BigMan_Flinch:
        tst.b   O_Step2(a5)                     ; 10428
        bne.b   l_1043E                         ; 1042C
        move.b  #$6,BM_FlinchTime(a5)           ; 1042E
        moveq   #SFX_HURT,d0                    ; 10434  [1MB] effect 19: hit  << 1MB only: 2 instruction(s) not in the 512K build >>
        bsr.w   PlaySfx                         ; 10436  [1MB] 
        addq.b  #$1,O_Step2(a5)                 ; 1043A
l_1043E:
        subq.b  #$1,BM_FlinchTime(a5)           ; 1043E
        bne.w   Animate                         ; 10442
        clr.b   O_Step(a5)                      ; 10446
        clr.b   O_Step2(a5)                     ; 1044A
        clr.b   O_Param(a5)                     ; 1044E
        rts                                     ; 10452

;---------------------------------------------------------------------------
; O_Step2: 0 start, 1 walk, 2 pause, 3-4 crouch
;---------------------------------------------------------------------------
BigMan_Walk:
        clr.w   d0                              ; 10454
        move.b  O_Step2(a5),d0                  ; 10456
        add.w   d0,d0                           ; 1045A
        add.w   d0,d0                           ; 1045C
        jmp     BigMan_Walk_Jumps(pc,d0.w)      ; 1045E
BigMan_Walk_Jumps:
        bra.w   BigMan_WalkStart                ; 10462
        bra.w   BigMan_Walking                  ; 10466
        bra.w   BigMan_Pause                    ; 1046A
        bra.w   BigMan_CrouchWait               ; 1046E
        bra.w   BigMan_Crouching                ; 10472
BigMan_WalkStart:
        lea.l   BigMan_AnimWalk(pc),a0          ; 10476
        bsr.w   SetAnimIndexed                  ; 1047A  start animation for current direction
        tst.b   BM_Crouched(a5)                 ; 1047E
        beq.b   l_104A6                         ; 10482
        lea.l   BigMan_AnimCrouch(pc),a0        ; 10484
        bsr.w   SetAnimIndexed                  ; 10488  start animation for current direction
        bsr.w   Random                          ; 1048C  random number
        andi.w  #$3,d0                          ; 10490
        move.b  BigManCrouchTimes(pc,d0.w),BM_CrouchTime(a5); 10494
        move.b  #$3,O_Step2(a5)                 ; 1049A
        clr.b   BM_Crouched(a5)                 ; 104A0
        rts                                     ; 104A4
l_104A6:
        addq.b  #$1,O_Step2(a5)                 ; 104A6
        rts                                     ; 104AA

;---------------------------------------------------------------------------
; x 64 frames: 2, 3, 3, 2
;---------------------------------------------------------------------------
BigManCrouchTimes:
	dc.b	$02,$03,$03,$02

;---------------------------------------------------------------------------
; Arthur on its level: fight. Directly below it: shoot down. Otherwise walk,
; turn at floor edges, and pause when the walk time runs out.
;---------------------------------------------------------------------------
BigMan_Walking:
