;---------------------------------------------------------------------------
; === Dragon (type 12, 200 pts per segment) ===
; Flying dragon boss of levels 2-3: a chain of segments led by the head (6 hits); the head aims and breathes fire at Arthur. Sound effects 12/20; awards 1000 extra on defeat.
; Dispatches on O_State: 0 main behaviour, 1 type-specific second phase, 2 killed (set by EnemyHitByShot after scoring), 3 remove.
;
; Behaviour, as coded:
;   * The placed head (parameter 0) builds the body: 7 segments (parameter 1) and a tail
;     (parameter 2) in free enemy slots, linked through Drg_Next / Drg_Prev.
;   * The head steers along path scripts of (frames, direction) pairs in 16 directions
;     at 2 px/frame. Each direction change is handed down the chain with a 6-frame
;     delay per segment (7 for the tail), which makes the body follow the head's path.
;   * Entrance: a short S-curve, then it waits frozen until it is on screen and Arthur
;     is no more than 32 px below it, for a further 2-5 x 16 frames, then attacks.
;   * Attack: when a path step ends it may (3 in 16) dive at Arthur if he is 24+ px in
;     front of it; otherwise it turns round once it is 94+ px past him (turn paths for the
;     upper and lower half of the screen), and climbs or descends towards his height.
;   * Every 32 frames, if Arthur is within 72 px vertically, it breathes fire (enemy shot
;     type 9) and opens its mouth for 10 frames.
;   * Hits: each hit on any segment scores 200. Hitting the tail kills it; hitting a body
;     segment kills the tail instead, so the dragon shortens from the tail. The head takes
;     6 hits; killing it kills every segment, scores a further 1000 and ends the boss.
;   * Off levels 2-3 it is removed when it gets far off screen.
;---------------------------------------------------------------------------
Enemy_Dragon:
        move.b  O_State(a5),d0                  ; 10C48
        add.w   d0,d0                           ; 10C4C
        add.w   d0,d0                           ; 10C4E
        jmp     Enemy_Dragon_Jumps(pc,d0.w)     ; 10C50
Enemy_Dragon_Jumps:
        bra.w   Dragon_Init                     ; 10C54
        bra.w   Dragon_Active                   ; 10C58
        bra.w   Dragon_Dying                    ; 10C5C
        bra.w   Dragon_Free                     ; 10C60

;---------------------------------------------------------------------------
; State 0: by part (O_Param): head / body segment / tail
;---------------------------------------------------------------------------
Dragon_Init:
        move.b  O_Param(a5),d0                  ; 10C64
        add.w   d0,d0                           ; 10C68
        add.w   d0,d0                           ; 10C6A
        jmp     Dragon_Init_Jumps(pc,d0.w)      ; 10C6C
Dragon_Init_Jumps:
        bra.w   Dragon_InitHead                 ; 10C70
        bra.w   Dragon_InitBody                 ; 10C74
        bra.w   Dragon_InitTail                 ; 10C78
Dragon_InitHead:
        move.b  O_Step(a5),d0                   ; 10C7C
        add.w   d0,d0                           ; 10C80
        add.w   d0,d0                           ; 10C82
        jmp     Dragon_InitHead_Jumps(pc,d0.w)  ; 10C84
Dragon_InitHead_Jumps:
        bra.w   Dragon_HeadSetup                ; 10C88
        bra.w   Dragon_BuildBody                ; 10C8C
        bra.w   Dragon_NumberChain              ; 10C90

;---------------------------------------------------------------------------
; Face Arthur, size 3, 6 HP, 16-way move table, start the entrance path
;---------------------------------------------------------------------------
Dragon_HeadSetup:
        clr.b   O_Dir(a5)                       ; 10C94
        clr.b   Drg_Facing(a5)                  ; 10C98
        clr.b   Drg_Part(a5)                    ; 10C9C
        move.w  O_X(a5),d0                      ; 10CA0
        cmp.w   g_ArthurX(a6),d0                ; 10CA4
        blt.b   l_10CB6                         ; 10CA8
        move.b  #$8,O_Dir(a5)                   ; 10CAA  Arthur to the left: direction 8, facing left
        move.b  #$1,Drg_Facing(a5)              ; 10CB0
l_10CB6:
        move.b  #$3,O_Size(a5)                  ; 10CB6
        lea.l   Dragon_AnimFly(pc),a0           ; 10CBC
        clr.w   d0                              ; 10CC0
        move.b  Drg_Facing(a5),d0               ; 10CC2
        add.w   d0,d0                           ; 10CC6
        adda.w  d0,a0                           ; 10CC8
        adda.w  (a0),a0                         ; 10CCA
        bsr.w   SetAnim                         ; 10CCC  start animation
        lea.l   DragonMoveTable(pc),a0          ; 10CD0
        move.l  a0,O_MoveTable(a5)              ; 10CD4
        lea.l   DragonEntrancePath(pc),a0       ; 10CD8
        move.b  (a0)+,Drg_PathTime(a5)          ; 10CDC
        move.b  (a0)+,O_Dir(a5)                 ; 10CE0
        move.l  a0,Drg_PathPtr(a5)              ; 10CE4
        move.b  #$2,Drg_Aggro(a5)               ; 10CE8  attack chance 3 in 16
        clr.b   Drg_Firing(a5)                  ; 10CEE
        clr.b   Drg_Pending(a5)                 ; 10CF2
        clr.b   Drg_Frozen(a5)                  ; 10CF6
        move.b  #$6,O_HP(a5)                    ; 10CFA
        move.w  O_Y(a5),Drg_HomeY(a5)           ; 10D00
        addq.b  #$1,O_Step(a5)                  ; 10D06  next step
        clr.b   O_Step2(a5)                     ; 10D0A
        rts                                     ; 10D0E

;---------------------------------------------------------------------------
; Allocate 7 body segments and the tail behind the head, each linked to the one
; before it (14 px apart, the first 20 px). Tries again next frame if the table is full.
;---------------------------------------------------------------------------
Dragon_BuildBody:
        moveq   #$7,d6                          ; 10D10
        clr.l   Drg_Prev(a5)                    ; 10D12
        movea.l a5,a3                           ; 10D16
l_10D18:
        lea.l   g_Enemies(a6),a4                ; 10D18
        moveq   #$27,d5                         ; 10D1C
l_10D1E:
        tst.b   (a4)                            ; 10D1E
        beq.b   l_10D2E                         ; 10D20
        lea.l   $3c(a4),a4                      ; 10D22
        dbra    d5,l_10D1E                      ; 10D26
        bra.w   Dragon_BuildExit                ; 10D2A
l_10D2E:
        move.l  a4,$24(a3)                      ; 10D2E
        cmp.b   #$7,d6                          ; 10D32  first segment: 20 px behind the head, 3 px lower
        beq.b   l_10D4C                         ; 10D36
        move.w  $6(a3),d0                       ; 10D38
        addi.w  #$e,d0                          ; 10D3C
        move.w  d0,$6(a4)                       ; 10D40
        move.w  $a(a3),$a(a4)                   ; 10D44
        bra.b   l_10D62                         ; 10D4A
l_10D4C:
        move.w  $6(a3),d0                       ; 10D4C
        addi.w  #$14,d0                         ; 10D50
        move.w  d0,$6(a4)                       ; 10D54
        move.w  $a(a3),d0                       ; 10D58
        subq.w  #$3,d0                          ; 10D5C
        move.w  d0,$a(a4)                       ; 10D5E
l_10D62:
        clr.b   $3(a4)                          ; 10D62
        clr.b   $4(a4)                          ; 10D66
        clr.b   $5(a4)                          ; 10D6A
        move.b  #$1,(a4)                        ; 10D6E
        clr.b   $1(a4)                          ; 10D72
        move.b  O_Type(a5),$1a(a4)              ; 10D76
        move.b  #$1,$2(a4)                      ; 10D7C
        move.l  a3,$28(a4)                      ; 10D82  link back to the previous segment
        movea.l a4,a3                           ; 10D86
        subq.w  #$1,d6                          ; 10D88
        bne.b   l_10D18                         ; 10D8A
        lea.l   g_Enemies(a6),a4                ; 10D8C
        moveq   #$27,d5                         ; 10D90
l_10D92:
        tst.b   (a4)                            ; 10D92
        beq.b   l_10DA0                         ; 10D94
        lea.l   $3c(a4),a4                      ; 10D96
        dbra    d5,l_10D92                      ; 10D9A
        bra.b   Dragon_BuildExit                ; 10D9E
l_10DA0:
        move.l  a4,$24(a3)                      ; 10DA0
        move.l  a3,$28(a4)                      ; 10DA4
        clr.l   $24(a4)                         ; 10DA8
        move.b  O_Type(a5),$1a(a4)              ; 10DAC
        move.b  #$2,$2(a4)                      ; 10DB2
        clr.b   $3(a4)                          ; 10DB8
        clr.b   $4(a4)                          ; 10DBC
        clr.b   $5(a4)                          ; 10DC0
        move.b  #$1,(a4)                        ; 10DC4
        clr.b   $1(a4)                          ; 10DC8
        move.w  $6(a3),d0                       ; 10DCC
        addi.w  #$c,d0                          ; 10DD0
        move.w  d0,$6(a4)                       ; 10DD4
        move.w  $a(a3),d0                       ; 10DD8
        addq.w  #$2,d0                          ; 10DDC
        move.w  d0,$a(a4)                       ; 10DDE
        addq.b  #$1,O_Step(a5)                  ; 10DE2  next step
Dragon_BuildExit:
        rts                                     ; 10DE6

;---------------------------------------------------------------------------
; Drg_Index: 8 for the head down to 0 for the tail
;---------------------------------------------------------------------------
Dragon_NumberChain:
        movea.l a5,a4                           ; 10DE8
        moveq   #$8,d0                          ; 10DEA
        moveq   #$8,d6                          ; 10DEC
l_10DEE:
        move.b  d0,$37(a4)                      ; 10DEE
        subq.b  #$1,d0                          ; 10DF2
        movea.l $24(a4),a4                      ; 10DF4
        dbra    d6,l_10DEE                      ; 10DF8
        move.b  #ST_ACTIVE,O_State(a5)          ; 10DFC
        clr.b   O_Step(a5)                      ; 10E02
        clr.b   O_Step2(a5)                     ; 10E06
        rts                                     ; 10E0A

;---------------------------------------------------------------------------
; Body segment: size 1, 1 HP, Drg_Part 1
;---------------------------------------------------------------------------
Dragon_InitBody:
        clr.b   O_Dir(a5)                       ; 10E0C
        move.w  O_X(a5),d0                      ; 10E10
        sub.w   g_ArthurX(a6),d0                ; 10E14
        blt.b   l_10E20                         ; 10E18
        move.b  #$8,O_Dir(a5)                   ; 10E1A
l_10E20:
        move.b  #$1,O_Size(a5)                  ; 10E20
        lea.l   Dragon_AnimBody(pc),a0          ; 10E26
        bsr.w   SetAnim                         ; 10E2A  start animation
        lea.l   DragonMoveTable(pc),a0          ; 10E2E
        move.l  a0,O_MoveTable(a5)              ; 10E32
        clr.b   Drg_NewDir(a5)                  ; 10E36
        clr.b   Drg_Delay(a5)                   ; 10E3A
        clr.b   Drg_Pending(a5)                 ; 10E3E
        clr.b   Drg_Frozen(a5)                  ; 10E42
        clr.b   Drg_Firing(a5)                  ; 10E46
        move.b  #$1,O_HP(a5)                    ; 10E4A
        move.b  #$1,Drg_Part(a5)                ; 10E50
        move.b  #ST_ACTIVE,O_State(a5)          ; 10E56
        clr.b   O_Step(a5)                      ; 10E5C
        clr.b   O_Step2(a5)                     ; 10E60
        rts                                     ; 10E64

;---------------------------------------------------------------------------
; Tail: size 0, 1 HP, Drg_Part 2
;---------------------------------------------------------------------------
Dragon_InitTail:
        clr.b   O_Dir(a5)                       ; 10E66
        move.w  O_X(a5),d0                      ; 10E6A
        sub.w   g_ArthurX(a6),d0                ; 10E6E
        blt.b   l_10E7A                         ; 10E72
        move.b  #$8,O_Dir(a5)                   ; 10E74
l_10E7A:
        move.b  #$0,O_Size(a5)                  ; 10E7A
        lea.l   Dragon_AnimTail(pc),a0          ; 10E80
        bsr.w   SetAnim                         ; 10E84  start animation
        lea.l   DragonMoveTable(pc),a0          ; 10E88
        move.l  a0,O_MoveTable(a5)              ; 10E8C
        clr.b   Drg_NewDir(a5)                  ; 10E90
        clr.b   Drg_Delay(a5)                   ; 10E94
        clr.b   Drg_Pending(a5)                 ; 10E98
        clr.b   Drg_Frozen(a5)                  ; 10E9C
        clr.b   Drg_Firing(a5)                  ; 10EA0
        move.b  #$1,O_HP(a5)                    ; 10EA4
        move.b  #$2,Drg_Part(a5)                ; 10EAA
        move.b  #ST_ACTIVE,O_State(a5)          ; 10EB0
        clr.b   O_Step(a5)                      ; 10EB6
        clr.b   O_Step2(a5)                     ; 10EBA
        rts                                     ; 10EBE

;---------------------------------------------------------------------------
; DragonEntrancePath - (frames, direction) steps flown on arrival (DSTEP; directions as
; DragonMoveTable: 0 right, 4 down, 8 left, 12 up), ended by a zero word. Then DragonPatrolPath.
;---------------------------------------------------------------------------
DragonEntrancePath:
	DSTEP	10,9	; WNW
	DSTEP	10,15	; ENE
	DSTEP	10,0	; E
	DSTEP	10,1	; ESE
	DSTEP	10,7	; WSW
	DSTEP	10,8	; W
	dc.w	0		; end

;---------------------------------------------------------------------------
; 16-way (dx, dy) at 2 px/frame (8.8), 0 = right, 4 = down
;---------------------------------------------------------------------------
DragonMoveTable:
	dc.b	$02,$00,$00,$00,$01,$D9,$FF,$3D,$01,$6A,$FE,$96,$00,$C3,$FE,$27
	dc.b	$00,$00,$FE,$00,$FF,$3D,$FE,$27,$FE,$96,$FE,$96,$FE,$27,$FF,$3D
	dc.b	$FE,$00,$00,$00,$FE,$27,$00,$C3,$FE,$96,$01,$6A,$FF,$3D,$01,$D9
	dc.b	$00,$00,$02,$00,$00,$C3,$01,$D9,$01,$6A,$01,$6A,$01,$D9,$00,$C3

;---------------------------------------------------------------------------
; State 1: head or segment; then remove it when far off screen (not on levels 2-3)
;---------------------------------------------------------------------------
Dragon_Active:
        tst.b   Drg_Part(a5)                    ; 10F0E
        bne.b   l_10F18                         ; 10F12
        bsr.b   Dragon_Head                     ; 10F14
        bra.b   l_10F1C                         ; 10F16
l_10F18:
        bsr.w   Dragon_Segment                  ; 10F18
l_10F1C:
        cmpi.w  #$2,g_Level(a6)                 ; 10F1C  levels 2 and 3: never removed
        beq.b   l_10F5E                         ; 10F22
        cmpi.w  #$3,g_Level(a6)                 ; 10F24
        beq.b   l_10F5E                         ; 10F2A
        move.w  O_X(a5),d0                      ; 10F2C
        sub.w   g_CameraX(a6),d0                ; 10F30
        addi.w  #$180,d0                        ; 10F34
        cmp.w   #$400,d0                        ; 10F38
        bhi.b   l_10F50                         ; 10F3C
        move.w  O_Y(a5),d0                      ; 10F3E
        sub.w   g_CameraY(a6),d0                ; 10F42
        addi.w  #$180,d0                        ; 10F46
        cmp.w   #$400,d0                        ; 10F4A
        bls.b   l_10F5E                         ; 10F4E
l_10F50:
        move.b  #ST_REMOVE,O_State(a5)          ; 10F50
        clr.b   O_Step(a5)                      ; 10F56
        clr.b   O_Step2(a5)                     ; 10F5A
l_10F5E:
        rts                                     ; 10F5E

;---------------------------------------------------------------------------
; O_Step 0 = entrance (O_Step2 0 start, 1 path, 2 pick wait, 3 wait to be seen,
; 4 wait for Arthur), O_Step 1 = attack.
;---------------------------------------------------------------------------
Dragon_Head:
        tst.b   O_Step(a5)                      ; 10F60
        bne.w   Dragon_Attack                   ; 10F64
        move.b  O_Step2(a5),d0                  ; 10F68
        add.w   d0,d0                           ; 10F6C
        add.w   d0,d0                           ; 10F6E
        jmp     Dragon_Head_Jumps(pc,d0.w)      ; 10F70
Dragon_Head_Jumps:
        bra.w   Dragon_EntranceStart            ; 10F74
        bra.w   Dragon_EntrancePath             ; 10F78
        bra.w   Dragon_PickWait                 ; 10F7C
        bra.w   Dragon_WaitSeen                 ; 10F80
        bra.w   Dragon_WaitArthur               ; 10F84
Dragon_EntranceStart:
        movea.l Drg_Next(a5),a4                 ; 10F88
        move.b  Drg_PathTime(a5),$39(a4)        ; 10F8C
        move.b  O_Dir(a5),$38(a4)               ; 10F92
        move.b  #$1,$34(a4)                     ; 10F98
        addq.b  #$1,O_Step2(a5)                 ; 10F9E
        rts                                     ; 10FA2

;---------------------------------------------------------------------------
; Follow the entrance path, handing each new direction to the next segment.
; At its end: freeze every segment and load the patrol path.
;---------------------------------------------------------------------------
Dragon_EntrancePath:
        subq.b  #$1,Drg_PathTime(a5)            ; 10FA4
        bne.b   l_10FDA                         ; 10FA8
        movea.l Drg_PathPtr(a5),a0              ; 10FAA
        move.b  (a0)+,d0                        ; 10FAE
        move.b  (a0)+,d1                        ; 10FB0
        tst.w   -$2(a0)                         ; 10FB2
        beq.b   l_10FDC                         ; 10FB6
        move.b  d0,Drg_PathTime(a5)             ; 10FB8
        move.b  d1,O_Dir(a5)                    ; 10FBC
        move.l  a0,Drg_PathPtr(a5)              ; 10FC0
        movea.l Drg_Next(a5),a4                 ; 10FC4
        move.b  d0,$39(a4)                      ; 10FC8
        move.b  d1,$38(a4)                      ; 10FCC
        move.b  #$1,$34(a4)                     ; 10FD0
        bra.w   ApplyMoveTable                  ; 10FD6
l_10FDA:
        rts                                     ; 10FDA
l_10FDC:
        moveq   #$8,d6                          ; 10FDC
        movea.l a5,a4                           ; 10FDE
l_10FE0:
        move.b  #$1,$35(a4)                     ; 10FE0
        movea.l $24(a4),a4                      ; 10FE6
        dbra    d6,l_10FE0                      ; 10FEA
        lea.l   DragonPatrolPath(pc),a0         ; 10FEE  patrol path
        adda.w  (a0),a0                         ; 10FF2
        move.b  (a0)+,Drg_PathTime(a5)          ; 10FF4
        move.b  (a0)+,O_Dir(a5)                 ; 10FF8
        move.l  a0,Drg_PathPtr(a5)              ; 10FFC
        movea.l Drg_Next(a5),a4                 ; 11000
        move.b  Drg_PathTime(a5),$39(a4)        ; 11004
        move.b  O_Dir(a5),$38(a4)               ; 1100A
        move.b  #$1,$34(a4)                     ; 11010
        addq.b  #$1,O_Step2(a5)                 ; 11016
        rts                                     ; 1101A

;---------------------------------------------------------------------------
; x 16 frames: 3, 2, 3, 2 (level 5: 5, 2, 5, 4)
;---------------------------------------------------------------------------
DragonWaitTimes:
	dc.b	$03,$02,$03,$02

;---------------------------------------------------------------------------
; Dragon wait times on level 5 (DragonWaitTimes elsewhere)
;---------------------------------------------------------------------------
DragonWaitTimesL5:
	dc.b	$05,$02,$05,$04
Dragon_PickWait:
        lea.l   DragonWaitTimesL5(pc),a0        ; 11024
        cmpi.w  #$5,g_Level(a6)                 ; 11028
        beq.b   l_11034                         ; 1102E
        lea.l   DragonWaitTimes(pc),a0          ; 11030
l_11034:
        move.w  g_GameFrame(a6),d0              ; 11034
        add.w   d7,d0                           ; 11038
        andi.w  #$3,d0                          ; 1103A
        adda.w  d0,a0                           ; 1103E
        move.b  (a0),Drg_Wait(a5)               ; 11040
        addq.b  #$1,O_Step2(a5)                 ; 11044
        rts                                     ; 11048
Dragon_WaitSeen:
        tst.b   O_OnScreen(a5)                  ; 1104A
        beq.b   l_11054                         ; 1104E
        addq.b  #$1,O_Step2(a5)                 ; 11050
l_11054:
        rts                                     ; 11054

;---------------------------------------------------------------------------
; Count down Drg_Wait (every 16 frames) while Arthur is no more than 32 px below;
; then unfreeze the chain and attack
;---------------------------------------------------------------------------
Dragon_WaitArthur:
        move.w  g_ArthurY(a6),d0                ; 11056
        addi.w  #$20,d0                         ; 1105A
        sub.w   O_Y(a5),d0                      ; 1105E  Arthur more than 32 px below it: wait
        bmi.b   l_11098                         ; 11062
        move.w  g_GameFrame(a6),d0              ; 11064
        addq.w  #$1,d0                          ; 11068
        andi.w  #$f,d0                          ; 1106A
        bne.b   l_11098                         ; 1106E
        subq.b  #$1,Drg_Wait(a5)                ; 11070
        bne.b   l_11098                         ; 11074
        move.b  #$1,O_Step(a5)                  ; 11076
        clr.b   O_Step2(a5)                     ; 1107C
        addq.b  #$1,g_BigEnemyCount(a6)         ; 11080  one more big enemy engaged
        moveq   #$8,d6                          ; 11084
        movea.l a5,a4                           ; 11086
l_11088:
        clr.b   $35(a4)                         ; 11088
        move.l  $24(a4),d0                      ; 1108C
        beq.b   l_11098                         ; 11090
        movea.l d0,a4                           ; 11092
        dbra    d6,l_11088                      ; 11094
l_11098:
        rts                                     ; 11098

;---------------------------------------------------------------------------
; Flap every 128 frames, steer, breathe fire, move
;---------------------------------------------------------------------------
Dragon_Attack:
        move.w  g_GameFrame(a6),d0              ; 1109A
        addq.w  #$1,d0                          ; 1109E
        andi.w  #$7f,d0                         ; 110A0
        bne.b   l_110C4                         ; 110A4
        lea.l   Dragon_AnimFlap(pc),a0          ; 110A6
        tst.b   Drg_Facing(a5)                  ; 110AA
        beq.b   l_110B2                         ; 110AE
        addq.l  #$2,a0                          ; 110B0
l_110B2:
        adda.w  (a0),a0                         ; 110B2
        move.l  a0,O_Anim(a5)                   ; 110B4
        move.b  #$a,O_AnimTimer(a5)             ; 110B8
        moveq   #SFX_STOMP,d0                   ; 110BE  [1MB] effect 24: the dragon attacks  << 1MB only: 2 instruction(s) not in the 512K build >>
        bsr.w   PlaySfx                         ; 110C0  [1MB] 
l_110C4:
        bsr.w   Animate                         ; 110C4
        bsr.w   Random                          ; 110C8  random number
        move.b  d0,d5                           ; 110CC
        bsr.b   Dragon_Steer                    ; 110CE
        bsr.w   Dragon_Breathe                  ; 110D0
        bra.w   ApplyMoveTable                  ; 110D4

;---------------------------------------------------------------------------
; When the path step ends: maybe dive at Arthur, turn round, or climb / descend
; towards his height (level 5: stay near Drg_HomeY)
;---------------------------------------------------------------------------
Dragon_Steer:
        subq.b  #$1,Drg_PathTime(a5)            ; 110D8
        beq.b   l_110E0                         ; 110DC
        rts                                     ; 110DE
l_110E0:
        cmpi.w  #$5,g_Level(a6)                 ; 110E0  level 5: never dives
        beq.b   Dragon_TurnCheck                ; 110E6
        moveq   #$f,d0                          ; 110E8  3 in 16 chance to dive
        and.b   d5,d0                           ; 110EA
        cmp.b   Drg_Aggro(a5),d0                ; 110EC
        bhi.b   Dragon_TurnCheck                ; 110F0
        tst.b   Drg_Facing(a5)                  ; 110F2
        beq.b   l_11130                         ; 110F6
        move.w  O_X(a5),d0                      ; 110F8  facing left: Arthur must be 24+ px to the left
        sub.w   g_ArthurX(a6),d0                ; 110FC
        subi.w  #$18,d0                         ; 11100
        bmi.b   Dragon_TurnCheck                ; 11104

;---------------------------------------------------------------------------
; Head for Arthur (not straight down) for 40 frames, 18 if it is in the bottom 96 px of the screen
;---------------------------------------------------------------------------
Dragon_DiveAtArthur:
        bsr.w   DirectionToArthur               ; 11106  direction towards Arthur
        cmp.b   #$4,d0                          ; 1110A  not straight down
        beq.b   Dragon_TurnCheck                ; 1110E
        move.b  d0,d4                           ; 11110
        move.w  g_CameraY(a6),d3                ; 11112
        addi.w  #$60,d3                         ; 11116
        moveq   #$28,d0                         ; 1111A
        move.w  O_Y(a5),d1                      ; 1111C
        cmp.w   d3,d1                           ; 11120
        bhi.b   l_11126                         ; 11122
        moveq   #$12,d0                         ; 11124
l_11126:
        move.b  d4,d1                           ; 11126
        movea.l Drg_PathPtr(a5),a0              ; 11128
        bra.w   Dragon_SetPathStep              ; 1112C
l_11130:
        move.w  g_ArthurX(a6),d0                ; 11130
        sub.w   O_X(a5),d0                      ; 11134
        subi.w  #$18,d0                         ; 11138
        bpl.b   Dragon_DiveAtArthur             ; 1113C
Dragon_TurnCheck:
        move.w  O_X(a5),d0                      ; 1113E
        cmp.w   g_ArthurX(a6),d0                ; 11142
        bhi.b   l_11152                         ; 11146
        tst.b   Drg_Facing(a5)                  ; 11148
        bne.b   l_1115A                         ; 1114C
        bra.w   Dragon_SeekHeight               ; 1114E
l_11152:
        tst.b   Drg_Facing(a5)                  ; 11152
        bne.w   Dragon_SeekHeight               ; 11156
l_1115A:
        move.w  g_LevelWidth(a6),d0             ; 1115A  past the right end of the level, or 94+ px past Arthur: turn
        addi.w  #$100,d0                        ; 1115E
        cmp.w   O_X(a5),d0                      ; 11162
        bls.b   Dragon_Turn                     ; 11166
        move.w  O_X(a5),d0                      ; 11168
        sub.w   g_ArthurX(a6),d0                ; 1116C
        addi.w  #$5e,d0                         ; 11170
        cmp.w   #$bc,d0                         ; 11174
        bcs.w   Dragon_SeekHeight               ; 11178

;---------------------------------------------------------------------------
; Turn round: path for the upper or lower half of the screen, flip Drg_Facing
;---------------------------------------------------------------------------
Dragon_Turn:
        move.w  g_CameraY(a6),d3                ; 1117C
        addi.w  #$80,d3                         ; 11180
        moveq   #$0,d0                          ; 11184
        move.w  O_Y(a5),d1                      ; 11186
        cmp.w   d3,d1                           ; 1118A
        bcs.b   l_11190                         ; 1118C
        moveq   #$2,d0                          ; 1118E
l_11190:
        lea.l   DragonTurnRight(pc),a0          ; 11190
        clr.w   d1                              ; 11194
        move.b  Drg_Facing(a5),d1               ; 11196
        beq.b   l_111A0                         ; 1119A
        lea.l   DragonTurnLeft(pc),a0           ; 1119C
l_111A0:
        adda.w  d0,a0                           ; 111A0
        adda.w  (a0),a0                         ; 111A2
        move.l  a0,Drg_PathPtr(a5)              ; 111A4
        eori.b  #$1,d1                          ; 111A8
        move.b  d1,Drg_Facing(a5)               ; 111AC
        add.w   d1,d1                           ; 111B0
        lea.l   Dragon_AnimFly(pc),a0           ; 111B2
        adda.w  d1,a0                           ; 111B6
        adda.w  (a0),a0                         ; 111B8
        bsr.w   SetAnim                         ; 111BA  start animation

;---------------------------------------------------------------------------
; Next (frames, direction) pair; bit 7 = loop (offset follows)
;---------------------------------------------------------------------------
Dragon_NextPathStep:
        movea.l Drg_PathPtr(a5),a0              ; 111BE
        move.b  (a0)+,d0                        ; 111C2
        move.b  (a0)+,d1                        ; 111C4
        tst.b   d0                              ; 111C6
        bpl.b   Dragon_SetPathStep              ; 111C8
        andi.b  #$7f,d0                         ; 111CA
        adda.w  (a0),a0                         ; 111CE

;---------------------------------------------------------------------------
; Take a (frames, direction) step and hand the direction to the next segment
; (10-frame delay)
;---------------------------------------------------------------------------
Dragon_SetPathStep:
        move.b  d0,Drg_PathTime(a5)             ; 111D0
        move.b  d1,O_Dir(a5)                    ; 111D4
        move.l  a0,Drg_PathPtr(a5)              ; 111D8
        move.l  Drg_Next(a5),d0                 ; 111DC
        beq.b   l_111FE                         ; 111E0
        movea.l d0,a4                           ; 111E2
        move.b  O_Dir(a5),d0                    ; 111E4
        cmp.b   $12(a4),d0                      ; 111E8
        beq.b   l_111FE                         ; 111EC
        move.b  d0,$38(a4)                      ; 111EE
        move.b  #$a,$39(a4)                     ; 111F2
        move.b  #$1,$34(a4)                     ; 111F8
l_111FE:
        rts                                     ; 111FE

;---------------------------------------------------------------------------
; 160+ px above Arthur: descend; below him: climb; else carry on (36-frame steps)
;---------------------------------------------------------------------------
Dragon_SeekHeight:
        cmpi.w  #$5,g_Level(a6)                 ; 11200
        beq.b   l_11234                         ; 11206
        lea.l   DragonClimb(pc),a0              ; 11208
        move.w  O_Y(a5),d0                      ; 1120C
        sub.w   g_ArthurY(a6),d0                ; 11210
        bmi.b   l_11220                         ; 11214
        cmp.w   #$a0,d0                         ; 11216  more than 160 px above him?
        bcs.b   Dragon_NextPathStep             ; 1121A
        lea.l   DragonDescend(pc),a0            ; 1121C
l_11220:
        move.b  Drg_Facing(a5),d0               ; 11220
        ext.w   d0                              ; 11224
        add.w   d0,d0                           ; 11226
        adda.w  d0,a0                           ; 11228
        move.b  (a0)+,d0                        ; 1122A
        move.b  (a0)+,d1                        ; 1122C
        movea.l Drg_PathPtr(a5),a0              ; 1122E
        bra.b   Dragon_SetPathStep              ; 11232
l_11234:
        move.w  Drg_HomeY(a5),d0                ; 11234  level 5: more than 256 px from its start height, or 94+ px from Arthur: head back
        sub.w   g_ArthurY(a6),d0                ; 11238
        addi.w  #$100,d0                        ; 1123C
        cmp.w   #$200,d0                        ; 11240
        bhi.b   l_1126E                         ; 11244
        move.w  O_Y(a5),d0                      ; 11246
        sub.w   g_ArthurY(a6),d0                ; 1124A
        addi.w  #$5e,d0                         ; 1124E
        cmp.w   #$bc,d0                         ; 11252
        bcs.w   Dragon_NextPathStep             ; 11256
        lea.l   DragonClimb(pc),a0              ; 1125A
        move.w  O_Y(a5),d0                      ; 1125E
        cmp.w   g_ArthurY(a6),d0                ; 11262
        bcs.b   l_1126C                         ; 11266
        lea.l   DragonDescend(pc),a0            ; 11268
l_1126C:
        bra.b   l_11220                         ; 1126C
l_1126E:
        lea.l   DragonClimb(pc),a0              ; 1126E
        move.w  O_Y(a5),d0                      ; 11272
        cmp.w   g_ArthurY(a6),d0                ; 11276
        bhi.b   l_11280                         ; 1127A
        lea.l   DragonDescend(pc),a0            ; 1127C
l_11280:
        bra.b   l_11220                         ; 11280

;---------------------------------------------------------------------------
; DragonDescend / DragonClimb - one (frames, direction) step for each facing (right, left),
; used by Dragon_SeekHeight to move towards Arthur's height.
;---------------------------------------------------------------------------
DragonDescend:
	DSTEP	36,2	; facing right: SE
	DSTEP	36,6	; facing left: SW
DragonClimb:
	DSTEP	36,14	; facing right: NE
	DSTEP	36,10	; facing left: NW

;---------------------------------------------------------------------------
; Body / tail: unless frozen, take the pending direction and move
;---------------------------------------------------------------------------
Dragon_Segment:
        tst.b   Drg_Frozen(a5)                  ; 1128A
        bne.b   l_112D0                         ; 1128E
        bsr.b   Dragon_PassDirection            ; 11290
        bra.w   ApplyMoveTable                  ; 11292

;---------------------------------------------------------------------------
; When Drg_Delay runs out take Drg_NewDir and hand it to the next segment
; (6 frames later, 7 for the tail)
;---------------------------------------------------------------------------
Dragon_PassDirection:
        tst.b   Drg_Pending(a5)                 ; 11296
        beq.b   l_112D0                         ; 1129A
        subq.b  #$1,Drg_Delay(a5)               ; 1129C
        bne.b   l_112D0                         ; 112A0
        move.b  Drg_NewDir(a5),O_Dir(a5)        ; 112A2
        clr.b   Drg_Pending(a5)                 ; 112A8
        move.l  Drg_Next(a5),d0                 ; 112AC
        beq.b   l_112D0                         ; 112B0
        movea.l d0,a4                           ; 112B2
        move.b  O_Dir(a5),$38(a4)               ; 112B4
        moveq   #$6,d0                          ; 112BA
        cmpi.b  #$2,$36(a4)                     ; 112BC
        bne.b   l_112C6                         ; 112C2
        moveq   #$7,d0                          ; 112C4
l_112C6:
        move.b  d0,$39(a4)                      ; 112C6
        move.b  #$1,$34(a4)                     ; 112CA
l_112D0:
        rts                                     ; 112D0

;---------------------------------------------------------------------------
; Every 32 frames, if Arthur is within 72 px vertically: fire (enemy shot type 9)
; from the mouth, mouth open for 10 frames
