Dragon_Breathe:
        tst.b   Drg_Firing(a5)                  ; 112D2
        bne.w   l_11366                         ; 112D6
        move.w  O_Y(a5),d0                      ; 112DA
        sub.w   g_ArthurY(a6),d0                ; 112DE
        addi.w  #$48,d0                         ; 112E2
        cmp.w   #$90,d0                         ; 112E6
        bhi.w   l_11386                         ; 112EA
        move.w  g_GameFrame(a6),d0              ; 112EE
        addq.w  #$1,d0                          ; 112F2
        andi.w  #$1f,d0                         ; 112F4
        bne.w   l_11386                         ; 112F8
        moveq   #$3,d0                          ; 112FC  d0 not used by FindFreeEnemyShot
        and.b   g_RandSeed+1(a6),d0             ; 112FE
        bsr.w   FindFreeEnemyShot               ; 11302  find a free enemy-projectile slot (fires a shot)
        bne.b   l_11386                         ; 11306
        lea.l   Dragon_AnimFire(pc),a0          ; 11308
        tst.b   Drg_Facing(a5)                  ; 1130C
        beq.b   l_11314                         ; 11310
        addq.l  #$2,a0                          ; 11312
l_11314:
