        move.l  a0,O_Anim(a5)                   ; 11316
        bsr.w   SetAnim                         ; 1131A  start animation
        move.b  #$a,Drg_Pending(a5)             ; 1131E
        addq.b  #$1,Drg_Firing(a5)              ; 11324
        move.b  Drg_Facing(a5),$12(a4)          ; 11328  shot direction = facing
