        clr.b   Drg_Firing(a5)                  ; 1136C
        lea.l   Dragon_AnimFly(pc),a0           ; 11370
        tst.b   Drg_Facing(a5)                  ; 11374
        beq.b   l_1137C                         ; 11378
        addq.l  #$2,a0                          ; 1137A
l_1137C:
