;---------------------------------------------------------------------------
; DragonPatrolPath - an offset to the patrol taken after the entrance. Two endless patrols,
; (frames, direction) steps with a loop (DLOOP): DragonPatrolLeftward weaves to the left and
; DragonPatrolRightward to the right. The turn tables below (Dragon_Turn, by facing, then upper / lower half of the
; screen) curl round and then join the patrol in the new direction.
;---------------------------------------------------------------------------
DragonPatrolPath:
	dc.w	DragonPatrolLeftward-*
DragonPatrolLeftward:
	DSTEP	10,10	; NW
	DSTEP	10,11	; NNW
	DSTEP	10,10	; NW
	DSTEP	10,11	; NNW
	DSTEP	10,10	; NW
	DSTEP	10,9	; WNW
	DSTEP	10,8	; W
	DSTEP	10,7	; WSW
	DSTEP	10,6	; SW
	DSTEP	10,5	; SSW
	DSTEP	10,8	; W
	DSTEP	10,6	; SW
	DSTEP	10,10	; NW
	DSTEP	10,6	; SW
	DSTEP	10,10	; NW
	DSTEP	10,6	; SW
	DSTEP	10,10	; NW
	DSTEP	10,6	; SW
	DSTEP	10,6	; SW
	DSTEP	10,6	; SW
	DSTEP	10,9	; WNW
	DSTEP	10,10	; NW
	DSTEP	10,11	; NNW
	DSTEP	10,5	; SSW
	DSTEP	10,5	; SSW
	DSTEP	10,6	; SW
	DSTEP	10,6	; SW
	DSTEP	10,5	; SSW
	DSTEP	10,8	; W
	DSTEP	10,11	; NNW
	DSTEP	10,10	; NW
	DSTEP	10,10	; NW
	DSTEP	10,7	; WSW
	DSTEP	10,6	; SW
	DSTEP	10,5	; SSW
	DSTEP	10,7	; WSW
	DSTEP	10,11	; NNW
	DSTEP	10,8	; W
	DSTEP	10,6	; SW
	DSTEP	10,5	; SSW
	DLOOP	10,6,DragonPatrolLeftward	; SW, then loop
DragonPatrolRightward:
	DSTEP	10,0	; E
	DSTEP	10,13	; NNE
	DSTEP	10,14	; NE
	DSTEP	10,15	; ENE
	DSTEP	10,0	; E
	DSTEP	10,15	; ENE
	DSTEP	10,1	; ESE
	DSTEP	10,2	; SE
	DSTEP	10,2	; SE
	DSTEP	10,2	; SE
	DSTEP	10,3	; SSE
	DSTEP	10,0	; E
	DSTEP	10,13	; NNE
	DSTEP	10,14	; NE
	DSTEP	10,15	; ENE
	DSTEP	10,1	; ESE
	DSTEP	10,2	; SE
	DSTEP	10,1	; ESE
	DSTEP	10,2	; SE
	DSTEP	10,3	; SSE
	DSTEP	10,2	; SE
	DSTEP	10,1	; ESE
	DSTEP	10,13	; NNE
	DSTEP	10,15	; ENE
	DSTEP	10,14	; NE
	DSTEP	10,15	; ENE
	DSTEP	10,0	; E
	DSTEP	10,1	; ESE
	DSTEP	10,2	; SE
	DSTEP	10,3	; SSE
	DSTEP	10,2	; SE
	DSTEP	10,1	; ESE
	DSTEP	10,0	; E
	DSTEP	10,1	; ESE
	DSTEP	10,0	; E
	DSTEP	10,15	; ENE
	DSTEP	10,14	; NE
	DSTEP	10,13	; NNE
	DSTEP	10,15	; ENE
	DSTEP	10,13	; NNE
	DLOOP	10,2,DragonPatrolRightward	; SE, then loop

;---------------------------------------------------------------------------
; DragonTurnRight - turn paths when facing right: upper / lower half of the screen.
;---------------------------------------------------------------------------
DragonTurnRight:
	dc.w	DragonTurnRightUpper-*	; in the upper half of the screen
	dc.w	DragonTurnRightLower-*	; in the lower half of the screen
DragonTurnRightUpper:
	DSTEP	10,13	; NNE
	DSTEP	10,12	; N
	DSTEP	10,11	; NNW
	DSTEP	10,10	; NW
	DLOOP	10,9,DragonPatrolLeftward	; WNW, then loop
DragonTurnRightLower:
	DSTEP	10,3	; SSE
	DSTEP	10,4	; S
	DSTEP	10,5	; SSW
	DSTEP	10,6	; SW
	DSTEP	10,7	; WSW
	DLOOP	10,7,DragonPatrolLeftward	; WSW, then loop

;---------------------------------------------------------------------------
; DragonTurnLeft - turn paths when facing left: upper / lower half of the screen.
;---------------------------------------------------------------------------
DragonTurnLeft:
	dc.w	DragonTurnLeftUpper-*	; in the upper half of the screen
	dc.w	DragonTurnLeftLower-*	; in the lower half of the screen
DragonTurnLeftUpper:
	DSTEP	10,11	; NNW
	DSTEP	10,12	; N
	DSTEP	10,13	; NNE
	DSTEP	10,14	; NE
	DSTEP	10,15	; ENE
	DLOOP	10,0,DragonPatrolRightward	; E, then loop
DragonTurnLeftLower:
	DSTEP	10,5	; SSW
	DSTEP	10,4	; S
	DSTEP	10,3	; SSE
	DSTEP	10,2	; SE
	DLOOP	10,1,DragonPatrolRightward	; ESE, then loop

;---------------------------------------------------------------------------
; State 2. O_Step: 0 decide, 1 head: sound 12, 2 explode, 3 wait then +1000,
; 4 segment: sound 20, 5 explode, 6 wait
;---------------------------------------------------------------------------
Dragon_Dying:
        move.b  O_Step(a5),d0                   ; 1146E
        add.w   d0,d0                           ; 11472
        add.w   d0,d0                           ; 11474
        jmp     Dragon_Dying_Jumps(pc,d0.w)     ; 11476
Dragon_Dying_Jumps:
        bra.w   Dragon_HitSegment               ; 1147A
        bra.w   Dragon_HeadDies                 ; 1147E
        bra.w   EnemyExplode                    ; 11482
        bra.w   Dragon_HeadWait                 ; 11486
        bra.w   Dragon_SegmentDies              ; 1148A
        bra.w   EnemyBurst                      ; 1148E
        bra.w   Dragon_SegmentWait              ; 11492

;---------------------------------------------------------------------------
; Head: every segment dies with it. Tail: unlink it. Body segment: it lives on and
; the tail dies instead.
;---------------------------------------------------------------------------
Dragon_HitSegment:
        movea.l a5,a4                           ; 11496
        move.b  $37(a4),d0                      ; 11498
        beq.b   l_114CA                         ; 1149C
        cmp.b   #$8,d0                          ; 1149E  the head?
        beq.b   l_114EC                         ; 114A2
l_114A4:
        movea.l $24(a4),a4                      ; 114A4  a body segment: find the tail
        tst.b   $37(a4)                         ; 114A8
        bne.b   l_114A4                         ; 114AC
        addq.b  #$1,(a4)                        ; 114AE  kill the tail instead (O_Active 2)
        move.b  #ST_ACTIVE,O_State(a5)          ; 114B0  and this segment carries on
        clr.b   O_Step(a5)                      ; 114B6
        move.b  #$1,(a5)                        ; 114BA
        clr.b   O_HP(a5)                        ; 114BE
        move.l  a4,-(a7)                        ; 114C2
        bsr.w   Dragon_Segment                  ; 114C4
        movea.l (a7)+,a4                        ; 114C8
l_114CA:
        movea.l $28(a4),a3                      ; 114CA  unlink the dying segment: the one before it becomes the tail
        cmpi.b  #$8,$37(a3)                     ; 114CE
        beq.b   l_114DA                         ; 114D4
        clr.b   $37(a3)                         ; 114D6
l_114DA:
        clr.l   $24(a3)                         ; 114DA
        move.b  #$2,$3(a4)                      ; 114DE  state 2, step 4: segment death
        move.b  #$4,$4(a4)                      ; 114E4
        rts                                     ; 114EA
l_114EC:
        move.l  $24(a4),d0                      ; 114EC
        beq.b   l_11508                         ; 114F0
l_114F2:
        movea.l d0,a3                           ; 114F2
        move.b  #$2,$3(a3)                      ; 114F4  every segment: state 2 step 4
        move.b  #$4,$4(a3)                      ; 114FA
        addq.b  #$1,(a3)                        ; 11500
        move.l  $24(a3),d0                      ; 11502
        bne.b   l_114F2                         ; 11506
l_11508:
        move.b  #$2,$3(a4)                      ; 11508
        move.b  #$1,$4(a4)                      ; 1150E
        rts                                     ; 11514
Dragon_HeadDies:
        moveq   #SFX_ENEMY_HIT,d0               ; 11516
        bsr.w   PlaySfx                         ; 11518  sound effect 12 (weapon/boss hit)
        move.b  #$1,Drg_HeadDead(a5)            ; 1151C
        move.b  #$3f,Drg_PathTime(a5)           ; 11522
        addq.b  #$1,O_Step(a5)                  ; 11528  next step
        clr.b   O_Step2(a5)                     ; 1152C
        rts                                     ; 11530
Dragon_HeadWait:
        subq.b  #$1,Drg_PathTime(a5)            ; 11532
        bne.b   l_11544                         ; 11536
        moveq   #PTS_1000,d0                    ; 11538
        bsr.w   AddScore                        ; 1153A  +1000 for the head
        move.b  #ST_REMOVE,O_State(a5)          ; 1153E
l_11544:
        rts                                     ; 11544
Dragon_SegmentDies:
        moveq   #SFX_ENEMY_DIE2,d0              ; 11546
        bsr.w   PlaySfx                         ; 11548  sound effect 20 (enemy event)
        clr.b   Drg_HeadDead(a5)                ; 1154C
        move.b  #$3f,Drg_PathTime(a5)           ; 11550
        addq.b  #$1,O_Step(a5)                  ; 11556  next step
        clr.b   O_Step2(a5)                     ; 1155A
        rts                                     ; 1155E
Dragon_SegmentWait:
        subq.b  #$1,Drg_PathTime(a5)            ; 11560
        bne.b   l_1156C                         ; 11564
        move.b  #ST_REMOVE,O_State(a5)          ; 11566
l_1156C:
        rts                                     ; 1156C

;---------------------------------------------------------------------------
; State 3: free the slot; if it was the head (not on level 5): BossKilled
;---------------------------------------------------------------------------
Dragon_Free:
        clr.b   (a5)                            ; 1156E  free this enemy slot
        tst.b   Drg_HeadDead(a5)                ; 11570  only the head counts for the boss
        beq.b   l_1158A                         ; 11574
        tst.b   g_BigEnemyCount(a6)             ; 11576
        beq.b   l_11580                         ; 1157A
        subq.b  #$1,g_BigEnemyCount(a6)         ; 1157C
l_11580:
        cmpi.w  #$5,g_Level(a6)                 ; 11580
        bne.w   BossKilled                      ; 11586
l_1158A:
        rts                                     ; 1158A
Dragon_AnimFly:
	dc.w	Dragon_AnimFly_0-*	; 0
	dc.w	Dragon_AnimFly_1-*	; 1
Dragon_AnimFlap:
	dc.w	Dragon_AnimFlap_0-*	; 0
	dc.w	Dragon_AnimFlap_1-*	; 1
Dragon_AnimFly_0:
	AF	$06,5
	AL	$07,5,Dragon_AnimFly_0
Dragon_AnimFly_1:
	AF	$02,5
	AL	$03,5,Dragon_AnimFly_1
Dragon_AnimFlap_0:
	AL	$08,10,Dragon_AnimFlap_0
Dragon_AnimFlap_1:
	AL	$04,10,Dragon_AnimFlap_1
Dragon_AnimFire:
	dc.w	Dragon_AnimFire_0-*	; 0
	dc.w	Dragon_AnimFire_1-*	; 1
Dragon_AnimFire_0:
	AF	$09,8
	AL	$08,8,Dragon_AnimFire_0
Dragon_AnimFire_1:
	AF	$05,8
	AL	$04,8,Dragon_AnimFire_1
Dragon_AnimBody:
	AL	$00,3,Dragon_AnimBody
Dragon_AnimTail:
	AL	$01,3,Dragon_AnimTail

;---------------------------------------------------------------------------
; === Astaroth (type 13, 10000 pts, 10 hits, cross only (final boss)) ===
; Seated final boss in the throne room: fires projectiles; can only be hurt by the cross, in a narrow band (see EnemyHitByShot); its last hit calls BossKilled -> Ending.
; Dispatches on O_State: 0 main behaviour, 1 type-specific second phase, 2 killed (set by EnemyHitByShot after scoring), 3 remove.
;
; Behaviour, as coded:
;   * Waits until on screen, then walks to and fro in a 128-pixel arena (camera X + 96
;     to + 224), at a random 0.18 or 0.41 px/frame, turning at the ends and after a
;     random 0-1023 frames, always facing Arthur.
;   * Fires enemy shot type 10 the way it faces, from a lower (Y-5) or upper (Y+12)
;     point, every 70-180 frames (AstarothShotGaps). While Arthur is within 80 px the shot
;     timer runs at a quarter of the speed and shots come from the lower point; further
;     away they come from whichever point was chosen last.
;   * A stand-and-fire phase (every 256-767 frames, faster shots from AstarothFastGaps)
;     is coded, but the branch that should keep it going is the wrong way round: the
;     phase ends in the same frame it starts.
;   * 10 hits, by the cross only (EnemyVulnerability).
;---------------------------------------------------------------------------
Enemy_Astaroth:
        move.b  O_State(a5),d0                  ; 115C0
        add.w   d0,d0                           ; 115C4
        add.w   d0,d0                           ; 115C6
        jmp     Enemy_Astaroth_Jumps(pc,d0.w)   ; 115C8
Enemy_Astaroth_Jumps:
        bra.w   Astaroth_Init                   ; 115CC
        bra.w   Astaroth_Active                 ; 115D0
        bra.w   Astaroth_Dying                  ; 115D4
        bra.w   Astaroth_Free                   ; 115D8

;---------------------------------------------------------------------------
; State 0: size 6, 10 HP, then wait to be on screen and fix the arena
;---------------------------------------------------------------------------
Astaroth_Init:
        tst.b   O_Step(a5)                      ; 115DC
        bne.b   Astaroth_Wake                   ; 115E0
        move.b  #$6,O_Size(a5)                  ; 115E2
        move.b  #$1,O_Dir(a5)                   ; 115E8
        move.b  #$1,Ast_Facing(a5)              ; 115EE
        clr.b   Ast_Turning(a5)                 ; 115F4
        clr.b   Ast_Standing(a5)                ; 115F8
        clr.b   Ast_HighShot(a5)                ; 115FC
        lea.l   AstarothMoveTables(pc),a0       ; 11600
        move.l  a0,O_MoveTable(a5)              ; 11604
        move.b  #$a,O_HP(a5)                    ; 11608
        bsr.w   Astaroth_NextStand              ; 1160E
        bsr.w   Astaroth_NextShotTime           ; 11612
        addq.b  #$1,O_Step(a5)                  ; 11616  next step
        rts                                     ; 1161A
Astaroth_Wake:
        tst.b   O_OnScreen(a5)                  ; 1161C
        beq.b   l_11642                         ; 11620
        move.w  g_CameraX(a6),d0                ; 11622  arena: camera X + 96 ... + 224
        addi.w  #$60,d0                         ; 11626
        move.w  d0,Ast_ArenaL(a5)               ; 1162A
        addi.w  #$80,d0                         ; 1162E
        move.w  d0,Ast_ArenaR(a5)               ; 11632
        addq.b  #ST_ACTIVE,O_State(a5)          ; 11636
        clr.b   O_Step(a5)                      ; 1163A
        clr.b   O_Step2(a5)                     ; 1163E
l_11642:
        rts                                     ; 11642

;---------------------------------------------------------------------------
; Walk with its move table; stop and turn at the arena ends
;---------------------------------------------------------------------------
Astaroth_Walk:
        move.w  d7,d0                           ; 11644
        add.w   g_GameFrame(a6),d0              ; 11646
        andi.w  #$1f,d0                         ; 1164A
        bne.b   l_11656                         ; 1164E  [1MB]   << changed from the 512K build ($116CE: bne.b $116d2) >>
        moveq   #SFX_THUD,d0                    ; 11650  [1MB]   << changed from the 512K build ($116D0: moveq #$c, d0) >>
        bsr.w   PlaySfx                         ; 11652  [1MB]   << changed from the 512K build ($116D2: bsr.w $ad7e) >>
l_11656:
        bsr.w   ApplyMoveTable                  ; 11656  [1MB] effect 9: footstep  << 1MB only: 1 instruction(s) not in the 512K build >>
        move.w  O_X(a5),d0                      ; 1165A
        cmp.w   Ast_ArenaL(a5),d0               ; 1165E
        bhi.b   l_11670                         ; 11662
        move.w  Ast_ArenaL(a5),O_X(a5)          ; 11664
        clr.b   O_Dir(a5)                       ; 1166A
        rts                                     ; 1166E
l_11670:
        cmp.w   Ast_ArenaR(a5),d0               ; 11670
        bcs.b   l_11682                         ; 11674
        move.w  Ast_ArenaR(a5),O_X(a5)          ; 11676
        move.b  #$1,O_Dir(a5)                   ; 1167C
l_11682:
        rts                                     ; 11682

;---------------------------------------------------------------------------
; State 1. O_Step 0 start a walk, 1 walk, 2 turn
;---------------------------------------------------------------------------
Astaroth_Active:
        move.b  O_Step(a5),d0                   ; 11684
        add.w   d0,d0                           ; 11688
        add.w   d0,d0                           ; 1168A
        jmp     Astaroth_Active_Jumps(pc,d0.w)  ; 1168C
Astaroth_Active_Jumps:
        bra.w   Astaroth_WalkStart              ; 11690
        bra.w   Astaroth_Walking                ; 11694
        bra.w   Astaroth_Turn                   ; 11698
Astaroth_WalkStart:
        bsr.w   Random                          ; 1169C  random number
        andi.b  #$3,d0                          ; 116A0
        move.b  d0,Ast_WalkTime(a5)             ; 116A4
        bsr.w   Random                          ; 116A8  random number
        move.b  d0,Ast_WalkTimeLo(a5)           ; 116AC
        clr.b   Ast_Turning(a5)                 ; 116B0
        bsr.w   Astaroth_SetAnim                ; 116B4
        addq.b  #$1,O_Step(a5)                  ; 116B8  next step
Astaroth_Walking:
        subq.w  #$1,Ast_WalkTime(a5)            ; 116BC
        beq.b   l_116D6                         ; 116C0
        bsr.b   Astaroth_Think                  ; 116C2
        tst.b   Ast_Standing(a5)                ; 116C4
        bne.b   l_116D2                         ; 116C8
        bsr.w   Astaroth_Walk                   ; 116CA
        bsr.w   Animate                         ; 116CE  animate
l_116D2:
        bra.w   CheckFarAway                    ; 116D2
l_116D6:
        bsr.w   Random                          ; 116D6  random number
        andi.b  #$2f,d0                         ; 116DA  143-190 frames
        addi.b  #$8f,d0                         ; 116DE
        move.b  d0,Ast_TurnWait(a5)             ; 116E2
        move.b  #$1,Ast_Turning(a5)             ; 116E6
        bsr.w   Astaroth_SetAnim                ; 116EC
        addq.b  #$1,O_Step(a5)                  ; 116F0  next step
        rts                                     ; 116F4

;---------------------------------------------------------------------------
; New random speed, turn round, walk again. (Ast_TurnWait is decremented once
; and only ends the step if it reaches 0, which it never does.)
;---------------------------------------------------------------------------
Astaroth_Turn:
        subq.b  #$1,Ast_TurnWait(a5)            ; 116F6
        beq.b   Astaroth_Think                  ; 116FA
        bsr.b   Astaroth_RandomSpeed            ; 116FC
        bchg    #$0,O_Dir(a5)                   ; 116FE  turn round
        clr.b   O_Step(a5)                      ; 11704
        rts                                     ; 11708
Astaroth_RandomSpeed:
        bsr.w   Random                          ; 1170A  random number
        andi.w  #$f,d0                          ; 1170E
        move.b  AstarothSpeedPick(pc,d0.w),d0   ; 11712
        lea.l   AstarothMoveTables(pc,d0.w),a0  ; 11716
        move.l  a0,O_MoveTable(a5)              ; 1171A
        rts                                     ; 1171E

;---------------------------------------------------------------------------
; Random choice of move table: 0 slow, 8 fast
;---------------------------------------------------------------------------
AstarothSpeedPick:
	dc.b	$00,$00,$00,$08,$08,$00,$00,$08,$00,$08,$08,$00,$08,$00,$00,$08

;---------------------------------------------------------------------------
; (dx, dy) 8.8 for O_Dir 0 right / 1 left: +-0.18 (slow), +-0.41 (fast)
;---------------------------------------------------------------------------
AstarothMoveTables:
	dc.b	$00,$2D,$00,$00,$FF,$D3,$00,$00,$00,$69,$00,$00,$FF,$97,$00,$00

;---------------------------------------------------------------------------
; Face Arthur, run the stand phase timer, and shoot
;---------------------------------------------------------------------------
Astaroth_Think:
        bsr.w   Astaroth_FaceArthur             ; 11740
        bsr.b   Astaroth_StandPhase             ; 11744
        tst.b   Ast_Standing(a5)                ; 11746
        bne.b   l_1175C                         ; 1174A
        bsr.w   Astaroth_CheckFar               ; 1174C
        tst.b   Ast_Far(a5)                     ; 11750
        bne.w   Astaroth_ShotTimer              ; 11754
