;---------------------------------------------------------------------------
; === Fire pillar (type 18, 100 pts, 4 hits) ===
; Column of fire on level 2: rises and falls in place, fires projectiles when on screen.
; Dispatches on O_State: 0 main behaviour, 1 type-specific second phase, 2 killed (set by EnemyHitByShot after scoring), 3 remove.
;
; Behaviour, as coded: a column (size class 8) that cannot be hurt (O_Active $81) while it is
; idle. Once on screen and with Arthur within 48 px vertically, two timers from
; FirePillarTimes (started at random points) decide when it fires enemy shot type 5 at him
; from its lower end (16 px below its centre), its upper end (7 px above), or both. While it
; winds up (30 frames) and fires it can be hit (4 hits). Pil_FlickA-C are written during
; shots from a table of frame numbers but nothing reads them - a removed effect.
;---------------------------------------------------------------------------
Enemy_FirePillar:
        move.w  g_GameFrame(a6),d0              ; 11C50
        add.b   d7,d0                           ; 11C54
        andi.b  #$f,d0                          ; 11C56
        bne.b   l_11C60                         ; 11C5A
        bsr.w   CheckOnScreen                   ; 11C5C  visible?
l_11C60:
        clr.w   d0                              ; 11C60
        move.b  O_State(a5),d0                  ; 11C62
        add.w   d0,d0                           ; 11C66
        add.w   d0,d0                           ; 11C68
        jmp     Enemy_FirePillar_Jumps(pc,d0.w) ; 11C6A
Enemy_FirePillar_Jumps:
        bra.w   FirePillar_Init                 ; 11C6E
        bra.w   FirePillar_Active               ; 11C72
        bra.w   FirePillar_Dying                ; 11C76
        bra.w   FirePillar_Free                 ; 11C7A

;---------------------------------------------------------------------------
; State 0: size 8, face Arthur, 4 HP, random start in the timer script
;---------------------------------------------------------------------------
FirePillar_Init:
        move.b  #$8,O_Size(a5)                  ; 11C7E
        move.b  #$2,O_Dir(a5)                   ; 11C84
        move.w  O_X(a5),d0                      ; 11C8A
        cmp.w   g_ArthurX(a6),d0                ; 11C8E
        blt.b   l_11C9A                         ; 11C92
        move.b  #$3,O_Dir(a5)                   ; 11C94
l_11C9A:
        lea.l   FirePillar_AnimIdle(pc),a0      ; 11C9A
        bsr.w   SetAnimIndexed                  ; 11C9E  start animation for current direction
        lea.l   FirePillarTimes(pc),a0          ; 11CA2
        move.w  d7,d0                           ; 11CA6
        add.w   g_GameFrame(a6),d0              ; 11CA8
        andi.w  #$3,d0                          ; 11CAC
        move.b  (a0,d0.w),Pil_LowWait(a5)       ; 11CB0
        move.l  a0,Pil_LowPtr(a5)               ; 11CB6
        move.b  $1(a0,d0.w),Pil_HighWait(a5)    ; 11CBA
        move.l  a0,Pil_HighPtr(a5)              ; 11CC0
        move.b  #$4,O_HP(a5)                    ; 11CC4
        addq.b  #ST_ACTIVE,O_State(a5)          ; 11CCA
        clr.b   O_Step(a5)                      ; 11CCE
        clr.b   O_Step2(a5)                     ; 11CD2
        rts                                     ; 11CD6

;---------------------------------------------------------------------------
; State 1. O_Step: 0 wait to be on screen, 1 idle, 2 lower shot, 3 upper shot, 4 both
;---------------------------------------------------------------------------
FirePillar_Active:
        move.b  O_Step(a5),d0                   ; 11CD8
        add.w   d0,d0                           ; 11CDC
        add.w   d0,d0                           ; 11CDE
        jmp     FirePillar_Active_Jumps(pc,d0.w)             ; 11CE0
FirePillar_Active_Jumps:
        bra.w   FirePillar_WaitSeen             ; 11CE4
        bra.w   FirePillar_Idle                 ; 11CE8
        bra.w   FirePillar_ShootLow             ; 11CEC
        bra.w   FirePillar_ShootHigh            ; 11CF0
        bra.w   FirePillar_ShootBoth            ; 11CF4
FirePillar_WaitSeen:
        tst.b   O_OnScreen(a5)                  ; 11CF8
        beq.b   l_11D02                         ; 11CFC
        addq.b  #$1,O_Step(a5)                  ; 11CFE  next step
l_11D02:
        rts                                     ; 11D02

;---------------------------------------------------------------------------
; O_Step2: 0 shield up, wait for Arthur's height; 1-2 run the timers; 3 choose
;---------------------------------------------------------------------------
FirePillar_Idle:
        clr.w   d0                              ; 11D04
        move.b  O_Step2(a5),d0                  ; 11D06
        add.w   d0,d0                           ; 11D0A
        add.w   d0,d0                           ; 11D0C
        jmp     FirePillar_Idle_Jumps(pc,d0.w)  ; 11D0E
FirePillar_Idle_Jumps:
