        bra.w   FirePillar_LowTimer             ; 11D16
        bra.w   FirePillar_HighTimer            ; 11D1A
        bra.w   FirePillar_Choose               ; 11D1E
FirePillar_Shield:
        move.b  #$81,(a5)                       ; 11D22  shield: shots pass through
        move.b  #$1,O_Dir(a5)                   ; 11D26
        move.w  O_X(a5),d0                      ; 11D2C
        cmp.w   g_ArthurX(a6),d0                ; 11D30
        blt.b   l_11D3C                         ; 11D34
        move.b  #$3,O_Dir(a5)                   ; 11D36
l_11D3C:
        lea.l   FirePillar_AnimIdle(pc),a0      ; 11D3C
        bsr.w   SetAnimIndexed                  ; 11D40  start animation for current direction
        clr.b   Pil_Fire(a5)                    ; 11D44
        move.w  O_Y(a5),d0                      ; 11D48
        sub.w   g_ArthurY(a6),d0                ; 11D4C
        addi.w  #$30,d0                         ; 11D50
        cmp.w   #$60,d0                         ; 11D54
        bhi.b   l_11D5E                         ; 11D58
        addq.b  #$1,O_Step2(a5)                 ; 11D5A
l_11D5E:
        rts                                     ; 11D5E
FirePillar_LowTimer:
        subq.b  #$1,Pil_LowWait(a5)             ; 11D60
        bne.b   l_11D82                         ; 11D64
        movea.l Pil_LowPtr(a5),a0               ; 11D66
        move.b  (a0)+,Pil_LowWait(a5)           ; 11D6A
        bpl.b   l_11D78                         ; 11D6E
        andi.b  #$7f,Pil_LowWait(a5)            ; 11D70
        adda.w  (a0),a0                         ; 11D76
l_11D78:
        move.l  a0,Pil_LowPtr(a5)               ; 11D78
        ori.b   #$2,Pil_Fire(a5)                ; 11D7C
l_11D82:
        addq.b  #$1,O_Step2(a5)                 ; 11D82
        rts                                     ; 11D86
FirePillar_HighTimer:
        subq.b  #$1,Pil_HighWait(a5)            ; 11D88
        bne.b   l_11DAA                         ; 11D8C
        movea.l Pil_HighPtr(a5),a0              ; 11D8E
        move.b  (a0)+,Pil_HighWait(a5)          ; 11D92
        bpl.b   l_11DA0                         ; 11D96
        andi.b  #$7f,Pil_HighWait(a5)           ; 11D98
        adda.w  (a0),a0                         ; 11D9E
l_11DA0:
        move.l  a0,Pil_HighPtr(a5)              ; 11DA0
        ori.b   #$1,Pil_Fire(a5)                ; 11DA4
l_11DAA:
        addq.b  #$1,O_Step2(a5)                 ; 11DAA
        rts                                     ; 11DAE

;---------------------------------------------------------------------------
; Shot due: hittable, O_Step = 1 + Pil_Fire
;---------------------------------------------------------------------------
FirePillar_Choose:
        move.b  Pil_Fire(a5),d0                 ; 11DB0
        beq.b   l_11DBA                         ; 11DB4
        move.b  #$1,(a5)                        ; 11DB6  hittable while it shoots
l_11DBA:
