        lea.l   FirePillarFlicker(pc),a0        ; 11F46
        move.b  $1(a0,d0.w),Pil_FlickB(a5)      ; 11F4A
        move.b  $1(a0,d0.w),Pil_FlickC(a5)      ; 11F50
        moveq   #$3,d0                          ; 11F56
        and.b   Pil_Timer(a5),d0                ; 11F58
        bne.b   l_11F62                         ; 11F5C
