;---------------------------------------------------------------------------
; Shared death burst: 36 frames at size class 3, then the caller's next step
; (Woody Pig, Petite Devil, Flying Knight, Red Arremer, Big Man, Dragon segments, plant). O_Dir is used as the timer.
;---------------------------------------------------------------------------
EnemyBurst:
        tst.b   O_Step2(a5)                     ; 12076
        bne.b   l_12096                         ; 1207A
        move.b  #$3,O_Size(a5)                  ; 1207C
        lea.l   EnemyData(pc),a0                ; 12082
        bsr.w   SetAnim                         ; 12086  start animation
        move.b  #$24,O_Dir(a5)                  ; 1208A
        addq.b  #$1,O_Step2(a5)                 ; 12090
        rts                                     ; 12094
l_12096:
        subq.b  #$1,O_Dir(a5)                   ; 12096
        bne.w   Animate                         ; 1209A
        addq.b  #$1,O_Step(a5)                  ; 1209E  next step
        clr.b   O_Step2(a5)                     ; 120A2
        rts                                     ; 120A6

;---------------------------------------------------------------------------
; Shared death explosion (used by Satan, Unicorn and Dragon): 3 frames at size
; class 3, then 18 at size 4, then the caller's next step. O_Dir is used as the timer.
;---------------------------------------------------------------------------
EnemyExplode:
        cmpi.b  #$1,O_Step2(a5)                 ; 120A8
